              <div class="option-content">
                <span class="option-text">{{ getColorNameWithoutPercentage(color.name) }}</span>
                <span class="option-count" v-if="activeTab !== 'activity' && color.count">({{ color.count }})</span>
                <span v-if="activeTab !== 'activity' && color.floorPrice" class="floor-price">
                  {{ color.floorPrice }} 
                  <img :src="tonlogofloor" alt="TON" class="ton-floor-icon">
                </span>
                <span v-else-if="activeTab !== 'activity'" class="floor-price no-floor"></span>
                <span v-if="color.percentage" class="option-percentage">
                  {{ color.percentage }}
                </span>
                <span v-else class="option-rarity">{{ color.rarityText }}</span>
              </div>
              
              <span 
                v-if="isOptionSelected('backdrop', color.id)"
                class="checkmark"
              ></span>
            </div>
          </div>
        </div>
      </transition>
    </div>
    </div>
    
    <div class="balance-filter-container" v-if="activeTab === 'market'">
      <div class="ton-balance balance-container" @click="toggleBalancePopup" style="cursor: pointer;">
        <img v-if="userAvatarUrl" :src="userAvatarUrl" class="user-avatar-mini">
        <div v-else class="user-avatar-placeholder-mini">👤</div>
        <span>{{ formattedTonBalance }}</span>
        <img :src="tonlogoblack" alt="TON" class="currency-icon-black">
      </div>

 
      
      <div class="filter-buttons">
        <!-- Cart button -->
        <div class="cart-button-wrapper">
          <button class="filter-button" @click.stop="toggleCartMenu">
            <img :src="bucket_img" alt="Cart" class="filter-icon-img">
            <span v-if="cartItems.length > 0" class="cart-badge">{{ getTotalNFTsInCart() }}</span>
          </button>
        </div>
        
        <button class="filter-button" @click.stop="toggleSortMenu">
          <img :src="filter_img" alt="Filter" class="filter-icon-img">
        </button>

        <button class="filter-button" @click.stop="togglePriceRangeMenu">
          <img :src="sell_img" alt="Price Range" class="filter-icon-img">
        </button>

        <transition name="slide-fade">
          <div 
            v-if="sortMenu.show" 
            class="sort-menu" 
            v-click-outside="() => sortMenu.show = false"
            :style="{ right: '10px', top: '50px' }"
          >
            <div 
              v-for="option in sortMenu.options" 
              :key="option.id"
              class="sort-option"
              :class="{ selected: sortMenu.selected === option.id }"
              @click="applySort(option.id)"
            >
              <span>{{ option.name }}</span>
            </div>
          </div>
        </transition>
        
        <transition name="slide-fade">
          <div 
            v-if="cartMenu.show" 
            class="cart-menu" 
            v-click-outside="() => cartMenu.show = false"
            :style="{ right: '10px', top: '50px' }"
          >
            <div class="cart-header">
              <h4 class="cart-total-obyav">Cart ({{ cartItems.length }})</h4>
              <button class="clear-cart-btn" @click="clearCart" v-if="cartItems.length > 0">
                Clear
              </button>
            </div>
            
            <div v-if="cartItems.length === 0" class="empty-cart">
              Your cart is empty
            </div>
            
            <!-- In cart-menu -->
            <div class="cart-items">
              <div 
                v-for="(item, index) in cartItems" 
                :key="item.id + '-' + index" 
                class="cart-item"
                @click="openCartItemModal(item)" 
              >
                <div v-if="item.html_content" class="cart-item-html-wrapper">
                  <iframe 
                    sandbox="allow-scripts allow-same-origin"
                    :srcdoc="addSquareStyles(item.html_content)"
                    class="cart-item-html-content"
                    @load="forceSquareStyles"
                  ></iframe>
                </div>
                <img v-else :src="getNftImage(item.nft_type)" :alt="item.nft_type" class="cart-item-image">
                
                <div class="cart-item-info">
                  <div class="cart-item-name-container">
                    <span class="cart-item-name">{{ extractNameFromNftObject(item).name }}</span>
                    <span v-if="extractNameFromNftObject(item).number" class="cart-item-number">
                      #{{ extractNameFromNftObject(item).number }}
                    </span>
                  </div>
                  <div class="cart-item-price-section">
                    <span class="cart-item-price">{{ item.price_per_unit }}</span>
                    <img v-if="item.currency === 'TON'" :src="tonlogoyellow" alt="TON" class="currency-icon-small">
                  </div>
                </div>
                
                <button class="remove-from-cart-btn" @click.stop="removeFromCart(item.id)">
                  ×
                </button>
              </div>
            </div>
            
            <div class="cart-total" v-if="cartItems.length > 0">
              <span>{{ calculateCartTotal() }}</span>
              <img :src="tonlogogray" alt="TON" class="currency-icon-small">
            </div>
          </div>
        </transition>
        
        <transition name="slide-fade">
          <div 
            v-if="priceRangeMenu.show" 
            class="price-range-menu" 
            v-click-outside="() => priceRangeMenu.show = false"
            :style="{ right: '10px', top: '50px' }"
          >
            <div class="price-range-header">
              <h4>Price</h4>
            </div>
            <div class="price-range-inputs">
              <div class="input-group">
                <label>Min</label>
                <input 
                  v-model="priceRangeMenu.minPrice" 
                  type="number" 
                  placeholder="0"
                  min="0"
                  step="0.01"
                >
              </div>
              <div class="input-group">
                <label>Max</label>
                <input 
                  v-model="priceRangeMenu.maxPrice" 
                  type="number" 
                  placeholder="∞"
                  min="0"
                  step="0.01"
                >
              </div>
            </div>
            <div class="price-range-actions">
              <button class="reset-btn" @click="resetPriceRange">
                Reset
              </button>
              <button class="apply-btn" @click="applyPriceRange">
                Apply
              </button>
            </div>
          </div>
        </transition>
      </div>
    </div>

    <!-- "Activity" Page -->
    <div v-if="activeTab === 'activity'" class="activity-page">
      <div class="activity-container">
        <div class="activity-filters">
          <div class="filter-buttons">
            <!-- All button (Text) -->
            <button 
              class="filter-button"
              :class="{ active: selectedActivityType === 'all' }"
              @click="setActivityType('all')"
            >
              All
            </button>
            
            <!-- Icon buttons for specific types -->
            <button 
              v-for="type in activityTypes" 
              :key="type.value"
              class="filter-button"
              :class="{ active: selectedActivityType === type.value }"
              @click="setActivityType(type.value)"
            >
              <img 
                v-if="type.value === 'purchase'" 
                :src="purschaseIcon" 
                alt="Purchase" 
                class="filter-button-icon"
              >
              <img 
                v-else-if="type.value === 'listing'" 
                :src="listIcon" 
                alt="Listing" 
                class="filter-button-icon"
              >
              <img 
                v-else-if="type.value === 'price_edit'" 
                :src="editIcon" 
                alt="Edit Price" 
                class="filter-button-icon"
              >
            </button>
            
            <div class="my-activity-toggle">
              <label class="toggle-label-activity">
                <input 
                  type="checkbox" 
                  class="toggle-input-activity" 
                  :checked="showOnlyMyActivity"
                  @change="toggleMyActivity"
                >
                <div class="toggle-switch-activity">
                  <div class="toggle-slider-activity" :class="{ active: showOnlyMyActivity }"></div>
                </div>
                <span class="toggle-text-activity">My Activity</span>
              </label>
            </div>
          </div>
        </div>

        <div class="activity-list" ref="activityListRef" @scroll="handleActivityScroll">
          <div v-if="filteredActivity.length === 0 && !loadingActivity" class="empty-activity">
            <div class="empty-activity-content">
              <div class="empty-activity-icon">📊</div>
              <h3>No activity found</h3>
              <p v-if="showOnlyMyActivity">
                You don't have any activity yet. Start trading to see your history here.
              </p>
              <p v-else>
                No activity in the marketplace yet. Be the first to make a trade!
              </p>
            </div>
          </div>

          <div v-else class="activity-items">
            <div 
              v-for="activity in filteredActivity" 
              :key="activity.id"
              class="activity-item"
              :class="[
                activity.operation_type, 
                { 'my-activity': activity.user_name === currentAccountName },
                { 'clickable': canOpenItemPage(activity) }
              ]"
              @click="handleActivityClick(activity)"
            >
              <!-- NFT Preview -->
              <div class="activity-nft-preview">
                <img 
                  :src="getNftImageUrl(activity.nft_object || activity)" 
                  :alt="getNftDisplayName(activity.nft_type, activity.nft_object)"
                  class="activity-nft-image"
                  loading="lazy"
                  @error="handleImageError"
                >
              </div>

              <!-- Activity Details -->
              <div class="activity-details">
                <div class="activity-main-row">
                  <div class="activity-info-left">
                    <div class="activity-header-info">
                      <div class="nft-title-container">
                        <h4 class="activity-nft-name">
                          {{ getNftDisplayName(activity.nft_type, activity.nft_object) }}
                        </h4>
                        <span v-if="activity.nft_object" class="nft-id-activity">
                          #{{ extractNftId(activity.nft_object) }}
                        </span>
                      </div>
                      <div class="activity-user-badge" v-if="activity.user_name === currentAccountName">
                        You
                      </div>
                    </div>
                    
                    <div class="activity-meta">
                      <div class="activity-type-container">
                        <span class="activity-type" :class="activity.operation_type">
                          {{ getActivityTypeLabel(activity.operation_type) }}
                        </span>
                        <span class="activity-date">{{ formatActivityDate(activity.created_at) }}</span>
                      </div>
                    </div>
                  </div>

                  <!-- Price always on the right side -->
                  <div class="activity-price-section" v-if="activity.price_per_unit">
                    <!-- Activity type icon in top right corner -->
                    <div class="activity-type-icon" @click.stop="setActivityType(activity.operation_type)">
                      <img 
                        v-if="activity.operation_type === 'price_edit'" 
                        :src="editIcon_blue" 
                        alt="Edit Price" 
                        class="activity-type-image"
                        :class="{ active: selectedActivityType === 'price_edit' }"
                      >
                      <img 
                        v-else-if="activity.operation_type === 'listing'" 
                        :src="listIcon_blue" 
                        alt="Listing" 
                        class="activity-type-image"
                        :class="{ active: selectedActivityType === 'listing' }"
                      >
                      <img 
                        v-else-if="activity.operation_type === 'purchase'" 
                        :src="purschaseIcon_green" 
                        alt="Purchase" 
                        class="activity-type-image"
                        :class="{ active: selectedActivityType === 'purchase' }"
                      >
                    </div>

                    <div class="activity-price">
                      <span class="price-amount">{{ formatPrice(activity.price_per_unit) }}</span>
                      <img v-if="activity.currency === 'TON'" :src="tonlogoyellow" alt="TON" class="currency-icon-small">
                      <span v-else class="currency-text">{{ activity.currency }}</span>
                    </div>
                    
                    <div class="activity-total" v-if="activity.amount > 1">
                      Total: {{ formatPrice(activity.total_price) }} {{ activity.currency }}
                    </div>
                  </div>
                </div>
              </div>
            </div>
            

            <!-- Button for manual loading (optional) -->
            <div v-if="!pagination.isLoading && pagination.hasMore" class="load-more-container">
              <button class="load-more-btn" @click="loadMoreActivity">
                Load More
              </button>
            </div>
            
            <!-- End of list message -->
            <div v-if="!pagination.hasMore && filteredActivity.length > 0" class="end-of-list">
              <span>• • •</span>
            </div>
          </div>
          
          <!-- Loading indicator for initial load -->
          <div v-if="loadingActivity && filteredActivity.length === 0" class="initial-loading">
            <div class="loading-spinner"></div>
          </div>
        </div>
      </div>
    </div>

    <!-- "My NFTs" Page -->
    <div v-if="activeTab === 'my-nfts'" class="market-page" data-tab="my-gifts">
      <div class="listed-unlisted-toggle-container">
        <div class="listed-unlisted-toggle ios-toggle">
          <div class="toggle-track" :class="{ active: myNftsViewMode === 'unlisted' }">
            <div class="toggle-thumb" :class="{ active: myNftsViewMode === 'unlisted' }"></div>
          </div>
          
          <input 
            type="checkbox" 
            class="toggle-input" 
            :checked="myNftsViewMode === 'unlisted'"
            @change="toggleMyNftsViewMode"
          >
        </div>
        
        <div class="toggle-labels-below">
          <span 
            class="toggle-label" 
            :class="{ active: myNftsViewMode === 'listed' }"
            @click="myNftsViewMode = 'listed'"
          >Listed</span>
          <span 
            class="toggle-label" 
            :class="{ active: myNftsViewMode === 'unlisted' }"
            @click="myNftsViewMode = 'unlisted'"
          >Unlisted</span>
        </div>
      </div>
      
      <div class="market-container" ref="marketContainerRef" @scroll="handleContainerScroll">
        <div class="market-grid">
          <!-- Loading indicator for initial load -->
          <div v-if="myGiftsPagination.isLoading && myGiftsPagination.allItems.length === 0" 
              class="initial-loading">
            <div class="loading-spinner-large"></div>
            <span>Loading your NFTs...</span>
          </div>
          
          <!-- Listed NFT -->
          <template v-if="myNftsViewMode === 'listed'">
            <div v-for="item in filteredMarketItems" :key="item.id" class="market-item" :class="{ 'ton': item.currency === 'TON' }">
              <!-- Clickable area (image + info) -->
              <div class="market-item-content" @click="goToItemPage(item)">
                <div class="nft-image-wrapper">
                  <img 
                    :src="getNftImageUrl(item.nft_object)" 
                    :alt="getNftDisplayName(item.nft_type, item.nft_object)"
                    class="nft-image"
                    loading="lazy"
                    @error="handleImageError"
                    @click.stop
                  >
                  
                  <!-- Cart icon overlay on image -->
                  <button 
                    class="cart-overlay-button"
                    @click.stop="isInCart(item.id) ? removeFromCart(item.id, $event) : addToCart(item, $event)"
                    :disabled="item.seller === currentAccountName"
                    :title="isInCart(item.id) ? 'Remove from cart' : 'Add to cart'"
                    :class="{ 'in-cart': isInCart(item.id) }"
                  >
                    <img 
                      :src="isInCart(item.id) ? rubish_bucket_icon : bucket_icon" 
                      :alt="isInCart(item.id) ? 'Remove from cart' : 'Add to cart'" 
                      class="cart-overlay-icon"
                    >
                  </button>
                </div>
                
                <div class="nft-info-container">
                  <h6 class="hustler">{{ getNftDisplayName(item.nft_type, item.nft_object)}} </h6>
                  <span class="nft-id" v-if="item.nft_object">#{{ extractNftId(item.nft_object) }}</span>
                </div>  
              </div>
              
              <!-- Action buttons (outside clickable area) -->
              <div class="item-actions">
                <button 
                  v-if="item.seller !== currentAccountName" 
                  class="buy-button" 
                  @click.stop="goToItemPage(item)" 
                  :disabled="item.seller === currentAccountName"
                >
                  {{ item.price_per_unit }} {{ item.currency }}
                </button>
                <button 
                  v-if="item.seller === currentAccountName" 
                  class="edit-price-button" 
                  @click.stop="goToItemPage(item)"
                >
                  Edit Price
                </button>
                <button 
                  v-if="item.seller === currentAccountName" 
                  class="cancel-sale-button" 
                  @click.stop="goToItemPage(item)"
                >
                  Cancel sale
                </button>
              </div>
            </div>
            
            <div v-if="!myGiftsPagination.isLoading && filteredMarketItems.length === 0" 
                class="empty-message">
              You have no active listings on the market
            </div>
          </template>
          
          <!-- Unlisted NFT -->
          <template v-else>
            <div class="market-item add-card" @click="handleAddNft">
              <div class="empty-nft-square">
                <span class="add-icon">+</span>
                <span class="add-text">Add Gift</span>
              </div>
            </div>
            
            <div v-for="item in filteredMarketItems" :key="'unlisted-'+item.id" class="market-item">
              <!-- Clickable area (image + info) -->
              <div class="market-item-content" @click="openFullscreenView(item)">
                <div class="nft-image-wrapper">
                  <img 
                    :src="getNftImageUrl(item.nft_object)" 
                    :alt="getNftDisplayName(item.nft_type, item.nft_object)"
                    class="nft-image"
                    loading="lazy"
                    @error="handleImageError"
                    @click.stop
                  >
                </div>
                
                <div class="nft-info-container">
                  <h6 class="hustler">{{ getNftDisplayName(item.nft_type, item.nft_object) }}</h6>
                  <span class="nft-id">#{{ extractNftId(item.nft_object) }}</span>
                </div>  
              </div>
              
              <!-- Action buttons (outside clickable area) -->
              <div class="action-buttons-container">
                <button 
                  class="action-btn action-btn-send full-width flat-button"
                  @click.stop="handleTransfer(item.nft_object)"
                >
                  <span class="btn-text">Send</span>
                </button>
                
                <div class="row-buttons with-spacing">
                  <button 
                    class="action-btn action-btn-sale compact-btn"
                    @click.stop="handleSell(item.nft_object)"
                  >
                    <div class="btn-content horizontal">
                      <span class="btn-text">Sell</span>
                    </div>
                  </button>
                  <button 
                    class="action-btn action-btn-withdraw compact-btn"
                    @click.stop="handleWithdraw(item.nft_object)"
                  >
                    <div class="btn-content horizontal">
                      <span class="btn-text">Withdraw</span>
                    </div>
                  </button>
                </div>
              </div>
            </div>
            
          </template>
          
          <!-- Loading more indicator -->
          <div v-if="myGiftsPagination.isLoadingMore" class="loading-more-indicator">
            <div class="loading-spinner-small"></div>
            <span>Loading more NFTs...</span>
          </div>
          
          <!-- End of list message -->
          <div v-if="!myGiftsPagination.hasMore && filteredMarketItems.length > 0 && !myGiftsPagination.isLoading" class="end-of-list">
            <span>All NFTs loaded</span>
          </div>
        </div>
      </div>
    </div>

    <!-- "Market" Page -->
    <div v-if="activeTab === 'market'" class="market-page" data-tab="market">
      
      <!-- Main scroll container -->
      <div class="market-container" ref="marketContainerRef">
        
        <!-- Grid with listings -->
        <div class="market-grid">
          
          <!-- Listings -->
          <div v-for="item in filteredMarketItems" :key="item.id" class="market-item" :class="getMarketItemClass(item)">
            <!-- Clickable area (image + info) -->
            <div class="market-item-content" @click="goToItemPage(item)">
              <div class="nft-image-wrapper">
                <img 
                  :src="getNftImageUrl(item)" 
                  :alt="getNftDisplayName(item.nft_type, item.nft_object)"
                  class="nft-image"
                  loading="lazy"
                  @error="handleImageError"
                  @click.stop
                >
                
                <!-- Cart icon overlay -->
                <button 
                  class="cart-overlay-button"
                  @click.stop="isInCart(item.id) ? removeFromCart(item.id, $event) : addToCart(item, $event)"
                  :disabled="item.seller === currentAccountName"
                  :title="isInCart(item.id) ? 'Remove from cart' : 'Add to cart'"
                  :class="{ 'in-cart': isInCart(item.id) }"
                >
                  <img 
                    :src="isInCart(item.id) ? rubish_bucket_icon : bucket_icon" 
                    :alt="isInCart(item.id) ? 'Remove from cart' : 'Add to cart'" 
                    class="cart-overlay-icon"
                  >
                </button>
              </div>
              
              <!-- NFT Info (name and ID) -->
              <div class="nft-info-container">
                <h6 class="hustler">{{ getNftDisplayName(item.nft_type, item.nft_object) }}</h6>
                <span class="nft-id" v-if="item.nft_object">#{{ extractNftIdFromData(item.nft_object) }}</span>
              </div>
            </div>
            
            <!-- Action buttons (separate, outside clickable area) -->
            <div class="item-actions">
              <!-- Button for other users' listings -->
              <button 
                v-if="item.seller !== currentAccountName" 
                class="buy-button" 
                @click.stop="goToItemPage(item)"
              >
                <span class="price-with-icon">
                  {{ item.price_per_unit }} 
                  <span v-if="item.currency === 'TON'" class="ton-icon-wrapper">
                    <img :src="tonlogo" alt="TON" class="currency-icon">
                  </span>
                  <span v-else class="currency-text">{{ item.currency }}</span>
                </span>
              </button>
              
              <!-- Buttons for own listings -->
              <template v-else>
                <button class="edit-price-button" @click.stop="goToItemPage(item)">
                  Edit Price
                </button>
                <button class="cancel-sale-button" @click.stop="goToItemPage(item)">
                  Cancel sale
                </button>
              </template>
            </div>
          </div>
          
          <!-- Loading indicator for initial load -->
          <div v-if="marketPagination.isLoading && marketPagination.allItems.length === 0" 
               class="initial-loading">
            <div class="loading-spinner-large"></div>
            <span>Loading marketplace...</span>
          </div>
          
          <!-- Message if no listings -->
          <div v-if="!marketPagination.isLoading && filteredMarketItems.length === 0" 
               class="empty-market">
            <div class="empty-icon">📭</div>
            <h3>No listings on the market yet</h3>
            <p>Be the first to list your NFT for sale!</p>
          </div>
          
        </div>
        
        <!-- Loading more indicator -->
        <div v-if="marketPagination.isLoadingMore" class="loading-more-indicator">
          <div class="loading-spinner-small"></div>
          <span>Loading more listings...</span>
        </div>
      </div>
      
      <!-- Debug statistics -->
      <div class="debug-stats" v-if="false">
        <div class="stat-item">
          <strong>Loaded:</strong> {{ marketPagination.allItems.length }}
        </div>
        <div class="stat-item">
          <strong>Offset:</strong> {{ marketPagination.offset }}
        </div>
        <div class="stat-item">
          <strong>Has more:</strong> {{ marketPagination.hasMore ? 'Yes' : 'No' }}
        </div>
        <div class="stat-item">
          <strong>Loading:</strong> {{ marketPagination.isLoadingMore ? 'Yes' : 'No' }}
        </div>
      </div>
    </div>

    <div v-if="htmlModal.show" class="fullscreen-view" :class="{ 'my-gifts-unlisted': htmlModal.isUnlisted && activeTab === 'my-nfts' }">
      <button class="back-button" @click="handleBackButton">
        <svg width="24" height="24" viewBox="0 0 24 24" fill="none">
          <path d="M15 18L9 12L15 6" stroke="currentColor" stroke-width="2" stroke-linecap="round"/>
        </svg>
      </button>
      
      <div class="fullscreen-content">
        <div class="html-container">
          <iframe 
            sandbox="allow-scripts allow-same-origin"
            :srcdoc="htmlModal.htmlContent"
            class="html-content-iframe"
            :class="{ 'unlisted-mode': htmlModal.isUnlisted && activeTab === 'my-nfts' }"
            ref="htmlIframe"
          ></iframe>
        </div>

        <!-- Top action buttons row -->
        <div class="action-buttons-row" v-if="!htmlModal.isUnlisted">
          <!-- SMART REPLACEMENT: if cart inactive → show Promote -->
          <template v-if="htmlModal.item">
            <!-- Case 1: User is OWNER of listing → show Promote -->
            <button 
              v-if="htmlModal.item.seller === currentAccountName"
              class="action-button-row promote-button"
              @click="openPromoteModal(htmlModal.item)"
              :title="isItemPromoted(htmlModal.item.id) ? 'Already promoted (click for info)' : 'Promote for 0.1 TON (24h)'"
              :class="{ 
                'promoted': isItemPromoted(htmlModal.item.id),
                'active': !isItemPromoted(htmlModal.item.id)
              }"
            >
              <img 
                :src="PromoteIcon" 
                alt="Promote" 
                class="action-button-icon"
              >
