  router.push({ path: '/profile', query: { openBalance: 'true' } })
}
const closeBalanceModal = () => {
  showBalanceModal.value = false
}
console.log('BalancePopup компонент импортирован:', BalancePopup)
    // Добавьте в setup() после других переменных
const isFullscreenActive = ref(false);
const isAnimationActive = ref(false);
// Функция для проверки активных модальных окон
const checkActiveModals = () => {
  // Проверяем fullscreen модалку
  const fullscreenActive = htmlModal.value?.show || false;
  
  // Проверяем анимации
  const animationActive = operationAnimation.value?.show || 
                         purchaseSuccess.value?.show || 
                         operationFail.value?.show || false;
  
  isFullscreenActive.value = fullscreenActive;
  isAnimationActive.value = animationActive;
  
  console.log('📊 Состояние модалок:', { fullscreenActive, animationActive });
};


// ========== ВИДЕО-БАННЕР С ЗАГРУЗКОЙ ИЗ БД ==========
const videoPlayer = ref(null);
const currentMedia = ref('Bank');
const mediaProgress = ref({
  Bank: 0,
  GIVEAWAY: 0,
  BONUSTON: 0,
  ZEROFEE: 0
});
const currentMediaSrc = ref(Bank);

// Конфигурация из БД
const videoConfig = ref({
  bank: false,
  giveaway: false,
  bonuston: false,
  zerofee: false
});

const videoLinks = ref({
  bank: '',
  giveaway: '',
  bonuston: '',
  zerofee: ''
});

const isLoadingConfig = ref(true);
const configError = ref(null);

const IMAGE_DURATION = 7200; // 5 секунд для изображений

// Функция для парсинга булевых значений из строк
const parseBoolean = (value) => {
  if (value === true || value === false) return value;
  if (value === 'true') return true;
  if (value === 'false') return false;
  return false;
};

// Загрузка конфигурации из БД
const loadVideoConfig = async () => {
  try {
    isLoadingConfig.value = true;
    configError.value = null;
    
    console.log('📥 Загрузка конфигурации видео из БД...');
    
    const { data, error } = await supabase
      .from('configurations')
      .select('home_video, video_link')
      .eq('id', 1)
      .single();
    
    if (error) {
      console.error('❌ Ошибка загрузки конфигурации:', error);
      configError.value = error.message;
      return;
    }
    
    console.log('✅ Данные из БД:', data);
    
    // Парсим home_video (это массив с объектом внутри)
    if (data?.home_video && Array.isArray(data.home_video) && data.home_video.length > 0) {
      const config = data.home_video[0]; // Берем первый элемент массива
      
      videoConfig.value = {
        bank: parseBoolean(config.bank),
        giveaway: parseBoolean(config.giveaway),
        bonuston: parseBoolean(config.bonuston),
        zerofee: parseBoolean(config.zerofee)
      };
    }
    
    // Парсим video_link (это массив с объектом внутри)
    if (data?.video_link && Array.isArray(data.video_link) && data.video_link.length > 0) {
      const links = data.video_link[0]; // Берем первый элемент массива
      
      videoLinks.value = {
        bank: links.bank || '',
        giveaway: links.giveaway || '',
        bonuston: links.bonuston || '',
        zerofee: links.zerofee || ''
      };
    }
    
    console.log('📋 Загруженная конфигурация:', videoConfig.value);
    console.log('🔗 Загруженные ссылки:', videoLinks.value);
    
  } catch (error) {
    console.error('❌ Критическая ошибка:', error);
    configError.value = error.message;
  } finally {
    isLoadingConfig.value = false;
  }
};

// Активные медиа на основе конфигурации из БД
const activeMediaList = computed(() => {
  const list = [];
  
  // Добавляем только те баннеры, которые включены в БД
  if (videoConfig.value.bank) {
    list.push({ type: 'Bank', src: Bank });
  }
  if (videoConfig.value.giveaway) {
    list.push({ type: 'GIVEAWAY', src: Giveaway });
  }
  if (videoConfig.value.bonuston) {
    list.push({ type: 'BONUSTON', src: BonusTon });
  }
  if (videoConfig.value.zerofee) {
    list.push({ type: 'ZEROFEE', src: ZeroFee });
  }
  
  console.log('📋 Активные медиа после загрузки:', list.map(m => m.type));
  return list;
});

const hasActiveVideo = computed(() => {
  return activeMediaList.value.length > 0;
});

const getProgress = (mediaType) => {
  return mediaProgress.value[mediaType] || 0;
};

let imageTimer = null;

const startImageTimer = () => {
  console.log('🖼️ Запуск таймера для изображения:', currentMedia.value);
  
  mediaProgress.value[currentMedia.value] = 0;
  
  if (imageTimer) clearInterval(imageTimer);
  
  const startTime = Date.now();
  const duration = IMAGE_DURATION;
  
  imageTimer = setInterval(() => {
    const elapsed = Date.now() - startTime;
    const progress = (elapsed / duration) * 100;
    
    if (progress >= 100) {
      mediaProgress.value[currentMedia.value] = 100;
      clearInterval(imageTimer);
      imageTimer = null;
      handleMediaEnd();
    } else {
      mediaProgress.value[currentMedia.value] = progress;
    }
  }, 100);
};

const onMediaLoaded = () => {
  console.log('✅ Видео загружено:', currentMedia.value);
  if (videoPlayer.value) {
    videoPlayer.value.playbackRate = 0.7;
    videoPlayer.value.play().catch(e => console.log('Ошибка воспроизведения:', e));
  }
};

const updateProgress = () => {
  if (!videoPlayer.value) return;
  
  const currentTime = videoPlayer.value.currentTime;
  const duration = videoPlayer.value.duration;
  
  if (duration && duration > 0) {
    const progress = (currentTime / duration) * 100;
    mediaProgress.value[currentMedia.value] = progress;
  }
};

const handleMediaEnd = () => {
  console.log('🔄 Медиа завершено:', currentMedia.value);
  
  const activeList = activeMediaList.value;
  if (activeList.length === 0) return;
  
  const currentIndex = activeList.findIndex(item => item.type === currentMedia.value);
  const nextIndex = (currentIndex + 1) % activeList.length;
  const nextMedia = activeList[nextIndex];
  
  switchToMedia(nextMedia.type);
};

const switchToMedia = async (mediaType) => {
  if (currentMedia.value === mediaType) return;
  
  console.log('🔄 Переключение на:', mediaType);
  
  if (videoPlayer.value) {
    videoPlayer.value.pause();
  }
  
  if (imageTimer) {
    clearInterval(imageTimer);
    imageTimer = null;
  }
  
  const mediaItem = activeMediaList.value.find(item => item.type === mediaType);
  if (!mediaItem) return;
  
  Object.keys(mediaProgress.value).forEach(key => {
    mediaProgress.value[key] = 0;
  });
  
  currentMedia.value = mediaType;
  currentMediaSrc.value = mediaItem.src;
  
  await nextTick();
  
  if (mediaType === 'Bank' || mediaType === 'GIVEAWAY') {
    if (videoPlayer.value) {
      videoPlayer.value.currentTime = 0;
      videoPlayer.value.load();
      videoPlayer.value.playbackRate = 0.7;
      videoPlayer.value.play().catch(e => console.log('Ошибка:', e));
    }
  } else {
    startImageTimer();
  }
};

const switchMedia = (mediaType) => {
  switchToMedia(mediaType);
};

const handleMediaClick = () => {
  let link = '';
  
  switch (currentMedia.value) {
    case 'Bank':
      link = videoLinks.value.bank;
      break;
    case 'GIVEAWAY':
      link = videoLinks.value.giveaway;
      break;
    case 'BONUSTON':
      link = videoLinks.value.bonuston;
      break;
    case 'ZEROFEE':
      link = videoLinks.value.zerofee;
      break;
  }
  
  console.log('👆 Клик по баннеру:', currentMedia.value, 'Ссылка:', link);
  
  if (link && link.trim() !== '') {
    window.open(link, '_blank');
  }
};

// Загружаем конфигурацию при монтировании
onMounted(async () => {
  console.log('🚀 Инициализация баннера');
  
  await loadVideoConfig();
  
  console.log('🎯 hasActiveVideo:', hasActiveVideo.value);
  console.log('📋 activeMediaList:', activeMediaList.value.map(m => m.type));
  
  // Запускаем первое медиа если есть активные
  if (hasActiveVideo.value && activeMediaList.value.length > 0) {
    // Устанавливаем первое медиа из списка
    const firstMedia = activeMediaList.value[0];
    currentMedia.value = firstMedia.type;
    currentMediaSrc.value = firstMedia.src;
    
    // Даем время на рендеринг
    setTimeout(() => {
      if (firstMedia.type === 'Bank' || firstMedia.type === 'GIVEAWAY') {
        if (videoPlayer.value) {
          videoPlayer.value.playbackRate = 0.7;
          videoPlayer.value.play().catch(e => console.log('Ошибка:', e));
        }
      } else {
        startImageTimer();
      }
    }, 500);
  }
});

onUnmounted(() => {
  if (imageTimer) clearInterval(imageTimer);
  if (videoPlayer.value) {
    videoPlayer.value.pause();
  }
});
    // Замените текущий operationFail на более универсальную структуру
// Замените текущий operationFail на более универсальную структуру
const operationAnimation = ref({
  show: false,
  animationData: null,
  type: '', // 'success' или 'fail'
  title: ''
});// В разделе setup(), после объявления других переменных:
const nftOptionsLoading = ref(false);

    // После marketPagination добавьте:
const myGiftsPagination = ref({
  offset: 0,
  limit: 15,
  hasMore: true,
  isLoading: false,
  isLoadingMore: false,
  allItems: [] // Все загруженные NFT пользователя
});
    // 1. Добавьте новые переменные состояния для пагинации
const pagination = ref({
  offset: 0,
  limit: 10,
  hasMore: true,
  isLoading: false
});
// 1. Убедитесь, что у вас есть правильная структура данных для пагинации
const marketPagination = ref({
  offset: 0,
  limit: 14,
  hasMore: true,
  isLoading: false,
  isLoadingMore: false,
  allItems: [] // Все загруженные объявления
});

// 2. Исправленная функция loadMarketItems для поддержки lazy loading
let marketLoadLock = false;



// 3. Функция для подгрузки следующих объявлений
const loadMoreMarketItems = async () => {
  if (marketPagination.value.isLoadingMore || !marketPagination.value.hasMore) {
    console.log('⏸️ Подгрузка невозможна:', {
      isLoadingMore: marketPagination.value.isLoadingMore,
      hasMore: marketPagination.value.hasMore
    });
    return;
  }
  
  console.log('🎯 Вызов loadMoreMarketItems');
  await loadMarketItems(true);
};

// 4. Обработчик скролла для автоматической подгрузки
const handleMarketScroll = () => {
  // Работаем только на вкладке Market
  if (activeTab.value !== 'market') return;
  
  const marketContainer = document.querySelector('.market-container');
  if (!marketContainer) {
    console.log('❌ Контейнер market не найден');
    return;
  }
  
  // Проверяем условия для загрузки
  if (marketPagination.value.isLoadingMore || !marketPagination.value.hasMore) {
    return;
  }
  
  // Рассчитываем позицию скролла
  const scrollPosition = marketContainer.scrollTop;
  const scrollHeight = marketContainer.scrollHeight;
  const clientHeight = marketContainer.clientHeight;
  
  // Проверяем, достигли ли мы конца списка (200px от конца)
  const threshold = 200;
  const distanceFromBottom = scrollHeight - scrollPosition - clientHeight;
  
  if (distanceFromBottom < threshold) {
    console.log('🔽 Достигнут конец списка, подгружаем следующие 15 объявлений...');
    console.log(`📊 Расстояние от конца: ${Math.round(distanceFromBottom)}px`);
    
    // Запускаем подгрузку с небольшой задержкой для плавности
    setTimeout(() => {
      loadMoreMarketItems();
    }, 300);
  }
};

