// 1. Исправленная функция loadMarketItems с сохранением lazy loading
let isInitialLoadInProgress = false;
let loadMarketItemsPromise = null;
const marketLoadState = {
  isInitialLoadInProgress: false,
  isLoadMoreInProgress: false,
  lastLoadTime: 0,
  loadCooldown: 1000, // 1 секунда между загрузками
};

const loadMarketItems = async (isLoadMore = false) => {
  const now = Date.now();
  
  // Проверка cooldown
  if (now - marketLoadState.lastLoadTime < marketLoadState.loadCooldown) {
    console.log('⏸️  Слишком частый вызов, пропускаем (cooldown)');
    return;
  }
  
  // Проверка уже выполняющейся загрузки
  if (isLoadMore && marketLoadState.isLoadMoreInProgress) {
    console.log('⏸️  Подгрузка уже выполняется');
    return;
  }
  
  if (!isLoadMore && marketLoadState.isInitialLoadInProgress) {
    console.log('⏸️  Начальная загрузка уже выполняется');
    return;
  }
  
  try {
    // Устанавливаем флаги
    if (isLoadMore) {
      marketLoadState.isLoadMoreInProgress = true;
      marketPagination.value.isLoadingMore = true;
    } else {
      marketLoadState.isInitialLoadInProgress = true;
      marketPagination.value.isLoading = true;
      marketPagination.value.offset = 0;
      marketPagination.value.hasMore = true;
    }
    
    marketLoadState.lastLoadTime = now;
    
    console.log(`📥 ${isLoadMore ? 'Подгрузка' : 'Загрузка'} объявлений...`);
    
    const { data, error, count } = await supabase
      .from('market')
      .select('*', { count: 'exact' })
      .order('created_at', { ascending: false })
      .range(
        marketPagination.value.offset, 
        marketPagination.value.offset + marketPagination.value.limit - 1
      );
    
    if (error) throw error;
    
    const newItems = data || [];
    console.log(`✅ Получено ${newItems.length} новых объявлений`);
    
    // КРИТИЧНО: Обновляем данные атомарно, без промежуточных состояний
    if (isLoadMore) {
      // Для подгрузки - добавляем к существующим
      const updatedItems = [...marketPagination.value.allItems, ...newItems];
      marketPagination.value.allItems = updatedItems;
    } else {
      // Для начальной загрузки - заменяем полностью
      marketPagination.value.allItems = newItems;
    }
    
    // Синхронизируем с marketItems
    marketItems.value = marketPagination.value.allItems;
    
    // Обновляем пагинацию
    const totalLoaded = marketPagination.value.allItems.length;
    marketPagination.value.hasMore = totalLoaded < (count || 0);
    
    if (newItems.length > 0) {
      marketPagination.value.offset += newItems.length;
    }
    
    console.log(`📊 Итого: ${totalLoaded} объявлений, еще есть: ${marketPagination.value.hasMore}`);
    
  } catch (error) {
    console.error('❌ Ошибка загрузки объявлений:', error);
    
    // При ошибке сбрасываем данные
    if (!isLoadMore) {
      marketPagination.value.allItems = [];
      marketItems.value = [];
    }
    
    throw error;
    
  } finally {
    // Всегда сбрасываем флаги
    marketPagination.value.isLoading = false;
    marketPagination.value.isLoadingMore = false;
    
    if (isLoadMore) {
      marketLoadState.isLoadMoreInProgress = false;
    } else {
      marketLoadState.isInitialLoadInProgress = false;
    }
    
    console.log('🏁 Загрузка завершена');
  }
};
// 2. Исправленная функция loadMyGifts
// Добавьте эту переменную в область видимости setup() (рядом с другими ref)
let myGiftsLoadInProgress = false;
let myGiftsLoadPromise = null;

const loadMyGifts = async (isLoadMore = false) => {
  // Защита от рекурсивных вызовов
  if (myGiftsLoadInProgress) {
    console.log('⏸️ loadMyGifts уже выполняется, пропускаем вызов');
    return;
  }

  // Если уже есть промис загрузки для начальной загрузки (не подгрузки)
  if (myGiftsLoadPromise && !isLoadMore) {
    console.log('📦 Используем существующий промис загрузки');
    try {
      await myGiftsLoadPromise;
    } catch (error) {
      console.error('❌ Ошибка в существующем промиссе:', error);
    }
    return;
  }

  myGiftsLoadInProgress = true;
  
  try {
    console.log('🚀 loadMyGifts НАЧАЛАСЬ', {
      isLoadMore,
      currentMode: myNftsViewMode.value,
      currentOffset: myGiftsPagination.value.offset,
      currentItems: myGiftsPagination.value.allItems.length
    });

    // Создаем промис для отслеживания
    myGiftsLoadPromise = (async () => {
      // Устанавливаем состояние загрузки
      if (isLoadMore) {
        myGiftsPagination.value.isLoadingMore = true;
      } else {
        myGiftsPagination.value.isLoading = true;
        // ТОЛЬКО для начальной загрузки сбрасываем offset
        myGiftsPagination.value.offset = 0;
        myGiftsPagination.value.hasMore = true;
        // НЕ сбрасываем данные здесь! Они сбросятся только при успешной загрузке
      }

      let loadedData = [];
      let totalAvailable = 0;

      if (myNftsViewMode.value === 'listed') {
        // Загрузка listed NFT
        console.log('📥 Загрузка listed NFT...');
        const { data, error, count } = await supabase
          .from('market')
          .select('*', { count: 'exact' })
          .eq('seller', currentAccountName.value)
          .order('created_at', { ascending: false })
          .range(
            myGiftsPagination.value.offset,
            myGiftsPagination.value.offset + myGiftsPagination.value.limit - 1
          );
        
        if (error) {
          console.error('❌ Ошибка загрузки listed NFT:', error);
          throw error;
        }
        
        loadedData = data || [];
        totalAvailable = count || 0;
        
        console.log(`✅ Listed NFT: загружено ${loadedData.length}, всего в базе: ${totalAvailable}`);
        
      } else {
        // Загрузка unlisted NFT
        console.log('📥 Загрузка unlisted NFT...');
        const { data: userData, error: userError } = await supabase
          .from('users')
          .select('nft_links')
          .eq('name', currentAccountName.value)
          .single();
        
        if (userError) {
          console.error('❌ Ошибка загрузки unlisted NFT:', userError);
          throw userError;
        }
        
        const nftLinks = userData?.nft_links || [];
        
        // УДАЛЯЕМ ДУБЛИКАТЫ ИЗ ИСХОДНЫХ ДАННЫХ
        const uniqueNftLinks = [];
        const seenUrls = new Set();
        const seenGiftIds = new Set();
        
        nftLinks.forEach(nft => {
          const nftData = typeof nft === 'object' ? nft : { url: nft };
          const nftUrl = nftData.url;
          const giftId = nftData.gift_id;
          
          // Создаем уникальный ключ
          let uniqueKey = null;
          if (giftId) {
            uniqueKey = `gift_${giftId}`;
          } else if (nftUrl) {
            const urlMatch = nftUrl.match(/-(\d+)(?:\?|$)/);
            const urlId = urlMatch ? urlMatch[1] : null;
            uniqueKey = urlId ? `url_${urlId}` : nftUrl;
          }
          
          if (uniqueKey) {
            if (seenUrls.has(uniqueKey) || (giftId && seenGiftIds.has(giftId))) {
              console.warn('🚫 Пропускаем дубликат NFT при загрузке:', { url: nftUrl, giftId });
              return;
            }
            seenUrls.add(uniqueKey);
            if (giftId) seenGiftIds.add(giftId);
          } else {
            if (seenUrls.has(nftUrl)) {
              console.warn('🚫 Пропускаем дубликат NFT (по URL):', nftUrl);
              return;
            }
            seenUrls.add(nftUrl);
          }
          
          uniqueNftLinks.push(nftData);
        });
        
        totalAvailable = uniqueNftLinks.length;
        
        const start = myGiftsPagination.value.offset;
        const end = Math.min(start + myGiftsPagination.value.limit, totalAvailable);
        
        loadedData = uniqueNftLinks.slice(start, end).map((nftData, index) => {
          const nftId = extractNftIdFromData(nftData);
          const nftName = extractNftNameFromUrl(nftData.url) || 'unknown';
          
          return {
            id: `unlisted-${nftId}-${index}`,
            item_id: `unlisted-${nftId}`,
            nft_type: `html_nft_${nftName}`,
            nft_object: nftData,
            html_content: generateNftHtmlForList(nftData),
            seller: currentAccountName.value,
            is_unlisted: true,
            price_per_unit: 0,
            currency: 'TON',
            created_at: nftData.acquired_at || new Date().toISOString(),
            nft_name: nftData.name || 'Unnamed NFT',
            model: nftData.model || '',
            symbol: nftData.symbol || '',
            backdrop: nftData.backdrop || ''
          };
        });
        
        console.log(`✅ Unlisted NFT: загружено ${loadedData.length} из ${totalAvailable} (уникальных: ${uniqueNftLinks.length}, исходных: ${nftLinks.length})`);
      }

      // КРИТИЧЕСКИ ВАЖНО: Атомарное обновление данных
      if (isLoadMore) {
        // Для подгрузки - добавляем к существующим
        myGiftsPagination.value.allItems = [
          ...myGiftsPagination.value.allItems,
          ...loadedData
        ];
      } else {
        // Для начальной загрузки - заменяем полностью
        myGiftsPagination.value.allItems = loadedData;
      }

      // Обновляем offset только если загрузили данные
      if (loadedData.length > 0) {
        myGiftsPagination.value.offset += loadedData.length;
      }

      // Определяем, есть ли еще данные для загрузки
      myGiftsPagination.value.hasMore = myGiftsPagination.value.offset < totalAvailable;

      console.log(`📊 Итог загрузки:`, {
        loaded: loadedData.length,
        totalInMemory: myGiftsPagination.value.allItems.length,
        totalAvailable: totalAvailable,
        newOffset: myGiftsPagination.value.offset,
        hasMore: myGiftsPagination.value.hasMore,
        isLoadMore: isLoadMore
      });

      // Примеры загруженных данных для отладки
      if (loadedData.length > 0) {
        console.log('📋 Примеры загруженных данных:');
        loadedData.slice(0, 2).forEach((item, i) => {
          console.log(`   ${i + 1}. ID: ${item.id}, Type: ${item.nft_type}, Unlisted: ${item.is_unlisted}`);
        });
      }

      return loadedData;
    })();

    // Ждем выполнения промиса
    await myGiftsLoadPromise;
    
  } catch (error) {
    console.error('❌ Критическая ошибка в loadMyGifts:', error);
    
    // При ошибке сбрасываем только если это не подгрузка
    if (!isLoadMore) {
      myGiftsPagination.value.allItems = [];
      console.log('⚠️  Сброшены данные из-за ошибки');
    }
    
    // Сбрасываем флаги пагинации
    myGiftsPagination.value.hasMore = false;
    
  } finally {
    // ВСЕГДА сбрасываем флаги загрузки
    myGiftsPagination.value.isLoading = false;
    myGiftsPagination.value.isLoadingMore = false;
    
    // Сбрасываем флаги блокировки с небольшой задержкой
    setTimeout(() => {
      myGiftsLoadInProgress = false;
      myGiftsLoadPromise = null;
    }, 50);
    
    console.log('🏁 loadMyGifts ЗАВЕРШЕНА');
  }
  
};


