// Исправленная функция для возврата средств с удалением из БД
const refundAllPendingOffersForItem = async (marketItemId, cancellationReason = 'item_removed_from_market') => {
  try {
    console.log(`🔍 Поиск активных офферов для marketItemId: ${marketItemId}...`);
    
    // ВАЖНО: В вашей БД офферы хранятся с item_id
    const { data: offersByItemId, error: error1 } = await supabase
      .from('offers')
      .select('*')
      .eq('item_id', marketItemId)
      .eq('status', 'pending');

    console.log(`🔍 Офферы по item_id '${marketItemId}':`, offersByItemId?.length || 0);
    
    if (offersByItemId && offersByItemId.length > 0) {
      offersByItemId.forEach(offer => {
        console.log('   Найден оффер:', {
          id: offer.id,
          item_id: offer.item_id,
          status: offer.status,
          buyer_name: offer.buyer_name,
          offer_price: offer.offer_price
        });
      });
    }
    
    // Если не нашли по item_id, пробуем другие варианты...
    let activeOffers = offersByItemId || [];
    
    // 2. Если не нашли, возможно item.id в market отличается от item_id в offers
    const { data: marketItem, error: marketError } = await supabase
      .from('market')
      .select('*')
      .eq('id', marketItemId)
      .single();
    
    if (!marketError && marketItem) {
      console.log('🔍 Данные из market для ID', marketItemId, ':', {
        id: marketItem.id,
        item_id: marketItem.item_id,
        nft_object: marketItem.nft_object
      });
      
      // Попробуем найти офферы по nft_id из nft_object
      try {
        const nftObj = typeof marketItem.nft_object === 'string' 
          ? JSON.parse(marketItem.nft_object) 
          : marketItem.nft_object;
        
        if (nftObj && nftObj.gift_id) {
          const { data: offersByNftId, error: nftError } = await supabase
            .from('offers')
            .select('*')
            .eq('nft_id', nftObj.gift_id.toString())
            .eq('status', 'pending');
          
          console.log(`🔍 Офферы по nft_id '${nftObj.gift_id}':`, offersByNftId?.length || 0);
          
          if (offersByNftId && offersByNftId.length > 0) {
            activeOffers = offersByNftId;
          }
        }
      } catch (e) {
        console.warn('⚠️ Не удалось разобрать nft_object:', e);
      }
    }
    
    // 3. Если всё ещё не нашли, ищем ВСЕ активные офферы и фильтруем
    if (activeOffers.length === 0) {
      const { data: allActiveOffers, error: allError } = await supabase
        .from('offers')
        .select('*')
        .eq('status', 'pending');
      
      if (allError) {
        console.error('❌ Ошибка получения всех офферов:', allError);
        return false;
      }
      
      console.log(`📊 Все активные офферы в базе: ${allActiveOffers?.length || 0}`);
      
      // Фильтруем офферы вручную по содержимому nft_data
      activeOffers = (allActiveOffers || []).filter(offer => {
        try {
          const nftData = typeof offer.nft_data === 'string' 
            ? JSON.parse(offer.nft_data) 
            : offer.nft_data;
          
          const marketItemNft = typeof marketItem?.nft_object === 'string'
            ? JSON.parse(marketItem.nft_object)
            : marketItem?.nft_object;
          
          // Сравниваем по gift_id
          if (nftData?.gift_id && marketItemNft?.gift_id) {
            return nftData.gift_id === marketItemNft.gift_id;
          }
          
          // Или по имени
          if (nftData?.name && marketItemNft?.name) {
            return nftData.name === marketItemNft.name;
          }
          
          return false;
        } catch (e) {
          return false;
        }
      });
      
      console.log(`✅ Найдено ${activeOffers.length} офферов по содержимому nft_data`);
    }
    
    // ВОЗВРАЩАЕМ СРЕДСТВА И УДАЛЯЕМ ОФФЕРЫ
    let refundSuccess = true;
    
    for (const offer of activeOffers) {
      try {
        // Получаем данные покупателя
        const { data: buyerData } = await supabase
          .from('users')
          .select('ton_balance, operation_history')
          .eq('name', offer.buyer_name)
          .single();
        
        if (buyerData) {
          const currentBalance = parseFloat(buyerData.ton_balance) || 0;
          const newBalance = currentBalance + parseFloat(offer.offer_price);
          
          // Возвращаем средства
          await supabase
            .from('users')
            .update({ 
              ton_balance: newBalance,
              operation_history: [
                {
                  id: `op_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
                  type: 'refund',
                  amount: offer.offer_price.toString(),
                  timestamp: new Date().toISOString(),
                  reason: cancellationReason
                },
                ...(buyerData.operation_history || [])
              ].slice(0, 100)
            })
            .eq('name', offer.buyer_name);
          
          // 🔥🔥🔥 УДАЛЯЕМ ОФФЕР ИЗ БАЗЫ ДАННЫХ
          await supabase
            .from('offers')
            .delete()
            .eq('id', offer.id);
          
          console.log(`✅ Оффер ${offer.id} удален, возвращено ${offer.offer_price} TON пользователю ${offer.buyer_name}`);
          
          // Удаляем из UI если это текущий пользователь
          if (offer.buyer_name === currentAccountName.value) {
            removeOfferFromUI(offer.id);
          }
        }
      } catch (offerError) {
        console.error(`❌ Ошибка при обработке оффера ${offer.id}:`, offerError);
        refundSuccess = false;
      }
    }
    
    return refundSuccess;
    
  } catch (error) {
    console.error('❌ Критическая ошибка в refundAllPendingOffersForItem:', error);
    return false;
  }
};

