// 4. Улучшенная функция загрузки всех данных для фильтрации
const loadAllDataForFiltering = async () => {
  console.log('📥 ЗАГРУЗКА ВСЕХ ДАННЫХ ДЛЯ ФИЛЬТРАЦИИ');
  
  if (activeTab.value === 'market') {
    console.log('🔍 Загрузка ВСЕХ market данных...');
    
    const { data: allData, error } = await supabase
      .from('market')
      .select('*');
    
    if (error) {
      console.error('❌ Ошибка загрузки market данных:', error);
      return;
    }
    
    allFilterOptions.value.marketItems = allData || [];
    console.log(`✅ Загружено ${allFilterOptions.value.marketItems.length} market объявлений`);
    
  } else if (activeTab.value === 'my-nfts') {
    if (!currentAccountName.value) {
      console.log('❌ Нет имени пользователя');
      return;
    }
    
    console.log('🔍 Загрузка ВСЕХ My Gifts данных...');
    
    // Listed NFT
    const { data: listedData, error: listedError } = await supabase
      .from('market')
      .select('*')
      .eq('seller', currentAccountName.value);
    
    if (listedError) {
      console.error('❌ Ошибка загрузки listed NFT:', listedError);
      return;
    }
    
    // Unlisted NFT
    const { data: userData, error: userError } = await supabase
      .from('users')
      .select('nft_links')
      .eq('name', currentAccountName.value)
      .single();
    
    if (userError) {
      console.error('❌ Ошибка загрузки unlisted NFT:', userError);
      return;
    }
    
    const nftLinks = userData.nft_links || [];
    const unlistedItems = nftLinks.map(nftData => ({
      id: `unlisted-${extractNftIdFromData(nftData)}`,
      item_id: `unlisted-${extractNftIdFromData(nftData)}`,
      nft_type: `html_nft_${extractNftNameFromUrl(nftData.url) || 'unknown'}`,
      nft_object: nftData,
      seller: currentAccountName.value,
      is_unlisted: true,
      price_per_unit: 0,
      currency: 'TON',
      created_at: nftData.acquired_at || new Date().toISOString()
    }));
    
    allFilterOptions.value.myGiftsItems = [...(listedData || []), ...unlistedItems];
    console.log(`✅ Загружено ${allFilterOptions.value.myGiftsItems.length} NFT (listed: ${listedData?.length || 0}, unlisted: ${unlistedItems.length})`);
  }
  else if (activeTab.value === 'activity') {
    console.log('🔍 Загрузка ВСЕХ Activity данных...');
    
    const { data: allData, error } = await supabase
      .from('activity_history')
      .select('*');
    
    if (error) {
      console.error('❌ Ошибка загрузки activity данных:', error);
      return;
    }
    
    allFilterOptions.value.activityItems = allData || [];
    console.log(`✅ Загружено ${allFilterOptions.value.activityItems.length} записей активности`);
    
    // Логируем уникальные символы для отладки
    const uniqueSymbols = new Set();
    allData?.forEach(item => {
      const symbol = extractSymbolFromActivityItem(item);
      if (symbol) uniqueSymbols.add(symbol);
    });
    console.log(`🔤 Уникальные символы в Activity: ${Array.from(uniqueSymbols).join(', ')}`);
  }
};
// 5. ОПТИМИЗИРОВАННАЯ функция toggleFilterOption - быстрая работа с фильтрами
const toggleFilterOption = async (category, option, event) => {
  if (event) {
    event.stopPropagation();
  }
  
  // 1. БЫСТРОЕ ОБНОВЛЕНИЕ ФИЛЬТРОВ без ожидания
  const updateFilters = () => {
    if (!selectedFilters.value[category]) {
      selectedFilters.value[category] = [];
    }
    
    let optionToUse = option;
    
    // Нормализация
    if (category === 'nft') {
      optionToUse = normalizeNftName(option);
    } else if (category === 'symbol') {
      optionToUse = normalizeSymbolName(option);
    } else if (category === 'model') {
      optionToUse = option.toLowerCase().trim();
    }
    // Для Backdrop сохраняем как есть
    
    const currentFilters = [...selectedFilters.value[category]];
    const index = currentFilters.indexOf(optionToUse);
    
    if (index === -1) {
      console.log(`🔍 Добавление фильтра ${category}: "${option}"`);
      currentFilters.push(optionToUse);
    } else {
      console.log(`🗑️ Удаление фильтра ${category}: "${option}"`);
      currentFilters.splice(index, 1);
    }
    
    // Обновляем фильтры
    selectedFilters.value[category] = currentFilters;
    
    // Очищаем зависимые фильтры
    if (category === 'nft' || category === 'model') {
      clearDependentFilters(category);
    }
    
    console.log(`✅ Фильтр ${category} обновлен:`, selectedFilters.value[category]);
  };
  
  // ВЫПОЛНЯЕМ СРАЗУ
  updateFilters();
  
  // 2. АСИНХРОННАЯ загрузка данных ТОЛЬКО если нужно
  const shouldLoadData = () => {
    // Проверяем, есть ли уже данные для текущей вкладки
    const currentTab = activeTab.value;
    
    if (currentTab === 'market') {
      return allFilterOptions.value.marketItems.length === 0;
    } else if (currentTab === 'my-nfts') {
      return allFilterOptions.value.myGiftsItems.length === 0;
    } else if (currentTab === 'activity') {
      return allFilterOptions.value.activityItems.length === 0;
    }
    return false;
  };
  
  // 3. Загружаем данные только при ПЕРВОМ использовании фильтров
  if (shouldLoadData()) {
    console.log('📥 Загружаем данные для фильтрации (первый раз)...');
    
    // Загружаем в ФОНОВОМ режиме, не блокируя UI
    setTimeout(async () => {
      try {
        await loadAllDataForFiltering();
      } catch (error) {
        console.error('❌ Ошибка фоновой загрузки данных:', error);
      }
    }, 0);
  } else {
    console.log('✅ Данные уже загружены, фильтруем мгновенно');
  }
  
  // 4. Убираем лишний nextTick - он не нужен здесь
  // await nextTick(); // УДАЛИТЬ эту строку!
  
  // 5. Форсируем обновление только если действительно нужно
  forceUpdate.value++;
};
