const availableNftOptions = computed(() => {
  const currentTab = activeTab.value;
  
  // Получаем данные в зависимости от активной вкладки
  let dataSource = [];
  
  if (currentTab === 'market') {
    dataSource = allFilterOptions.value.marketItems || [];
  } else if (currentTab === 'my-nfts') {
    dataSource = allFilterOptions.value.myGiftsItems || [];
  } else if (currentTab === 'activity') {
    dataSource = allFilterOptions.value.activityItems || [];
  }
  
  // Если данных нет - возвращаем пустой массив
  if (dataSource.length === 0) {
    console.log(`📊 Нет данных для вкладки ${currentTab}`);
    return [];
  }
  
  const availableNfts = new Set();
  
  dataSource.forEach(item => {
    try {
      let itemName = '';
      
      if (item.nft_object) {
        const nftObject = typeof item.nft_object === 'string' 
          ? JSON.parse(item.nft_object) 
          : item.nft_object;
        
        if (nftObject && nftObject.name && nftObject.name.trim()) {
          itemName = nftObject.name.trim();
        }
      }
      
      if (!itemName) {
        itemName = getNftDisplayName(item.nft_type, item.nft_object);
      }
      
      if (itemName && itemName.trim()) {
        const normalizedItemName = normalizeNftName(itemName);
        if (normalizedItemName && normalizedItemName !== 'unknown') {
          availableNfts.add(itemName);
        }
      }
    } catch (error) {
      console.warn(`⚠️ Ошибка обработки NFT:`, error);
    }
  });
  
  console.log(`📊 Уникальных NFT для вкладки ${currentTab}: ${availableNfts.size}`);
  
  if (availableNfts.size > 0) {
    console.log(`📋 Список NFT для ${currentTab}:`, Array.from(availableNfts).sort());
  }
  
  return Array.from(availableNfts).sort();
});









