// Обновленная функция lazy loading для Activity
const handleActivityScroll = () => {
  const activityList = document.querySelector('.activity-list');
  if (!activityList || pagination.value.isLoading || !pagination.value.hasMore) return;
  
  // Проверяем, достигли ли мы конца списка
  const scrollPosition = activityList.scrollTop + activityList.clientHeight;
  const scrollHeight = activityList.scrollHeight;
  
  // Если близко к концу (100px от конца) - загружаем следующую порцию
  const threshold = 100;
  
  if (scrollHeight - scrollPosition < threshold) {
    console.log('🔽 Достигнут конец списка, загружаем следующую порцию активности...');
    loadMoreActivityWithFilters();
  }
};

// Функция для загрузки следующей порции активности с учетом фильтров
const loadMoreActivityWithFilters = async () => {
  try {
    if (pagination.value.isLoading || !pagination.value.hasMore) {
      return;
    }
    
    pagination.value.isLoading = true;
    
    // Получаем ВСЕ отфильтрованные активности
    const allActivities = allFilterOptions.value.activityItems || [];
    let filtered = [...allActivities];
    
    // Применяем фильтры (та же логика, что и в computed)
    if (showOnlyMyActivity.value && currentAccountName.value) {
      filtered = filtered.filter(activity => 
        activity.user_name === currentAccountName.value
      );
    }
    
    if (selectedActivityType.value && selectedActivityType.value !== 'all') {
      filtered = filtered.filter(
        activity => activity.operation_type === selectedActivityType.value
      );
    }
    
    // Применяем общие фильтры
    const hasCommonFilters = selectedFilters.value.nft.length > 0 || 
                           selectedFilters.value.model.length > 0 || 
                           selectedFilters.value.symbol.length > 0 || 
                           selectedFilters.value.backdrop.length > 0 ||
                           selectedIdFilter.value !== null;
    
    if (hasCommonFilters) {
      filtered = filtered.filter(activity => {
        try {
          const nftObject = typeof activity.nft_object === 'string' 
            ? JSON.parse(activity.nft_object) 
            : activity.nft_object;
          
          if (!nftObject) return false;
          
          // NFT фильтр
          if (selectedFilters.value.nft.length > 0) {
            const itemName = nftObject.name || '';
            const normalizedItemName = normalizeNftName(itemName);
            
            const passesNftFilter = selectedFilters.value.nft.some(selectedNft => {
              const normalizedSelected = normalizeNftName(selectedNft);
              return normalizedItemName.includes(normalizedSelected) || normalizedItemName === normalizedSelected;
            });
            if (!passesNftFilter) return false;
          }
          
          // Model фильтр
          if (selectedFilters.value.model.length > 0) {
            const itemModel = nftObject.model || '';
            if (!itemModel) return false;
            
            const cleanItemModel = itemModel.split(' ')[0].toLowerCase().trim();
            const passesModelFilter = selectedFilters.value.model.some(selectedModel => {
              const cleanSelectedModel = selectedModel.toLowerCase().trim();
              return cleanItemModel === cleanSelectedModel || cleanItemModel.includes(cleanSelectedModel);
            });
            if (!passesModelFilter) return false;
          }
          
          // Symbol фильтр
          if (selectedFilters.value.symbol.length > 0) {
            const itemSymbol = nftObject.symbol || '';
            if (!itemSymbol) return false;
            
            const normalizedItemSymbol = normalizeSymbolName(itemSymbol);
            const passesSymbolFilter = selectedFilters.value.symbol.some(selectedSymbol => {
              const normalizedSelectedSymbol = normalizeSymbolName(selectedSymbol);
              return normalizedItemSymbol === normalizedSelectedSymbol;
            });
            if (!passesSymbolFilter) return false;
          }
          
          // Backdrop фильтр
          if (selectedFilters.value.backdrop.length > 0) {
            const itemBackdrop = nftObject.backdrop || '';
            if (!itemBackdrop) return false;
            
            const cleanItemBackdrop = itemBackdrop.split(' ')[0].toLowerCase().trim();
            const passesBackdropFilter = selectedFilters.value.backdrop.some(selectedBackdrop => {
              const cleanSelectedBackdrop = selectedBackdrop.split(' ')[0].toLowerCase().trim();
              return cleanItemBackdrop === cleanSelectedBackdrop;
            });
            if (!passesBackdropFilter) return false;
          }
          
          return true;
        } catch (error) {
          return false;
        }
      });
    }
    
    // Сортируем по дате
    filtered.sort((a, b) => {
      const dateA = a.created_at ? new Date(a.created_at) : new Date(0);
      const dateB = b.created_at ? new Date(b.created_at) : new Date(0);
      return dateB - dateA;
    });
    
    // Берем следующую порцию данных
    const startIndex = displayedActivity.value.length;
    const endIndex = Math.min(startIndex + pagination.value.limit, filtered.length);
    const nextBatch = filtered.slice(startIndex, endIndex);
    
    // Добавляем к отображаемым данным
    displayedActivity.value = [...displayedActivity.value, ...nextBatch];
    
    // Обновляем состояние пагинации
    pagination.value.hasMore = endIndex < filtered.length;
    
    console.log(`✅ Загружено ${nextBatch.length} активностей, всего отображается ${displayedActivity.value.length}`);
    
  } catch (error) {
    console.error('❌ Ошибка при подгрузке активности:', error);
  } finally {
    pagination.value.isLoading = false;
  }
};
