// Добавьте после других переменных состояния
const sellerLanguage = ref('en'); // По умолчанию английский

// ========== ФУНКЦИЯ ДЛЯ ПРИНЯТИЯ ОФФЕРА (acceptOffer) ==========
// Добавьте эту функцию в ваш код, если её нет

// ========== ФУНКЦИЯ ДЛЯ ПРИНЯТИЯ ОФФЕРА (acceptOffer) ==========
const acceptOffer = async (offerId) => {
  try {
    console.log('🚀 =========== НАЧАЛО acceptOffer ===========');
    
    // === ПРОВЕРКА 1: Загрузка комиссии ===
    if (platformFee.value === null) {
      console.log('⏳ Комиссия не загружена, загружаем из БД...');
      await loadPlatformFee();
      
      if (platformFee.value === null) {
        showNotification('Ошибка: не удалось загрузить комиссию из таблицы configurations', 'error');
        return;
      }
    }
    
    // Получаем данные оффера
    const { data: offer, error: offerError } = await supabase
      .from('offers')
      .select('*')
      .eq('id', offerId)
      .single();
    
    if (offerError || !offer) {
      console.error('❌ Оффер не найден:', offerError);
      showNotification('Offer not found', 'error');
      return;
    }
    
    // Проверяем, что текущий пользователь - продавец
    if (offer.seller_name !== currentAccountName.value) {
      console.error('❌ Вы не являетесь продавцом этого товара');
      showNotification('You are not the seller of this item', 'error');
      return;
    }
    
    // Проверяем, что оффер еще активен
    if (offer.status !== 'pending') {
      console.error('❌ Оффер уже не активен');
      showNotification('This offer is no longer active', 'error');
      return;
    }
    
    // Получаем данные товара из market
    const { data: marketItem, error: marketError } = await supabase
      .from('market')
      .select('*')
      .eq('id', offer.item_id)
      .single();
    
    if (marketError || !marketItem) {
      console.error('❌ Товар не найден на рынке:', marketError);
      showNotification('Item not found on market', 'error');
      return;
    }
    
    // Проверяем, что товар все еще принадлежит продавцу
    if (marketItem.seller !== currentAccountName.value) {
      console.error('❌ Товар больше не принадлежит вам');
      showNotification('You no longer own this item', 'error');
      return;
    }
    
    // === РАСЧЕТ КОМИССИИ ===
    const totalPrice = offer.offer_price;
    const currentFee = platformFee.value;
    const feePercent = currentFee / 100;
    const commissionAmount = totalPrice * feePercent;
    const sellerReceives = totalPrice - commissionAmount;
    
    console.log(`💰 Комиссия за оффер: ${currentFee}% от ${totalPrice} TON = ${commissionAmount.toFixed(3)} TON`);
    console.log(`💵 Продавец получит: ${sellerReceives.toFixed(3)} TON`);

    // Получаем данные продавца (текущего пользователя) для обновления истории
    const { data: sellerUserData, error: sellerUserError } = await supabase
      .from('users')
      .select('ton_balance, operation_history')
      .eq('name', currentAccountName.value)
      .single();

    if (sellerUserError) {
      console.error('❌ Ошибка получения данных продавца:', sellerUserError);
      return;
    }

    // Получаем данные покупателя для записи в историю
    const { data: buyerUserData, error: buyerUserError } = await supabase
      .from('users')
      .select('username, telegram')
      .eq('name', offer.buyer_name)
      .single();

    if (buyerUserError) {
      console.warn('⚠️ Не удалось получить данные покупателя:', buyerUserError);
    }

    // Формируем ссылку на изображение
    let imageLink = null;
    if (marketItem.nft_object && marketItem.nft_object.url) {
      imageLink = marketItem.nft_object.url;
    } else if (marketItem.url) {
      imageLink = marketItem.url;
    } else {
      const nftName = getNftDisplayName(marketItem.nft_type, marketItem.nft_object);
      const nftId = extractNftIdFromData(marketItem.nft_object) || 'unknown';
      imageLink = `https://nft.fragment.com/gift/${nftName.replace(/\s+/g, '')}-${nftId}.webp`;
    }

    // === ДОБАВЛЯЕМ ЗАПИСЬ ОПЕРАЦИИ В ИСТОРИЮ ПРОДАВЦА ===
    const saleOperation = {
      id: `op_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
      type: 'offer_sale',
      amount: sellerReceives.toString(),
      commission: commissionAmount.toString(),
      timestamp: new Date().toISOString(),
      walletAddress: currentAccountName.value,
      currency: 'TON',
      buyer: offer.buyer_name,
      buyer_username: buyerUserData?.username || offer.buyer_name,
      offerId: offerId,
      nftName: getNftDisplayName(marketItem.nft_type, marketItem.nft_object),
      nftId: extractNftIdFromData(marketItem.nft_object) || 'unknown',
      link: imageLink
    };

    const sellerCurrentHistory = sellerUserData.operation_history || [];
    const updatedSellerHistory = [saleOperation, ...sellerCurrentHistory].slice(0, 100);
    
    // === ДОБАВЛЯЕМ ЗАПИСЬ ОПЕРАЦИИ В ИСТОРИЮ ПОКУПАТЕЛЯ (ОПЦИОНАЛЬНО) ===
    let updatedBuyerHistory = null;
    if (buyerUserData) {
      const purchaseOperation = {
        id: `op_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
        type: 'offer_purchase',
        amount: totalPrice.toString(),
        commission: commissionAmount.toString(),
        timestamp: new Date().toISOString(),
        walletAddress: offer.buyer_name,
        currency: 'TON',
        seller: currentAccountName.value,
        seller_username: currentAccountName.value,
        offerId: offerId,
        nftName: getNftDisplayName(marketItem.nft_type, marketItem.nft_object),
        nftId: extractNftIdFromData(marketItem.nft_object) || 'unknown',
        link: imageLink
      };

      const { data: buyerHistoryData } = await supabase
        .from('users')
        .select('operation_history')
        .eq('name', offer.buyer_name)
        .single();

      if (buyerHistoryData) {
        const buyerCurrentHistory = buyerHistoryData.operation_history || [];
        updatedBuyerHistory = [purchaseOperation, ...buyerCurrentHistory].slice(0, 100);
      }
    }
    
    // === ДОБАВЛЯЕМ ЗАПИСЬ КОМИССИИ В ТАБЛИЦУ CONFIGURATIONS ===
    await updateConfigurationsStats(commissionAmount, 'offer_acceptance_commission');
    
    // МГНОВЕННО УДАЛЯЕМ ИЗ UI
    console.log('🗑️ МГНОВЕННО удаляем объявление из UI...');
    
    const itemIndex = marketItems.value.findIndex(item => item.id === marketItem.id);
    if (itemIndex !== -1) {
      marketItems.value.splice(itemIndex, 1);
    }
    
    const paginationIndex = marketPagination.value.allItems.findIndex(item => item.id === marketItem.id);
    if (paginationIndex !== -1) {
      marketPagination.value.allItems.splice(paginationIndex, 1);
    }
    
    if (allFilterOptions.value.marketItems) {
      const filterIndex = allFilterOptions.value.marketItems.findIndex(item => item.id === marketItem.id);
      if (filterIndex !== -1) {
        allFilterOptions.value.marketItems.splice(filterIndex, 1);
      }
    }
    
    console.log('✅ Объявление удалено из UI');

    // ПОКАЗЫВАЕМ АНИМАЦИЮ УСПЕХА
    showSuccessAnimation('offer_accepted');
    showNotification('Offer accepted successfully!', 'success');

    // ОПЕРАЦИИ С БД В ФОНЕ
    setTimeout(async () => {
      try {
        console.log('🚀 =========== ФОН: acceptOffer (операции с БД) ===========');
        
        // Получаем данные покупателя
        const { data: buyerData, error: buyerError } = await supabase
          .from('users')
          .select('ton_balance, operation_history, username, telegram, nft_links, score')
          .eq('name', offer.buyer_name)
          .single();
        
        if (buyerError || !buyerData) {
          console.error('❌ Покупатель не найден');
          return;
        }
        
        // Получаем данные продавца
        const { data: sellerData, error: sellerError } = await supabase
          .from('users')
          .select('ton_balance, operation_history, score')
          .eq('name', currentAccountName.value)
          .single();
        
        if (sellerError || !sellerData) {
          console.error('❌ Продавец не найден');
          return;
        }
        
        // === НАЧИСЛЕНИЕ SCORE ПОКУПАТЕЛЮ (за покупку) ===
        const buyerScoreToAdd = Math.floor(totalPrice * 100);
        const buyerCurrentScore = parseInt(buyerData.score) || 0;
        const buyerNewScore = buyerCurrentScore + buyerScoreToAdd;
        
        console.log(`🎯 Начисление очков покупателю: ${totalPrice} TON → ${buyerScoreToAdd} очков (было: ${buyerCurrentScore}, стало: ${buyerNewScore})`);
        
        // === НАЧИСЛЕНИЕ SCORE ПРОДАВЦУ (за продажу) ===
        const sellerScoreToAdd = Math.floor(totalPrice * 50);
        const sellerCurrentScore = parseInt(sellerData.score) || 0;
        const sellerNewScore = sellerCurrentScore + sellerScoreToAdd;
        
        console.log(`🎯 Начисление очков продавцу: ${totalPrice} TON → ${sellerScoreToAdd} очков (было: ${sellerCurrentScore}, стало: ${sellerNewScore})`);
        
        // Подготавливаем данные NFT для покупателя
        const nftData = {
          url: marketItem.nft_object?.url || '',
          name: getNftDisplayName(marketItem.nft_type, marketItem.nft_object),
          model: marketItem.nft_object?.model || '',
          symbol: marketItem.nft_object?.symbol || '',
          backdrop: marketItem.nft_object?.backdrop || '',
          gift_id: marketItem.nft_object?.gift_id || 0,
          from_user: buyerData.username ? `@${buyerData.username}` : `@${offer.buyer_name}`,
          user_name: buyerData.telegram ? buyerData.telegram.toString() : offer.buyer_name,
          acquired_at: new Date().toISOString()
        };
        
        // Обновляем баланс продавца
        const sellerCurrentBalance = parseFloat(sellerData.ton_balance) || 0;
        const sellerNewBalance = sellerCurrentBalance + sellerReceives;
        
        // Записываем операции
        const purchaseOperation = {
          id: `op_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
          type: 'purchase_from_offer',
          amount: totalPrice.toString(),
          commission: commissionAmount.toString(),
          timestamp: new Date().toISOString(),
          walletAddress: offer.buyer_name,
          currency: 'TON',
          itemId: marketItem.id,
          offerId: offer.id,
          scoreEarned: buyerScoreToAdd,
          link: imageLink
        };
        
        // Обновляем истории
        const buyerHistory = buyerData.operation_history || [];
        const updatedBuyerHistory = [purchaseOperation, ...buyerHistory].slice(0, 100);
        
        // Получаем текущие NFT покупателя
        const currentLinks = buyerData.nft_links || [];
        const updatedLinks = [...currentLinks, nftData];
        
        // ПАРАЛЛЕЛЬНЫЕ ОПЕРАЦИИ С БД
        const operations = [
          // Обновляем данные покупателя
          supabase
            .from('users')
            .update({ 
              nft_links: updatedLinks,
              operation_history: updatedBuyerHistory,
              score: buyerNewScore
            })
            .eq('name', offer.buyer_name),
          
          // Обновляем данные продавца (баланс и историю)
          supabase
            .from('users')
            .update({ 
              ton_balance: sellerNewBalance,
              operation_history: updatedSellerHistory,
              score: sellerNewScore
            })
            .eq('name', currentAccountName.value),
          
          // Удаляем товар с рынка
          supabase
            .from('market')
            .delete()
            .eq('id', marketItem.id),
          
          // Обновляем статус оффера
          supabase
            .from('offers')
            .update({ 
              status: 'accepted',
              accepted_at: new Date().toISOString(),
              commission_amount: commissionAmount
            })
            .eq('id', offer.id)
        ];
        
        // Если есть история для покупателя (отдельная операция), обновляем и её
        if (updatedBuyerHistory) {
          operations.push(
            supabase
              .from('users')
              .update({ operation_history: updatedBuyerHistory })
              .eq('name', offer.buyer_name)
          );
        }
        
        await Promise.all(operations);
        
        // Обновляем локальный баланс продавца
        tonBalance.value = sellerNewBalance.toString();
        
        // ЗАПИСЫВАЕМ АКТИВНОСТЬ В activity_history
        console.log('🔍 Записываем активность в activity_history...');
        
        const activityData = {
          user_name: offer.buyer_name,
          operation_type: 'purchase',
          item_id: marketItem.item_id || marketItem.id,
          nft_type: marketItem.nft_type,
          nft_object: marketItem.nft_object,
          price_per_unit: totalPrice,
          currency: 'TON',
          amount: 1,
          total_price: totalPrice,
          counterparty: currentAccountName.value,
          commission: commissionAmount,
          created_at: new Date().toISOString(),
          offer_id: offer.id,
          score_earned: buyerScoreToAdd
        };
        
        const { error: activityError } = await supabase
          .from('activity_history')
          .insert([activityData]);
        
        if (activityError) {
          console.error('❌ Ошибка записи в activity_history:', activityError);
        } else {
          console.log('✅ Активность успешно записана');
        }
        
        console.log(`🎉 Оффер принят! Покупателю начислено ${buyerScoreToAdd} очков, продавцу начислено ${sellerScoreToAdd} очков`);
        console.log(`💰 Комиссия ${commissionAmount.toFixed(3)} TON записана в configurations`);
        console.log('📝 Операция продавца записана в историю:', saleOperation);
        if (updatedBuyerHistory) {
          console.log('📝 Операция покупателя записана в историю');
        }
        console.log('🏁 =========== КОНЕЦ acceptOffer ===========');
        
      } catch (error) {
        console.error('❌ Ошибка в фоне при принятии оффера:', error);
        showNotification(`Background error: ${error.message}`, 'error');
      }
    }, 10);
    
  } catch (error) {
    console.error('❌ Ошибка при принятии оффера:', error);
    showNotification(`Error accepting offer: ${error.message}`, 'error');
  }
};
