// Функция для создания уникального ключа NFT
const createNftUniqueKey = (nftData) => {
  try {
    if (!nftData) return null;
    
    const nftObj = typeof nftData === 'object' ? nftData : { url: nftData };
    
    // Приоритет 1: gift_id
    if (nftObj.gift_id) {
      return `gift_${nftObj.gift_id}`;
    }
    
    // Приоритет 2: ID из URL
    if (nftObj.url) {
      const urlMatch = nftObj.url.match(/-(\d+)(?:\?|$)/);
      if (urlMatch && urlMatch[1]) {
        return `url_${urlMatch[1]}`;
      }
    }
    
    // Приоритет 3: полный URL
    if (nftObj.url) {
      return `full_${nftObj.url}`;
    }
    
    return null;
  } catch (error) {
    console.error('❌ Error creating NFT unique key:', error);
    return null;
  }
};

// Функция для проверки и удаления дубликатов из базы данных
const removeDuplicatesFromDatabase = async () => {
  try {
    console.log('🔍 Проверка дубликатов в базе данных...');
    
    if (!currentAccountName.value) {
      console.log('❌ Нет текущего пользователя');
      return 0;
    }
    
    // Получаем текущие nft_links пользователя
    const { data: userData, error } = await supabase
      .from('users')
      .select('nft_links')
      .eq('name', currentAccountName.value)
      .single();
    
    if (error || !userData) {
      console.error('❌ Ошибка получения данных пользователя:', error);
      return 0;
    }
    
    const nftLinks = userData.nft_links || [];
    
    if (nftLinks.length === 0) {
      console.log('✅ Нет NFT для проверки');
      return 0;
    }
    
    // Создаем карту уникальных NFT
    const uniqueMap = new Map();
    const duplicates = [];
    
    nftLinks.forEach((nft, index) => {
      const key = createNftUniqueKey(nft);
      if (!key) return;
      
      if (uniqueMap.has(key)) {
        duplicates.push({ index, key, nft });
        console.log(`🚫 Найден дубликат NFT с ключом: ${key}`);
      } else {
        uniqueMap.set(key, nft);
      }
    });
    
    if (duplicates.length === 0) {
      console.log('✅ Дубликаты не найдены');
      return 0;
    }
    
    // Создаем новый массив без дубликатов
    const uniqueNfts = Array.from(uniqueMap.values());
    
    console.log(`📊 Удаляем ${duplicates.length} дубликатов из базы данных...`);
    
    // Обновляем базу данных
    const { error: updateError } = await supabase
      .from('users')
      .update({ 
        nft_links: uniqueNfts,
        updated_at: new Date().toISOString()
      })
      .eq('name', currentAccountName.value);
    
    if (updateError) {
      console.error('❌ Ошибка обновления базы данных:', updateError);
      return 0;
    }
    
    console.log(`✅ Успешно удалено ${duplicates.length} дубликатов из базы данных`);
    
    // Обновляем локальные данные
    myUnlistedNfts.value = uniqueNfts;
    
    // Обновляем myGiftsPagination.allItems
    if (myGiftsPagination.value.allItems.length > 0) {
      const uniqueItems = [];
      const seenItemKeys = new Set();
      
      myGiftsPagination.value.allItems.forEach(item => {
        if (item.is_unlisted) {
          const itemKey = createNftUniqueKey(item.nft_object || item);
          if (itemKey && !seenItemKeys.has(itemKey)) {
            seenItemKeys.add(itemKey);
            uniqueItems.push(item);
          }
        } else {
          uniqueItems.push(item);
        }
      });
      
      myGiftsPagination.value.allItems = uniqueItems;
    }
    
    // Принудительно обновляем интерфейс
    forceUpdate.value++;
    
    return duplicates.length;
    
  } catch (error) {
    console.error('❌ Ошибка при удалении дубликатов из базы:', error);
    return 0;
  }
};

// Функция для удаления дубликатов из массива NFT
const removeDuplicatesFromArray = (nftArray) => {
  if (!nftArray || !Array.isArray(nftArray)) return [];
  
  const uniqueMap = new Map();
  const duplicates = [];
  
  nftArray.forEach((nft, index) => {
    const key = createNftUniqueKey(nft);
    if (!key) return;
    
    if (uniqueMap.has(key)) {
      duplicates.push({ index, key, nft });
      console.log(`🚫 Найден дубликат NFT с ключом: ${key}`);
    } else {
      uniqueMap.set(key, nft);
    }
  });
  
  if (duplicates.length > 0) {
    console.log(`🗑️ Найдено ${duplicates.length} дубликатов, оставляем только уникальные`);
  }
  
  return Array.from(uniqueMap.values());
};



// Функция для проверки и удаления дубликатов при загрузке
const ensureNoDuplicatesInUnlisted = async (nftArray) => {
  if (!nftArray || !Array.isArray(nftArray)) return [];
  
  const uniqueMap = new Map();
  const duplicates = [];
  
  nftArray.forEach((nft, index) => {
    const key = createNftUniqueKey(nft);
    if (!key) return;
    
    if (uniqueMap.has(key)) {
      duplicates.push({ index, key, nft });
      console.log(`🚫 Обнаружен дубликат NFT с ключом: ${key}`);
    } else {
      uniqueMap.set(key, nft);
    }
  });
  
  if (duplicates.length > 0) {
    console.log(`⚠️ Найдено ${duplicates.length} дубликатов, они будут удалены`);
    
    // Если есть дубликаты, немедленно удаляем их из базы данных
    await removeDuplicatesFromDatabase();
    
    // Возвращаем только уникальные NFT
    return Array.from(uniqueMap.values());
  }
  
  return nftArray;
};

