// Функция для извлечения имени символа БЕЗ процента
// Пример: "Handset 0.5%" → "Handset"
const getSymbolNameWithoutPercentage = (symbolName) => {
  if (!symbolName) return '';
  // Убираем процент и число перед ним
  return symbolName.replace(/\s*\d+\.?\d*%\s*$/, '').trim();
};

// Функция для извлечения процента из названия символа
// Пример: "Handset 0.5%" → "0.5%"
const getPercentageFromSymbolName = (symbolName) => {
  if (!symbolName) return '';
  const match = symbolName.match(/(\d+\.?\d*)%$/);
  return match ? `${match[1]}%` : '';
};

// Функции для получения выбранных и невыбранных символов с правильной сортировкой
const getSelectedSymbolOptions = () => {
  return getFilteredSymbols()
    .filter(symbol => isOptionSelected('symbol', symbol.name))
    .sort((a, b) => {
      // На Market сортируем по цене
      if (activeTab.value === 'market') {
        return (b.floorPrice || 0) - (a.floorPrice || 0);
      }
      // На других вкладках - по алфавиту
      return a.name.localeCompare(b.name);
    });
};

const getFilteredSymbols = () => {
  const allSymbols = getAvailableSymbolOptions();
  const query = searchQuery.value.toLowerCase().trim();
  
  if (!query) {
    // Если нет поискового запроса, возвращаем все символы
    return allSymbols.sort((a, b) => {
      const aSelected = isOptionSelected('symbol', a.name);
      const bSelected = isOptionSelected('symbol', b.name);
      
      // Выбранные сверху
      if (aSelected && !bSelected) return -1;
      if (!aSelected && bSelected) return 1;
      
      // На вкладке Market сортируем по цене
      if (activeTab.value === 'market') {
        const aPrice = a.floorPrice || 0;
        const bPrice = b.floorPrice || 0;
        if (aPrice !== bPrice) {
          return bPrice - aPrice; // от большей к меньшей
        }
      }
      
      // По алфавиту
      return a.name.localeCompare(b.name);
    });
  }
  
  // Фильтруем по поисковому запросу
  const filtered = allSymbols.filter(symbol => {
    return symbol.name.toLowerCase().includes(query) || 
           symbol.normalized?.toLowerCase().includes(query);
  });
  
  // Сортируем аналогично
  return filtered.sort((a, b) => {
    const aSelected = isOptionSelected('symbol', a.name);
    const bSelected = isOptionSelected('symbol', b.name);
    
    if (aSelected && !bSelected) return -1;
    if (!aSelected && bSelected) return 1;
    
    // На вкладке Market сортируем по цене
    if (activeTab.value === 'market') {
      const aPrice = a.floorPrice || 0;
      const bPrice = b.floorPrice || 0;
      if (aPrice !== bPrice) {
        return bPrice - aPrice;
      }
    }
    
    return a.name.localeCompare(b.name);
  });
};

const loadSymbolOptions = async () => {
  console.log('🚀 ЗАПУСК loadSymbolOptions для вкладки:', activeTab.value);
  
  try {
    symbolsLoading.value = true;
    
    // Создаем тестовые символы
    const testSymbols = [
      { name: 'Handset' },
      { name: 'Obon Lantern' },
      { name: 'Strawberry' },
      { name: 'Venetian Mask' },
      { name: 'Heart' },
      { name: 'Star' },
      { name: 'Moon' },
      { name: 'Sun' }
    ];
    
    // Для Market всегда генерируем floorPrice
    // Для My Gifts тоже можно показывать цену, если нужно
    const shouldShowPrice = activeTab.value === 'market'; // или activeTab.value !== 'activity'
    
    // Генерируем данные для символов
    const processedSymbols = testSymbols.map((symbol, index) => {
      // Генерируем HTML для символа
      const htmlContent = generateSimpleSymbolHtml(symbol.name) || 
                        createSimpleHtml(symbol.name);
      
      // Всегда генерируем floorPrice (для тестирования)
      // В реальном приложении это должно загружаться из API
      const floorPrice = shouldShowPrice ? 
        parseFloat((Math.random() * 5 + 0.5).toFixed(1)) : 
        null;
      
      // Количество для разных вкладок
      let count = 0;
      if (activeTab.value === 'market') {
        count = Math.floor(Math.random() * 50) + 5; // Для Market
      } else if (activeTab.value === 'my-nfts') {
        count = Math.floor(Math.random() * 10) + 1; // Для My Gifts
      }
      // Для Activity оставляем 0
      
      return {
        id: index + 1,
        name: symbol.name,
        value: symbol.name.toLowerCase().replace(/\s+/g, '_'),
        htmlContent: htmlContent,
        count: count,
        floorPrice: floorPrice, // Всегда есть значение (null или число)
        rarityClass: 'common',
        rarityText: 'Common',
        imageUrl: null,
        normalized: symbol.name.toLowerCase().replace(/\s+/g, '_'),
        percentage: `${(Math.random() * 15 + 1).toFixed(1)}%` // Процент редкости
      };
    });
    
    console.log('🎯 Символы загружены:', processedSymbols.map(s => ({
      name: s.name,
      floorPrice: s.floorPrice,
      hasPrice: s.floorPrice !== null && s.floorPrice !== undefined,
      count: s.count,
      tab: activeTab.value
    })));
    
    // Сохраняем символы
    symbolOptions.value = processedSymbols;
    
    // Принудительное обновление
    triggerForceUpdate();
    
    console.log(`✅ Загружено ${processedSymbols.length} символов, floorPrice для Market: ${shouldShowPrice}`);
    
  } catch (error) {
    console.error('❌ Ошибка загрузки символов:', error);
    
    // Fallback с минимальными данными
    const fallbackSymbols = [
      {
        id: 1,
        name: 'Handset',
        value: 'handset',
        htmlContent: createSimpleHtml('Handset'),
        count: activeTab.value === 'market' ? 10 : 0,
        floorPrice: activeTab.value === 'market' ? 2.5 : null,
        rarityClass: 'common',
        rarityText: 'Common',
        normalized: 'handset',
        percentage: '12.5%'
      }
    ];
    
    symbolOptions.value = fallbackSymbols;
    triggerForceUpdate();
    
  } finally {
    symbolsLoading.value = false;
    console.log('🏁 loadSymbolOptions завершен');
  }
};

// Вспомогательная функция для создания простого HTML
const createSimpleHtml = (symbolName) => {
  return `
    <!DOCTYPE html>
    <html>
    <head>
      <style>
        body, html {
          margin: 0;
          padding: 0;
          width: 100%;
          height: 100%;
          display: flex;
          align-items: center;
          justify-content: center;
          background: transparent;
          font-family: Arial, sans-serif;
        }
        .symbol-container {
          width: 40px;
          height: 40px;
          border-radius: 8px;
          background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
