const getModelsForNftSortedByRarity = (nftType) => {
  try {
    console.group(`🔍 Получение моделей для NFT: ${nftType}`);
    
    if (!nftModelsCache.value[nftType]) {
      console.log('❌ Нет моделей в кэше');
      console.groupEnd();
      return [];
    }
    
    console.log('📋 Модели в кэше:', nftModelsCache.value[nftType]);
    
    const searchQuery = modelSearchQuery.value.toLowerCase().trim();
    const modelsData = [];
    
    nftModelsCache.value[nftType].forEach((modelString, index) => {
      console.log(`📝 Обработка модели ${index + 1}:`, modelString);
      
      const parts = modelString.split(' — ');
      if (parts.length === 2) {
        const name = parts[0].trim();
        const rarityText = parts[1].trim();
        
        // Пытаемся распарсить как процент
        const percentageMatch = rarityText.match(/(\d+\.?\d*)%/);
        let rarity = percentageMatch ? parseFloat(percentageMatch[1]) : null;
        let displayRarityText = rarityText;
        let rarityClass = '';
        
        // Если это не процент, а текстовая редкость
        if (rarity === null) {
          const lowerRarity = rarityText.toLowerCase();
          
          // Определяем класс и отображаемый текст на основе текстовой редкости
          if (lowerRarity.includes('legendary')) {
            rarity = 1; // Присваиваем числовое значение для сортировки (1 - самая редкая)
            displayRarityText = 'Legendary';
            rarityClass = 'legendary';
          } else if (lowerRarity.includes('epic')) {
            rarity = 2;
            displayRarityText = 'Epic';
            rarityClass = 'epic';
          } else if (lowerRarity.includes('rare')) {
            rarity = 3;
            displayRarityText = 'Rare';
            rarityClass = 'rare';
          } else if (lowerRarity.includes('uncommon')) {
            rarity = 4;
            displayRarityText = 'Uncommon';
            rarityClass = 'uncommon';
          } else if (lowerRarity.includes('common')) {
            rarity = 5;
            displayRarityText = 'Common';
            rarityClass = 'common';
          } else {
            // Если не удалось определить, оставляем как есть
            rarity = 999;
            displayRarityText = rarityText;
            rarityClass = 'unknown';
          }
        } else {
          // Если это процент, используем его как есть
          displayRarityText = `${rarity}%`;
          // Определяем класс на основе процента
          if (rarity < 1) rarityClass = 'legendary';
          else if (rarity < 5) rarityClass = 'epic';
          else if (rarity < 15) rarityClass = 'rare';
          else if (rarity < 30) rarityClass = 'uncommon';
          else rarityClass = 'common';
        }
        
        console.log('🔤 Название модели:', name);
        console.log('📊 Редкость (оригинал):', rarityText);
        console.log('📊 Редкость (отображение):', displayRarityText);
        console.log('📊 Редкость (число для сортировки):', rarity);
        console.log('📊 Класс редкости:', rarityClass);
        
        // Фильтрация по поисковому запросу
        const matchesSearch = searchQuery === '' || 
                            name.toLowerCase().includes(searchQuery) ||
                            rarityText.toLowerCase().includes(searchQuery);
        
        console.log('🔍 Соответствует поиску:', matchesSearch);
        
        if (name && rarity !== null && matchesSearch) {
          // Генерируем URL изображения
          const imageUrl = getModelImageUrl(nftType, name);
          
          modelsData.push({
            name,
            rarity, // Числовое значение для сортировки
            rarityText: displayRarityText, // Отображаемый текст редкости
            originalRarity: rarityText, // Оригинальный текст редкости
            rarityClass, // Класс для стилизации
            parentNft: nftType,
            imageUrl: imageUrl,
            isSelected: isOptionSelected('model', name),
            displayName: getNftDisplayNameForGroup(nftType),
            floorPrice: getFloorPrice('model', name)
          });
          
          console.log('✅ Модель добавлена:', name);
        }
      } else {
        console.log('⚠️ Неправильный формат модели:', modelString);
      }
    });
    
    // СОРТИРОВКА: сначала выбранные, затем по редкости (меньше число = реже)
    modelsData.sort((a, b) => {
      if (a.isSelected && !b.isSelected) return -1;
      if (!a.isSelected && b.isSelected) return 1;
      return a.rarity - b.rarity;
    });
    
    console.log(`📊 Итоговое количество моделей: ${modelsData.length}`);
    console.log('📋 Данные моделей:', modelsData.map(m => ({
      name: m.name,
      rarityText: m.rarityText,
      rarityClass: m.rarityClass,
      isSelected: m.isSelected
    })));
    console.groupEnd();
    
    return modelsData;
    
  } catch (error) {
    console.error(`❌ Ошибка получения моделей для ${nftType}:`, error);
    console.groupEnd();
    return [];
  }
};

