const extractModelRarity = (item) => {
  if (!item.nft_object) return 0;
  try {
    const model = JSON.parse(item.nft_object).model;
    const match = model.match(/(\d+\.?\d*)%/);
    return match ? parseFloat(match[1]) : 0;
  } catch {
    return 0;
  }
};

