// Состояние свайпа
const swipeState = ref({
  isSwiping: false,
  startY: 0,
  currentY: 0,
  threshold: 1, // КРИТИЧЕСКИ МАЛЕНЬКИЙ ПОРОГ - всего 5px!
  velocity: 0,
  lastY: 0,
  lastTime: 0
});

// Начало свайпа
const startSwipe = (e) => {
  // Проверяем, что касание в верхней области (первые 150px)
  const rect = e.target.getBoundingClientRect();
  const clientY = e.type.includes('touch') ? e.touches[0].clientY : e.clientY;
  const relativeY = clientY - rect.top;
  
  // Если коснулись в зоне handle
  if (relativeY < 150) {
    e.preventDefault();
    e.stopPropagation(); // Останавливаем всплытие
    
    swipeState.value = {
      isSwiping: true,
      startY: clientY,
      currentY: 0,
      threshold: 1, // 5 ПИКСЕЛЕЙ - микро-движение!
      velocity: 0,
      lastY: clientY,
      lastTime: Date.now()
    };
    
    // Визуальная обратная связь
    const menu = e.target.closest('.filter-dropdown-menu-nft, .filter-dropdown-menu-model, .filter-dropdown-menu-backdrop, .filter-dropdown-menu-add-gift');
    if (menu) {
      menu.classList.add('dragging');
    }
    
    document.addEventListener('mousemove', handleSwipeMove);
    document.addEventListener('mouseup', stopSwipe);
    document.addEventListener('touchmove', handleSwipeMove, { passive: false });
    document.addEventListener('touchend', stopSwipe);
  }
};

// Обработка движения
const handleSwipeMove = (e) => {
  if (!swipeState.value.isSwiping) return;
  
  e.preventDefault();
  e.stopPropagation();
  
  const clientY = e.type.includes('touch') ? e.touches[0].clientY : e.clientY;
  const deltaY = clientY - swipeState.value.startY;
  
  // Рассчитываем скорость
  const now = Date.now();
  const timeDelta = now - swipeState.value.lastTime;
  if (timeDelta > 0) {
    const yDelta = clientY - swipeState.value.lastY;
    swipeState.value.velocity = yDelta / timeDelta;
  }
  
  swipeState.value.lastY = clientY;
  swipeState.value.lastTime = now;
  swipeState.value.currentY = deltaY;
  
  // При любом движении вниз > 0
  if (deltaY > 5) {
    const menu = document.querySelector('.filter-dropdown-menu-nft.dragging, .filter-dropdown-menu-model.dragging, .filter-dropdown-menu-backdrop.dragging, .filter-dropdown-menu-add-gift.dragging');
    if (menu) {
      // Двигаем меню за пальцем
      menu.style.transform = `translateY(${deltaY}px)`;
      
      // МГНОВЕННОЕ ЗАКРЫТИЕ при 5px!
      if (deltaY >= swipeState.value.threshold) {
        closeMenuNow(menu);
      }
    }
  }
};

// МГНОВЕННОЕ закрытие при микро-движении
const closeMenuNow = (menu) => {
  if (!menu) return;
  
  // Убираем обработчики
  swipeState.value.isSwiping = false;
  document.removeEventListener('mousemove', handleSwipeMove);
  document.removeEventListener('mouseup', stopSwipe);
  document.removeEventListener('touchmove', handleSwipeMove);
  document.removeEventListener('touchend', stopSwipe);
  
  // Анимация закрытия - супер быстрая
  menu.style.transition = 'transform 1s ease-out';
  menu.style.transform = 'translateY(100%)';
  
  // Закрываем
  setTimeout(() => {
    closeFilterMenu();
    menu.style.transition = '';
    menu.style.transform = '';
    menu.classList.remove('dragging');
  }, 100);
};

// Завершение свайпа
const stopSwipe = () => {
  if (!swipeState.value.isSwiping) return;
  
  const menu = document.querySelector('.filter-dropdown-menu-nft.dragging, .filter-dropdown-menu-model.dragging, .filter-dropdown-menu-backdrop.dragging, .filter-dropdown-menu-add-gift.dragging');
  
  if (menu) {
    menu.classList.remove('dragging');
    
    // ЛЮБОЕ движение вниз > 2px закрывает меню!
    const distance = swipeState.value.currentY;
    
    if (distance > 0.1) { // Даже 2-3 пикселя достаточно!
      menu.style.transition = 'transform 1s ease-out';
      menu.style.transform = 'translateY(100%)';
      
      setTimeout(() => {
        closeFilterMenu();
        menu.style.transition = '';
        menu.style.transform = '';
      }, 100);
    } else {
      // Возвращаем на место
      menu.style.transition = 'transform 1s ease-out';
      menu.style.transform = '';
      
      setTimeout(() => {
        menu.style.transition = '';
      }, 100);
    }
  }
  
  swipeState.value.isSwiping = false;
  
  document.removeEventListener('mousemove', handleSwipeMove);
  document.removeEventListener('mouseup', stopSwipe);
  document.removeEventListener('touchmove', handleSwipeMove);
  document.removeEventListener('touchend', stopSwipe);
};

// Добавьте в return:
