const loadNftModels = async (nftItemOrName) => {
  try {
    console.log('🔍 loadNftModels called with:', nftItemOrName);
    
    if (!nftItemOrName) {
      console.warn('❌ NFT item/name is empty');
      return [];
    }
    
    // === 1. ОПРЕДЕЛЯЕМ ИМЯ NFT ===
    let normalizedName = '';
    
    if (typeof nftItemOrName === 'string') {
      // Если передана строка (например, "Money Pot", "html_nft_moneypot")
      normalizedName = normalizeNftName(nftItemOrName);
    } else if (typeof nftItemOrName === 'object' && nftItemOrName !== null) {
      // Если передан объект NFT
      normalizedName = normalizeNftName(nftItemOrName.nft_type, nftItemOrName);
    } else {
      console.warn('❌ Invalid input type for loadNftModels');
      return [];
    }
    
    if (!normalizedName) {
      console.warn('❌ Could not normalize NFT name');
      return [];
    }
    
    console.log(`📊 Normalized NFT name: "${normalizedName}"`);
    
    // === 2. ПРОВЕРЯЕМ КЭШ ===
    if (nftModelsCache.value[normalizedName]) {
      console.log(`✅ Found in cache: "${normalizedName}"`);
      return nftModelsCache.value[normalizedName];
    }
    
    // === 3. ПОИСК КОЛОНКИ В БАЗЕ ДАННЫХ ===
    // В таблице nft каждая колонка называется точно как имя NFT
    
    // Основное имя колонки (как normalizeNftName возвращает)
    const dbColumnName = normalizedName;
    const quotedColumnName = `"${dbColumnName}"`;
    
    console.log(`🔍 Query 1: ${quotedColumnName}`);
    
    // Попытка 1: Точное совпадение
    let { data, error } = await supabase
      .from('nft')
      .select(quotedColumnName)
      .not(quotedColumnName, 'is', null)
      .limit(1);
    
    // Если точное совпадение не сработало, пробуем альтернативы
    if (error || !data || data.length === 0) {
      if (error) {
        console.warn(`⚠️ Query 1 failed: ${error.message}`);
      } else {
        console.warn(`⚠️ Query 1 returned no data for "${dbColumnName}"`);
      }
      
      // === ПОПЫТКА 2: Без пробелов ===
      const nameWithoutSpaces = dbColumnName.replace(/\s+/g, '');
      const quotedNoSpaces = `"${nameWithoutSpaces}"`;
      
      console.log(`🔍 Query 2: ${quotedNoSpaces}`);
      
      const result2 = await supabase
        .from('nft')
        .select(quotedNoSpaces)
        .not(quotedNoSpaces, 'is', null)
        .limit(1);
      
      if (result2.error || !result2.data || result2.data.length === 0) {
        if (result2.error) {
          console.warn(`⚠️ Query 2 failed: ${result2.error.message}`);
        }
        
        // === ПОПЫТКА 3: Получаем структуру таблицы и ищем похожие колонки ===
        console.log('🔍 Getting table structure...');
        const { data: tableData, error: tableError } = await supabase
          .from('nft')
          .select('*')
          .limit(1);
        
        if (tableError) {
          console.error('❌ Error getting table structure:', tableError);
          return [];
        }
        
        if (!tableData || tableData.length === 0) {
          console.warn('❌ No data in nft table');
          return [];
        }
        
        const availableColumns = Object.keys(tableData[0]);
        console.log('📋 Available columns:', availableColumns);
        
        // Нормализуем для поиска
        const normalizedSearch = dbColumnName.toLowerCase().replace(/\s+/g, '');
        
        // Ищем похожую колонку
        let similarColumn = null;
        
        // Сначала точное совпадение (без пробелов и регистра)
        for (const column of availableColumns) {
          const normalizedCol = column.toLowerCase().replace(/\s+/g, '');
          if (normalizedCol === normalizedSearch) {
            similarColumn = column;
            console.log(`🎯 Found exact normalized match: "${similarColumn}"`);
            break;
          }
        }
        
        // Если не нашли точное, ищем частичное
        if (!similarColumn) {
          for (const column of availableColumns) {
            const normalizedCol = column.toLowerCase();
            if (normalizedCol.includes(normalizedSearch) || 
                normalizedSearch.includes(normalizedCol)) {
              similarColumn = column;
              console.log(`🔍 Found partial match: "${similarColumn}"`);
              break;
            }
          }
        }
        
        if (similarColumn) {
          // Пробуем запрос с найденной колонкой
          const quotedSimilar = `"${similarColumn}"`;
          console.log(`🔍 Query 3: ${quotedSimilar}`);
          
          const result3 = await supabase
            .from('nft')
            .select(quotedSimilar)
            .not(quotedSimilar, 'is', null)
            .limit(1);
          
          if (!result3.error && result3.data && result3.data.length > 0) {
            data = result3.data;
            dbColumnName = similarColumn;
            console.log(`✅ Using column: "${dbColumnName}"`);
          }
        } else {
          console.warn(`❌ No matching column found for "${normalizedName}"`);
          return [];
        }
      } else {
        // Используем результат из запроса 2
        data = result2.data;
        dbColumnName = nameWithoutSpaces;
        console.log(`✅ Using column without spaces: "${dbColumnName}"`);
      }
    }
    
    // === 4. ИЗВЛЕЧЕНИЕ ДАННЫХ ===
    if (!data || data.length === 0) {
      console.warn(`❌ No data found for column "${dbColumnName}"`);
      return [];
    }
    
    // Извлекаем массив моделей
    const modelsArray = data[0][dbColumnName];
    
    if (!modelsArray) {
      // Пробуем найти данные в первом доступном ключе
      const firstKey = Object.keys(data[0])[0];
      const alternativeData = data[0][firstKey];
      
      if (Array.isArray(alternativeData)) {
        console.log(`🔄 Using alternative data from key "${firstKey}"`);
        modelsArray = alternativeData;
      }
    }
    
    if (!Array.isArray(modelsArray)) {
      console.warn(`❌ Data is not array for column "${dbColumnName}":`, modelsArray);
      return [];
    }
    
    // === 5. КЭШИРОВАНИЕ ===
    nftModelsCache.value[normalizedName] = modelsArray;
    console.log(`✅ Loaded ${modelsArray.length} models for "${normalizedName}"`);
    
    return modelsArray;
    
  } catch (error) {
    console.error('❌ Error in loadNftModels:', error);
    return [];
  }
};


// Функция нормализации имен NFT СОХРАНЯЕТ исходный формат
const normalizeNftName = (name, sourceItem = null) => {
  if (!name) return '';
  
  console.log('🔍 normalizeNftName input:', { name, sourceItem });
  
  // 1. Сначала попробуем извлечь реальное имя из sourceItem (если он передан)
  const extractRealName = (item) => {
    if (!item) return '';
    
    try {
      // Для Market: из nft_object
      if (item.nft_object) {
        const nftObj = typeof item.nft_object === 'string' 
          ? JSON.parse(item.nft_object) 
          : item.nft_object;
        if (nftObj && nftObj.name) {
          return nftObj.name; // "UFC Strike"
        }
      }
      
      // Для MyGifts Unlisted: из item.name
      if (item.name) {
        return item.name; // "UFC Strike"
      }
    } catch (e) {
      console.warn('Error extracting real name:', e);
    }
    
    return '';
  };
  
  // Если передан sourceItem, используем его для извлечения имени
  if (sourceItem) {
    const realName = extractRealName(sourceItem);
    if (realName) {
      console.log('✅ Found real name from sourceItem:', realName);
      return realName; // "UFC Strike"
    }
  }
  
  // 2. Если name уже является нормальным именем (с пробелами), возвращаем как есть
  const nameStr = String(name);
  
  // Если имя уже содержит пробелы и выглядит как нормальное имя, оставляем как есть
  if (nameStr.includes(' ') && nameStr !== nameStr.toLowerCase()) {
    console.log('✅ Already normalized (has spaces and uppercase):', nameStr);
    return nameStr; // "UFC Strike"
  }
  
  // 3. Если это nft_type типа "html_nft_ufcstrike", преобразуем в "UFC Strike"
  let cleanName = nameStr;
  
  // Убираем префиксы HTML NFT
  if (cleanName.startsWith('html_nft_')) {
    cleanName = cleanName.replace('html_nft_', '');
  } else if (cleanName.startsWith('htmlnft')) {
    cleanName = cleanName.replace('htmlnft', '');
  }
  
  // Преобразуем в формат с пробелами
  // Пример: "ufcstrike" -> "UFC Strike"
  if (!cleanName.includes(' ') && cleanName.length > 0) {
    // Добавляем пробелы перед заглавными буквами (если есть)
    cleanName = cleanName.replace(/([a-z])([A-Z])/g, '$1 $2');
    
    // Делаем первую букву заглавной
    cleanName = cleanName.charAt(0).toUpperCase() + cleanName.slice(1);
  }
  
  console.log('✅ normalizeNftName output:', cleanName);
  return cleanName; // "UFC Strike"
};

// ДОПОЛНИТЕЛЬНАЯ функция для сравнения (удаляет пробелы)
const normalizeNftNameForComparison = (name) => {
  if (!name) return '';
  
  // Приводим к нижнему регистру и удаляем все не-буквенно-цифровые символы
  const result = String(name).toLowerCase().replace(/[^a-z0-9]/g, '');
  console.log('🔍 normalizeNftNameForComparison:', name, '->', result);
  return result; // "ufcstrike"
};


// Новая функция для удаления моделей конкретного NFT
const removeModelsForNft = (nftType) => {
  if (!selectedFilters.value.model || selectedFilters.value.model.length === 0) {
    return;
  }
  
  // Получаем все модели для этого NFT
  const modelsToRemove = [];
  if (nftModelsCache.value[nftType]) {
    nftModelsCache.value[nftType].forEach(modelString => {
      const modelName = modelString.split(' — ')[0].trim();
      modelsToRemove.push(modelName);
    });
  }
  
  // Удаляем эти модели из выбранных фильтров
  if (modelsToRemove.length > 0) {
    selectedFilters.value.model = selectedFilters.value.model.filter(
      model => !modelsToRemove.includes(model)
    );
    console.log(`Удалены модели для NFT ${nftType}:`, modelsToRemove);
  }
};

const reloadModels = async () => {
  modelsLoading.value = true;
  nftModelsCache.value = {}; // Очищаем кэш
  
  try {
    const loadPromises = selectedFilters.value.nft.map(async (nftType) => {
      console.log(`Перезагружаем модели для ${nftType}`);
      return await loadNftModels(nftType);
    });
    
    await Promise.all(loadPromises);
    console.log('Все модели перезагружены');
  } catch (error) {
