const sendOfferDirect = async () => {
  try {
    offerModal.value.loading = true;
    
    // Проверяем баланс пользователя
    const savedAccount = localStorage.getItem('currentAccount');
    if (!savedAccount) {
      throw new Error('User not logged in');
    }
    
    const currentAccount = JSON.parse(savedAccount);
    const userName = currentAccount.name;

    // Получаем текущий баланс пользователя
    const { data: userData, error: userError } = await supabase
      .from('users')
      .select('ton_balance')
      .eq('name', userName)
      .single();

    if (userError) throw userError;

    const currentBalance = parseFloat(userData.ton_balance) || 0;
    const offerAmount = parseFloat(offerModal.value.offerPrice);

    // Проверяем достаточно ли средств
    if (currentBalance < offerAmount) {
      throw new Error(`Insufficient balance. Need ${offerAmount} TON, have ${currentBalance} TON`);
    }

    // Списываем средства с баланса пользователя
    const newBalance = currentBalance - offerAmount;
    
    const { error: updateError } = await supabase
      .from('users')
      .update({ ton_balance: newBalance })
      .eq('name', userName);

    if (updateError) throw updateError;

    // Подготавливаем данные NFT для оффера
    const nftData = {
      url: offerModal.value.item?.nft_object?.url || offerModal.value.item?.url || '',
      name: getNftDisplayName(offerModal.value.item?.nft_type, offerModal.value.item?.nft_object),
      model: offerModal.value.item?.nft_object?.model || '',
      symbol: offerModal.value.item?.nft_object?.symbol || '',
      backdrop: offerModal.value.item?.nft_object?.backdrop || '',
      acquired_at: new Date().toISOString()
    };

    // Извлекаем NFT ID из URL
    let nftId = 'unknown';
    const url = offerModal.value.item?.nft_object?.url || offerModal.value.item?.url;
    if (url) {
      const match = url.match(/-(\d+)(?:\?|$)/);
      nftId = match ? match[1] : 'unknown';
    }

    // Создаем запись оффера в базе данных
    const offerData = {
      item_id: offerModal.value.item?.id,
      seller_name: offerModal.value.item?.seller,
      buyer_name: userName,
      current_price: offerModal.value.currentPrice,
      offer_price: offerAmount,
      nft_data: nftData,
      status: 'pending',
      nft_name: nftData.name,
      nft_id: nftId,
      created_at: new Date().toISOString()
    };

    const { data, error } = await supabase
      .from('offers')
      .insert([offerData])
      .select();

    if (error) throw error;

    // ОТПРАВЛЯЕМ УВЕДОМЛЕНИЕ ПРОДАВЦУ ЧЕРЕЗ БОТА
    await sendOfferNotificationToSeller(offerData);

    // Обновляем локальный баланс
    tonBalance.value = newBalance.toString();

    showNotification('Offer sent successfully!', 'success');
    
    // Закрываем все модальные окна
    offerModal.value.show = false;
    offerConfirmModal.value.show = false;
    
    // Показываем анимацию успеха
    showSuccessAnimation('offer_sent');
    
  } catch (error) {
    console.error('Error sending offer:', error);
    showNotification(`Error sending offer: ${error.message}`, 'error');
  } finally {
    offerModal.value.loading = false;
  }
};
const sendOfferNotificationToSeller = async (offerData) => {
  try {
    // Получаем telegram_id продавца по его имени
    const { data: sellerData, error } = await supabase
      .from('users')
      .select('telegram')
      .eq('name', offerData.seller_name)
      .single();

    if (error || !sellerData || !sellerData.telegram) {
      console.error('❌ Не удалось найти telegram_id продавца:', offerData.seller_name);
      return false;
    }

    const sellerTelegramId = sellerData.telegram;
    
    // Формируем данные для отправки боту
    const notificationData = {
      seller_telegram_id: sellerTelegramId,
      buyer_name: offerData.buyer_name,
      nft_name: offerData.nft_name,
      nft_id: offerData.nft_id,
      current_price: offerData.current_price,
      offer_price: offerData.offer_price,
      item_id: offerData.item_id
    };

    console.log('📤 Отправка уведомления продавцу:', notificationData);

    // Отправляем запрос к API бота
    // Предполагается, что у вас есть endpoint для обработки уведомлений
    const response = await fetch('/api/send-offer-notification', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(notificationData)
    });

    if (response.ok) {
      console.log('✅ Уведомление продавцу отправлено успешно');
      return true;
    } else {
      console.error('❌ Ошибка отправки уведомления:', await response.text());
      return false;
    }

  } catch (error) {
    console.error('❌ Ошибка отправки уведомления продавцу:', error);
    return false;
  }
};


// Обработчик скролла для вкладки "My Gifts"
// Обработчик скролла для вкладки "My Gifts"
let loadMyGiftsDebounce = null;

const handleContainerScroll = (event) => {
  if (activeTab.value !== 'my-nfts') return;
  
  const container = event?.target || document.querySelector('.market-container');
  if (!container) return;
  
  // Проверяем условия для загрузки
  if (myGiftsPagination.value.isLoadingMore || !myGiftsPagination.value.hasMore) {
    return;
  }
  
  // ВАЖНО: Не загружаем если еще не загрузили первую порцию
  if (myGiftsPagination.value.allItems.length === 0) {
    return;
  }
  
  // Рассчитываем позицию скролла
  const scrollTop = container.scrollTop;
  const scrollHeight = container.scrollHeight;
  const clientHeight = container.clientHeight;
  
  // Проверяем, достигли ли мы конца списка
  const threshold = 100;
  const distanceFromBottom = scrollHeight - scrollTop - clientHeight;
  
  // DEBUG
  console.log('📜 Скролл:', {
    scrollTop,
    clientHeight,
    scrollHeight,
    distanceFromBottom: Math.round(distanceFromBottom)
  });
  
  // ТОЛЬКО когда реально доскроллили до конца
  if (distanceFromBottom < threshold && distanceFromBottom > -10) {
    console.log('🎯 Достигнут конец, загружаем еще');
    loadMoreMyGifts();
  }
};

// Функция для получения символов с фильтрацией по поисковому запросу
const getFilteredSymbolsFromActivityHistory = (searchQuery = '') => {
  return extractSymbolsFromActivityHistory().then(symbols => {
    if (!searchQuery) return symbols;
    
    const query = searchQuery.toLowerCase();
    return symbols.filter(symbol => 
      symbol.name.toLowerCase().includes(query) ||
      symbol.fullName.toLowerCase().includes(query)
    );
  });
};
// Альтернативная версия - загрузка с пагинацией
const extractSymbolsFromActivityHistoryPaginated = async (limit = 1000) => {
  try {
    let allSymbols = new Set();
    let offset = 0;
    let hasMore = true;

    while (hasMore) {
      const { data, error } = await supabase
        .from('activity_history')
        .select('nft_object')
        .not('nft_object', 'is', null)
        .range(offset, offset + limit - 1);

      if (error) throw error;

      if (!data || data.length === 0) {
        hasMore = false;
        break;
      }

      data.forEach(item => {
        try {
          const nftObject = typeof item.nft_object === 'string' 
            ? JSON.parse(item.nft_object) 
            : item.nft_object;

          if (nftObject && nftObject.symbol) {
            allSymbols.add(nftObject.symbol);
          }
        } catch (parseError) {
          console.error('Ошибка парсинга nft_object:', parseError);
        }
      });

      offset += limit;
      
      // Прерываем если получили меньше данных чем лимит
      if (data.length < limit) {
        hasMore = false;
      }
    }

    // Преобразуем Set в массив объектов
    const symbolData = Array.from(allSymbols).map(symbol => {
      const symbolName = symbol.replace(/\d+\.?\d*%/, '').trim();
      const percentageMatch = symbol.match(/(\d+\.?\d*)%/);
      const percentage = percentageMatch ? parseFloat(percentageMatch[1]) : 0;
      
      return {
        name: symbolName,
        fullName: symbol,
        percentage: percentage,
        rarityText: percentage > 0 ? `${percentage}%` : 'N/A',
        rarityClass: getRarityClass(percentage)
      };
    });

    symbolData.sort((a, b) => a.name.localeCompare(b.name));
    
    console.log(`✅ Извлечено ${symbolData.length} уникальных символов (пагинация)`);
    return symbolData;

  } catch (error) {
    console.error('❌ Ошибка пагинированного извлечения:', error);
    return [];
  }
};

