const myNftsViewMode = ref('unlisted'); // 'listed' или 'unlisted'
    const myUnlistedNfts = ref([]);
    // Функция для загрузки unlisted NFT из nft_links
const loadUnlistedNfts = async () => {
  try {
    if (!currentAccountName.value) return;
    
    const { data, error } = await supabase
      .from('users')
      .select('nft_links')
      .eq('name', currentAccountName.value)
      .single();
      
    if (error) throw error;
    
    const nftLinks = data?.nft_links || [];
    
    // УДАЛЯЕМ ДУБЛИКАТЫ NFT по URL или ID
    const uniqueNfts = [];
    const seenUrls = new Set();
    const seenGiftIds = new Set(); // Добавляем проверку по gift_id
    
    nftLinks.forEach(nft => {
      const nftData = typeof nft === 'object' ? nft : { url: nft };
      const nftUrl = nftData.url;
      const giftId = nftData.gift_id;
      
      // Создаем уникальный ключ (предпочитаем gift_id, если есть)
      let uniqueKey = null;
      if (giftId) {
        uniqueKey = `gift_${giftId}`;
      } else if (nftUrl) {
        // Извлекаем ID из URL как дополнительную проверку
        const urlMatch = nftUrl.match(/-(\d+)(?:\?|$)/);
        const urlId = urlMatch ? urlMatch[1] : null;
        uniqueKey = urlId ? `url_${urlId}` : nftUrl;
      }
      
      // Если есть ключ и он уже встречался - это дубликат
      if (uniqueKey) {
        if (seenUrls.has(uniqueKey) || (giftId && seenGiftIds.has(giftId))) {
          console.warn('🚫 Найден дубликат NFT:', { url: nftUrl, giftId });
          return;
        }
        
        // Сохраняем ключ
        seenUrls.add(uniqueKey);
        if (giftId) seenGiftIds.add(giftId);
      } else {
        // Fallback: используем URL как есть
        if (seenUrls.has(nftUrl)) {
          console.warn('🚫 Найден дубликат NFT (по URL):', nftUrl);
          return;
        }
        seenUrls.add(nftUrl);
      }
      
      uniqueNfts.push(nftData);
    });
    
    myUnlistedNfts.value = uniqueNfts;
    
    console.log(`✅ Загружено ${uniqueNfts.length} уникальных NFT (было ${nftLinks.length})`);
    
  } catch (error) {
    console.error('❌ Ошибка загрузки unlisted NFT:', error);
    myUnlistedNfts.value = [];
  }
};
    
    

