// Функция для очистки дубликатов в базе данных (можно вызывать при необходимости)
const cleanupDuplicates = async () => {
  try {
    console.log('🧹 Запуск очистки дубликатов...');
    
    // Очистка дубликатов в market
    const { data: marketData } = await supabase
      .from('market')
      .select('*');
    
    if (marketData) {
      const uniqueMarketItems = [];
      const seenMarketItems = new Set();
      const duplicatesToDelete = [];
      
      marketData.forEach(item => {
        const itemKey = item.item_id || `${item.nft_type}_${item.seller}_${item.price_per_unit}`;
        
        if (!seenMarketItems.has(itemKey)) {
          seenMarketItems.add(itemKey);
          uniqueMarketItems.push(item);
        } else {
          duplicatesToDelete.push(item.id);
        }
      });
      
      // Удаляем дубликаты
      if (duplicatesToDelete.length > 0) {
        const { error } = await supabase
          .from('market')
          .delete()
          .in('id', duplicatesToDelete);
          
        if (error) throw error;
        console.log(`🗑️ Удалено ${duplicatesToDelete.length} дубликатов объявлений`);
      }
    }
    
    // Очистка дубликатов в пользовательских NFT
    const { data: usersData } = await supabase
      .from('users')
      .select('name, nft_links');
    
    if (usersData) {
      for (const user of usersData) {
        if (user.nft_links && user.nft_links.length > 0) {
          const uniqueNfts = [];
          const seenNftUrls = new Set();
          
          user.nft_links.forEach(nft => {
            const nftUrl = typeof nft === 'object' ? nft.url : nft;
            
            if (!seenNftUrls.has(nftUrl)) {
              seenNftUrls.add(nftUrl);
              uniqueNfts.push(nft);
            }
          });
          
          // Обновляем если нашли дубликаты
          if (uniqueNfts.length !== user.nft_links.length) {
            const { error } = await supabase
              .from('users')
              .update({ nft_links: uniqueNfts })
              .eq('name', user.name);
              
            if (error) throw error;
            console.log(`🔄 Очищены дубликаты NFT для пользователя ${user.name}`);
          }
        }
      }
    }
    
    console.log('✅ Очистка дубликатов завершена');
    showNotification('Дубликаты очищены', 'success');
    
  } catch (error) {
    console.error('❌ Ошибка очистки дубликатов:', error);
    showNotification('Ошибка очистки дубликатов', 'error');
  }
};


const getBackdropOptions = () => {
  let allItems = [];
  
  if (activeTab.value === 'my-nfts') {
    // Для My Gifts используем данные соответствующего режима
    if (myNftsViewMode.value === 'listed') {
      allItems = allFilterOptions.value.myGiftsItems?.filter(item => !item.is_unlisted) || [];
    } else {
      allItems = allFilterOptions.value.myGiftsItems?.filter(item => item.is_unlisted) || [];
    }
  } else if (activeTab.value === 'market') {
    allItems = allFilterOptions.value.marketItems || [];
  } else if (activeTab.value === 'activity') {
    allItems = allFilterOptions.value.activityItems || [];
  }
  
  console.log(`📊 Получение backdrop опций (режим: ${myNftsViewMode.value}, элементы: ${allItems.length})`);
  
  const backdropMap = new Map();
  
  allItems.forEach(item => {
    try {
      const backdropValue = extractBackdropFromNft(item);
      
      if (backdropValue) {
        const cleanName = backdropValue.replace(/\s*\d+\.?\d*%\s*$/, '').trim();
        
        if (!backdropMap.has(cleanName)) {
          backdropMap.set(cleanName, {
            id: cleanName,
            name: backdropValue,
            count: 1,
            floorPrice: null,
            percentage: backdropValue.includes('%') 
              ? backdropValue.match(/(\d+\.?\d*%)/)?.[0] || ''
              : '',
            rarityText: ''
          });
        } else {
          const existing = backdropMap.get(cleanName);
          existing.count += 1;
        }
      }
    } catch (error) {
      console.warn('⚠️ Ошибка обработки backdrop:', error);
    }
  });
  
  const options = Array.from(backdropMap.values());
  
  // Добавляем floor price (если нужно)
  if (activeTab.value !== 'activity') {
    options.forEach(option => {
      const matchingItems = allItems.filter(item => {
        const itemBackdrop = extractBackdropFromNft(item);
        return itemBackdrop && itemBackdrop.includes(option.name.split(' ')[0]);
      });
      
      if (matchingItems.length > 0) {
        const prices = matchingItems
          .map(item => item.price_per_unit)
          .filter(price => price > 0);
        
        if (prices.length > 0) {
          option.floorPrice = Math.min(...prices);
        }
      }
    });
  }
  
  console.log(`✅ Backdrop опции (${myNftsViewMode.value}):`, options.map(o => o.name));
  return options;
};

// Функция для извлечения числового значения из rarityText (например, "0.3%" → 0.3)
const extractRarityValue = (rarityText) => {
  if (!rarityText) return 0;
  
  // Убираем все нечисловые символы, кроме точки и знака процента
  const match = rarityText.match(/(\d+(?:\.\d+)?)%/);
  if (match) {
    return parseFloat(match[1]);
  }
  
  // Если нет процента, пытаемся найти число
  const numberMatch = rarityText.match(/(\d+(?:\.\d+)?)/);
  if (numberMatch) {
    return parseFloat(numberMatch[1]);
  }
  
  return 0;
};

