// Функция для получения ВСЕХ моделей отсортированных по редкости (проценты)
const getAllModelDataSortedByRarity = () => {
  const allModels = [];
  
  // Собираем все модели из выбранных NFT
  selectedFilters.value.nft.forEach(nftType => {
    const models = getGroupedModelOptions()[nftType] || [];
    models.forEach(model => {
      allModels.push({
        ...model,
        originalNftType: nftType,
        // Добавляем числовое значение редкости для сортировки
        rarityValue: extractRarityValue(model.rarityText)
      });
    });
  });
  
  // Сортируем по редкости (от самых низких процентов к высоким)
  return allModels.sort((a, b) => {
    // Сначала по числовому значению редкости
    if (a.rarityValue !== b.rarityValue) {
      return a.rarityValue - b.rarityValue; // От меньшего к большему
    }
    
    // Затем по имени
    return a.name.localeCompare(b.name);
  });
};

// Функция для генерации HTML контента для модели
const generateModelHtmlContent = (modelData) => {
  // Если у модели уже есть HTML контент
