    return modelData.htmlContent;
  }
  
  // Проверяем, есть ли у модели связанный NFT для генерации изображения
  if (modelData.originalNftType && modelData.name) {
    // Создаем временный NFT объект для генерации изображения
    const tempNftData = {
      name: modelData.name,
