// Функция для получения минимальной цены (floor price) для NFT
const getFloorPriceForNft = async (nftName) => {
  try {
    // Получаем данные из таблицы floor_price
    const { data, error } = await supabase
      .from('floor_price')
      .select('*')
      .order('id', { ascending: false })
      .limit(1)
      .single();

    if (error) {
      console.error('❌ Ошибка получения floor price:', error);
      return 0; // Если ошибка, разрешаем любую цену
    }

    if (!data) {
      console.warn('⚠️ Нет данных floor price');
      return 0;
    }

    // Ищем значение для данного NFT
    // Имя колонки может содержать пробелы и специальные символы
    let floorPrice = 0;
    
    // Проходим по всем колонкам таблицы
    for (const [key, value] of Object.entries(data)) {
      if (key.toLowerCase() === nftName.toLowerCase().trim() && value !== null) {
        floorPrice = parseFloat(value) || 0;
        break;
      }
    }

    console.log(`📊 Floor price для "${nftName}": ${floorPrice}`);
    return floorPrice;

  } catch (error) {
    console.error('❌ Ошибка в getFloorPriceForNft:', error);
    return 0;
  }
};

// Функция для нормализации имени NFT (для сопоставления с колонками таблицы)
