// Упрощенная функция сортировки
const getSortedNftOptions = () => {
  const allOptions = nftOptions.value;
  
  if (!allOptions.length) return [];
  
  // Применяем поиск
  const filtered = searchQuery.value 
    ? allOptions.filter(option => 
        option.name.toLowerCase().includes(searchQuery.value.toLowerCase())
      )
    : allOptions;
  
  // Сортируем: выбранные сверху, затем по алфавиту
  return filtered.sort((a, b) => {
    const aSelected = isOptionSelected('nft', a.originalType);
    const bSelected = isOptionSelected('nft', b.originalType);
    
    if (aSelected && !bSelected) return -1;
    if (!aSelected && bSelected) return 1;
    
    return a.name.localeCompare(b.name);
  });
};
