const handleImageError = (event) => {
  const img = event.target;
  console.warn('⚠️ Ошибка загрузки изображения:', img.src);
  
  // Пробуем альтернативный URL или дефолтное изображение
  const nftName = img.alt;
  if (nftName && nftName !== 'unknown') {
    // Удаляем из кэша чтобы перегенерировать
    delete nftImageCache.value[nftName];
    
    // Через 500ms пробуем перезагрузить
    setTimeout(async () => {
      try {
