// Загрузка всех типов NFT из таблицы nft_type
const loadNftTypesFromDB = async () => {
  if (typesLoaded) return;
  
  try {
    console.log('🔄 Загрузка типов NFT из таблицы nft_type...');
    
    const { data, error } = await supabase
      .from('nft_type')
      .select('*')
      .limit(1)
      .single();
    
    if (error) {
      console.error('❌ Ошибка загрузки типов NFT:', error);
      return;
    }
    
    console.log('📋 Получены данные:', data);
    
    // Проходим по всем ключам (колонкам) в данных
    for (const [nftName, nftType] of Object.entries(data)) {
      // Пропускаем поле id
      if (nftName === 'id') continue;
      
      // Сохраняем в кэш
      nftTypeCache.value[nftName] = nftType;
      console.log(`   ✅ "${nftName}" -> ${nftType}`);
    }
    
    typesLoaded = true;
    console.log('✅ Загружены типы NFT:', Object.keys(nftTypeCache.value).length);
    
    // Проверяем, что Chill Flame загрузился
    if (nftTypeCache.value['Chill Flame']) {
      console.log('🎉 Chill Flame найден! Тип:', nftTypeCache.value['Chill Flame']);
    } else {
      console.warn('⚠️ Chill Flame не найден в загруженных данных');
    }
    
  } catch (error) {
    console.error('❌ Ошибка в loadNftTypesFromDB:', error);
  }
};
const getNftType = (nftName) => {
  if (!nftName) return 'old';
  
  // Очищаем имя от процентов (например "Happy Brownie 0.5%" -> "Happy Brownie")
  const cleanName = nftName.replace(/\s*\d+\.?\d*%\s*$/, '').trim();
  
  // 1. Прямое совпадение
  if (nftTypeCache.value[cleanName]) {
    return nftTypeCache.value[cleanName];
  }
  
  // 2. Совпадение без учета регистра
  for (const [dbName, nftType] of Object.entries(nftTypeCache.value)) {
    if (dbName.toLowerCase() === cleanName.toLowerCase()) {
      return nftType;
    }
  }
  
  // 3. Частичное совпадение (для случаев типа "B-Day Candle" vs "B-Day Candle")
  for (const [dbName, nftType] of Object.entries(nftTypeCache.value)) {
    if (cleanName.toLowerCase().includes(dbName.toLowerCase()) || 
        dbName.toLowerCase().includes(cleanName.toLowerCase())) {
      console.log(`   ⚠️ Частичное совпадение: "${dbName}" -> ${nftType}`);
      return nftType;
    }
  }
  
  console.log(`   ❌ Тип не найден для "${cleanName}", используем "old"`);
  return 'old';
};
