// Функция для получения URL NEW NFT
const getNewNftImageUrl = (nftData) => {
  try {
    // Извлекаем данные
    let nftObj = nftData;
    if (nftData.nft_object) {
      nftObj = typeof nftData.nft_object === 'string' 
        ? JSON.parse(nftData.nft_object) 
        : nftData.nft_object;
    }
    
    // Получаем название NFT
    let nftName = '';
    if (nftObj.name) {
      nftName = nftObj.name;
    } else if (nftData.nft_type) {
      nftName = getNftDisplayName(nftData.nft_type, nftObj);
    }
    
    const cleanNftName = nftName.replace(/\s*\d+\.?\d*%\s*$/, '').trim();
    
    // Получаем компоненты
    let modelName = '';
    let patternName = '';
    let backdropName = '';
    
    if (nftObj.model) {
      modelName = nftObj.model.replace(/\s*\d+\.?\d*%\s*$/, '').trim();
    }
    if (nftObj.symbol) {
      patternName = nftObj.symbol.replace(/\s*\d+\.?\d*%\s*$/, '').trim();
    }
    if (nftObj.backdrop) {
      backdropName = nftObj.backdrop.replace(/\s*\d+\.?\d*%\s*$/, '').trim();
    }
    
    console.log('🔍 NEW NFT данные:', {
      name: cleanNftName,
      model: modelName,
      symbol: patternName,
      backdrop: backdropName
    });
    
    // Формируем URL
    const encodedNft = encodeURIComponent(cleanNftName);
    const encodedModel = encodeURIComponent(modelName);
    const encodedBackdrop = encodeURIComponent(backdropName);
    const encodedPattern = encodeURIComponent(patternName);
    
    return `https://storage.googleapis.com/generate_gifts/${encodedNft}/${encodedModel}_${encodedBackdrop}_${encodedPattern}.png`;
    
  } catch (error) {
    console.error('❌ Ошибка getNewNftImageUrl:', error);
    return default_nft_image;
  }
};
// Функция для получения URL OLD NFT
const getOldNftImageUrl = (nftData) => {
  try {
    let nftObj = nftData;
    if (nftData.nft_object) {
      nftObj = typeof nftData.nft_object === 'string' 
        ? JSON.parse(nftData.nft_object) 
        : nftData.nft_object;
    }
    
    if (nftObj.url) {
      const nftId = extractNftIdFromData(nftObj);
      const nftNameMatch = nftObj.url?.match(/\/nft\/([^-]+)/);
      const oldNftName = nftNameMatch ? nftNameMatch[1] : 'unknown';
      return `https://nft.fragment.com/gift/${oldNftName}-${nftId}.webp`;
    }
    
    return default_nft_image;
    
  } catch (error) {
    console.error('❌ Ошибка getOldNftImageUrl:', error);
    return default_nft_image;
  }
};

const executeTransfer = async () => {
  try {
    console.log('🔄 executeTransfer вызвана!', {
      transferModal: transferModal.value,
      nftData: transferModal.value.nftData,
      recipientUsername: transferModal.value.recipientUsername
    });
    
    const { nftData, recipientUsername } = transferModal.value;
    
    if (!nftData) {
      console.error('❌ Нет данных NFT');
      showNotification('Missing NFT data', 'error');
      return;
    }

    if (!recipientUsername || recipientUsername.trim() === '') {
      console.error('❌ Нет имени получателя:', recipientUsername);
      showNotification('Please enter recipient username', 'error');
      return;
    }

    // Проверяем, что получатель не является текущим пользователем
    if (recipientUsername.toLowerCase() === currentAccountName.value.toLowerCase()) {
      showNotification('You cannot transfer a gift to yourself', 'error');
      return;
    }

    console.log('🔍 Проверка получателя:', recipientUsername);

    // ИСПРАВЛЕНИЕ: используем ilike и limit(1) вместо eq и single()
    const { data: users, error: recipientError } = await supabase
      .from('users')
      .select('username, telegram, nft_links, operation_history')
      .ilike('username', recipientUsername)
      .limit(1);

    if (recipientError) {
      console.error('❌ Ошибка проверки получателя:', recipientError);
      showNotification('Error checking recipient. Please try again.', 'error');
      return;
    }

    // Проверяем наличие данных
    if (!users || users.length === 0) {
      console.error('❌ Получатель не найден');
      showNotification('Recipient not found', 'error');
      return;
    }

    const recipientData = users[0]; // Берем первого пользователя

    console.log('✅ Получатель найден:', {
      username: recipientData.username,
      telegram: recipientData.telegram
    });

    // Получаем данные отправителя (включая username)
    const { data: senderData, error: senderFetchError } = await supabase
      .from('users')
      .select('username, nft_links, operation_history')
      .eq('name', currentAccountName.value)
      .single();

    if (senderFetchError) {
      console.error('❌ Ошибка получения данных отправителя:', senderFetchError);
      throw new Error('Failed to get sender data');
    }

    // Получаем ID NFT
    const nftId = extractNftIdFromData(nftData);
    console.log(`🚀 Начинаем передачу NFT #${nftId} пользователю ${recipientData.username}`);
    
    // Сохраняем копию NFT данных для удаления из интерфейса
    const nftToRemove = {
      nft_object: nftData,
      id: `unlisted-${nftId}`
    };

    // ПОДГОТАВЛИВАЕМ ДАННЫЕ NFT ДЛЯ ПОЛУЧАТЕЛЯ
    const transferredNftData = {
      url: nftData.url || '',
      name: extractNftDataWithNumber(nftData).name,
      model: nftData.model || '',
      symbol: nftData.symbol || '',
      backdrop: nftData.backdrop || '',
      gift_id: nftData.gift_id || extractGiftIdFromNftObject(nftData),
      from_user: recipientData.username ? `@${recipientData.username}` : `@${recipientUsername}`,
      user_name: recipientData.telegram ? recipientData.telegram.toString() : recipientUsername,
      acquired_at: new Date().toISOString()
    };

    console.log('📤 Добавляем NFT получателю с данными получателя:', transferredNftData);

    // === ЗАПИСЬ В ИСТОРИЮ ОТПРАВИТЕЛЯ ===
    const sendOperation = {
      id: `op_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
      type: 'transfer_sent',
      amount: '0',
      timestamp: new Date().toISOString(),
      walletAddress: currentAccountName.value,
      currency: 'TON',
      recipient: recipientUsername,
      recipient_username: recipientData.username,
      nftName: transferredNftData.name,
      nftId: nftId,
      link: transferredNftData.url || null
    };

    const senderCurrentHistory = senderData.operation_history || [];
    const updatedSenderHistory = [sendOperation, ...senderCurrentHistory].slice(0, 100);

    // === ЗАПИСЬ В ИСТОРИЮ ПОЛУЧАТЕЛЯ ===
    const receiveOperation = {
      id: `op_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
      type: 'transfer_received',
      amount: '0',
      timestamp: new Date().toISOString(),
      walletAddress: recipientUsername,
      currency: 'TON',
      sender: currentAccountName.value,
      sender_username: senderData.username || currentAccountName.value,
      nftName: transferredNftData.name,
      nftId: nftId,
      link: transferredNftData.url || null
    };

    const recipientCurrentHistory = recipientData.operation_history || [];
    const updatedRecipientHistory = [receiveOperation, ...recipientCurrentHistory].slice(0, 100);

    // Добавляем NFT получателю
    const recipientCurrentLinks = recipientData.nft_links || [];
    const updatedRecipientLinks = [...recipientCurrentLinks, transferredNftData];

    // Обновляем данные получателя (NFT + история)
    const { error: recipientUpdateError } = await supabase
      .from('users')
      .update({ 
        nft_links: updatedRecipientLinks,
        operation_history: updatedRecipientHistory 
      })
      .eq('username', recipientData.username);

    if (recipientUpdateError) {
      console.error('❌ Ошибка добавления NFT получателю:', recipientUpdateError);
      throw new Error('Failed to add NFT to recipient');
    }

    console.log('✅ NFT добавлен получателю с данными получателя');

    // Удаляем NFT у отправителя
    console.log('🗑️ Удаляем NFT у отправителя...');
    
    let updatedSenderLinks = [];
    if (senderData && senderData.nft_links) {
      updatedSenderLinks = senderData.nft_links.filter(nft => {
        const currentNft = typeof nft === 'object' ? nft : { url: nft };
        const currentNftId = extractNftIdFromData(currentNft);
        return currentNftId !== nftId;
      });

      console.log(`📊 У отправителя было ${senderData.nft_links.length} NFT, останется ${updatedSenderLinks.length}`);
    }

    // Обновляем данные отправителя (NFT + история)
    const { error: senderUpdateError } = await supabase
      .from('users')
      .update({ 
        nft_links: updatedSenderLinks,
        operation_history: updatedSenderHistory 
      })
      .eq('name', currentAccountName.value);

    if (senderUpdateError) {
      console.error('❌ Ошибка удаления NFT у отправителя:', senderUpdateError);
      throw new Error('Failed to remove NFT from sender');
    }

    console.log('✅ NFT удален у отправителя в базе данных');
    
    // КРИТИЧНО: Немедленно удаляем NFT из интерфейса отправителя
    console.log('🗑️ Немедленное удаление NFT из интерфейса...');
    removeNftFromAllLists(nftToRemove);
    
    // Сбрасываем состояние пагинации для My Gifts
    myGiftsPagination.value = {
      offset: 0,
      limit: 15,
      hasMore: true,
      isLoading: false,
      isLoadingMore: false,
      allItems: []
    };
    
    // Очищаем данные фильтрации
    allFilterOptions.value.myGiftsItems = [];
    
    console.log('✅ Локальное состояние сброшено');

    // Закрываем модальное окно
    transferModal.value = {
      show: false,
      nftData: null,
      nftType: '',
      confirmStep: false,
      loading: false,
      amount: 1,
      recipientUsername: '',
      price: '',
      totalPrice: 0,
      commission: 0,
      finalAmount: 0,
      isHtmlNft: false
    };
    
    console.log('✅ Модальное окно закрыто');
    
    // Показываем анимацию успеха
    showSuccessAnimation('transfer');
    showNotification(`NFT successfully transferred to ${recipientData.username}!`, 'success');
    
    // Фоновое обновление данных
    setTimeout(async () => {
      try {
        console.log('🔄 Фоновое обновление данных...');
        
        await loadUnlistedNfts();
        
        if (currentAccountName.value) {
          await loadUserData();
        }
        
        await loadAllDataForFiltering();
        await loadMyGifts(false);
        
        console.log('✅ Все данные успешно обновлены');
      } catch (refreshError) {
        console.warn('⚠️ Ошибка при фоновом обновлении данных:', refreshError);
      }
    }, 800);

  } catch (error) {
    console.error('❌ Transfer failed:', error);
    showNotification('Transfer failed. Please try again.', 'error');
    showOperationAnimation('fail', 'Transfer failed');
    transferModal.value.loading = false;
  }
};
// Вспомогательная функция для корректного извлечения nft_object
const extractNftObjectForTransfer = (item) => {
  try {
    if (!item || !item.nft_object) return null;
    
    let nftObj = item.nft_object;
    
    // Если это строка, парсим
    if (typeof nftObj === 'string') {
      nftObj = JSON.parse(nftObj);
    }
    
    // Если это массив, берем первый элемент
    if (Array.isArray(nftObj) && nftObj.length > 0) {
      nftObj = nftObj[0];
    }
    
    // Сохраняем все оригинальные поля
    const extractedObject = {
      url: nftObj.url || '',
      name: nftObj.name || getNftDisplayName(item.nft_type),
      model: nftObj.model || '',
      symbol: nftObj.symbol || '',
      backdrop: nftObj.backdrop || '',
      gift_id: nftObj.gift_id || extractGiftIdFromNftObject(item.nft_object),
      from_user: nftObj.from_user,
      user_name: nftObj.user_name || item.seller
    };
    
    console.log('✅ Extracted nft_object for transfer:', extractedObject);
    return extractedObject;
    
  } catch (error) {
    console.error('❌ Error extracting nft_object:', error);
    return null;
  }
};



