// Функция для удаления проданного объявления из отображения
const removeSoldItemFromView = (itemId) => {
  console.log('🗑️ Удаление проданного объявления:', itemId);
  
  // 1. Удаляем из marketItems
  const marketIndex = marketItems.value.findIndex(item => item.id === itemId);
  if (marketIndex !== -1) {
    marketItems.value.splice(marketIndex, 1);
  }
  
  // 2. Удаляем из lazy loaded данных market
  const marketPaginationIndex = marketPagination.value.allItems.findIndex(item => item.id === itemId);
  if (marketPaginationIndex !== -1) {
    marketPagination.value.allItems.splice(marketPaginationIndex, 1);
  }
  
  // 3. Удаляем из allFilterOptions.marketItems
  if (allFilterOptions.value.marketItems) {
    const allFilterIndex = allFilterOptions.value.marketItems.findIndex(item => item.id === itemId);
    if (allFilterIndex !== -1) {
      allFilterOptions.value.marketItems.splice(allFilterIndex, 1);
    }
  }
  
  // 4. Удаляем из cart, если там есть
  removeFromCart(itemId);
  
  console.log('✅ Объявление удалено из всех списков');
};

const executeWithdraw = async () => {
  try {
    if (withdrawModal.value.loading) {
      console.log('⏳ Withdrawal already in progress...');
      return;
    }
    
    withdrawModal.value.loading = true;

    // Detailed data check
    console.log('🔍 Checking data in executeWithdraw:');
    console.log('withdrawModal.value:', withdrawModal.value);
    console.log('nftData:', withdrawModal.value.nftData);

    // Check if nftData exists
    if (!withdrawModal.value.nftData) {
      console.error('❌ nftData is null or undefined');
      showNotification('Error: NFT data not found', 'error');
      withdrawModal.value.loading = false;
      return;
    }

    const nftData = withdrawModal.value.nftData;
    console.log('📦 NFT data for withdrawal:', nftData);

    // Safe data extraction
    const gift_id = nftData.gift_id || null;
    const msg_id = nftData.msg_id || null;
    const user_name = nftData.user_name || null;
    const from_user = nftData.from_user || null;
    const url = nftData.url || null;

    console.log('📋 Extracted data:', {
      gift_id,
      msg_id,
      user_name,
      from_user,
      url
    });

    // Check required fields
    if (!user_name && !from_user) {
      console.error('❌ Recipient not specified');
      showNotification('Error: gift recipient not specified', 'error');
      withdrawModal.value.loading = false;
      return;
    }

    if (!gift_id && !msg_id) {
      console.error('❌ Gift ID not specified');
      showNotification('Error: gift ID not specified', 'error');
      withdrawModal.value.loading = false;
      return;
    }

    // BALANCE CHECK AND 0.1 TON FEE DEDUCTION
    const withdrawFee = 0.25; // Withdrawal fee 0.1 TON

    // Get user's current balance with operation history
    const { data: userData, error: fetchError } = await supabase
      .from('users')
      .select('ton_balance, nft_links, operation_history')
      .eq('name', currentAccountName.value)
      .single();

    if (fetchError) throw fetchError;

    const currentBalance = parseFloat(userData.ton_balance) || 0;
    const currentLinks = userData.nft_links || [];

    // Check if user has enough funds for the fee
    if (currentBalance < withdrawFee) {
      showNotification(`Insufficient TON for withdrawal. Need ${withdrawFee} TON, balance: ${currentBalance} TON`, 'error');
      withdrawModal.value.loading = false;
      return;
    }

    // Create withdrawal operation record
    const withdrawOperation = {
      id: `op_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
      type: 'withdraw',
      amount: withdrawFee.toString(),
      timestamp: new Date().toISOString(),
      transactionHash: null,
      walletAddress: currentAccountName.value,
      currency: 'TON',
      nftId: gift_id || msg_id,
      recipient: user_name || from_user,
      feeType: 'gift_withdrawal'
    };

    // Update operation history
    const currentHistory = userData.operation_history || [];
    const updatedHistory = [withdrawOperation, ...currentHistory].slice(0, 100);

    // ✅ KEEP PREVIOUS FUNCTIONALITY: CREATE RECORD IN sent_gift
    const sentGiftData = {
      message_id: gift_id || msg_id,
      recipient: user_name || from_user,
      created_at: new Date().toISOString()
    };

    console.log('📝 Data for sent_gift:', sentGiftData);

    // Insert record into sent_gift table
    const { data: sentGiftResult, error: sentGiftError } = await supabase
      .from('sent_gift')
      .insert([sentGiftData])
      .select();

    if (sentGiftError) {
      console.error('❌ Error creating sent_gift record:', sentGiftError);
      throw sentGiftError;
    }

    console.log('✅ sent_gift record created:', sentGiftResult);

    // Find and remove NFT from collection
    const updatedLinks = currentLinks.filter(link => {
      return link.url !== url && 
             link.gift_id !== gift_id && 
             link.msg_id !== msg_id;
    });

    console.log(`🗑️ Removing NFT from collection. Before: ${currentLinks.length}, After: ${updatedLinks.length}`);

    // UPDATE USER COLLECTION AND DEDUCT FEE
    const newBalance = currentBalance - withdrawFee;
    
    const { error: updateError } = await supabase
      .from('users')
      .update({ 
        nft_links: updatedLinks,
        ton_balance: newBalance,
        operation_history: updatedHistory
      })
      .eq('name', currentAccountName.value);

    if (updateError) throw updateError;

    console.log('✅ NFT successfully withdrawn from collection, fee deducted');
    console.log('📝 Withdrawal operation recorded:', withdrawOperation);
    
    // UPDATE LOCAL BALANCE
    tonBalance.value = newBalance.toString();

    // Record activity
    const activityData = {
      operation_type: 'withdraw',
      user_name: currentAccountName.value,
      nft_type: nftData.name || 'Unknown NFT',
      nft_object: nftData,
      price_per_unit: withdrawFee,
      currency: 'TON',
      amount: 1,
      total_price: withdrawFee,
      recipient: user_name || from_user,
      gift_id: gift_id || msg_id
    };

    await supabase
      .from('activity_history')
      .insert([activityData]);

    // ========== KEY CHANGE: REMOVE FROM LOCAL LISTS ==========
    // Get NFT ID for removal
    const nftId = extractNftIdFromData(nftData);
    const nftNameMatch = nftData.url?.match(/\/nft\/([^-]+)/);
    const nftName = nftNameMatch ? nftNameMatch[1] : 'unknown';
    const fullNftIdentifier = `${nftName}-${nftId}`;
    
    // CREATE ID FOR REMOVAL FROM LOCAL LISTS
    const itemIdToRemove = `unlisted-${nftId}`;
    
    // IMMEDIATE REMOVAL FROM LOCAL LISTS (for instant display)
    // 1. Remove from myUnlistedNfts
    const unlistedIndex = myUnlistedNfts.value.findIndex(nft => {
      const id = extractNftIdFromData(nft);
      return id === nftId;
    });
    
    if (unlistedIndex !== -1) {
      console.log(`✅ Removing from myUnlistedNfts (index ${unlistedIndex})`);
      myUnlistedNfts.value.splice(unlistedIndex, 1);
    }
    
    // 2. Remove from myGiftsPagination.allItems
    const paginationIndex = myGiftsPagination.value.allItems.findIndex(item => {
      const id = extractNftIdFromData(item.nft_object || item);
      return id === nftId;
    });
    
    if (paginationIndex !== -1) {
      console.log(`✅ Removing from myGiftsPagination.allItems (index ${paginationIndex})`);
      myGiftsPagination.value.allItems.splice(paginationIndex, 1);
    }
    
    // 3. Remove from allFilterOptions.myGiftsItems
    if (allFilterOptions.value.myGiftsItems) {
      const filterIndex = allFilterOptions.value.myGiftsItems.findIndex(item => {
        const id = extractNftIdFromData(item.nft_object || item);
        return id === nftId;
      });
      
      if (filterIndex !== -1) {
        console.log(`✅ Removing from allFilterOptions.myGiftsItems (index ${filterIndex})`);
        allFilterOptions.value.myGiftsItems.splice(filterIndex, 1);
      }
    }
    
    // 4. Remove from filteredMarketItems (for current display)
    if (activeTab.value === 'my-nfts' && myNftsViewMode.value === 'unlisted') {
      const filteredIndex = filteredMarketItems.value.findIndex(item => {
        const id = extractNftIdFromData(item.nft_object || item);
        return id === nftId;
      });
      
      if (filteredIndex !== -1) {
        console.log(`✅ Removing from filteredMarketItems (index ${filteredIndex})`);
        filteredMarketItems.value.splice(filteredIndex, 1);
      }
    }
    
    // Show success animation (without passing removal data, since already removed)
    showOperationSuccess('Withdrawal Successful!');
    // ========== END OF CHANGES ==========
    
    // Close modal windows
    withdrawModal.value.show = false;
    
    // Close fullscreen view if open
    if (htmlModal.value.show) {
      htmlModal.value.show = false;
    }
    
    // Navigate to /shop (with small delay for smoothness)
    setTimeout(() => {
      router.push('/shop');
    }, 500);

    // Update data (not immediately, but after animation)
    setTimeout(async () => {
      await loadUnlistedNfts();
      await loadUserData(); // Update user data
    }, 2000); // After animation completes

  } catch (error) {
    console.error('❌ Error withdrawing gift:', error);
    showNotification('Error withdrawing gift', 'error');
    
    // Show error animation
    showOperationFailed('Error withdrawing gift');
  } finally {
    // Always unlock the button
    withdrawModal.value.loading = false;
  }
};

// Дополнительная функция для удаления объявления после анимации
const removeWithdrawnItem = (withdrawInfo) => {
  if (!withdrawInfo || !withdrawInfo.fullIdentifier) {
    console.log('❌ Нет информации для удаления объявления');
    return;
  }
  
  console.log('🗑️ Удаление выведенного NFT:', withdrawInfo.fullIdentifier);
  
  // 1. Удаляем из myUnlistedNfts
  const nftIndex = myUnlistedNfts.value.findIndex(nft => {
    const nftId = extractNftIdFromData(nft);
    const nftNameMatch = nft.url?.match(/\/nft\/([^-]+)/);
    const nftName = nftNameMatch ? nftNameMatch[1] : 'unknown';
    return `${nftName}-${nftId}` === withdrawInfo.fullIdentifier;
  });
  
  if (nftIndex !== -1) {
    console.log('✅ Найден в myUnlistedNfts, удаляю...');
    myUnlistedNfts.value.splice(nftIndex, 1);
  }
  
  // 2. Обновляем filteredMarketItems для вкладки "My Gifts"
  if (activeTab.value === 'my-nfts' && myNftsViewMode.value === 'unlisted') {
    const filteredIndex = filteredMarketItems.value.findIndex(item => {
      const itemId = extractNftIdFromData(item.nft_object || item);
      const itemNameMatch = (item.nft_object?.url || item.url)?.match(/\/nft\/([^-]+)/);
      const itemName = itemNameMatch ? itemNameMatch[1] : 'unknown';
      return `${itemName}-${itemId}` === withdrawInfo.fullIdentifier;
    });
    
    if (filteredIndex !== -1) {
      console.log('✅ Найден в filteredMarketItems, удаляю...');
      filteredMarketItems.value.splice(filteredIndex, 1);
    }
  }
  
  // 3. Обновляем myGiftsPagination.allItems
  const paginationIndex = myGiftsPagination.value.allItems.findIndex(item => {
    const itemId = extractNftIdFromData(item.nft_object || item);
    const itemNameMatch = (item.nft_object?.url || item.url)?.match(/\/nft\/([^-]+)/);
    const itemName = itemNameMatch ? itemNameMatch[1] : 'unknown';
    return `${itemName}-${itemId}` === withdrawInfo.fullIdentifier;
  });
  
  if (paginationIndex !== -1) {
    console.log('✅ Найден в myGiftsPagination, удаляю...');
    myGiftsPagination.value.allItems.splice(paginationIndex, 1);
  }
  
  // 4. Обновляем allFilterOptions.myGiftsItems
  if (allFilterOptions.value.myGiftsItems) {
    const allFilterIndex = allFilterOptions.value.myGiftsItems.findIndex(item => {
      const itemId = extractNftIdFromData(item.nft_object || item);
      const itemNameMatch = (item.nft_object?.url || item.url)?.match(/\/nft\/([^-]+)/);
      const itemName = itemNameMatch ? itemNameMatch[1] : 'unknown';
      return `${itemName}-${itemId}` === withdrawInfo.fullIdentifier;
    });
    
    if (allFilterIndex !== -1) {
      console.log('✅ Найден в allFilterOptions.myGiftsItems, удаляю...');
      allFilterOptions.value.myGiftsItems.splice(allFilterIndex, 1);
    }
  }
  
  console.log('✅ NFT успешно удален из всех локальных списков');
};

// Обновленная функция showOperationSuccess
const showOperationSuccess = (title, operationData = null) => {
  operationAnimation.value = {
    show: true,
    type: 'success',
    title: title,
    animationData: SuccessAnimation,
    operationData: operationData // Сохраняем данные операции
  };
  
  // Запускаем таймер для скрытия и выполнения действий после анимации
  setTimeout(() => {
    operationAnimation.value.show = false;
    
    // Если есть данные операции, выполняем дополнительные действия
    if (operationData) {
      if (operationData.type === 'withdraw') {
        removeWithdrawnItem(operationData);
      }
      // Можно добавить обработку других типов операций
    }
  }, 2000); // Длительность анимации + небольшая задержка
};

const showOperationFailed = (title) => {
  operationAnimation.value = {
    show: true,
    type: 'fail',
    title: title,
    animationData: FailAnimation,
    operationData: null
  };
  
  setTimeout(() => {
    operationAnimation.value.show = false;
  }, 2000);
};
// Кэш для типов NFT
// Кэш для URL изображений
const imageUrlCache = ref({});

const fetchNftImageUrl = async (nftData) => {
  try {
    if (!nftData) return default_nft_image;
    
    // Извлекаем данные
    let nftObj = nftData;
    if (nftData.nft_object) {
      nftObj = typeof nftData.nft_object === 'string' 
        ? JSON.parse(nftData.nft_object) 
        : nftData.nft_object;
    }
    
    // Получаем название NFT
    let nftName = '';
    if (nftObj.name) {
      nftName = nftObj.name;
    } else if (nftData.nft_type) {
      nftName = getNftDisplayName(nftData.nft_type, nftObj);
    }
    
    console.log(`🎯 Обработка NFT: "${nftName}"`);
    
    const cleanNftName = nftName.replace(/\s*\d+\.?\d*%\s*$/, '').trim();
    
    // Определяем тип NFT
    const nftType = await getNftGenerationType(cleanNftName);
    
    console.log(`📌 Тип для "${cleanNftName}": ${nftType === 'new' ? '🆕 NEW' : '📦 OLD'}`);
    
    let imageUrl = default_nft_image;
    
    if (nftType === 'new') {
      console.log(`🆕 Генерация URL для NEW NFT: ${cleanNftName}`);
      
      let modelName = nftObj.model ? nftObj.model.replace(/\s*\d+\.?\d*%\s*$/, '').trim() : '';
      let patternName = nftObj.symbol ? nftObj.symbol.replace(/\s*\d+\.?\d*%\s*$/, '').trim() : '';
      let backdropName = nftObj.backdrop ? nftObj.backdrop.replace(/\s*\d+\.?\d*%\s*$/, '').trim() : '';
      
      console.log(`   Модель: "${modelName}"`);
      console.log(`   Узор: "${patternName}"`);
      console.log(`   Фон: "${backdropName}"`);
      
      if (cleanNftName && modelName && backdropName && patternName) {
        const encodedNft = encodeURIComponent(cleanNftName);
        const encodedModel = encodeURIComponent(modelName);
        const encodedBackdrop = encodeURIComponent(backdropName);
        const encodedPattern = encodeURIComponent(patternName);
        
        imageUrl = `https://storage.googleapis.com/generate_gifts/${encodedNft}/${encodedModel}_${encodedBackdrop}_${encodedPattern}.png`;
        console.log(`🆘🆘🆘⛔⛔⛔⛔🆘⛔🆘🆘🆘🆘⛔⛔⛔⛔✅ Сгенерирован NEW URL: ${imageUrl}`);
      } else {
        console.warn(`⚠️ Недостаточно данных для NEW NFT, используем OLD формат`);
        nftType = 'old'; // Принудительно переключаемся на OLD
      }
    }
    
    if (nftType === 'old' || imageUrl === default_nft_image) {
      console.log(`📦 Генерация URL для OLD NFT: ${cleanNftName}`);
      
      if (nftObj.url) {
        const nftId = extractNftIdFromData(nftObj);
        const nftNameMatch = nftObj.url?.match(/\/nft\/([^-]+)/);
        const oldNftName = nftNameMatch ? nftNameMatch[1] : cleanNftName.toLowerCase().replace(/\s+/g, '');
        imageUrl = `https://nft.fragment.com/gift/${oldNftName}-${nftId}.webp`;
        console.log(`✅ Сгенерирован OLD URL: ${imageUrl}`);
      } else {
        console.warn(`⚠️ Нет URL для OLD NFT`);
      }
    }
    
    return imageUrl;
    
  } catch (error) {
    console.error('❌ Ошибка fetchNftImageUrl:', error);
    return default_nft_image;
  }
};

const getNftGenerationType = async (nftName) => {
  try {
    if (!nftName) return 'old';
    
    // Очищаем имя от процентов и лишних пробелов
    const cleanName = nftName.replace(/\s*\d+\.?\d*%\s*$/, '').trim();
    
    console.log(`🔍 Поиск типа для: "${cleanName}"`);
    
    // Проверяем кэш
    if (nftTypeCache.value[cleanName]) {
      console.log(`📦 Из кэша: ${cleanName} = ${nftTypeCache.value[cleanName]}`);
      return nftTypeCache.value[cleanName];
    }
    
    // Получаем данные из таблицы nft_type
    const { data, error } = await supabase
      .from('nft_type')
      .select('*')
      .limit(1)
      .single();
    
    if (error) {
      console.error('❌ Ошибка получения типа NFT:', error);
      return 'old';
    }
    
    console.log('⛔⛔🆘🆘⛔⛔🆘📋 Данные из таблицы nft_type:', data);
    
    // Ищем имя в данных (без учета регистра)
    let nftType = 'old';
    for (const [key, value] of Object.entries(data)) {
      if (key !== 'id') {
        // Сравниваем без учета регистра
        if (key.toLowerCase() === cleanName.toLowerCase()) {
          nftType = value;
          console.log(`✅ Найдено точное совпадение: "${key}" = ${value}`);
          break;
        }
        // Также проверяем частичное совпадение (на случай разных написаний)
        if (cleanName.toLowerCase().includes(key.toLowerCase()) || 
            key.toLowerCase().includes(cleanName.toLowerCase())) {
          nftType = value;
          console.log(`⚠️ Частичное совпадение: "${key}" ~ "${cleanName}" = ${value}`);
          break;
        }
      }
    }
    
    // Сохраняем в кэш
    nftTypeCache.value[cleanName] = nftType;
    console.log(`💾 Сохранено в кэш: ${cleanName} = ${nftType}`);
    
    return nftType;
    
  } catch (error) {
    console.error('❌ Ошибка в getNftGenerationType:', error);
    return 'old';
  }
};

// Предзагрузка URL для всех items
const preloadItemsImages = async (items) => {
  if (!items || items.length === 0) return;
  
  console.log(`🔄 Предзагрузка изображений для ${items.length} items...`);
  
  const promises = items.map(async (item) => {
    if (item && !item._cachedImageUrl) {
      item._cachedImageUrl = await fetchNftImageUrl(item);
    }
  });
  
  await Promise.all(promises);
  console.log('✅ Предзагрузка изображений завершена');
};


const getNftImageUrl = (nftData) => {
  if (!nftData) return default_nft_image;
  
  try {
    let nftObj = nftData;
    if (nftData.nft_object) {
      nftObj = typeof nftData.nft_object === 'string' 
        ? JSON.parse(nftData.nft_object) 
        : nftData.nft_object;
    }
    
    let nftName = '';
    if (nftObj.name) {
      nftName = nftObj.name;
    } else if (nftData.nft_type) {
      nftName = getNftDisplayName(nftData.nft_type, nftObj);
    }
    
    const nftType = getNftType(nftName);
    
    
    if (nftType === 'new') {
      // NEW NFT - новый формат
      const cleanNftName = nftName.replace(/\s*\d+\.?\d*%\s*$/, '').trim();
      
      let modelName = nftObj.model ? nftObj.model.replace(/\s*\d+\.?\d*%\s*$/, '').trim() : '';
      let patternName = nftObj.symbol ? nftObj.symbol.replace(/\s*\d+\.?\d*%\s*$/, '').trim() : '';
      let backdropName = nftObj.backdrop ? nftObj.backdrop.replace(/\s*\d+\.?\d*%\s*$/, '').trim() : '';
      
      if (cleanNftName && modelName && backdropName && patternName) {
        const encodedNft = encodeURIComponent(cleanNftName);
        const encodedModel = encodeURIComponent(modelName);
        const encodedBackdrop = encodeURIComponent(backdropName);
        const encodedPattern = encodeURIComponent(patternName);
        
        return `https://storage.googleapis.com/generate_gifts/${encodedNft}/${encodedModel}_${encodedBackdrop}_${encodedPattern}.png`;
      }
    }
    
    // OLD NFT
    if (nftObj.url) {
      const nftId = extractNftIdFromData(nftObj);
      const nftNameMatch = nftObj.url?.match(/\/nft\/([^-]+)/);
      const oldNftName = nftNameMatch ? nftNameMatch[1] : 'unknown';
      return `https://nft.fragment.com/gift/${oldNftName}-${nftId}.webp`;
    }
    
    return default_nft_image;
    
  } catch (error) {
    console.error('❌ Ошибка getNftImageUrl:', error);
    return default_nft_image;
  }
};

// Синхронная версия для использования в шаблоне (требует предзагрузки)
const getNftImageUrlSync = (nftData) => {
  if (!nftData) return default_nft_image;
  
  let nftObj = nftData;
  if (nftData.nft_object) {
    try {
      nftObj = typeof nftData.nft_object === 'string' 
        ? JSON.parse(nftData.nft_object) 
        : nftData.nft_object;
    } catch (e) {
      nftObj = nftData;
    }
  }
  
  // Если есть предзагруженный URL в данных
  if (nftData._cachedImageUrl) {
    return nftData._cachedImageUrl;
  }
  
  // Fallback на старый формат
  if (nftObj.url) {
    const nftId = extractNftIdFromData(nftObj);
    const nftNameMatch = nftObj.url?.match(/\/nft\/([^-]+)/);
    const oldNftName = nftNameMatch ? nftNameMatch[1] : 'unknown';
    return `https://nft.fragment.com/gift/${oldNftName}-${nftId}.webp`;
  }
  
  return default_nft_image;
};
