const generateNftHtmlForList = (nftData) => {
  try {
    const nftId = extractNftIdFromData(nftData);
    const nftNameFromData = extractNftDataWithNumber(nftData).name || 'NFT';
    
    // Используем синхронную функцию getNftImageUrl
    const imageUrl = getNftImageUrl(nftData);
    
    return `
<!DOCTYPE html>
<html>
<head>
  <title>NFT Display - ${nftNameFromData}-${nftId}</title>
  <style>
    body, html {
      margin: 0;
      padding: 0;
      width: 100%;
      height: 100%;
      background: transparent;
      overflow: hidden;
      cursor: pointer;
    }
    #image-container {
      width: 100%;
      height: 100%;
      display: flex;
      align-items: center;
      justify-content: center;
      background: transparent;
    }
    .nft-image {
      max-width: 100%;
      max-height: 100%;
      object-fit: contain;
    }
  </style>
</head>
<body>
  <div id="image-container">
    <img src="${imageUrl}" alt="${nftNameFromData}" class="nft-image" 
         onerror="this.onerror=null; this.src='${default_nft_image}';">
  </div>
  <script>
    document.addEventListener('click', function() {
      if (window.parent) {
        window.parent.postMessage({
          type: 'openFullscreenView',
          nftId: '${nftId}',
          nftName: '${nftNameFromData}'
        }, '*');
      }
    });

    const observer = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          const img = document.querySelector('.nft-image');
          if (img && !img.loaded) {
            img.loaded = true;
          }
          observer.disconnect();
        }
      });
    }, { threshold: 0.1 });

    observer.observe(document.getElementById('image-container'));
  <\/script>
</body>
</html>
    `;
  } catch (error) {
    console.error('Error generating NFT HTML for list:', error);
    return `
      <div style="width: 100%; height: 100%; background: #f0f0f0; display: flex; align-items: center; justify-content: center; cursor: pointer;">
        <img src="${default_nft_image}" alt="Default NFT" style="max-width: 80%; max-height: 80%;">
      </div>
    `;
  }
};
const generateNftHtmlForFullscreen = (nftData) => {
