    const nftId = extractNftIdFromData(nftObj);
    const nftType = getNftType(nftName);
    
    console.log(`🎬 Fullscreen для "${nftName}" (${nftType === 'new' ? '🆕 NEW' : '📦 OLD'})`);
    
    // Для NEW NFT - только статическое изображение
    if (nftType === 'new') {
      const imageUrl = getNftImageUrl(nftData);
      
      return `
<!DOCTYPE html>
<html>
<head>
  <title>NFT Display - ${nftName}-${nftId}</title>
  <style>
