      `;
    }
    
    // Для OLD NFT - Lottie анимация с правильным именем
    // Используем функцию cleanNftNameForUrl для правильного форматирования
    const cleanName = cleanNftNameForUrl(nftName);
    const lottieUrl = `https://nft.fragment.com/gift/${cleanName}-${nftId}.lottie.json`;
    const fallbackImageUrl = `https://nft.fragment.com/gift/${cleanName}-${nftId}.webp`;
    
    console.log(`🎬 OLD NFT URL: ${lottieUrl}`);
    
    return `
<!DOCTYPE html>
<html>
<head>
  <title>NFT Display - ${nftName}-${nftId}</title>
  <script src="https://cdnjs.cloudflare.com/ajax/libs/bodymovin/5.12.2/lottie.min.js"><\/script>
  <style>
    * {
      margin: 0;
      padding: 0;
      box-sizing: border-box;
      border-radius: 30px;
    }
    
    body, html {
      margin: 0;
      padding: 0;
      width: 100%;
      height: 100%;
      background: transparent;
      overflow: hidden;
      cursor: pointer;
      display: flex;
      align-items: center;
      justify-content: center;
    }
    
    #main-container {
      display: inline-block;
      position: relative;
      background: transparent;
    }
    
    #animation-container {
      display: inline-block;
      position: relative;
      line-height: 0;
    }
    
    #image-container {
      display: none;
      position: absolute;
      top: 0;
      left: 0;
      width: 100%;
      height: 100%;
    }
    
    .nft-image {
      width: 100%;
      height: 100%;
      object-fit: contain;
      display: block;
    }
    
    .lottie-animation {
      display: block;
      width: 100%;
      height: 100%;
    }
  </style>
</head>
<body>
  <div id="main-container">
    <div id="animation-container">
      <div class="lottie-animation"></div>
    </div>
    <div id="image-container">
      <img class="nft-image" alt="${nftName}">
    </div>
  </div>
  <script>
    let currentAnimation = null;
    let currentImage = null;
    let containerSize = { width: 0, height: 0 };

    function updateContainerSize() {
      const mainContainer = document.getElementById('main-container');
      const animationContainer = document.getElementById('animation-container');
      
      if (animationContainer.offsetWidth > 0 && animationContainer.offsetHeight > 0) {
        containerSize.width = animationContainer.offsetWidth;
        containerSize.height = animationContainer.offsetHeight;
        
        mainContainer.style.width = containerSize.width + 'px';
        mainContainer.style.height = containerSize.height + 'px';
      }
    }

    function loadAnimationWhenVisible() {
      if (currentAnimation) {
        currentAnimation.destroy();
        currentAnimation = null;
      }
      
      if (currentImage && currentImage.parentNode) {
        currentImage.parentNode.removeChild(currentImage);
        currentImage = null;
      }
      
      document.getElementById('animation-container').style.display = 'block';
      document.getElementById('image-container').style.display = 'none';
      
      const animationContainer = document.querySelector('.lottie-animation');
      animationContainer.innerHTML = '';

      currentAnimation = lottie.loadAnimation({
        container: animationContainer,
        renderer: "svg",
        loop: false,
        autoplay: true,
        path: "${lottieUrl}"
      });

      currentAnimation.addEventListener('DOMLoaded', function() {
        setTimeout(updateContainerSize, 100);
      });

      currentAnimation.addEventListener('config_ready', function() {
        setTimeout(updateContainerSize, 100);
      });

      currentImage = new Image();
      currentImage.src = "${fallbackImageUrl}";
      currentImage.className = 'nft-image';
      currentImage.alt = '${nftName}';
      
      currentImage.onload = function() {
        updateContainerSize();
      };
      
      document.getElementById('image-container').innerHTML = '';
      document.getElementById('image-container').appendChild(currentImage);

      currentAnimation.addEventListener('complete', function() {
        if (currentImage.complete && currentImage.naturalWidth !== 0) {
          document.getElementById('animation-container').style.display = 'none';
          document.getElementById('image-container').style.display = 'block';
          updateContainerSize();
        } else {
          currentImage.onload = function() {
            document.getElementById('animation-container').style.display = 'none';
            document.getElementById('image-container').style.display = 'block';
            updateContainerSize();
          };
          currentImage.onerror = function() {
            document.getElementById('animation-container').style.display = 'block';
            document.getElementById('image-container').style.display = 'none';
          };
        }
      });

      currentAnimation.addEventListener('error', function() {
        console.error('Lottie animation error, showing fallback image');
        document.getElementById('animation-container').style.display = 'none';
        document.getElementById('image-container').style.display = 'block';
        updateContainerSize();
      });
      
      if (window.parent) {
        window.parent.postMessage({
          type: 'animationRestarted',
          nftId: '${cleanName}-${nftId}'
        }, '*');
      }
    }

    function replayAnimation() {
      loadAnimationWhenVisible();
    }

    document.addEventListener('click', function() {
      replayAnimation();
    });

    window.addEventListener('message', function(event) {
      if (event.data.type === 'replayAnimation') {
        replayAnimation();
      }
    });

    const resizeInterval = setInterval(updateContainerSize, 500);
    loadAnimationWhenVisible();

    window.addEventListener('beforeunload', function() {
      clearInterval(resizeInterval);
    });

    window.replayAnimation = replayAnimation;
  <\/script>
</body>
</html>
    `;
    
  } catch (error) {
    console.error('Error generating NFT HTML for fullscreen:', error);
    return `
      <div style="width:100%;height:100%;background:#f0f0f0;display:flex;align-items:center;justify-content:center;">
        <div style="text-align:center;">
          <h3>Error loading NFT</h3>
          <p>Click to retry</p>
        </div>
      </div>
    `;
  }
};

// Функция для очистки имени NFT для URL (для OLD NFT)
const cleanNftNameForUrl = (nftName) => {
  if (!nftName) return '';
  
  // Убираем проценты
  let cleanName = nftName.replace(/\s*\d+\.?\d*%\s*$/, '');
  
  // Убираем пробелы и дефисы, приводим к нижнему регистру
  cleanName = cleanName
    .toLowerCase()
    .replace(/[\s-]/g, '')      // убираем пробелы и дефисы
    .replace(/[^a-z0-9]/g, ''); // оставляем только буквы и цифры
  
  return cleanName;
};
const openFullscreenView = (item) => {
  try {
    if (!item) {
      console.error('Item is undefined');
      return;
    }
    
    console.log('🎯 Открываем fullscreen view для:', item.item_id || item.id);
    console.log('📋 Полные данные item:', item);
    
    // Определяем, является ли NFT unlisted (не выставлен на продажу)
    const hasValidMarketData = item.item_id && item.price_per_unit && item.seller;
    const isFromMyGifts = !item.item_id && item.seller === currentAccountName.value;
    
    const isUnlisted = item.is_unlisted || 
                      isFromMyGifts ||
                      (!item.item_id && item.url) ||
                      (item.nft_type && item.nft_type.includes('unlisted'));
    
    console.log('📊 Статус NFT:', { 
      isUnlisted, 
      hasItemId: !!item.item_id,
      hasPrice: !!item.price_per_unit,
      hasSeller: !!item.seller,
      isFromMyGifts,
      hasValidMarketData,
      isOwner: item.seller === currentAccountName.value,
      currentUser: currentAccountName.value
    });

    // Для unlisted NFT определяем доступные действия
    let actionType = 'send'; // по умолчанию для unlisted
    if (!isUnlisted && item.price_per_unit) {
      actionType = 'buy'; // для listed с ценой
    }
    
    // Если есть URL с fragment.com - можно вывести
    if (isUnlisted && item.url && item.url.includes('fragment.com')) {
      actionType = 'withdraw';
    }

    // Генерируем правильный HTML контент в зависимости от типа NFT
    let htmlContent = '';
    try {
      // Пробуем получить данные NFT
      const nftData = item.nft_object || item;
