      // Используем ОДИНАКОВЫЙ HTML для всех NFT
      htmlContent = generateNftHtmlForFullscreen(nftData);
    } catch (htmlError) {
      console.error('❌ Ошибка генерации HTML:', htmlError);
      htmlContent = `
        <div style="width: 100%; height: 100%; background: #f0f0f0; display: flex; align-items: center; justify-content: center; cursor: pointer;">
          <div style="text-align: center;">
            <h3>Error loading NFT</h3>
            <p>Click to retry</p>
          </div>
        </div>
      `;
    }

    // === ИСПРАВЛЕНИЕ: ПРАВИЛЬНО ИЗВЛЕКАЕМ ИМЯ ИЗ БАЗЫ ДАННЫХ ===
    const getSafeNftName = () => {
      try {
        console.log('🔍 Извлекаем имя NFT из данных:');
        
        // 1. Прямая попытка: ищем name в nft_object
        if (item.nft_object) {
          try {
            const nftObj = typeof item.nft_object === 'string' 
              ? JSON.parse(item.nft_object) 
              : item.nft_object;
            
            if (nftObj && nftObj.name) {
              console.log('✅ Нашли name в nft_object:', nftObj.name);
              return nftObj.name;
            }
          } catch (parseError) {
            console.warn('Ошибка парсинга nft_object:', parseError);
          }
        }
        
        // 2. Прямая попытка: сам item может содержать name (для unlisted из users.nft_links)
        if (item.name) {
          console.log('✅ Нашли name в самом item:', item.name);
          return item.name;
        }
        
        // 3. Используем стандартную функцию как fallback
        const fallbackName = getNftDisplayName(item.nft_type, item.nft_object) || 'NFT';
        console.log('⚠️ Используем fallback name:', fallbackName);
        
        return fallbackName;
        
      } catch (error) {
        console.warn('Ошибка получения имени NFT:', error);
        return 'NFT';
      }
    };
    
    const nftName = getSafeNftName();
    console.log('📛 Итоговое NFT Name:', nftName);

    // Извлекаем ID NFT безопасно
    const getSafeNftId = () => {
      try {
        // 1. Из nft_object
        if (item.nft_object) {
          const id = extractNftId(item.nft_object);
          if (id) return id;
        }
        
        // 2. Из item напрямую
        if (item.nft_id || item.gift_id) {
          return item.nft_id || item.gift_id;
        }
        
        // 3. Из URL
        if (item.url) {
          const match = item.url.match(/-(\d+)/);
          if (match) return match[1];
        }
        
        // 4. Попытка извлечь из nft_object как объекта
        try {
          const nftObj = typeof item.nft_object === 'string' 
            ? JSON.parse(item.nft_object) 
            : item.nft_object;
          
          if (nftObj && nftObj.url) {
            const match = nftObj.url.match(/-(\d+)/);
            if (match) return match[1];
          }
        } catch (parseError) {
          console.warn('Ошибка парсинга для ID:', parseError);
        }
        
        return null;
      } catch (error) {
        console.warn('Ошибка получения ID NFT:', error);
        return null;
      }
    };
    
    const nftId = getSafeNftId();
    console.log('🆔 NFT ID:', nftId);

    // ВСЕГДА пытаемся извлечь детали (model, symbol, backdrop)
    let modelData = { name: 'Не указано', percentage: '' };
    let symbolData = { name: 'Не указано', percentage: '' };
    let backdropData = { name: 'Не указано', percentage: '' };
    
    console.log('🔍 Извлекаем детали NFT...');
    
    try {
      let nftObj = null;
      
      if (item.nft_object) {
        nftObj = typeof item.nft_object === 'string' 
          ? JSON.parse(item.nft_object) 
          : item.nft_object;
      } else if (item.url || item.gift_id) {
        // Используем сам item как источник данных для unlisted NFT
        nftObj = item;
      }
      
      if (nftObj) {
        console.log('📋 Исходные данные из nftObj:', {
          model: nftObj.model,
          symbol: nftObj.symbol,
          backdrop: nftObj.backdrop
        });
        
        // Функция для извлечения значения и процента
        const extractValueAndPercentage = (value) => {
          if (!value || value === 'undefined' || value === undefined) {
            return { name: 'Не указано', percentage: '' };
          }
          
          try {
            const stringValue = String(value).trim();
            if (!stringValue) {
              return { name: 'Не указано', percentage: '' };
            }
            
            // Если строка уже содержит процент, разделяем
            if (stringValue.includes('%')) {
              // Ищем последнее число с процентами
              const match = stringValue.match(/(.*?)\s*(\d+\.?\d*%)$/);
              if (match) {
                return { 
                  name: match[1].trim(), 
                  percentage: match[2].trim()
                };
              }
            }
            
            // Если нет процента, возвращаем как есть
            return { name: stringValue, percentage: '' };
          } catch (e) {
            console.warn('Ошибка обработки значения:', value, e);
            return { name: String(value), percentage: '' };
          }
        };

        modelData = extractValueAndPercentage(nftObj.model);
        symbolData = extractValueAndPercentage(nftObj.symbol);
        backdropData = extractValueAndPercentage(nftObj.backdrop);
        
        console.log('✅ Извлеченные данные:', {
          model: modelData,
          symbol: symbolData,
          backdrop: backdropData
        });
      } else {
        console.warn('❌ nftObj не найден для извлечения деталей');
      }
    } catch (parseError) {
      console.error('❌ Ошибка парсинга данных NFT:', parseError);
    }

    // Telegram link
    let telegramLink = null;
    if (item.url && item.url.includes('t.me/nft/')) {
      telegramLink = item.url;
    } else {
      try {
        const url = item.url || (item.nft_object && item.nft_object.url);
        if (url) {
          const fullNftName = extractFullNftName(url);
          telegramLink = fullNftName ? `https://t.me/nft/${fullNftName}` : null;
        }
      } catch (urlError) {
        console.warn('Ошибка извлечения Telegram URL:', urlError);
      }
    }

    console.log('📊 Final modal data:', { 
      isUnlisted, 
      actionType, 
      nftName,
      nftId,
      model: modelData.name,
      symbol: symbolData.name,
      backdrop: backdropData.name,
      hasTelegramLink: !!telegramLink
    });

    // Устанавливаем модальное окно
    htmlModal.value = {
      show: true,
      htmlContent: htmlContent,
      title: nftName, // ✅ Теперь будет правильное имя из базы
      model: modelData.name,
      modelPercentage: modelData.percentage,
      symbol: symbolData.name,
      symbolPercentage: symbolData.percentage,
      backdrop: backdropData.name,
      backdropPercentage: backdropData.percentage,
      telegramLink: telegramLink,
      item: item,
      isUnlisted: isUnlisted,
      actionType: actionType,
      nftId: nftId,
      showTopButtons: !isUnlisted,
      price: item.price_per_unit || null,
      currency: item.currency || null,
      seller: item.seller || null
    };

    console.log('✅ Fullscreen view успешно открыт');

  } catch (err) {
    console.error('❌ Критическая ошибка при открытии полноэкранного просмотра:', err);
    
    // Fallback с минимальными данными
    htmlModal.value = {
      show: true,
      htmlContent: `
        <div style="width: 100%; height: 100%; background: #f0f0f0; display: flex; align-items: center; justify-content: center; cursor: pointer;">
          <div style="text-align: center;">
            <h3>Error loading NFT</h3>
            <p>Click to retry</p>
          </div>
        </div>
      `,
      title: 'NFT',
      model: 'Не указано',
      modelPercentage: '',
      symbol: 'Не указано',
      symbolPercentage: '',
      backdrop: 'Не указано',
      backdropPercentage: '',
      telegramLink: null,
      item: item,
      isUnlisted: true,
      actionType: 'send',
      nftId: null,
      showTopButtons: false,
      price: null,
      currency: null,
      seller: null
    };
  }
};
// Функция для записи операций в историю баланса
const addBalanceOperation = async (type, amount, transactionHash = null, walletAddress = null) => {
  try {
    const currentAccount = currentAccountName.value;
    if (!currentAccount) {
      console.error('❌ Нет текущего пользователя для записи операции');
      return false;
    }

    // Получаем текущие данные пользователя
    const { data: userData, error: fetchError } = await supabase
      .from('users')
      .select('operation_history, wallet_address')
      .eq('name', currentAccount)
      .single();

    if (fetchError && fetchError.code !== 'PGRST116') {
      console.error('❌ Ошибка получения данных пользователя:', fetchError);
      return false;
    }

    // Определяем адрес кошелька
    const actualWalletAddress = walletAddress || userData?.wallet_address || 'unknown';

    // Создаем новую операцию
    const operation = {
      id: `op_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
      type: type, // 'topup', 'withdraw', 'purchase', 'offer', 'promote'
      amount: amount.toString(),
      timestamp: new Date().toISOString(),
      transactionHash: transactionHash,
      walletAddress: actualWalletAddress,
      currency: 'TON' // Добавляем валюту
    };

    // Подготавливаем обновленную историю операций
    let updatedHistory = [];
    
    if (userData && userData.operation_history && Array.isArray(userData.operation_history)) {
      // Добавляем новую операцию в начало массива (последняя операция первой)
      updatedHistory = [operation, ...userData.operation_history];
      // Ограничиваем историю последними 100 операциями
      if (updatedHistory.length > 100) {
        updatedHistory = updatedHistory.slice(0, 100);
      }
    } else {
      updatedHistory = [operation];
    }

    // Обновляем запись в базе данных
    const { error: updateError } = await supabase
      .from('users')
      .update({ 
        operation_history: updatedHistory,
        // Также обновляем баланс при операциях снятия/пополнения
        ...(type === 'topup' || type === 'withdraw' ? {
          balance: (parseFloat(userData?.balance || 0) + (type === 'topup' ? parseFloat(amount) : -parseFloat(amount)))
        } : {})
      })
      .eq('name', currentAccount);

    if (updateError) {
      console.error('❌ Ошибка обновления истории операций:', updateError);
      return false;
    }

    console.log(`✅ Операция ${type} на сумму ${amount} TON записана в историю`);
    return true;

  } catch (error) {
    console.error('❌ Ошибка при записи операции в историю:', error);
    return false;
  }
};
// Вспомогательная функция для получения правильного nft_object для действий
const getNftObjectForFullscreen = (item) => {
  if (!item) return null;
  
  // Если item уже содержит nft_object
  if (item.nft_object) {
    return typeof item.nft_object === 'string' 
      ? JSON.parse(item.nft_object) 
      : item.nft_object;
  }
  
  // Если это unlisted NFT из MyGifts, item сам по себе содержит нужные данные
  if (item.url && item.gift_id) {
    return item;
  }
  
  // В противном случае возвращаем item как есть
  return item;
};

// Обновленные функции для fullscreen view
const handleWithdrawFromFullscreen = () => {
  try {
    const nftData = getNftObjectForFullscreen(htmlModal.value.item);
    if (!nftData) {
      console.error('No NFT data for withdrawal');
      return;
    }
    
    withdrawModal.value = {
      show: true,
      nftData: nftData,
      nftType: nftData.name || 'html_nft',
      confirmStep: false,
      loading: false,
      amount: 1,
      isHtmlNft: true
    };
    
    htmlModal.value.show = false;
  } catch (error) {
    console.error('Error in handleWithdrawFromFullscreen:', error);
  }
