// Функция для нормализации имени файла символа
const normalizeSymbolFileName = (symbolName) => {
  if (!symbolName) return '';
  
  // Убираем проценты и все, что после них
  const withoutPercentage = symbolName.replace(/\s*\d+\.?\d*%\s*$/, '').trim();
  
  // Преобразуем в нижний регистр
  return withoutPercentage.toLowerCase();
};


// Функция для извлечения процента из названия символа
const getSymbolPercentage = (symbolName) => {
  if (!symbolName) return '';
  const match = symbolName.match(/(\d+\.?\d*)%$/);
  return match ? match[0] : ''; // Возвращает "5.23%" или пустую строку
};

// Функция для извлечения числового значения процента (если нужно для сортировки)
const getSymbolPercentageValue = (symbolName) => {
  if (!symbolName) return 0;
  const match = symbolName.match(/(\d+\.?\d*)%$/);
  return match ? parseFloat(match[1]) : 0;
};
// Основная функция генерации HTML для символов
const generateSymbolHtml = (symbolName) => {
  try {
    if (!symbolName) {
      console.warn('❌ Symbol name is undefined');
      return createFallbackHtml('Unknown Symbol');
    }
    
    const safeSymbolName = String(symbolName).trim();
    
    if (!safeSymbolName) {
      console.warn('❌ Symbol name is empty');
      return createFallbackHtml('Empty Symbol');
    }
    
    // Нормализуем имя файла (убираем проценты и приводим к нижнему регистру)
    const fileName = normalizeSymbolFileName(safeSymbolName);
    
    if (!fileName) {
      console.warn('❌ Не удалось нормализовать имя файла для символа:', safeSymbolName);
      return createFallbackHtml(safeSymbolName);
    }
    
    // Кодируем только пробелы как %20, остальное оставляем как есть
    const encodedFileName = fileName.replace(/ /g, '%20');
    
    // Создаем URL
    const symbolLink = `https://gifts.coffin.meme/patterns/${encodedFileName}.tgs`;
    
    console.log(`🔗 Генерируем HTML для символа: ${safeSymbolName}`);
    console.log(`📎 Нормализованное имя: ${fileName}`);
    console.log(`📎 Закодированное имя: ${encodedFileName}`);
    console.log(`📎 Ссылка на .tgs: ${symbolLink}`);
    
    return `
<!DOCTYPE html>
<html>
<head>
    <meta charset="UTF-8">
    <script src="https://cdnjs.cloudflare.com/ajax/libs/bodymovin/5.7.13/lottie.min.js"><\/script>
    <script src="https://cdnjs.cloudflare.com/ajax/libs/pako/2.0.4/pako.min.js"><\/script>
    <style>
        body, html {
            margin: 0;
            padding: 0;
            width: 100%;
            height: 100%;
            background: transparent;
            overflow: hidden;
            display: flex;
            align-items: center;
            justify-content: center;
        }
        #animation-container {
            width: 80%;
            height: 80%;
            display: flex;
            align-items: center;
            justify-content: center;
        }
        #animation {
            width: 100%;
            height: 100%;
        }
        .fallback {
            display: flex;
            align-items: center;
            justify-content: center;
            width: 100%;
            height: 100%;
            background: #f0f0f0;
            border-radius: 8px;
            color: #666;
            font-size: 12px;
            text-align: center;
            padding: 10px;
            cursor: pointer;
        }
        .fallback:hover {
            background: #e0e0e0;
        }
    </style>
</head>
<body>
    <div id="animation-container">
        <div id="animation"></div>
        <div id="fallback" class="fallback" style="display: none;">
            ${safeSymbolName}<br>
            <small>Click to reload</small>
        </div>
    </div>

    <script>
        console.log('🎬 Начало загрузки анимации: ${safeSymbolName}');
        console.log('📥 URL файла: ${symbolLink}');
        
        let animationInstance = null;

        async function loadAnimation() {
            try {
                console.log('📥 Загружаем анимацию...');
                
                const response = await fetch('${symbolLink}', {
                    mode: 'cors',
                    credentials: 'omit'
                });
                
                if (!response.ok) {
                    throw new Error('HTTP ' + response.status + ' - ' + response.statusText);
                }
                
                const arrayBuffer = await response.arrayBuffer();
                console.log('📦 Получено байт:', arrayBuffer.byteLength);
                
                if (arrayBuffer.byteLength === 0) {
                    throw new Error('Файл пустой');
                }
                
                const compressedData = new Uint8Array(arrayBuffer);
                const decompressedData = pako.inflate(compressedData, { to: 'string' });
                const animationData = JSON.parse(decompressedData);
                
                console.log('✅ Анимация распакована');

                animationInstance = lottie.loadAnimation({
                    container: document.getElementById('animation'),
                    renderer: 'svg',
                    loop: true,
                    autoplay: true,
                    animationData: animationData
                });

                console.log('🎉 Анимация загружена успешно');
                
                // Уведомляем родительское окно об успешной загрузке
                try {
                    window.parent.postMessage({
                        type: 'symbolAnimationLoaded',
                        symbolName: '${safeSymbolName}',
                        fileName: '${encodedFileName}'
                    }, '*');
                } catch (e) {
                    console.warn('Не удалось отправить сообщение родителю:', e);
                }

            } catch (error) {
                console.error('❌ Ошибка загрузки анимации:', error.message);
                
                // Уведомляем родительское окно об ошибке
                try {
                    window.parent.postMessage({
                        type: 'symbolAnimationError',
                        symbolName: '${safeSymbolName}',
                        fileName: '${encodedFileName}',
                        error: error.message
                    }, '*');
                } catch (e) {
                    console.warn('Не удалось отправить сообщение об ошибке:', e);
                }
                
                // Показываем fallback
                document.getElementById('animation').style.display = 'none';
                document.getElementById('fallback').style.display = 'flex';
            }
        }

        // Обработчик клика для перезагрузки
        document.getElementById('fallback').addEventListener('click', function() {
            console.log('🔄 Перезагрузка анимации...');
            document.getElementById('animation').style.display = 'block';
            document.getElementById('fallback').style.display = 'none';
            loadAnimation();
        });

        // Запускаем загрузку с задержкой для избежания перегрузки
        setTimeout(() => {
            loadAnimation();
        }, 100);
        
        // Очистка при размонтировании
        window.addEventListener('beforeunload', function() {
            if (animationInstance) {
                animationInstance.destroy();
                animationInstance = null;
            }
        });
    <\/script>
</body>
</html>
    `;
    
  } catch (error) {
    console.error('❌ Критическая ошибка в generateSymbolHtml:', error);
    return createFallbackHtml(symbolName || 'Error');
  }
};



// Функция для сброса зависимых фильтров при изменении основного
const resetDependentFilters = (changedCategory) => {
  const dependencyOrder = ['nft', 'model', 'symbol', 'backdrop'];
  const changedIndex = dependencyOrder.indexOf(changedCategory);
  
  if (changedIndex === -1) return;
  
  // Сбрасываем только фильтры, которые логически зависят от измененного
  // Например, при изменении NFT сбрасываем model, symbol, backdrop
  // Но при изменении symbol или backdrop ничего не сбрасываем
  for (let i = changedIndex + 1; i < dependencyOrder.length; i++) {
    const categoryToReset = dependencyOrder[i];
    selectedFilters.value[categoryToReset] = [];
  }
  
  console.log(`Сброшены фильтры после ${changedCategory}`);
};

