// Обновленная функция getBackdropCount - сравниваем полные названия
const getBackdropCount = (backdropName) => {
  try {
    const items = getCurrentDataSource.value;
    let count = 0;
    
    items.forEach(item => {
      const itemBackdrop = extractBackdropFromNft(item);
      if (itemBackdrop) {
        // Сравниваем полные названия (без процентов)
        const cleanItemBackdrop = itemBackdrop.replace(/\d+\.?\d*%/, '').trim();
        const cleanBackdropName = backdropName.replace(/\d+\.?\d*%/, '').trim();
        
        if (cleanItemBackdrop.toLowerCase() === cleanBackdropName.toLowerCase()) {
          count++;
        }
      }
    });
    
    return count;
  } catch (error) {
    console.error('Error getting backdrop count:', error);
    return 0;
  }
};
// Обновленная функция getBackdropFloorPrice - сравниваем полные названия
const getBackdropFloorPrice = (backdropName) => {
  try {
    const items = getCurrentDataSource.value;
    let minPrice = Infinity;
    
    items.forEach(item => {
      const itemBackdrop = extractBackdropFromNft(item);
      if (itemBackdrop) {
        // Сравниваем полные названия (без процентов)
        const cleanItemBackdrop = itemBackdrop.replace(/\d+\.?\d*%/, '').trim();
        const cleanBackdropName = backdropName.replace(/\d+\.?\d*%/, '').trim();
        
        if (cleanItemBackdrop.toLowerCase() === cleanBackdropName.toLowerCase() && item.price_per_unit) {
          const price = parseFloat(item.price_per_unit);
          if (price < minPrice) {
            minPrice = price;
          }
        }
      }
    });
    
    return minPrice !== Infinity ? minPrice : null;
  } catch (error) {
    console.error('Error getting backdrop floor price:', error);
    return null;
  }
};





