// В script секции, добавьте ref и метод replayHtmlAnimation

// Добавьте ref для iframe
const htmlIframe = ref(null);

// Метод для перезапуска анимации
const replayHtmlAnimation = () => {
  if (htmlIframe.value && htmlModal.value.htmlContent) {
    // Сохраняем текущий контент
    const currentContent = htmlModal.value.htmlContent;
    
    // Временно очищаем iframe
    htmlIframe.value.srcdoc = '';
    
    // Используем setTimeout для гарантии, что iframe очистился
    setTimeout(() => {
      // Восстанавливаем контент - это заставит анимацию запуститься заново
      htmlIframe.value.srcdoc = currentContent;
      
      // Отправляем сообщение в iframe для принудительного запуска анимации
      try {
        const iframeWindow = htmlIframe.value.contentWindow;
        if (iframeWindow) {
          iframeWindow.postMessage({ type: 'replayAnimation' }, '*');
        }
      } catch (error) {
        console.log('Анимация перезапущена через перезагрузку iframe');
      }
    }, 50);
  }
};
