const loadSymbolOptions = async () => {
  try {
    console.log('🚀 Начало загрузки символов...');
    symbolsLoading.value = true;
    
    // Получаем все символы из базы данных
    // ВАЖНО: Замените 'patterns' на реальное название вашей таблицы
    // Или используйте данные из другой таблицы
    
    let symbolsData = [];
    
    // Попробуйте несколько источников
    try {
      // Вариант 1: Попробуйте таблицу 'symbols'
      const { data: symbolsData1, error: error1 } = await supabase
        .from('symbols')
        .select('*');
      
      if (!error1 && symbolsData1 && symbolsData1.length > 0) {
        console.log('✅ Данные из таблицы symbols:', symbolsData1.length);
        symbolsData = symbolsData1;
      } else {
        console.log('❌ Таблица symbols пуста или не существует');
      }
    } catch (error) {
      console.log('⚠️  Ошибка доступа к таблице symbols:', error.message);
    }
    
    // Если не нашли в symbols, попробуем activity
    if (symbolsData.length === 0) {
      try {
        const { data: activityData, error: activityError } = await supabase
          .from('activity_history')
          .select('nft_object')
          .limit(100);
        
        if (!activityError && activityData) {
          // Извлекаем уникальные символы из activity
          const uniqueSymbols = new Set();
          
          activityData.forEach(item => {
            try {
              const nftObj = typeof item.nft_object === 'string' 
                ? JSON.parse(item.nft_object) 
                : item.nft_object;
              
              if (nftObj?.symbol) {
                const symbolName = nftObj.symbol.split(' ')[0]; // Убираем проценты
                if (symbolName && symbolName.trim()) {
                  uniqueSymbols.add(symbolName.trim());
                }
              }
            } catch (e) {
              // Игнорируем ошибки парсинга
            }
          });
          
          // Преобразуем Set в массив объектов
          symbolsData = Array.from(uniqueSymbols).map((name, index) => ({
            id: index + 1,
            name: name,
            description: `Символ из активности: ${name}`,
            image_url: null
          }));
          
          console.log('✅ Извлечены символы из activity:', symbolsData.length);
        }
      } catch (error) {
        console.log('⚠️  Ошибка извлечения символов из activity:', error.message);
      }
    }
    
    // Если всё ещё нет данных, используем тестовые символы
    if (symbolsData.length === 0) {
      console.log('⚠️  Нет данных о символах, используем тестовые');
      symbolsData = [
        { id: 1, name: 'Handset', description: 'Тестовый символ 1' },
        { id: 2, name: 'Obon Lantern', description: 'Тестовый символ 2' },
        { id: 3, name: 'Strawberry', description: 'Тестовый символ 3' },
        { id: 4, name: 'Venetian Mask', description: 'Тестовый символ 4' }
      ];
    }
    
    console.log('📊 Символы для обработки:', symbolsData);
    
    // Генерируем HTML контент для каждого символа
    const processedSymbols = symbolsData.map(symbol => {
      const htmlContent = generateSymbolHtml(symbol.name);
      
      console.log(`📝 Символ: ${symbol.name}`, {
        hasHtml: !!htmlContent,
        htmlLength: htmlContent?.length || 0,
        htmlPreview: htmlContent ? htmlContent.substring(0, 100) + '...' : 'null'
      });
      
      return {
        ...symbol,
        value: symbol.name.toLowerCase().replace(/\s+/g, '_'),
        htmlContent: htmlContent || createFallbackHtml(symbol.name),
        count: Math.floor(Math.random() * 50) + 1,
        floorPrice: parseFloat((Math.random() * 5 + 0.1).toFixed(1)),
        rarityClass: 'common',
        rarityText: 'Common',
        imageUrl: symbol.image_url || null
      };
    });
    
    console.log('✅ Обработанные символы:', processedSymbols.length);
    
    // Сохраняем символы
    symbolOptions.value = processedSymbols;
    
    // Принудительно обновляем компонент
    triggerForceUpdate();
    
  } catch (error) {
    console.error('❌ Критическая ошибка загрузки символов:', error);
    
    // Fallback с тестовыми данными
    const fallbackSymbols = [
      'Handset',
      'Obon Lantern', 
      'Strawberry',
      'Venetian Mask'
    ].map((name, index) => ({
      id: index + 1,
      name: name,
      value: name.toLowerCase().replace(/\s+/g, '_'),
      htmlContent: generateSymbolHtml(name) || createFallbackHtml(name),
      count: Math.floor(Math.random() * 50) + 1,
      floorPrice: parseFloat((Math.random() * 5 + 0.1).toFixed(1)),
      rarityClass: 'common',
      rarityText: 'Common'
    }));
    
    symbolOptions.value = fallbackSymbols;
    triggerForceUpdate();
    
  } finally {
    symbolsLoading.value = false;
    console.log('🏁 Загрузка символов завершена');
  }
};

