    // Проверка входных данных
    if (!symbolName) {
      console.warn('❌ Имя символа не указано');
      return createFallbackHtml('Unknown');
    }
    
    const safeSymbolName = String(symbolName).trim();
    
    if (!safeSymbolName) {
      console.warn('❌ Имя символа пустое');
      return createFallbackHtml('Empty');
    }
    
    console.log(`✅ Имя символа валидно: "${safeSymbolName}"`);
    
    // ПРОСТАЯ ВЕРСИЯ ДЛЯ ОТЛАДКИ - без TGS анимации
    return `
