const replayHtmlAnimation = (event) => {
  event.stopPropagation();
  
  if (htmlIframe.value) {
    try {
      // Пытаемся вызвать функцию replayAnimation внутри iframe
      const iframeWindow = htmlIframe.value.contentWindow;
      if (iframeWindow && typeof iframeWindow.replayAnimation === 'function') {
        iframeWindow.replayAnimation();
        console.log('✅ Анимация перезапущена через функцию iframe');
      } else {
        // Fallback: отправляем сообщение
        iframeWindow.postMessage({ 
          type: 'replayAnimation',
          timestamp: Date.now()
        }, '*');
        console.log('✅ Сообщение для перезапуска отправлено');
      }
    } catch (error) {
      console.log('❌ Ошибка при перезапуске анимации:', error);
      // Ultimate fallback: перезагружаем iframe
      const currentContent = htmlIframe.value.srcdoc;
      htmlIframe.value.srcdoc = '';
      setTimeout(() => {
        htmlIframe.value.srcdoc = currentContent;
      }, 50);
    }
  }
};
// Вспомогательная функция для извлечения ID из HTML контента
const extractNftIdFromHtml = (htmlContent) => {
  try {
    const match = htmlContent.match(/nftId['"]?\s*:\s*['"]([^'"]+)['"]/);
    return match ? match[1] : null;
  } catch (error) {
    console.error('Ошибка извлечения NFT ID из HTML:', error);
    return null;
  }
};
// Функция загрузки активности с учетом ВСЕХ фильтров
const loadActivityHistory = async (isLoadMore = false) => {
  try {
    // Блокируем параллельные запросы
    if (window.activityLoadingInProgress) {
      console.log('⏳ Загрузка активности уже выполняется, пропускаем');
      return;
    }
    
    window.activityLoadingInProgress = true;
    
    if (!isLoadMore) {
      // Первоначальная загрузка - сбрасываем пагинацию
      pagination.value.offset = 0;
      pagination.value.hasMore = true;
      displayedActivity.value = [];
      activityItems.value = [];
      loadingActivity.value = true;
      
      console.log('📊 Начальная загрузка истории активности (пагинация)');
    } else {
      console.log(`📊 Автоматическая подгрузка следующих ${pagination.value.limit} записей`);
    }

    // Создаем базовый запрос - ДОБАВЛЯЕМ ФИЛЬТРАЦИЮ ПО ТИПАМ
    let query = supabase
      .from('activity_history')
      .select('*', { count: 'exact' })
      .in('operation_type', ['listing', 'price_edit', 'purchase']) // ФИЛЬТР: только эти типы
      .order('created_at', { ascending: false });

    // Применяем фильтры которые можно сделать на сервере
    if (selectedActivityType.value && selectedActivityType.value !== 'all') {
      query = query.eq('operation_type', selectedActivityType.value);
    }
    
    if (showOnlyMyActivity.value && currentAccountName.value) {
      query = query.eq('user_name', currentAccountName.value);
    }
    
    // Используем пагинацию
    const { data, error, count } = await query
      .range(pagination.value.offset, pagination.value.offset + pagination.value.limit - 1);
    
    if (error) {
      console.error('❌ Ошибка загрузки активности:', error);
      return;
    }
    
    const loadedData = data || [];
    const totalCount = count || 0;
    
    console.log(`✅ Загружено ${loadedData.length} записей (пагинация: ${pagination.value.offset}-${pagination.value.offset + pagination.value.limit - 1})`);
    
    // Логируем типы активности для отладки
    if (loadedData.length > 0) {
      const typesCount = {};
      loadedData.forEach(item => {
        typesCount[item.operation_type] = (typesCount[item.operation_type] || 0) + 1;
      });
      console.log('📊 Типы активности в загруженных данных:', typesCount);
    }
    
    // ПРИМЕНЯЕМ ФИЛЬТРЫ НА КЛИЕНТЕ
    let filteredData = loadedData;
    
    // Проверяем, есть ли активные фильтры
    const hasCommonFilters = selectedFilters.value.nft.length > 0 || 
                           selectedFilters.value.model.length > 0 || 
                           selectedFilters.value.symbol.length > 0 || 
                           selectedFilters.value.backdrop.length > 0 ||
                           selectedIdFilter.value !== null;
    
    if (hasCommonFilters && filteredData.length > 0) {
      console.log('🔍 Применяем фильтры на клиенте...');
      
      filteredData = filteredData.filter(activity => {
        try {
          let nftName = '';
          let model = '';
          let symbol = '';
          let backdrop = '';
          
          if (activity.nft_object) {
            try {
              const nftObject = typeof activity.nft_object === 'string' 
                ? JSON.parse(activity.nft_object) 
                : activity.nft_object;
              
              if (nftObject) {
                nftName = nftObject.name || '';
                model = nftObject.model || '';
                symbol = nftObject.symbol || '';
                backdrop = nftObject.backdrop || '';
              }
            } catch (parseError) {
              // Пропускаем ошибки парсинга
            }
          }
          
          // NFT фильтр
          if (selectedFilters.value.nft.length > 0) {
            if (!nftName || nftName.trim() === '') return false;
            
            const normalizedItemName = normalizeNftName(nftName);
            let passesNftFilter = false;
            
            for (const selectedNft of selectedFilters.value.nft) {
              const normalizedSelected = normalizeNftName(selectedNft);
              if (normalizedItemName.includes(normalizedSelected) || 
                  normalizedItemName === normalizedSelected) {
                passesNftFilter = true;
                break;
              }
            }
            
            if (!passesNftFilter) return false;
          }
          
          // Model фильтр
          if (selectedFilters.value.model.length > 0) {
            if (!model) return false;
            
            const cleanItemModel = model.split(' ')[0].toLowerCase().trim();
            let passesModelFilter = false;
            
            for (const selectedModel of selectedFilters.value.model) {
              const cleanSelectedModel = selectedModel.toLowerCase().trim();
              if (cleanItemModel === cleanSelectedModel) {
                passesModelFilter = true;
                break;
              }
            }
            
            if (!passesModelFilter) return false;
          }
          
          // Symbol фильтр
          if (selectedFilters.value.symbol.length > 0) {
            if (!symbol) return false;
            
            const normalizedItemSymbol = normalizeSymbolName(symbol);
            let passesSymbolFilter = false;
            
            for (const selectedSymbol of selectedFilters.value.symbol) {
              const normalizedSelectedSymbol = normalizeSymbolName(selectedSymbol);
              if (normalizedItemSymbol === normalizedSelectedSymbol) {
                passesSymbolFilter = true;
                break;
              }
            }
            
            if (!passesSymbolFilter) return false;
          }
          
          // Backdrop фильтр
          if (selectedFilters.value.backdrop.length > 0) {
            if (!backdrop) return false;
            
            const cleanItemBackdrop = backdrop.split(' ')[0].toLowerCase().trim();
            let passesBackdropFilter = false;
            
            for (const selectedBackdrop of selectedFilters.value.backdrop) {
              const cleanSelectedBackdrop = selectedBackdrop.split(' ')[0].toLowerCase().trim();
              if (cleanItemBackdrop === cleanSelectedBackdrop) {
                passesBackdropFilter = true;
                break;
              }
            }
            
            if (!passesBackdropFilter) return false;
          }
          
          // ID фильтр
          if (selectedIdFilter.value !== null) {
            try {
              if (activity.nft_object) {
                const nftObject = typeof activity.nft_object === 'string' 
                  ? JSON.parse(activity.nft_object) 
                  : activity.nft_object;
                
                if (nftObject && nftObject.url) {
                  const match = nftObject.url.match(/-(\d+)(?:\?|$)/);
                  const itemId = match ? parseInt(match[1]) : 0;
                  if (itemId !== selectedIdFilter.value) {
                    return false;
                  }
                } else {
                  return false;
                }
              }
            } catch (error) {
              return false;
            }
          }
          
          return true;
          
        } catch (error) {
          return false;
        }
      });
      
      console.log(`🔍 После фильтрации: ${filteredData.length} из ${loadedData.length} записей`);
    }
    
    // Добавляем новые записи
    if (isLoadMore) {
      // Для подгрузки - добавляем к существующим
      displayedActivity.value = [...displayedActivity.value, ...filteredData];
    } else {
      // Для начальной загрузки - заменяем
      displayedActivity.value = filteredData;
    }
    
    activityItems.value = displayedActivity.value;
    
    // Обновляем состояние пагинации
    const totalLoaded = pagination.value.offset + loadedData.length;
    pagination.value.hasMore = totalLoaded < totalCount;
    
    if (pagination.value.hasMore) {
      // Обновляем offset для следующей загрузки
      pagination.value.offset = totalLoaded;
      console.log(`📊 Есть еще данные (${totalLoaded}/${totalCount})`);
      
      // АВТОМАТИЧЕСКАЯ ПОДГРУЗКА: 
      // Загружаем следующую порцию если после фильтрации получилось мало данных
      // Это обеспечивает плавный UX без необходимости скроллить
      if (displayedActivity.value.length < 8) {
        console.log('🔄 После фильтрации мало данных, автоматически подгружаем еще...');
        setTimeout(() => {
          loadActivityHistory(true);
        }, 300);
      }
      
    } else {
      console.log(`🏁 Все данные загрузки (${totalLoaded}/${totalCount})`);
    }
    
    console.log(`✅ Отображается ${displayedActivity.value.length} активностей`);
    
  } catch (error) {
    console.error('❌ Ошибка загрузки истории активности:', error);
  } finally {
    loadingActivity.value = false;
    // Очищаем флаг
    window.activityLoadingInProgress = false;
  }
};
// В setup() добавьте методы:
// Открыть модальное окно продвижения
const openPromoteModal = (item) => {
  promoteModal.value = {
    show: true,
    item: item,
    loading: false,
    cost: 0.1,
    duration: 24
  };
};

// Подтвердить продвижение
const confirmPromotion = async () => {
  if (!promoteModal.value.item) return;
  
  try {
    promoteModal.value.loading = true;
    
    // Проверяем баланс
    const currentBalance = parseFloat(tonBalance.value);
    if (currentBalance < promoteModal.value.cost) {
      throw new Error('Insufficient TON balance');
    }
    
    // Получаем данные пользователя с историей операций
    const { data: userData, error: userError } = await supabase
      .from('users')
      .select('ton_balance, operation_history')
      .eq('name', currentAccountName.value)
      .single();

    if (userError) throw userError;

    // Списываем стоимость продвижения
    const newBalance = currentBalance - promoteModal.value.cost;
    
    // Создаем запись операции продвижения
    const promotionOperation = {
      id: `op_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
      type: 'promote',
      amount: promoteModal.value.cost.toString(),
      timestamp: new Date().toISOString(),
      transactionHash: null,
      walletAddress: currentAccountName.value,
      currency: 'TON',
      itemId: promoteModal.value.item.id,
      nftType: promoteModal.value.item.nft_type,
      duration: promoteModal.value.duration
    };

    // Обновляем историю операций
    const currentHistory = userData.operation_history || [];
    const updatedHistory = [promotionOperation, ...currentHistory].slice(0, 100);

    // Обновляем баланс и историю операций
    const { error: updateError } = await supabase
      .from('users')
      .update({ 
        ton_balance: newBalance,
        operation_history: updatedHistory 
      })
      .eq('name', currentAccountName.value);

    if (updateError) throw updateError;

    // Обновляем локальный баланс
    tonBalance.value = newBalance.toString();

    // === ДОБАВЛЯЕМ ЗАПИСЬ В ТАБЛИЦУ CONFIGURATIONS ===
    await updateConfigurationsStats(promoteModal.value.cost, 'promotion');

    // Отправляем транзакцию (пример)
    const success = await processPromotionPayment(promoteModal.value.cost);
    
    if (success) {
      // Добавляем объявление в продвинутые
      await addPromotedItem(promoteModal.value.item.id);
      
      // Записываем активность
      const activityData = {
        operation_type: 'promotion',
        user_name: currentAccountName.value,
        nft_type: promoteModal.value.item.nft_type,
        nft_object: promoteModal.value.item.nft_object,
        price_per_unit: promoteModal.value.cost,
        currency: 'TON',
        amount: 1,
        total_price: promoteModal.value.cost,
        item_id: promoteModal.value.item.id
      };

      await supabase
        .from('activity_history')
        .insert([activityData]);

      console.log('✅ Продвижение успешно');
      console.log('📝 Операция продвижения записана:', promotionOperation);
      
      showSuccessAnimation('Promotion successful!');
      showNotification('NFT promoted for 24 hours!', 'success');
      
      // Закрываем модальное окно
      promoteModal.value.show = false;
      
      // Обновляем данные
      await loadUserData();
      await reloadAllMarketItems();
    }
    
  } catch (error) {
    console.error('Promotion error:', error);
    showNotification(`Promotion failed: ${error.message}`, 'error');
    showErrorAnimation('Promotion failed');
  } finally {
    promoteModal.value.loading = false;
  }
};


// Обработка платежа за продвижение
const processPromotionPayment = async (amount) => {
  // Интеграция с TON кошельком
  // Это пример - замените на реальную логику оплаты
  return new Promise((resolve) => {
    setTimeout(() => {
      resolve(true); // Имитация успешной оплаты
    }, 1500);
  });
