// Добавить объявление в продвинутые
const addPromotedItem = async (itemId) => {
  try {
    // Сохраняем в локальное хранилище с таймером
    const promotionData = {
      itemId: itemId,
      expiresAt: Date.now() + (24 * 60 * 60 * 1000) // 24 часа
    };
    
    // Получаем текущие продвинутые объявления
    const currentPromoted = JSON.parse(localStorage.getItem('promotedItems') || '[]');
    
    // Удаляем старые записи для этого товара (если есть)
    const filtered = currentPromoted.filter(item => item.itemId !== itemId);
    
    // Добавляем новое
    filtered.push(promotionData);
    
    // Сохраняем
    localStorage.setItem('promotedItems', JSON.stringify(filtered));
    
    // Обновляем reactive состояние
    promotedItems.value = filtered;
    
    // Также можно сохранить в базу данных через Supabase
    if (currentAccountName.value) {
      await supabase
        .from('promotions')
        .upsert({
          user_id: currentAccountName.value,
          item_id: itemId,
          expires_at: new Date(promotionData.expiresAt).toISOString(),
          cost: 0.1
        });
    }
    
  } catch (error) {
    console.error('Error adding promoted item:', error);
  }
};

// Проверить, является ли объявление продвинутым
const isItemPromoted = (itemId) => {
  // Проверяем в локальном хранилище
  const promotedItemsList = JSON.parse(localStorage.getItem('promotedItems') || '[]');
  
  return promotedItemsList.some(item => {
    return item.itemId === itemId && item.expiresAt > Date.now();
  });
};

// Загрузить продвинутые объявления
const loadPromotedItems = () => {
  const stored = localStorage.getItem('promotedItems');
  if (stored) {
    promotedItems.value = JSON.parse(stored);
  }
};

// Очистить истекшие продвижения
const cleanupExpiredPromotions = () => {
  const currentTime = Date.now();
  const validPromotions = promotedItems.value.filter(item => item.expiresAt > currentTime);
  
  if (validPromotions.length !== promotedItems.value.length) {
    localStorage.setItem('promotedItems', JSON.stringify(validPromotions));
    promotedItems.value = validPromotions;
  }
};

// Обновить класс для market-item если он продвинут
const getMarketItemClass = (item) => {
  const baseClass = { 'ton': item.currency === 'TON' };
  
  if (isItemPromoted(item.id)) {
    baseClass['promoted'] = true;
  }
  
  return baseClass;
};


// 1. Функция для загрузки ВСЕХ доступных Backdrop из всей базы данных
const loadAllBackdrops = async () => {
  try {
    console.log('🔍 Загрузка ВСЕХ доступных Backdrop из всей базы данных...');
    
    let allBackdrops = new Set();
    let backdropWithPercentages = {}; // Для хранения полных названий с процентами
    
    // Загружаем ВСЕ данные из market
    const { data: marketData, error: marketError } = await supabase
      .from('market')
      .select('nft_object');
    
    if (marketError) throw marketError;
    
    // Извлекаем Backdrop из market данных
    marketData?.forEach(item => {
      try {
        if (item.nft_object) {
          const nftObj = typeof item.nft_object === 'string' 
            ? JSON.parse(item.nft_object) 
            : item.nft_object;
          
          if (nftObj.backdrop) {
            const backdropName = nftObj.backdrop.replace(/\d+\.?\d*%/, '').trim();
            if (backdropName) {
              allBackdrops.add(backdropName);
              // Сохраняем полное название с процентом
              backdropWithPercentages[backdropName] = nftObj.backdrop;
            }
          }
        }
      } catch (e) {
        console.warn('Ошибка парсинга nft_object в market:', e);
      }
    });
    
    // Загружаем ВСЕ данные из activity_history
    const { data: activityData, error: activityError } = await supabase
      .from('activity_history')
      .select('nft_object');
    
    if (activityError) throw activityError;
    
    // Извлекаем Backdrop из activity данных
    activityData?.forEach(item => {
      try {
        if (item.nft_object) {
          const nftObj = typeof item.nft_object === 'string' 
            ? JSON.parse(item.nft_object) 
            : item.nft_object;
          
          if (nftObj.backdrop) {
            const backdropName = nftObj.backdrop.replace(/\d+\.?\d*%/, '').trim();
            if (backdropName) {
              allBackdrops.add(backdropName);
              if (!backdropWithPercentages[backdropName]) {
                backdropWithPercentages[backdropName] = nftObj.backdrop;
              }
            }
          }
        }
      } catch (e) {
        console.warn('Ошибка парсинга nft_object в activity:', e);
      }
    });
    
    // Загружаем ВСЕ данные пользователей
    const { data: usersData, error: usersError } = await supabase
      .from('users')
      .select('nft_links');
    
    if (usersError) throw usersError;
    
    // Извлекаем Backdrop из NFT коллекций пользователей
    usersData?.forEach(user => {
      const nftLinks = user.nft_links || [];
      nftLinks.forEach(nftData => {
        if (nftData.backdrop) {
          const backdropName = nftData.backdrop.replace(/\d+\.?\d*%/, '').trim();
          if (backdropName) {
            allBackdrops.add(backdropName);
            if (!backdropWithPercentages[backdropName]) {
              backdropWithPercentages[backdropName] = nftData.backdrop;
            }
          }
        }
      });
    });
    
    // Преобразуем в массив объектов с правильной структурой
    const backdropOptions = Array.from(allBackdrops).map(backdropName => {
      const fullBackdropName = backdropWithPercentages[backdropName] || backdropName;
      const backdropPercentage = fullBackdropName.replace(backdropName, '').trim();
      
      // Генерируем SVG
      const svgContent = generateBackdropSvg(backdropName);
      
      // Определяем ID (используется для фильтрации)
      const backdropId = backdropName.toLowerCase().replace(/\s+/g, '_');
      
      return {
        id: backdropId,
        name: backdropName,
        fullName: fullBackdropName,
        percentage: backdropPercentage,
        svgContent: svgContent,
        rarityText: getBackdropRarityText(backdropName),
        count: 0,
        floorPrice: null
      };
    });
    
    // Сортируем по имени
    backdropOptions.sort((a, b) => a.name.localeCompare(b.name));
    
    console.log(`✅ Загружено ${backdropOptions.length} уникальных Backdrop`);
    
    // Сохраняем в allFilterOptions
    allFilterOptions.value.allBackdrops = backdropOptions;
    
    // Обновляем счетчики для текущей вкладки
    await updateBackdropCountsAndPrices();
    
    return backdropOptions;
    
  } catch (error) {
    console.error('❌ Ошибка загрузки всех Backdrop:', error);
    return [];
  }
};

// ========== ФУНКЦИИ ДЛЯ РАБОТЫ С СИМВОЛАМИ ==========
// Функция для отображения имени символа
const getSymbolDisplayName = (symbol) => {
  if (!symbol || !symbol.name) return 'Неизвестный символ';
  
  // Если имя содержит процент (Activity), убираем его
  if (symbol.name.includes('%')) {
    return symbol.name.replace(/\s*\d+\.?\d*%\s*$/, '').trim();
  }
  
  return symbol.name;
};

// Функция для получения текста редкости
const getSymbolRarityForDisplay = (symbol) => {
  if (!symbol) return '';
  
  console.log('🔍 Данные символа для редкости:', {
    name: symbol.name,
    percentage: symbol.percentage,
    rarityText: symbol.rarityText,
    rarityClass: symbol.rarityClass,
    activeTab: activeTab.value
  });
  
  // ПРИОРИТЕТ 1: Прямое поле с процентом (самый надежный)
  if (symbol.percentage && symbol.percentage.trim()) {
    return symbol.percentage;
  }
  
  // ПРИОРИТЕТ 2: Извлекаем из имени (для Activity)
  if (symbol.name && symbol.name.includes('%')) {
    const match = symbol.name.match(/(\d+\.?\d*)%$/);
    if (match) return `${match[1]}%`;
  }
  
  // ПРИОРИТЕТ 3: Поле rarityText
  if (symbol.rarityText && symbol.rarityText.trim()) {
    return symbol.rarityText;
  }
  
  // ПРИОРИТЕТ 4: Если ничего нет, пытаемся рассчитать редкость
  return calculateRarityFromSymbol(symbol);
};

// Функция для расчета редкости из доступных данных
const calculateRarityFromSymbol = (symbol) => {
  if (!symbol) return '';
  
  // Если есть count и floorPrice, можем рассчитать примерную редкость
  if (symbol.count !== undefined && symbol.floorPrice !== undefined) {
    // Простая логика: чем выше цена и меньше количество = выше редкость
    const rarityScore = symbol.floorPrice / (symbol.count + 1);
    
    if (rarityScore > 10) return 'Легендарный';
    if (rarityScore > 5) return 'Эпический';
    if (rarityScore > 2) return 'Редкий';
    if (rarityScore > 1) return 'Необычный';
    return 'Обычный';
  }
  
  // Если только count
  if (symbol.count !== undefined) {
    if (symbol.count <= 5) return 'Легендарный';
    if (symbol.count <= 20) return 'Эпический';
    if (symbol.count <= 50) return 'Редкий';
    if (symbol.count <= 100) return 'Необычный';
    return 'Обычный';
  }
  
  // Если только floorPrice
  if (symbol.floorPrice !== undefined) {
    if (symbol.floorPrice > 50) return 'Легендарный';
    if (symbol.floorPrice > 20) return 'Эпический';
    if (symbol.floorPrice > 10) return 'Редкий';
    if (symbol.floorPrice > 5) return 'Необычный';
    return 'Обычный';
  }
  
  // Дефолтное значение
  return 'Обычный';
};

// Функция для получения CSS класса редкости
const getRarityClass = (symbol) => {
  const rarityText = getSymbolRarityForDisplay(symbol).toLowerCase();
  
  if (rarityText.includes('легендар') || rarityText.includes('legendary')) {
    return 'legendary';
  }
  if (rarityText.includes('эпич') || rarityText.includes('epic')) {
    return 'epic';
  }
  if (rarityText.includes('редк') || rarityText.includes('rare')) {
    return 'rare';
  }
  if (rarityText.includes('необыч') || rarityText.includes('uncommon')) {
    return 'uncommon';
  }
  
  return 'common';
};

// Функция для обогащения данных символов редкостью
const enrichSymbolsWithRarity = (symbols) => {
  return symbols.map(symbol => {
    // Если у символа уже есть процент, оставляем как есть
    if (symbol.percentage) return symbol;
    
    // Добавляем процент на основе данных
    const rarityText = calculateRarityFromSymbol(symbol);
    let percentage = '';
    
    // Сопоставляем текстовую редкость с процентом
    switch (rarityText.toLowerCase()) {
      case 'легендарный':
      case 'legendary':
        percentage = '1-2%';
        break;
      case 'эпический':
      case 'epic':
        percentage = '3-5%';
        break;
      case 'редкий':
      case 'rare':
        percentage = '6-10%';
        break;
      case 'необычный':
      case 'uncommon':
        percentage = '11-20%';
        break;
      default:
        percentage = '21%+';
    }
    
    return {
      ...symbol,
      percentage: percentage,
      rarityText: rarityText,
      rarityClass: getRarityClass({...symbol, percentage: percentage})
    };
  });
};


