// Исправленная функция extractSymbolFromNft
const extractSymbolFromNft = (item) => {
  try {
    if (!item) return '';
    
    // Если у item уже есть поле symbol
    if (item.symbol) return item.symbol;
    
    // Извлекаем из nft_object
    if (item.nft_object) {
      const nftObj = typeof item.nft_object === 'string' 
        ? JSON.parse(item.nft_object) 
        : item.nft_object;
      
      // Ищем символ в разных возможных местах
      return nftObj.symbol || 
             nftObj.attributes?.symbol || 
             nftObj.properties?.symbol || 
             nftObj.metadata?.symbol || 
             '';
    }
    
    return '';
  } catch (error) {
    console.error('Error extracting symbol from NFT:', error);
    return '';
  }
};

