// Добавьте эти функции рядом с другими функциями (например, после checkRecipientExists):
// Исправленная функция проверки получателя
const checkGiftRecipient = async () => {
  // Если поле пустое, сбрасываем проверку
  if (!giftModal.value.recipientUsername || giftModal.value.recipientUsername.trim() === '') {
    giftModal.value.recipientCheck = {
      loading: false,
      exists: false,
      data: null,
      avatarUrl: null,
      error: null
    };
    return;
  }
  
  // Получаем username текущего пользователя
  const currentUsername = await getCurrentUserUsername();
  
  // Проверяем, не пытается ли пользователь отправить подарок самому себе
  if (currentUsername && 
      giftModal.value.recipientUsername.toLowerCase() === currentUsername.toLowerCase()) {
    giftModal.value.recipientCheck = {
      loading: false,
      exists: true,
      data: { username: currentUsername },
      avatarUrl: null,
      error: 'cannot_self'
    };
    return;
  }
  
  // Устанавливаем состояние загрузки
  giftModal.value.recipientCheck = {
    ...giftModal.value.recipientCheck,
    loading: true,
    exists: false,
    error: null
  };
  
  try {
    const cleanUsername = giftModal.value.recipientUsername.replace('@', '').trim();
    
    if (cleanUsername.length < 2) {
      giftModal.value.recipientCheck = {
        loading: false,
        exists: false,
        data: null,
        avatarUrl: null,
        error: null
      };
      return;
    }
    
    // Используем select с фильтром и limit
    const { data, error } = await supabase
      .from('users')
      .select('username, name, nft_links, telegram, avatar_link')
      .ilike('username', cleanUsername)
      .limit(1);
    
    if (error) {
      console.error('❌ Ошибка поиска пользователя:', error);
      giftModal.value.recipientCheck = {
        loading: false,
        exists: false,
        data: null,
        avatarUrl: null,
        error: null
      };
      return;
    }
    
    // Проверяем есть ли данные
    const userData = data && data.length > 0 ? data[0] : null;
    
    // Парсим avatar_url если он есть
    let avatarUrl = null;
    if (userData?.avatar_link) {
      try {
        if (typeof userData.avatar_link === 'string') {
          if (userData.avatar_link.startsWith('{') || userData.avatar_link.startsWith('[')) {
            const parsed = JSON.parse(userData.avatar_link);
            avatarUrl = parsed.url || parsed;
          } else {
            avatarUrl = userData.avatar_link;
          }
        } else if (typeof userData.avatar_link === 'object' && userData.avatar_link !== null) {
          avatarUrl = userData.avatar_link.url || userData.avatar_link;
        }
      } catch (e) {
        console.warn('⚠️ Ошибка парсинга avatar_link:', e);
      }
    }
    
    giftModal.value.recipientCheck = {
      loading: false,
      exists: !!userData,
      data: userData || null,
      avatarUrl: avatarUrl,
      error: null
    };
    
    if (userData) {
      console.log(`✅ Получатель подарка найден: ${userData.username}`);
    }
    
  } catch (error) {
    console.error('❌ Ошибка проверки получателя подарка:', error);
    giftModal.value.recipientCheck = {
      loading: false,
      exists: false,
      data: null,
      avatarUrl: null,
      error: null
    };
  }
};
// Функция для обновления имени пользователя в поле ввода подарка
const updateGiftUsername = async (event) => {
  let value = event.target.value;
  value = value.replace(/@/g, '');
  giftModal.value.recipientUsername = value;
  
  // Получаем username текущего пользователя
  const currentUsername = await getCurrentUserUsername();
  
  // Проверяем, не пытается ли пользователь отправить подарок самому себе
  if (currentUsername && value.toLowerCase() === currentUsername.toLowerCase()) {
    giftModal.value.recipientCheck = {
      loading: false,
      exists: true,
      data: { username: currentUsername },
      avatarUrl: null,
      error: 'cannot_self'
    };
    return;
  }
  
  checkGiftRecipient();
};
// Функция для получения username текущего пользователя
const getCurrentUserUsername = async () => {
  try {
    if (!currentAccountName.value) return null;
    
    const { data, error } = await supabase
      .from('users')
      .select('username')
      .eq('name', currentAccountName.value)
      .single();
    
    if (error) {
      console.error('❌ Ошибка получения username:', error);
      return null;
    }
    
    return data?.username;
  } catch (error) {
    console.error('❌ Ошибка в getCurrentUserUsername:', error);
    return null;
  }
};
