const showFailAnimation = (operationType = 'general', title = null) => {
  console.log('❌ Показываем анимацию ошибки для:', operationType);
  
  // Определяем текст в зависимости от типа операции
  let animationTitle = title;
  
  if (!animationTitle) {
    const titleMap = {
      'purchase': 'Purchase Failed!',
      'price_update': 'Price Update Failed!',
      'price_edit': 'Price Update Failed!',
      'cancel_sale': 'Cancel Sale Failed!',
      'listing': 'Listing Failed!',
      'sell': 'Sale Failed!',
      'offer_sent': 'Offer Failed!',
      'gift_sent': 'Gift Failed!',
      'transfer': 'Transfer Failed!',
      'withdraw': 'Withdrawal Failed!',
      'general': 'Operation Failed!'
    };
    
    animationTitle = titleMap[operationType] || 'Operation Failed!';
  }
  
  operationAnimation.value = {
    show: true,
    animationData: FailAnimation,
    type: 'fail',
    title: animationTitle,
    operation: operationType
  };
};

// Универсальная функция для воспроизведения анимации
let lottieAnimation = null;
const playLottieAnimation = () => {
  console.log('🎨 playLottieAnimation вызвана, show:', operationAnimation.value.show);
  
  if (operationAnimation.value.show && operationAnimation.value.animationData) {
    console.log('✅ Условия для анимации выполнены, тип:', operationAnimation.value.type);
    
    nextTick(() => {
      if (lottieAnimation) {
        lottieAnimation.destroy();
      }
      
      const container = document.querySelector('.lottie-animation-container');
      if (!container) {
        console.error('❌ Контейнер для анимации не найден');
        // Создаем контейнер динамически если его нет
        const overlay = document.querySelector('.animation-overlay');
        if (overlay) {
          const newContainer = document.createElement('div');
          newContainer.className = 'lottie-animation-container';
          overlay.appendChild(newContainer);
        }
      }
      
      const animationContainer = document.querySelector('.lottie-animation-container');
      if (animationContainer) {
        try {
          lottieAnimation = lottie.loadAnimation({
            container: animationContainer,
            renderer: 'svg',
            loop: false,
            autoplay: true,
            animationData: operationAnimation.value.animationData,
            rendererSettings: {
              preserveAspectRatio: 'xMidYMid meet'
            }
          });
          
          // Обработчик завершения анимации
          lottieAnimation.addEventListener('complete', () => {
            console.log('🏁 Анимация завершена');
            // Ждем 1 секунду на последнем кадре
            setTimeout(() => {
              operationAnimation.value.show = false;
              if (lottieAnimation) {
                lottieAnimation.destroy();
                lottieAnimation = null;
              }
            }, 1000);
          });
          
          // Обработчик ошибки загрузки
          lottieAnimation.addEventListener('error', () => {
            console.error('❌ Ошибка загрузки анимации');
            setTimeout(() => {
              operationAnimation.value.show = false;
            }, 2000);
          });
        } catch (error) {
          console.error('❌ Error loading Lottie animation:', error);
          // Fallback: закрываем через 2 секунды
          setTimeout(() => {
            operationAnimation.value.show = false;
          }, 2000);
        }
      }
    });
  }
};

// Наблюдатель для отслеживания изменений operationAnimation
watch(() => operationAnimation.value.show, (newVal) => {
  if (newVal) {
    playLottieAnimation();
  }
});
