        ? JSON.parse(activityItem.nft_object) 
        : activityItem.nft_object;
      
      return nftObj.symbol || '';
    }
    
    return '';
  } catch (error) {
    console.error('Error extracting symbol from activity:', error);
    return '';
  }
};



