const handleSell = async (nftData) => {
  try {
    console.log('⚡ БЫСТРОЕ открытие модального окна продажи...');
    
    // ПЕРЕД открытием модального окна загружаем актуальную комиссию
    console.log('📥 Загружаем актуальную комиссию перед открытием...');
    await loadPlatformFee(true);
    console.log(`✅ Загружена комиссия: ${platformFee.value}%`);
    
    // Получаем имя NFT для проверки минимальной цены
    const nftName = extractNftDataWithNumber(nftData).name;
    const normalizedNftName = normalizeNftNameForFloorPrice(nftName);
    
    // Получаем минимальную цену асинхронно
    let floorPrice = 0;
    getFloorPriceForNft(normalizedNftName).then(price => {
      floorPrice = price;
      // Обновляем модальное окно с полученной минимальной ценой
      if (sellModal.value.show) {
        sellModal.value.floorPrice = floorPrice;
        // Если цена уже введена, проверяем ее
        if (sellModal.value.price) {
          updateCalculations();
        }
      }
    }).catch(error => {
      console.error('❌ Ошибка получения минимальной цены:', error);
    });
    
    // Открываем модальное окно
    const isHtmlNft = nftData && nftData.url;
    
    sellModal.value = {
      show: true,
      nftType: isHtmlNft ? `html_nft_${extractNftNameFromUrl(nftData.url)}` : nftData.nft_type,
      amount: isHtmlNft ? 1 : '',
      price: floorPrice > 0 ? floorPrice.toFixed(2) : '',
      confirmStep: false,
      isHtmlNft: isHtmlNft,
      totalPrice: 0,
      commission: 0,
      finalAmount: 0,
      nftData: nftData,
      floorPrice: floorPrice,
      priceError: '',
      previewImageUrl: getNftImageUrl(nftData)
    };
    
    console.log(`✅ Модальное окно продажи открыто (минимальная цена: ${floorPrice} TON)`);
    console.log(`💸 Комиссия при открытии: ${platformFee.value}%`);
    
    // Обновляем расчеты с начальной ценой
    updateCalculations();
    
    // Фоновые проверки
    setTimeout(async () => {
      try {
        console.log('🔍 Фоновая проверка дубликатов...');
        
        const conflicts = await checkForImmediateConflicts(nftData);
        
        if (conflicts.hasMarketDuplicates) {
          console.log('🚫 Найдены дубликаты на маркете');
          showNotification('Обнаружены дубликаты на маркете. NFT удалено из вашей коллекции.', 'warning');
          sellModal.value.show = false;
          await removeNftFromUnlisted(nftData);
          await cleanupUnlistedDuplicates();
          await loadUnlistedNfts();
          return;
        }
        
        if (conflicts.hasUnlistedDuplicates) {
          console.log('🚫 Найдены дубликаты в unlisted');
          showNotification('Обнаружены дубликаты в вашей коллекции. Выполняется очистка...', 'info');
          await cleanupUnlistedDuplicates();
          await loadUnlistedNfts();
          sellModal.value.nftData = nftData;
        }
        
        console.log('✅ Фоновые проверки завершены');
        
      } catch (error) {
        console.error('❌ Ошибка при фоновых проверках:', error);
      }
    }, 300);
    
  } catch (error) {
    console.error('❌ Критическая ошибка при открытии модального окна:', error);
    showNotification('Ошибка при подготовке к продаже', 'error');
  }
};


// Updated function updateCalculations с динамической комиссией
const updateCalculations = () => {
  const price = parseFloat(sellModal.value.price) || 0;
  const amount = sellModal.value.amount || 1;
  const floorPrice = sellModal.value.floorPrice || 0;
  
  console.log('🧮 updateCalculations вызвана');
  console.log(`   - ТЕКУЩЕЕ platformFee.value: ${platformFee.value} (тип: ${typeof platformFee.value})`);
  
  // Проверка минимальной цены
  if (floorPrice > 0 && price > 0) {
    if (price < floorPrice) {
      sellModal.value.priceError = `Minimum price: ${floorPrice.toFixed(2)} TON`;
    } else {
      sellModal.value.priceError = '';
    }
  }
  
  // Расчеты с динамической комиссией
  const totalPrice = price * amount;
  
  // Убеждаемся что platformFee.value - число
  let feePercent;
  if (platformFee.value === undefined || platformFee.value === null) {
    console.warn('⚠️ platformFee.value не определен, загружаем заново...');
    // Асинхронно загружаем комиссию
    loadPlatformFee().then(() => {
      // После загрузки пересчитываем
      if (sellModal.value.show) {
        setTimeout(updateCalculations, 100);
      }
    });
    feePercent = 2; // Временное значение
  } else {
    feePercent = Number(platformFee.value);
  }
  
  if (isNaN(feePercent) || feePercent < 0) {
    console.warn('⚠️ Невалидное значение комиссии, используем 2%');
    feePercent = 2;
  }
  
  console.log(`   - Используемая комиссия: ${feePercent}%`);
  
  // Комиссия применяется только для HTML NFT
  const commission = sellModal.value.isHtmlNft ? totalPrice * (feePercent / 100) : 0;
  const finalAmount = totalPrice - commission;
  
  sellModal.value.totalPrice = totalPrice;
  sellModal.value.commission = commission;
  sellModal.value.finalAmount = finalAmount;
  
  console.log(`💰 Расчет комиссии: ${feePercent}% от ${totalPrice} TON = ${commission} TON, к получению: ${finalAmount} TON`);
};

// Add validation function before confirmation
const validateSellPrice = () => {
  const price = parseFloat(sellModal.value.price) || 0;
  const floorPrice = sellModal.value.floorPrice || 0;
  
  if (floorPrice > 0 && price < floorPrice) {
    return {
      valid: false,
      message: `Price must be at least ${floorPrice.toFixed(2)} TON`
    };
  }
  
  if (price <= 0) {
    return {
      valid: false,
      message: 'Please enter a valid price'
    };
  }
  
  return { valid: true };
};

// Показать подтверждение продажи
const showSellConfirmation = () => {
  console.log('🔍 showSellConfirmation вызвана');
  console.log(`   - Текущая комиссия: ${platformFee.value}%`);
  
  // Проверяем обязательные поля
  if (!sellModal.value.price || (!sellModal.value.isHtmlNft && !sellModal.value.amount)) {
    showNotification('Пожалуйста, укажите корректные данные', 'error');
