    sellModal.value.priceError = `Цена должна быть не менее ${floorPrice.toFixed(2)} TON`;
    
    if (navigator.vibrate) {
      navigator.vibrate(200);
    }
    
    showNotification(`Минимальная цена: ${floorPrice.toFixed(2)} TON`, 'error');
