  }
  
  // Очищаем ошибки
  sellModal.value.priceError = '';
  
  // Обновляем расчеты перед подтверждением
  updateCalculations();
  
  // Переходим к подтверждению
  sellModal.value.confirmStep = true;
  
  console.log(`✅ Цена ${price} TON соответствует минимальной цене ${floorPrice} TON`);
  console.log(`💸 Комиссия платформы: ${platformFee.value}%`);
};


const getAllNftOptions = async () => {
  const currentTab = activeTab.value;
  console.log(`📊 Получение NFT опций для вкладки: ${currentTab}`);
  
  // Получаем все данные для текущей вкладки
  const allItems = getAllDataForFiltering();
  console.log(`📊 Всего элементов для фильтрации: ${allItems.length}`);
  
  const nftOptionsMap = new Map();
  const contentPromises = [];
  
  // Обрабатываем каждый элемент
  allItems.forEach((item, index) => {
    try {
      const nftName = getNftDisplayName(item.nft_type, item.nft_object);
      const normalizedName = normalizeNftName(nftName);
      
      if (!normalizedName || normalizedName === 'unknown') {
        return;
      }
      
      if (!nftOptionsMap.has(normalizedName)) {
        const option = {
          name: nftName,
          normalizedName: normalizedName,
          originalType: normalizedName,
          count: 0,
          floorPrice: null,
          imageUrl: default_nft_image,
          htmlContent: null,
          isLoading: true,
        };
        
        nftOptionsMap.set(normalizedName, option);
        
        // Асинхронно генерируем контент с использованием generateNftOptionImageUrl
        const contentPromise = (async () => {
          try {
            // ИСПОЛЬЗУЕМ НОВУЮ ФУНКЦИЮ ДЛЯ ГЕНЕРАЦИИ URL
            const imageUrl = await generateNftOptionImageUrl(nftName);
            
            // Генерируем HTML контент на основе этого URL
            const content = await generateNftImageContentFromUrl(nftName, imageUrl);
            
            option.imageUrl = content.imageUrl;
            option.htmlContent = content.htmlContent;
            option.isLoading = false;
            
            console.log(`✅ Сгенерирован контент для ${nftName}:`, {
              hasHtml: !!content.htmlContent,
              imageUrl: content.imageUrl
            });
          } catch (error) {
            console.error(`❌ Ошибка для ${nftName}:`, error);
            option.imageUrl = default_nft_image;
            option.htmlContent = null;
            option.isLoading = false;
          }
        })();
        
        contentPromises.push(contentPromise);
      }
      
      // Обновляем счетчик
      const option = nftOptionsMap.get(normalizedName);
      option.count++;
      
      // Обновляем минимальную цену
      if (item.price_per_unit) {
        const price = parseFloat(item.price_per_unit);
        if (!option.floorPrice || price < option.floorPrice) {
          option.floorPrice = price;
        }
      }
      
    } catch (error) {
      console.warn(`⚠️ Ошибка обработки элемента ${index}:`, error);
    }
  });
  
  // Ждем завершения всех генераций контента
  await Promise.allSettled(contentPromises);
  
  // Преобразуем Map в массив
  const options = Array.from(nftOptionsMap.values());
  console.log(`✅ Собрано ${options.length} уникальных NFT опций`);
  
  return options;
};

// АГРЕССИВНАЯ ФУНКЦИЯ ОЧИСТКИ ДУБЛИКАТОВ МАРКЕТА
const cleanupMarketDuplicates = async () => {
  try {
    console.log('🧹 Агрессивная очистка дубликатов маркета...');
    
    const { data: allItems, error } = await supabase
      .from('market')
      .select('*')
      .order('created_at', 'asc');

    if (error) throw error;
    if (!allItems || allItems.length === 0) return;

    const itemsToKeep = new Map();
    const duplicatesToDelete = [];

    allItems.forEach(item => {
      // Создаем комплексный ключ для каждого объявления
      let key = `${item.seller}_${item.nft_type}`;
      
      // Для HTML NFT добавляем URL в ключ
      if (item.nft_object) {
        try {
          const nftObj = typeof item.nft_object === 'string' ? JSON.parse(item.nft_object) : item.nft_object;
          if (nftObj.url) {
            key += `_${nftObj.url}`;
          }
        } catch (e) {
          console.error('Error parsing nft_object:', e);
        }
      } else {
        // Для обычных NFT используем цену и количество
        key += `_${item.price_per_unit}_${item.amount || 1}`;
      }

      // Если ключ уже существует, помечаем как дубликат
      if (itemsToKeep.has(key)) {
        duplicatesToDelete.push(item.id);
        console.log(`🚫 Найден дубликат маркета: ${key} (ID: ${item.id})`);
      } else {
        itemsToKeep.set(key, item);
      }
    });

    // УДАЛЯЕМ ВСЕ ДУБЛИКАТЫ
    if (duplicatesToDelete.length > 0) {
      console.log(`🗑️ Удаляем ${duplicatesToDelete.length} дубликатов маркета...`);
      
      const { error: deleteError } = await supabase
        .from('market')
        .delete()
        .in('id', duplicatesToDelete);
        
      if (deleteError) throw deleteError;
      
      console.log(`✅ Удалено ${duplicatesToDelete.length} дубликатов маркета`);
    } else {
      console.log('✅ Дубликаты маркета не найдены');
    }
    
  } catch (error) {
    console.error('❌ Ошибка очистки дубликатов маркета:', error);
  }
};

// АГРЕССИВНАЯ ФУНКЦИЯ ОЧИСТКИ ДУБЛИКАТОВ UNLISTED
const cleanupUnlistedDuplicates = async () => {
  try {
    console.log('🧹 Агрессивная очистка дубликатов unlisted...');
    
    const { data: userData, error } = await supabase
      .from('users')
      .select('name, nft_links')
      .eq('name', currentAccountName.value)
      .single();

    if (error) throw error;

    const nftLinks = userData?.nft_links || [];
    if (nftLinks.length === 0) return;

    const uniqueNfts = [];
    const seenUrls = new Set();

    nftLinks.forEach(nft => {
      const nftUrl = typeof nft === 'object' ? nft.url : nft;
      
      if (!seenUrls.has(nftUrl)) {
        seenUrls.add(nftUrl);
        uniqueNfts.push(nft);
      } else {
        console.log(`🚫 Найден дубликат unlisted: ${nftUrl}`);
      }
    });

    // Если есть дубликаты, обновляем базу
    if (uniqueNfts.length !== nftLinks.length) {
      console.log(`🗑️ Удаляем ${nftLinks.length - uniqueNfts.length} дубликатов unlisted...`);
      
      const { error: updateError } = await supabase
        .from('users')
        .update({ nft_links: uniqueNfts })
        .eq('name', currentAccountName.value);

      if (updateError) throw updateError;
      
      console.log(`✅ Удалено ${nftLinks.length - uniqueNfts.length} дубликатов unlisted`);
    } else {
      console.log('✅ Дубликаты unlisted не найдены');
    }
    
  } catch (error) {
    console.error('❌ Ошибка очистки дубликатов unlisted:', error);
  }
};
