// Функция для начисления реферального вознаграждения
const addReferralBonus = async (referrerData, commissionAmount, buyerName, item) => {
  try {
    if (!referrerData || !referrerData.name) {
      console.log('ℹ️ Нет данных о реферере для начисления');
      return false;
    }
    
    // Рассчитываем 0.1% от комиссии
    const referralBonus = commissionAmount * 0.001; // 0.1% = 0.001
    const roundedBonus = Math.round(referralBonus * 1000) / 1000; // Округляем до 3 знаков
    
    if (roundedBonus <= 0) {
      console.log(`ℹ️ Сумма вознаграждения слишком мала: ${roundedBonus} TON`);
      return false;
    }
    
    console.log(`💰 Начисление реферального бонуса: ${roundedBonus} TON (0.1% от комиссии ${commissionAmount} TON)`);
    
    // Получаем текущий баланс реферера
    const { data: referrerUser, error: fetchError } = await supabase
      .from('users')
      .select('ton_balance, operation_history, username')
      .eq('name', referrerData.name)
      .single();
    
    if (fetchError) {
      console.error('❌ Ошибка получения данных реферера:', fetchError);
      return false;
    }
    
    const currentBalance = parseFloat(referrerUser.ton_balance) || 0;
    const newBalance = currentBalance + roundedBonus;
    
    // Формируем ссылку на изображение NFT
    let imageLink = null;
    if (item && item.nft_object && item.nft_object.url) {
      imageLink = item.nft_object.url;
    } else if (item && item.url) {
      imageLink = item.url;
    } else {
      const nftName = getNftDisplayName(item?.nft_type, item?.nft_object) || 'Unknown';
      const nftId = extractNftIdFromData(item?.nft_object) || 'unknown';
      imageLink = `https://nft.fragment.com/gift/${nftName.replace(/\s+/g, '')}-${nftId}.webp`;
    }
    
    // Создаем запись операции
    const referralOperation = {
      id: `op_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
      type: 'referral',
      amount: roundedBonus.toString(),
      currency: 'TON',
      timestamp: new Date().toISOString(),
      from_user: buyerName,
      commission_source: commissionAmount,
      referral_percentage: '0.1%',
      description: `Referral bonus from purchase by ${buyerName}`,
      link: imageLink
    };
    
    // Обновляем историю операций
    const currentHistory = referrerUser.operation_history || [];
    const updatedHistory = [referralOperation, ...currentHistory].slice(0, 100);
    
    // Обновляем баланс и историю реферера
    const { error: updateError } = await supabase
      .from('users')
      .update({
        ton_balance: newBalance,
        operation_history: updatedHistory
      })
      .eq('name', referrerData.name);
    
    if (updateError) {
      console.error('❌ Ошибка обновления баланса реферера:', updateError);
      return false;
    }
    
    console.log(`✅ Реферальный бонус ${roundedBonus} TON начислен пользователю ${referrerData.name}`);
    console.log('📝 Операция реферала записана в историю:', referralOperation);
    
    // Отправляем уведомление рефереру в Telegram (если есть)
    if (referrerData.telegram) {
      try {
        const nftName = getNftDisplayName(item?.nft_type, item?.nft_object) || 'NFT';
        const messageText = `🎉 *Реферальный бонус!*\n\n` +
          `Ваш реферал *${buyerName}* совершил покупку.\n\n` +
          `🎁 *${nftName}*\n` +
          `💰 Вы получили: *${roundedBonus} TON*\n` +
          `📊 Комиссия с продажи: ${commissionAmount} TON\n` +
          `🔗 Процент: 0.1% от комиссии\n\n` +
          `Спасибо, что приглашаете друзей в DROPS! 🚀`;
        
        const telegramUrl = 'https://api.telegram.org/bot8549009179:AAES5a75EWbQs5roRKyosjUiNCTCgSUwRB4/sendMessage';
        
        await fetch(telegramUrl, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            chat_id: referrerData.telegram,
            text: messageText,
            parse_mode: 'Markdown'
          })
        });
        console.log(`📨 Уведомление о реферальном бонусе отправлено рефереру ${referrerData.name}`);
      } catch (telegramError) {
        console.error('❌ Ошибка отправки уведомления рефереру:', telegramError);
      }
    }
    
    return true;
    
  } catch (error) {
    console.error('❌ Ошибка в addReferralBonus:', error);
    return false;
  }
};
