const forceCleanupAllDuplicates = async () => {
  try {
    console.log('💥 ЗАПУСК ПРИНУДИТЕЛЬНОЙ ОЧИСТКИ ВСЕХ ДУБЛИКАТОВ...');
    
    // Очистка маркета
