// 3. Меняем функцию checkRecipientExists
const checkRecipientExists = async () => {
  if (!transferModal.value.recipientUsername) { 
    recipientCheck.value = { loading: false, exists: false, data: null };
    return;
  }
  
  recipientCheck.value.loading = true;
  
  try {
    const cleanUsername = transferModal.value.recipientUsername.replace('@', '').trim(); // Очищаем @
    
    // ДОБАВЛЯЕМ avatar_link В SELECT
    const { data, error } = await supabase
      .from('users')
      .select('username, name, nft_links, telegram, avatar_link') // Добавляем avatar_link
      .ilike('username', cleanUsername)
      .maybeSingle();
    
    if (error) {
      console.error('❌ Ошибка поиска пользователя:', error);
      recipientCheck.value = { loading: false, exists: false, data: null };
      return;
    }
    
    recipientCheck.value = {
      loading: false,
      exists: !!data,
      data: data || null,
      // Парсим avatar_link если он есть
      avatarUrl: data?.avatar_link ? parseAvatarUrl(data.avatar_link) : null
    };
    
    if (data) {
      console.log(`✅ Пользователь найден: ${data.username}`);
      if (data.avatar_link) {
        console.log(`🖼️ Аватарка найдена:`, data.avatar_link);
      }
    }
    
  } catch (error) {
    console.error('❌ Ошибка проверки получателя:', error);
    recipientCheck.value = { loading: false, exists: false, data: null };
  }
};

// Вспомогательная функция для парсинга avatar_link
const parseAvatarUrl = (avatarLink) => {
  try {
    // Если avatar_link уже строка с URL
    if (typeof avatarLink === 'string') {
      // Проверяем, может это JSON строка
      if (avatarLink.startsWith('{') || avatarLink.startsWith('[')) {
        try {
          const parsed = JSON.parse(avatarLink);
          return parsed.url || parsed;
        } catch (e) {
          // Если не удалось распарсить, возвращаем как есть
          return avatarLink;
        }
      }
      return avatarLink;
    }
    
    // Если avatar_link это объект
    if (typeof avatarLink === 'object' && avatarLink !== null) {
      return avatarLink.url || avatarLink;
    }
    
    return null;
  } catch (error) {
    console.error('❌ Ошибка парсинга avatar_link:', error);
    return null;
  }
};

