// Функция для извлечения NFT ID из Activity
const extractNftIdFromActivityItem = (activityItem) => {
  try {
    if (activityItem.nft_object) {
      const nftObj = typeof activityItem.nft_object === 'string' 
        ? JSON.parse(activityItem.nft_object) 
        : activityItem.nft_object;
      
      if (nftObj.url) {
        const match = nftObj.url.match(/-(\d+)(?:\?|$)/);
        return match ? match[1] : '';
      }
    }
    return '';
  } catch (error) {
    console.error('Error extracting NFT ID from activity:', error);
    return '';
  }
};
