  if (error) {
    console.error('Ошибка загрузки аватара:', error);
    return;
  }
  
  if (data?.avatar_link) {
    try {
      const avatar = typeof data.avatar_link === 'string' 
        ? JSON.parse(data.avatar_link) 
        : data.avatar_link;
      userAvatarUrl.value = avatar.url;
    } catch (e) {
      userAvatarUrl.value = null;
    }
  }
};


const fetchUserBalance = async () => {
  try {
    if (!currentAccountName.value) return;
    
    const { data, error } = await supabase
      .from('users')
      .select('ton_balance')
      .eq('name', currentAccountName.value)
      .single();
      
    if (error) throw error;
    
    if (data) {
      const balance = parseFloat(data.ton_balance || 0);
      
      // Форматируем: если число целое - без .00, если дробное - с округлением до 2 знаков
      if (Number.isInteger(balance)) {
        tonBalance.value = balance.toString(); // 67 → "67"
      } else {
        // Округляем до 2 знаков и убираем лишние нули в конце
        tonBalance.value = balance.toFixed(2).replace(/\.?0+$/, ''); // 67.5 → "67.5", 67.55 → "67.55"
      }
      
      console.log('💰 Баланс пользователя загружен:', tonBalance.value);
    }
  } catch (error) {
    console.error('❌ Ошибка загрузки баланса:', error);
    tonBalance.value = '0';
  }
};
// Функция строгой проверки дубликатов
const checkForDuplicateListing = async (sellData) => {
  try {
    const { data: existingItems, error } = await supabase
      .from('market')
      .select('*')
      .eq('seller', currentAccountName.value);

    if (error) throw error;
    if (!existingItems || existingItems.length === 0) return false;

    // Проверяем каждый существующий item на дубликат
    for (const existingItem of existingItems) {
      if (areItemsDuplicates(existingItem, sellData)) {
        console.warn('🚫 Найден дубликат при создании:', {
          existing: existingItem,
          new: sellData
        });
        return true;
      }
    }

    return false;
  } catch (error) {
    console.error('❌ Ошибка проверки дубликатов:', error);
    return false; // В случае ошибки разрешаем создание
  }
};

// Функция для обновления статистики в таблице configurations
const updateConfigurationsStats = async (amount, operationType) => {
  try {
    console.log(`📊 Обновление статистики: ${operationType}, сумма: ${amount} TON`);
    
    // Округляем до тысячных (3 знака после запятой)
    const roundedAmount = Math.round(amount * 1000) / 1000;
    
    // Получаем текущие данные из таблицы configurations
    const { data: configData, error: fetchError } = await supabase
      .from('configurations')
      .select('total_fee, total_operations')
      .limit(1)
      .maybeSingle();
    
    if (fetchError) {
      console.error('❌ Ошибка получения данных configurations:', fetchError);
      return;
    }
    
    // Текущие значения
    const currentTotalFee = parseFloat(configData?.total_fee || 0);
    const currentOperations = configData?.total_operations || [];
    
    // Новое значение
    const newTotalFee = currentTotalFee + roundedAmount;
    
    // Создаем новую запись операции с явным указанием типа
    const newOperation = {
      id: `op_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
      type: operationType, // 'offer_commission', 'offer_acceptance_commission', 'sale_commission', etc.
      originalAmount: amount.toString(),
      amount: roundedAmount.toString(),
      timestamp: new Date().toISOString(),
      currency: 'TON',
      description: `Commission from ${operationType}`
    };
    
    // Обновляем массив операций
    const updatedOperations = [newOperation, ...currentOperations].slice(0, 1000);
    
    // Обновляем таблицу configurations
    const { error: updateError } = await supabase
      .from('configurations')
      .upsert({
        id: configData?.id || 1,
        total_fee: newTotalFee,
        total_operations: updatedOperations,
        updated_at: new Date().toISOString()
      }, { onConflict: 'id' });
    
    if (updateError) {
      console.error('❌ Ошибка обновления configurations:', updateError);
    } else {
      console.log(`✅ Статистика обновлена: total_fee=${newTotalFee} TON, операция ${operationType} добавлена`);
    }
    
  } catch (error) {
    console.error('❌ Ошибка в updateConfigurationsStats:', error);
  }
};

