// Вспомогательная функция для получения объекта NFT
const getNftObjectForActions = (item) => {
  if (!item) return null;
  
  // Если item уже является nft_object
  if (item.url && item.gift_id) {
    return item;
  }
  
  // Если item имеет свойство nft_object
  if (item.nft_object) {
    return typeof item.nft_object === 'string' 
      ? JSON.parse(item.nft_object) 
      : item.nft_object;
  }
  
  // Возвращаем как есть
  return item;
};
