        ? JSON.parse(item.nft_object) 
        : item.nft_object;
      
      if (nftObject && nftObject.symbol && nftObject.symbol.trim()) {
        const symbolData = extractSymbolWithPercentageFromNftObject(nftObject);
        if (symbolData.name) {
