// Функция для расчета комиссии
const calculateCommission = (price) => {
  if (!price || price <= 0) return '0.00';
  
  // Используем platformFee из БД (уже загруженную)
  let feePercent = platformFee.value;
  
  // Если комиссия не загружена, используем временное значение
  if (feePercent === null || feePercent === undefined) {
    console.warn('⚠️ Комиссия не загружена, используется временное значение 2%');
    feePercent = 2;
  }
  
  const commission = parseFloat(price) * (feePercent / 100);
  return commission.toFixed(2);
};

// Функция для расчета суммы к получению после вычета комиссии
const calculateReceiveAmount = (price) => {
  if (!price || price <= 0) return '0.00';
  
  // Используем platformFee из БД
  let feePercent = platformFee.value;
  
  // Если комиссия не загружена, используем временное значение
  if (feePercent === null || feePercent === undefined) {
    console.warn('⚠️ Комиссия не загружена, используется временное значение 2%');
    feePercent = 2;
  }
  
  const commission = parseFloat(price) * (feePercent / 100);
  const receiveAmount = parseFloat(price) - commission;
  return receiveAmount.toFixed(2);
};
