// Функция для извлечения данных символа с процентом
const extractSymbolWithPercentageFromNftObject = (nftObject) => {
  if (!nftObject || !nftObject.symbol) {
    return { name: '', percentage: 0 };
  }
  
  const symbol = nftObject.symbol.trim();
  // Извлекаем процент из строки типа "Handset 0.5%"
  const percentageMatch = symbol.match(/(\d+\.?\d*)%/);
  const percentage = percentageMatch ? parseFloat(percentageMatch[1]) : 0;
  
  // Извлекаем название (без процента)
  const name = symbol.replace(/(\d+\.?\d*%)/, '').trim();
  
  return { name, percentage };
};

// Функция для извлечения данных бэкдропа с процентом
const extractBackdropWithPercentageFromNftObject = (nftObject) => {
  if (!nftObject || !nftObject.backdrop) {
    return { name: '', percentage: 0 };
  }
  
  const backdrop = nftObject.backdrop.trim();
  // Извлекаем процент из строки типа "Dark Lilac 2%"
  const percentageMatch = backdrop.match(/(\d+\.?\d*)%/);
  const percentage = percentageMatch ? parseFloat(percentageMatch[1]) : 0;
  
  // Извлекаем название (без процента)
  const name = backdrop.replace(/(\d+\.?\d*%)/, '').trim();
  
  return { name, percentage };
};
