// 4. Упрощенная функция getRandomModelFromNft
// Исправленная функция для получения случайной модели из базы данных
// Функция для получения случайной модели из колонки NFT
// Функция для получения случайной модели из колонки NFT
// Простая функция для получения случайной модели
const getRandomModelFromNft = async (nftName) => {
  try {
    // Получаем данные из колонки
    const { data, error } = await supabase
      .from('nft')
      .select(`"${nftName.replace(/"/g, '""')}"`)
      .limit(1);

    if (error || !data || data.length === 0) {
      return 'hauntedhouse';
    }

    const modelsData = data[0][nftName];
    if (!modelsData) return 'hauntedhouse';

    // Обрабатываем данные
    let modelsArray = [];
    
    if (Array.isArray(modelsData)) {
      modelsArray = modelsData;
    } else if (typeof modelsData === 'string') {
      try {
        modelsArray = JSON.parse(modelsData);
      } catch {
        return 'hauntedhouse';
      }
    } else {
      return 'hauntedhouse';
    }

    if (!Array.isArray(modelsArray) || modelsArray.length === 0) {
      return 'hauntedhouse';
    }

    // Выбираем случайную модель
    const randomIndex = Math.floor(Math.random() * modelsArray.length);
    const randomModel = modelsArray[randomIndex];
    
    // Форматируем
    let modelName = randomModel.toString()
      .replace(/\s*[—\-]\s*\d+\.?\d*%\s*$/i, '')
      .replace(/\s*\d+\.?\d*%\s*$/i, '')
      .trim();

    const formattedModelName = modelName
      .toLowerCase()
      .replace(/[^a-z0-9]/g, '')
      .replace(/\s+/g, '');

    return formattedModelName || 'hauntedhouse';

  } catch (error) {
    return 'hauntedhouse';
  }
};

// Функция для получения резервной модели
const getFallbackModel = (nftName) => {
  console.log(`🔄 Используем резервную модель для: "${nftName}"`);
  
  const fallbackModels = {
    'jack-in-the-box': 'hauntedhouse',
    'plush pepe': 'happybrownie',
    'lol pop': 'rainbowpop',
    'happy brownie': 'chocolatebrownie',
  };
  
  const normalizedNftName = nftName.toLowerCase();
  for (const [key, model] of Object.entries(fallbackModels)) {
    if (normalizedNftName.includes(key) || key.includes(normalizedNftName)) {
      return model;
    }
  }
  
  return 'hauntedhouse'; // Дефолтная модель
};


