// Функция для загрузки ВСЕХ уникальных значений из таблицы market
const loadAllMarketFilterOptions = async () => {
  try {
    console.log('🎯 Загрузка ВСЕХ уникальных значений для фильтров из market...');
    
    // Загружаем ВСЕ записи из таблицы market
    const { data: allMarketItems, error } = await supabase
      .from('market')
      .select('nft_object')
      .order('created_at', { ascending: false });

    if (error) {
      console.error('❌ Ошибка загрузки данных из market для фильтров:', error);
      return;
    }

    // Инициализируем наборы для уникальных значений
    const nftSet = new Set();
    const modelSet = new Set();
    const symbolSet = new Set();
    const backdropSet = new Set();

    // Обрабатываем каждую запись
    allMarketItems.forEach(item => {
      try {
        const nftObject = typeof item.nft_object === 'string' 
          ? JSON.parse(item.nft_object) 
          : item.nft_object;
        
        if (nftObject) {
          // Добавляем NFT тип (name)
          if (nftObject.name && nftObject.name.trim()) {
            const cleanName = nftObject.name.trim();
            nftSet.add(cleanName);
          }
          
          // Добавляем модель
          if (nftObject.model && nftObject.model.trim()) {
            // Извлекаем название модели (без процента)
            const modelName = nftObject.model.split(' ')[0].trim();
            if (modelName && modelName.toLowerCase() !== 'не указано') {
              modelSet.add(modelName);
            }
          }
          
          // Добавляем символ
          if (nftObject.symbol && nftObject.symbol.trim()) {
            const symbolName = nftObject.symbol.split(' ')[0].trim();
            if (symbolName && symbolName.toLowerCase() !== 'не указано') {
              symbolSet.add(symbolName);
            }
          }
          
          // Добавляем бэкдроп
          if (nftObject.backdrop && nftObject.backdrop.trim()) {
            const backdropName = nftObject.backdrop.split(' ')[0].trim();
            if (backdropName && backdropName.toLowerCase() !== 'не указано') {
              backdropSet.add(backdropName);
            }
          }
        }
      } catch (parseError) {
        console.warn('⚠️ Ошибка парсинга nft_object:', parseError);
      }
    });

    // Сохраняем результаты
    allFilterOptions.value = {
      nft: Array.from(nftSet).sort(),
      model: Array.from(modelSet).sort(),
      symbol: Array.from(symbolSet).sort(),
      backdrop: Array.from(backdropSet).sort()
    };

    console.log('✅ Загружены ВСЕ опции для фильтров из market:', {
      nft: allFilterOptions.value.nft,
      model: allFilterOptions.value.model,
      symbol: allFilterOptions.value.symbol,
      backdrop: allFilterOptions.value.backdrop
    });

  } catch (error) {
    console.error('❌ Общая ошибка загрузки опций фильтров:', error);
  }
};

