// Функция для проверки структуры таблицы nft
// Функция для проверки структуры таблицы nft
const checkNftTableStructure = async () => {
  try {
    console.log('🔍 Проверка структуры таблицы nft...');
    
    // Получаем информацию о таблице
    const { data, error } = await supabase
      .from('nft')
      .select('*')
      .limit(1);

    if (error) {
      console.error('❌ Ошибка при проверке таблицы:', error);
      return;
    }

    if (data && data.length > 0) {
      const record = data[0];
      console.log('📊 Первая запись в таблице nft:', record);
      console.log('📋 Ключи (названия колонок):', Object.keys(record));
      
      // Показываем все колонки
      Object.keys(record).forEach(col => {
        const value = record[col];
        const type = typeof value;
        const isArray = Array.isArray(value);
        const isObject = type === 'object' && value !== null && !isArray;
        
        console.log(`   "${col}":`, {
          type: type,
          isArray: isArray,
          isObject: isObject,
          value: isArray ? `Array[${value.length}]` : 
                 isObject ? 'Object' : 
                 value ? String(value).substring(0, 50) + '...' : 
                 'null/empty'
        });
      });
    } else {
      console.log('📭 Таблица nft пуста');
    }
    
  } catch (error) {
    console.error('💥 Ошибка при проверке структуры:', error);
  }
};

const checkAndRefundExpiredOffer = async (itemId, buyerName) => {
  try {
    console.log('🔍 Проверяем доступность объявления для возврата средств...', itemId);
    
    // 1. Проверяем, существует ли еще объявление
    const { data: marketItem, error } = await supabase
      .from('market')
      .select('id, seller, status')
      .eq('id', itemId)
      .single();
    
    // Если объявление не найдено или продано
    if (error || !marketItem) {
      console.log('⚠️ Объявление не найдено, возвращаем средства...');
      
      // Находим активный оффер этого пользователя
      const { data: activeOffer } = await supabase
        .from('offers')
        .select('id, offer_price, buyer_name')
        .eq('item_id', itemId)
        .eq('buyer_name', buyerName)
        .eq('status', 'pending')
        .single();
      
      if (activeOffer) {
        // Возвращаем средства
        const { data: buyerData } = await supabase
          .from('users')
          .select('ton_balance')
          .eq('name', buyerName)
          .single();
        
        if (buyerData) {
          const currentBalance = parseFloat(buyerData.ton_balance) || 0;
          const newBalance = currentBalance + parseFloat(activeOffer.offer_price);
          
          await supabase
            .from('users')
            .update({ ton_balance: newBalance })
            .eq('name', buyerName);
          
          // Обновляем статус оффера
          await supabase
            .from('offers')
            .update({ 
              status: 'refunded',
              refund_reason: 'Item sold to another buyer',
              refunded_at: new Date().toISOString()
            })
            .eq('id', activeOffer.id);
          
          console.log('✅ Средства возвращены покупателю:', buyerName);
          
          // Обновляем локальный баланс если это текущий пользователь
          if (buyerName === currentAccountName.value) {
            tonBalance.value = newBalance.toString();
          }
          
          return {
            refunded: true,
            amount: activeOffer.offer_price,
            reason: 'Item sold to another buyer'
          };
        }
      }
    }
    
    return { refunded: false };
    
  } catch (error) {
    console.error('❌ Ошибка проверки возврата средств:', error);
    return { refunded: false, error: error.message };
  }
};
// Новая функция для генерации URL в формате storage.googleapis.com
const generateStorageUrl = (nftName, modelName = '', patternName = '', backdropName = '') => {
  try {
    // Очищаем названия от процентов
    const cleanNftName = nftName.replace(/\s*\d+\.?\d*%\s*$/, '').trim();
    const cleanModel = modelName.replace(/\s*\d+\.?\d*%\s*$/, '').trim();
    const cleanPattern = patternName.replace(/\s*\d+\.?\d*%\s*$/, '').trim();
    const cleanBackdrop = backdropName.replace(/\s*\d+\.?\d*%\s*$/, '').trim();
    
    // Кодируем каждую часть для URL
    const encodedNftName = encodeURIComponent(cleanNftName);
    const encodedModel = encodeURIComponent(cleanModel);
    const encodedPattern = encodeURIComponent(cleanPattern);
    const encodedBackdrop = encodeURIComponent(cleanBackdrop);
    
    // Если есть все параметры - полный формат
    if (cleanModel && cleanPattern && cleanBackdrop) {
      return `https://storage.googleapis.com/generate_gifts/${encodedNftName}/${encodedModel}_${encodedPattern}_${encodedBackdrop}.png`;
    }
    
    // Если только модель и название
    if (cleanModel) {
      return `https://storage.googleapis.com/generate_gifts/${encodedNftName}/${encodedModel}.png`;
    }
    
    // Fallback
    console.warn(`⚠️ Недостаточно данных для генерации URL: nftName=${cleanNftName}, model=${cleanModel}`);
    return default_nft_image;
    
  } catch (error) {
    console.error('Error generating storage URL:', error);
    return default_nft_image;
  }
};
// Функция для генерации URL объявлений в новом формате
// Функция для генерации URL объявлений в новом формате
const generateMarketImageUrl = (nftData) => {
  try {
    if (!nftData) return default_nft_image;
    
    // Извлекаем данные из nft_object
    let nftObj = nftData;
    if (nftData.nft_object) {
      nftObj = typeof nftData.nft_object === 'string' 
        ? JSON.parse(nftData.nft_object) 
        : nftData.nft_object;
    }
    
    // Получаем название NFT (очищаем от процентов)
    let nftName = '';
    if (nftObj.name) {
      nftName = nftObj.name;
    } else if (nftData.nft_type) {
      nftName = getNftDisplayName(nftData.nft_type, nftObj);
    }
    
    // Очищаем название от процентов
    const cleanNftName = nftName.replace(/\s*\d+\.?\d*%\s*$/, '').trim();
    
    // Получаем модель (только название, без процента)
    let modelName = '';
    if (nftObj.model) {
      modelName = nftObj.model.replace(/\s*\d+\.?\d*%\s*$/, '').trim();
    }
    
    // Получаем узор/symbol (только название, без процента)
    let patternName = '';
    if (nftObj.symbol) {
      patternName = nftObj.symbol.replace(/\s*\d+\.?\d*%\s*$/, '').trim();
    }
    
    // Получаем фон/backdrop (только название, без процента)
    let backdropName = '';
    if (nftObj.backdrop) {
      backdropName = nftObj.backdrop.replace(/\s*\d+\.?\d*%\s*$/, '').trim();
    }
    
    console.log('🔍 generateMarketImageUrl данные:', {
      cleanNftName,
      modelName,
      patternName,
      backdropName
    });
    
    // Если есть все три компонента - генерируем полный URL
    // ПОРЯДОК: Модель_Фон_Узор (как в примере: Spaceship_Ivory White_Avocado)
    if (cleanNftName && modelName && backdropName && patternName) {
      const encodedNft = encodeURIComponent(cleanNftName);
      const encodedModel = encodeURIComponent(modelName);
      const encodedBackdrop = encodeURIComponent(backdropName);
      const encodedPattern = encodeURIComponent(patternName);
      
      return `https://storage.googleapis.com/generate_gifts/${encodedNft}/${encodedModel}_${encodedBackdrop}_${encodedPattern}.png`;
    }
    
    // Если только название и модель
    if (cleanNftName && modelName) {
      const encodedNft = encodeURIComponent(cleanNftName);
      const encodedModel = encodeURIComponent(modelName);
      return `https://storage.googleapis.com/generate_gifts/${encodedNft}/${encodedModel}.png`;
    }
    
    // Если нет полных данных - используем старый формат
    console.log('⚠️ Недостаточно данных для нового формата, используем старый URL');
    const nftId = extractNftIdFromData(nftObj);
    const urlMatch = nftObj.url?.match(/\/nft\/([^-]+)/);
    const oldNftName = urlMatch ? urlMatch[1] : 'unknown';
    return `https://nft.fragment.com/gift/${oldNftName}-${nftId}.webp`;
    
  } catch (error) {
    console.error('❌ Ошибка генерации URL объявления:', error);
    return default_nft_image;
  }
};
