// Обновленная функция для Activity HTML
const generateNftHtmlForListActivity = (nftData) => {
  try {
    const nftId = extractNftIdFromData(nftData);
    const nftNameFromData = extractNftDataWithNumber(nftData).name || 'NFT';
    
    // Используем ту же логику, что и для Fullscreen
    const imageUrl = getActivityImageUrl(nftData);
    
    return `
<!DOCTYPE html>
<html>
<head>
  <title>NFT Display - ${nftNameFromData}-${nftId}</title>
  <style>
    body, html {
      margin: 0;
      padding: 0;
      width: 100%;
      height: 100%;
      background: transparent;
      overflow: hidden;
      cursor: pointer;
    }
    #image-container {
      width: 100%;
      height: 100%;
      display: flex;
      align-items: center;
      justify-content: center;
      background: transparent;
    }
    .nft-image {
      max-width: 100%;
      max-height: 100%;
      object-fit: contain;
    }
  </style>
</head>
<body>
  <div id="image-container">
    <img src="${imageUrl}" alt="${nftNameFromData}" class="nft-image" 
         onerror="this.onerror=null; this.src='${default_nft_image}';">
  </div>
  <script>
    document.addEventListener('click', function() {
      if (window.parent) {
        window.parent.postMessage({
          type: 'openFullscreenView',
          nftId: '${nftId}',
          nftName: '${nftNameFromData}'
        }, '*');
      }
    });

    const observer = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          const img = document.querySelector('.nft-image');
          if (img && !img.loaded) {
            img.loaded = true;
          }
          observer.disconnect();
        }
      });
    }, { threshold: 0.1 });

    observer.observe(document.getElementById('image-container'));
  <\/script>
</body>
</html>
    `;
  } catch (error) {
    console.error('Error generating NFT HTML for activity:', error);
    return `
      <div style="width: 100%; height: 100%; background: #f0f0f0; display: flex; align-items: center; justify-content: center; cursor: pointer;">
        <img src="${default_nft_image}" alt="Default NFT" style="max-width: 80%; max-height: 80%;">
      </div>
    `;
  }
};


const executePriceEdit = async () => {
  try {
    // Защита от повторных нажатий
    if (editPriceModal.value.loading) {
      console.log('⏳ Изменение цены уже обрабатывается...');
      return;
    }
    
    // Блокируем кнопку
    editPriceModal.value.loading = true;
    
    const { item, newPrice, currentPrice } = editPriceModal.value;
    
    // Проверяем, что новая цена отличается от текущей
    if (parseFloat(newPrice) === parseFloat(currentPrice)) {
      showNotification('New price must be different from current price', 'error');
      editPriceModal.value.loading = false;
      return;
    }
    
    if (!newPrice || newPrice <= 0) {
      showNotification('Please enter a valid price', 'error');
      editPriceModal.value.loading = false;
      return;
    }

    console.log('🔄 Обновление цены для NFT...', item.id);

    // === ПРОВЕРКА FLOOR PRICE ===
    const nftName = getNftDisplayName(item.nft_type, item.nft_object);
    const normalizedNftName = normalizeNftNameForFloorPrice(nftName);
    
    // Получаем минимальную цену для этого NFT
    const floorPrice = await getFloorPriceForNft(normalizedNftName);
    
    // Проверяем, что новая цена не ниже минимальной
    if (floorPrice > 0 && parseFloat(newPrice) < floorPrice) {
      showNotification(`Price cannot be lower than floor price: ${floorPrice.toFixed(2)} TON`, 'error');
      editPriceModal.value.loading = false;
      return;
    }
    // === КОНЕЦ ПРОВЕРКИ FLOOR PRICE ===

    // === ПРОВЕРКА ЛИМИТА БЕСПЛАТНЫХ ИЗМЕНЕНИЙ ===
    const isOverLimit = freePriceEdits.value >= PRICE_EDIT_LIMIT;
    const needsPayment = isOverLimit && !priceEditFeePaid.value;
    
    console.log(`📊 Статус изменений цены:`, {
      freeEditsUsed: freePriceEdits.value,
      limit: PRICE_EDIT_LIMIT,
      isOverLimit,
      needsPayment,
      fee: PRICE_EDIT_FEE
    });

    // Формируем ссылку на изображение для операций
    let imageLink = null;
    if (item.nft_object && item.nft_object.url) {
      imageLink = item.nft_object.url;
    } else if (item.url) {
      imageLink = item.url;
    } else {
      const nftNameForLink = nftName.replace(/\s+/g, '') || 'Unknown';
      const nftIdForLink = extractNftIdFromData(item.nft_object) || 'unknown';
      imageLink = `https://nft.fragment.com/gift/${nftNameForLink}-${nftIdForLink}.webp`;
    }

    // Если нужно оплатить и еще не оплачено
    if (needsPayment) {
      // Проверяем баланс пользователя
      const { data: userData, error: userError } = await supabase
        .from('users')
        .select('ton_balance')
        .eq('name', currentAccountName.value)
        .single();

      if (userError) {
        console.error('❌ Ошибка получения баланса:', userError);
        showNotification('Could not verify your balance', 'error');
        editPriceModal.value.loading = false;
        return;
      }

      const currentBalance = parseFloat(userData.ton_balance) || 0;

      if (currentBalance < PRICE_EDIT_FEE) {
        showNotification(`Insufficient balance. Need ${PRICE_EDIT_FEE} TON for price change. You have ${currentBalance.toFixed(2)} TON`, 'error');
        editPriceModal.value.loading = false;
        return;
      }

      // Списываем комиссию
      const newBalance = currentBalance - PRICE_EDIT_FEE;
      
      const { error: updateError } = await supabase
        .from('users')
        .update({ ton_balance: newBalance })
        .eq('name', currentAccountName.value);

      if (updateError) {
        console.error('❌ Ошибка списания комиссии:', updateError);
        showNotification('Failed to deduct fee', 'error');
        editPriceModal.value.loading = false;
        return;
      }

      // Обновляем локальный баланс
      tonBalance.value = newBalance.toString();
      
      // === ДОБАВЛЯЕМ ЗАПИСЬ В ТАБЛИЦУ CONFIGURATIONS ===
      await updateConfigurationsStats(PRICE_EDIT_FEE, 'price_edit_package');
      
      // Отмечаем, что оплата прошла
      priceEditFeePaid.value = true;
      
      // СБРАСЫВАЕМ СЧЕТЧИК (пользователь получил новые 5 изменений)
      freePriceEdits.value = 0;
      
      console.log(`💰 Комиссия ${PRICE_EDIT_FEE} TON списана. Получен новый пакет из ${PRICE_EDIT_LIMIT} изменений`);
      
      // Записываем операцию покупки пакета в историю
      const packageOperation = {
        id: `op_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
        type: 'price_edit_package',
        amount: PRICE_EDIT_FEE.toString(),
        timestamp: new Date().toISOString(),
        transactionHash: null,
        walletAddress: currentAccountName.value,
        currency: 'TON',
        itemId: item.id,
        packageSize: PRICE_EDIT_LIMIT,
        link: imageLink // Добавляем ссылку
      };

      const { data: userWithHistory } = await supabase
        .from('users')
        .select('operation_history')
        .eq('name', currentAccountName.value)
        .single();

      if (userWithHistory) {
        const currentHistory = userWithHistory.operation_history || [];
        const updatedHistory = [packageOperation, ...currentHistory].slice(0, 100);
        
        await supabase
          .from('users')
          .update({ operation_history: updatedHistory })
          .eq('name', currentAccountName.value);
      }
    }
    // === КОНЕЦ ПРОВЕРКИ ЛИМИТА ===

    // Сохраняем старую цену для записи в историю
    const oldPrice = currentPrice;

    // Обновляем цену в базе данных
    const { error } = await supabase
      .from('market')
      .update({ 
        price_per_unit: parseFloat(newPrice),
        total_price: parseFloat(newPrice) * item.amount,
        created_at: new Date().toISOString()
      })
      .eq('id', item.id);

    if (error) throw error;

    // Обновляем локальные данные
    const itemIndex = marketItems.value.findIndex(marketItem => marketItem.id === item.id);
    if (itemIndex !== -1) {
      marketItems.value[itemIndex].price_per_unit = parseFloat(newPrice);
      marketItems.value[itemIndex].total_price = parseFloat(newPrice) * item.amount;
    }

    // Записываем в историю с корректными данными
    await recordPriceEditActivity(item, oldPrice, newPrice);

    // === ОБНОВЛЯЕМ СЧЕТЧИК (только если не платили за новый пакет) ===
    if (!priceEditFeePaid.value) {
      // Если не платили - увеличиваем счетчик
      const newCount = freePriceEdits.value + 1;
      freePriceEdits.value = newCount;
      await updatePriceEditCount(newCount);
      console.log(`✅ Счетчик бесплатных изменений обновлен: ${newCount}/${PRICE_EDIT_LIMIT}`);
    } else {
      // Если платили - счетчик уже сброшен в 0, сохраняем
      await updatePriceEditCount(freePriceEdits.value);
      console.log(`✅ Новый пакет изменений активирован: 0/${PRICE_EDIT_LIMIT} использовано`);
    }

    console.log('✅ Цена успешно обновлена');
    
    // Показываем успешное изменение цены с анимацией
    showSuccessAnimation('price_update');
    
    // Закрываем модальное окно с небольшой задержкой для анимации
    setTimeout(() => {
      editPriceModal.value.show = false;
    }, 500);
    
  } catch (error) {
    console.error('Error updating price:', error);
    showFailAnimation('Update Failed', 'price_update_failed');
  } finally {
    // Всегда разблокируем кнопку
    editPriceModal.value.loading = false;
  }
};

const validateItemAvailability = async (item) => {
  console.log('🔍 Проверка доступности товара:', item.id || item.item_id);
  
  const { data: marketItem, error } = await supabase
    .from('market')
    .select('id, item_id, seller, nft_type, nft_object, price_per_unit, is_active')
    .or(`id.eq.${item.id},item_id.eq.${item.item_id}`)
    .eq('is_active', true)
    .maybeSingle();
  
  if (error || !marketItem) {
    console.error('❌ Товар недоступен:', error);
    throw new Error('Item is no longer available for offers');
  }
  
  console.log('✅ Товар доступен:', marketItem);
  return marketItem;
};


// Обновленная проверка баланса (в функции sendOffer):
const checkBalanceAndReserve = async (buyerName, offerAmount) => {
  // Получаем актуальные данные пользователя
  const { data: buyerData, error: buyerError } = await supabase
    .from('users')
    .select('ton_balance')
    .eq('name', buyerName)
    .single();
  
  if (buyerError) {
    console.error('❌ Ошибка получения баланса:', buyerError);
    throw new Error('Could not verify your balance');
  }
  
  const currentBalance = parseFloat(buyerData.ton_balance) || 0;
  
  // Проверяем, достаточно ли средств
  if (currentBalance < offerAmount) {
    const errorMessage = `Insufficient balance. Need ${offerAmount.toFixed(2)} TON, have ${currentBalance.toFixed(2)} TON`;
    throw new Error(errorMessage);
  }
  
  // Резервируем средства (вычитаем из баланса)
  const newBalance = currentBalance - offerAmount;
  
  const { error: updateError } = await supabase
    .from('users')
    .update({ ton_balance: newBalance })
    .eq('name', buyerName);
  
  if (updateError) {
    console.error('❌ Ошибка резервирования средств:', updateError);
    throw new Error('Failed to reserve funds');
  }
  
  console.log(`✅ Средства зарезервированы: ${currentBalance} → ${newBalance} TON`);
  
  return {
    oldBalance: currentBalance,
    newBalance: newBalance,
    reservedAmount: offerAmount
  };
};
