// Внутри setup() добавьте:
const generateBackdropSvg = (colorName) => {
  try {
    console.log('🔍 generateBackdropSvg called with:', colorName);
    
    // Нормализуем название цвета
    let normalizedColorName = colorName;
    
    // Если есть процент, удаляем его
    if (colorName && typeof colorName === 'string') {
      normalizedColorName = colorName.replace(/\s*\d+\.?\d*%\s*$/, '').trim();
    }
    
    // Преобразуем в формат как в gradients
    normalizedColorName = normalizedColorName.replace(/\s+/g, '_');
    
    console.log('🔍 Looking for gradient key:', normalizedColorName);
    
    // Ищем градиент
    let gradient = gradients[normalizedColorName];
    
    // Если не нашли напрямую, ищем по совпадению
    if (!gradient) {
      console.log('⚠️ Direct match not found, trying fuzzy match...');
      
      // Пробуем найти по частичному совпадению
      const gradientKeys = Object.keys(gradients);
      const foundKey = gradientKeys.find(key => {
        // Сравниваем без учета регистра и подчеркиваний
        const keyNormalized = key.toLowerCase().replace(/_/g, ' ');
        const searchNormalized = normalizedColorName.toLowerCase().replace(/_/g, ' ');
        return keyNormalized === searchNormalized;
      });
      
      if (foundKey) {
        console.log('✅ Found gradient by fuzzy match:', foundKey);
        gradient = gradients[foundKey];
        normalizedColorName = foundKey;
      }
    }
    
    if (!gradient) {
      console.error('❌ Gradient not found for:', colorName, 'normalized:', normalizedColorName);
      
      // Создаем тестовый SVG с красной рамкой для отладки
      return `
        <svg width="40" height="40" viewBox="0 0 40 40" xmlns="http://www.w3.org/2000/svg">
          <rect width="40" height="40" rx="8" fill="#cccccc" stroke="red" stroke-width="2"/>
          <text x="20" y="20" text-anchor="middle" dy=".3em" font-size="8" fill="red">?</text>
        </svg>
      `;
    }
    
    console.log('✅ Found gradient:', normalizedColorName, gradient);
    
    // Создаем уникальный ID для градиента
    const gradientId = `gradient-${normalizedColorName}-${Date.now()}`;
    
    // Создаем SVG с градиентом
    const stops = gradient.stops.map(stop => 
      `<stop offset="${stop.offset}" stop-color="${stop.color}" />`
    ).join('\n');
    
    const svg = `
      <svg width="40" height="40" viewBox="0 0 40 40" xmlns="http://www.w3.org/2000/svg">
        <defs>
          <linearGradient id="${gradientId}" x1="0%" y1="0%" x2="100%" y2="100%">
            ${stops}
          </linearGradient>
        </defs>
        <rect width="40" height="40" rx="8" fill="url(#${gradientId})" />
        <!-- Для отладки добавляем границу -->
        <rect width="40" height="40" rx="8" fill="none" stroke="#000" stroke-width="0.5" opacity="0.3" />
      </svg>
    `;
    
    console.log('✅ Generated SVG for:', colorName);
    return svg;
    
  } catch (error) {
    console.error('❌ Error in generateBackdropSvg:', error, 'for color:', colorName);
    
    // Fallback SVG с сообщением об ошибке
    return `
      <svg width="40" height="40" viewBox="0 0 40 40" xmlns="http://www.w3.org/2000/svg">
        <rect width="40" height="40" rx="8" fill="#ffcccc"/>
        <text x="20" y="20" text-anchor="middle" dy=".3em" font-size="6" fill="red">Error</text>
      </svg>
    `;
  }
};

// Также добавьте простую тестовую функцию для проверки
const testBackdropSvg = () => {
  console.log('🧪 Testing backdrop SVG generation...');
  
  // Тестируем несколько цветов
  const testColors = ['Dark Lilac', 'Aquamarine', 'NonExistentColor'];
  
  testColors.forEach(color => {
    console.log(`\n🧪 Testing ${color}:`);
    const svg = generateBackdropSvg(color);
    console.log('Generated SVG:', svg.substring(0, 200) + '...');
  });
};

