const addNftToUnlistedForBuyer = async (nftData, buyerName) => {
  try {
    const { data: buyerData, error: fetchError } = await supabase
      .from('users')
      .select('nft_links')
      .eq('name', buyerName)
      .single();

    if (fetchError) throw fetchError;

    const currentLinks = buyerData.nft_links || [];
    
    // СОЗДАЕМ УНИКАЛЬНЫЙ КЛЮЧ ДЛЯ НОВОГО NFT
    const giftId = nftData.gift_id;
    let nftId = null;
    
    // Извлекаем ID из URL как запасной вариант
    if (nftData.url) {
      const urlMatch = nftData.url.match(/-(\d+)(?:\?|$)/);
      nftId = urlMatch ? urlMatch[1] : null;
    }
    
    // Приоритет: gift_id > ID из URL
    const uniqueKey = giftId ? `gift_${giftId}` : (nftId ? `url_${nftId}` : nftData.url);
    
    // ПРОВЕРЯЕМ, НЕТ ЛИ УЖЕ ЭТОГО NFT В КОЛЛЕКЦИИ ПОКУПАТЕЛЯ
    const alreadyExists = currentLinks.some(existingNft => {
      // Проверяем по gift_id
      if (giftId && existingNft.gift_id === giftId) {
        return true;
      }
      
      // Проверяем по ID из URL
      if (nftId && existingNft.url) {
        const existingUrlMatch = existingNft.url.match(/-(\d+)(?:\?|$)/);
        const existingNftId = existingUrlMatch ? existingUrlMatch[1] : null;
        if (existingNftId === nftId) {
          return true;
        }
      }
      
      // Проверяем по полному URL как запасной вариант
      return nftData.url && existingNft.url === nftData.url;
    });

    if (alreadyExists) {
      console.warn('⚠️ NFT уже есть в коллекции покупателя:', { 
        url: nftData.url, 
        giftId,
        nftId 
      });
      
      // ВОЗВРАЩАЕМ СПЕЦИАЛЬНЫЙ СТАТУС, ЧТО NFT УЖЕ СУЩЕСТВУЕТ
      return { 
        status: 'already_exists', 
        message: 'NFT already exists in buyer collection' 
      };
    }

    // Добавляем NFT в коллекцию покупателя
    const updatedLinks = [...currentLinks, nftData];

    const { error: updateError } = await supabase
      .from('users')
      .update({ nft_links: updatedLinks })
      .eq('name', buyerName);

    if (updateError) throw updateError;

    console.log('✅ NFT добавлено в коллекцию покупателя:', buyerName, {
      url: nftData.url,
      giftId,
      nftId
    });
    
    return { status: 'added', message: 'NFT added successfully' };

  } catch (error) {
    console.error('❌ Ошибка добавления NFT покупателю:', error);
    throw error;
  }
};

