        const altAvailable = await testImageUrl(altUrl, 1000); // 1 секунда таймаут
        if (altAvailable) {
          console.log(`✅ Альтернативный URL доступен: ${altUrl}`);
          nftImageCache.value[nftName] = altUrl;
          return altUrl;
        }
      }
      
      // Если ничего не работает, используем локальное изображение
      console.log(`🏠 Используем локальное изображение для: ${nftName}`);
      nftImageCache.value[nftName] = default_nft_image;
      return default_nft_image;
    }
    
  } catch (error) {
    console.error(`❌ Ошибка загрузки изображения для ${nftName}:`, error);
    nftImageCache.value[nftName] = default_nft_image;
    return default_nft_image;
  }
};


