// 3. Исправьте setupMarketSubscription - добавьте проверку
const marketSubscription = ref(null);
const userSubscription = ref(null);

const setupMarketSubscription = () => {
  // Удаляем существующие подписки
  if (marketSubscription.value) {
    supabase.removeChannel(marketSubscription.value);
  }
  
  // Создаем новую подписку с защитой
  marketSubscription.value = supabase
    .channel('market_changes_safe')
    .on(
      'postgres_changes',
      {
        event: '*',
        schema: 'public',
        table: 'market'
      },
      (payload) => {
        console.log('📢 Изменение в market:', payload.eventType);
        
        // Добавляем задержку и защиту от повторных вызовов
        setTimeout(async () => {
          if (!isMarketLoadingInProgress) {
            console.log('🔄 Обновление данных из-за изменений в БД');
            await loadMarketItems(false);
          }
        }, 1000);
      }
    )
    .subscribe((status) => {
      console.log('📡 Статус подписки на market:', status);
    });
};
// 1. Обновленная функция для загрузки Backdrop для текущей вкладки
const loadBackdropsForCurrentTab = async () => {
  try {
    console.log(`🔍 Загрузка Backdrop для вкладки: ${activeTab.value}`);
    
    let allBackdrops = new Set();
    let backdropWithPercentages = {};
    
    if (activeTab.value === 'market') {
      // Загружаем ВСЕ данные из market для текущей вкладки
      const { data: marketData, error: marketError } = await supabase
        .from('market')
        .select('nft_object');
      
      if (marketError) throw marketError;
      
      // Извлекаем Backdrop только из market данных
      marketData?.forEach(item => {
        try {
          if (item.nft_object) {
            const nftObj = typeof item.nft_object === 'string' 
              ? JSON.parse(item.nft_object) 
              : item.nft_object;
            
            if (nftObj.backdrop) {
              const backdropName = nftObj.backdrop.replace(/\d+\.?\d*%/, '').trim();
              if (backdropName) {
                allBackdrops.add(backdropName);
                backdropWithPercentages[backdropName] = nftObj.backdrop;
              }
            }
          }
        } catch (e) {
          console.warn('Ошибка парсинга nft_object в market:', e);
        }
      });
      
    } else if (activeTab.value === 'my-nfts') {
      if (!currentAccountName.value) {
        console.log('❌ Нет имени пользователя для загрузки My Gifts Backdrop');
        return;
      }
      
      // Загружаем listed NFT текущего пользователя
      const { data: listedData, error: listedError } = await supabase
        .from('market')
        .select('nft_object')
        .eq('seller', currentAccountName.value);
      
      if (!listedError && listedData) {
        listedData.forEach(item => {
          try {
            if (item.nft_object) {
              const nftObj = typeof item.nft_object === 'string' 
                ? JSON.parse(item.nft_object) 
                : item.nft_object;
              
              if (nftObj.backdrop) {
                const backdropName = nftObj.backdrop.replace(/\d+\.?\d*%/, '').trim();
                if (backdropName) {
                  allBackdrops.add(backdropName);
                  backdropWithPercentages[backdropName] = nftObj.backdrop;
                }
              }
            }
          } catch (e) {
            console.warn('Ошибка парсинга listed item:', e);
          }
        });
      }
      
      // Загружаем unlisted NFT текущего пользователя
      const { data: userData, error: userError } = await supabase
        .from('users')
        .select('nft_links')
        .eq('name', currentAccountName.value)
        .single();
      
      if (!userError && userData?.nft_links) {
        userData.nft_links.forEach(nftData => {
          if (nftData.backdrop) {
            const backdropName = nftData.backdrop.replace(/\d+\.?\d*%/, '').trim();
            if (backdropName) {
              allBackdrops.add(backdropName);
              if (!backdropWithPercentages[backdropName]) {
                backdropWithPercentages[backdropName] = nftData.backdrop;
              }
            }
          }
        });
      }
      
    } else if (activeTab.value === 'activity') {
      // Загружаем ВСЕ данные из activity_history для текущей вкладки
      const { data: activityData, error: activityError } = await supabase
        .from('activity_history')
        .select('nft_object');
      
      if (activityError) throw activityError;
      
      // Извлекаем Backdrop только из activity данных
      activityData?.forEach(item => {
        try {
          if (item.nft_object) {
            const nftObj = typeof item.nft_object === 'string' 
              ? JSON.parse(item.nft_object) 
              : item.nft_object;
            
            if (nftObj.backdrop) {
              const backdropName = nftObj.backdrop.replace(/\d+\.?\d*%/, '').trim();
              if (backdropName) {
                allBackdrops.add(backdropName);
                backdropWithPercentages[backdropName] = nftObj.backdrop;
              }
            }
          }
        } catch (e) {
          console.warn('Ошибка парсинга nft_object в activity:', e);
        }
      });
    }
    
    // Преобразуем в массив объектов с правильной структурой
    const backdropOptions = Array.from(allBackdrops).map(backdropName => {
      const fullBackdropName = backdropWithPercentages[backdropName] || backdropName;
      const backdropPercentage = fullBackdropName.replace(backdropName, '').trim();
      
      // Генерируем SVG
      const svgContent = generateBackdropSvg(backdropName);
      
      // Определяем ID (используется для фильтрации)
      const backdropId = backdropName.toLowerCase().replace(/\s+/g, '_');
      
      return {
        id: backdropId,
        name: backdropName,
        fullName: fullBackdropName,
        percentage: backdropPercentage,
        svgContent: svgContent,
        rarityText: getBackdropRarityText(backdropName),
        count: 0,
        floorPrice: null
      };
    });
    
    // Сортируем по имени
    backdropOptions.sort((a, b) => a.name.localeCompare(b.name));
    
    console.log(`✅ Загружено ${backdropOptions.length} уникальных Backdrop для вкладки ${activeTab.value}`);
    
    // Сохраняем в allFilterOptions для текущей вкладки
    allFilterOptions.value[`${activeTab.value}Backdrops`] = backdropOptions;
    
    // Обновляем счетчики для текущей вкладки
    await updateBackdropCountsAndPricesForCurrentTab();
    
    return backdropOptions;
    
  } catch (error) {
    console.error(`❌ Ошибка загрузки Backdrop для вкладки ${activeTab.value}:`, error);
    return [];
  }
};

// 2. Обновленная функция для обновления счетчиков и цен Backdrop для текущей вкладки
const updateBackdropCountsAndPricesForCurrentTab = async () => {
  try {
    console.log('🔄 Обновление счетчиков и цен Backdrop для текущей вкладки...');
    
    const currentTab = activeTab.value;
    const backdropKey = `${currentTab}Backdrops`;
    
    if (!allFilterOptions.value[backdropKey] || allFilterOptions.value[backdropKey].length === 0) {
      console.log(`❌ Backdrop для вкладки ${currentTab} не загружены`);
      return;
    }
    
    // Создаем мапу для быстрого доступа
    const backdropMap = {};
    allFilterOptions.value[backdropKey].forEach(backdrop => {
      backdropMap[backdrop.id] = {
        ...backdrop,
        count: 0,
        floorPrice: null
      };
    });
    
    console.log(`📊 Обновление для вкладки: ${currentTab}`);
    
    // Загружаем и обрабатываем данные в зависимости от вкладки
    if (currentTab === 'market') {
      const { data: marketData, error } = await supabase
        .from('market')
        .select('*');
      
      if (error) throw error;
      
      marketData?.forEach(item => {
        try {
          if (item.nft_object) {
            const nftObj = typeof item.nft_object === 'string' 
              ? JSON.parse(item.nft_object) 
              : item.nft_object;
            
            if (nftObj.backdrop) {
              const backdropName = nftObj.backdrop.replace(/\d+\.?\d*%/, '').trim();
              const backdropId = backdropName.toLowerCase().replace(/\s+/g, '_');
              
              if (backdropMap[backdropId]) {
                backdropMap[backdropId].count++;
                
                // Обновляем минимальную цену
                if (item.currency === 'TON' && item.price_per_unit) {
                  const price = parseFloat(item.price_per_unit);
                  if (backdropMap[backdropId].floorPrice === null || price < backdropMap[backdropId].floorPrice) {
                    backdropMap[backdropId].floorPrice = price;
                  }
                }
              }
            }
          }
        } catch (e) {
          console.warn('Ошибка обработки market item:', e);
        }
      });
      
    } else if (currentTab === 'my-nfts') {
      if (!currentAccountName.value) return;
      
      // Listed NFT
      const { data: listedData, error: listedError } = await supabase
        .from('market')
        .select('*')
        .eq('seller', currentAccountName.value);
      
      if (!listedError && listedData) {
        listedData.forEach(item => {
          try {
            if (item.nft_object) {
              const nftObj = typeof item.nft_object === 'string' 
                ? JSON.parse(item.nft_object) 
                : item.nft_object;
              
              if (nftObj.backdrop) {
                const backdropName = nftObj.backdrop.replace(/\d+\.?\d*%/, '').trim();
                const backdropId = backdropName.toLowerCase().replace(/\s+/g, '_');
                
                if (backdropMap[backdropId]) {
                  backdropMap[backdropId].count++;
                  
                  if (item.currency === 'TON' && item.price_per_unit) {
                    const price = parseFloat(item.price_per_unit);
                    if (backdropMap[backdropId].floorPrice === null || price < backdropMap[backdropId].floorPrice) {
                      backdropMap[backdropId].floorPrice = price;
                    }
                  }
                }
              }
            }
          } catch (e) {
            console.warn('Ошибка обработки listed item:', e);
          }
        });
      }
      
      // Unlisted NFT
      const { data: userData, error: userError } = await supabase
        .from('users')
        .select('nft_links')
        .eq('name', currentAccountName.value)
        .single();
      
      if (!userError && userData?.nft_links) {
        userData.nft_links.forEach(nftData => {
          if (nftData.backdrop) {
            const backdropName = nftData.backdrop.replace(/\d+\.?\d*%/, '').trim();
            const backdropId = backdropName.toLowerCase().replace(/\s+/g, '_');
            
            if (backdropMap[backdropId]) {
              backdropMap[backdropId].count++;
            }
          }
        });
      }
      
    } else if (currentTab === 'activity') {
      const { data: activityData, error } = await supabase
        .from('activity_history')
        .select('*');
      
      if (error) throw error;
      
      activityData?.forEach(item => {
        try {
          if (item.nft_object) {
            const nftObj = typeof item.nft_object === 'string' 
              ? JSON.parse(item.nft_object) 
              : item.nft_object;
            
            if (nftObj.backdrop) {
              const backdropName = nftObj.backdrop.replace(/\d+\.?\d*%/, '').trim();
              const backdropId = backdropName.toLowerCase().replace(/\s+/g, '_');
              
              if (backdropMap[backdropId]) {
                backdropMap[backdropId].count++;
                
                if (item.price_per_unit) {
                  const price = parseFloat(item.price_per_unit);
                  if (backdropMap[backdropId].floorPrice === null || price < backdropMap[backdropId].floorPrice) {
                    backdropMap[backdropId].floorPrice = price;
                  }
                }
              }
            }
          }
        } catch (e) {
          console.warn('Ошибка обработки activity item:', e);
        }
      });
    }
    
    // Обновляем массив Backdrop для текущей вкладки
    allFilterOptions.value[backdropKey] = Object.values(backdropMap)
      .sort((a, b) => a.name.localeCompare(b.name));
    
    console.log(`✅ Обновлены счетчики для ${allFilterOptions.value[backdropKey].length} Backdrop на вкладке ${currentTab}`);
    
  } catch (error) {
    console.error('❌ Ошибка обновления счетчиков Backdrop:', error);
  }
};

// В начале setup(), после объявления переменных
const allBackdropOptions = ref({
  market: [],    // Все backdrop из всей таблицы market
  myGifts: [],   // Все backdrop из всех NFT пользователя
  activity: []   // Все backdrop из всей истории активности
});
// Функция для загрузки ВСЕХ backdrop опций для каждой вкладки
const loadAllBackdropOptions = async (tab) => {
  try {
    console.log(`📥 Загрузка ВСЕХ backdrop опций для вкладки: ${tab}`);
    
    if (tab === 'market') {
      // Загружаем ВСЕ товары из market для получения всех backdrop
      const { data: allMarketData, error: marketError } = await supabase
        .from('market')
        .select('*');
      
      if (marketError) throw marketError;
      
      // Извлекаем все уникальные backdrop
      const uniqueBackdrops = new Set();
      allMarketData.forEach(item => {
        const backdrop = extractBackdropFromNft(item);
        if (backdrop && backdrop.trim()) {
          uniqueBackdrops.add(backdrop);
        }
      });
      
      allBackdropOptions.value.market = Array.from(uniqueBackdrops).sort();
      console.log(`✅ Загружено ${allBackdropOptions.value.market.length} backdrop из market`);
      
    } else if (tab === 'my-nfts' && currentAccountName.value) {
      // Загружаем ВСЕ NFT пользователя (listed + unlisted)
      const [listedResult, userResult] = await Promise.all([
        supabase
          .from('market')
          .select('*')
          .eq('seller', currentAccountName.value),
        supabase
          .from('users')
          .select('nft_links')
          .eq('name', currentAccountName.value)
          .single()
      ]);
      
      const uniqueBackdrops = new Set();
      
      // Listed NFT
      if (listedResult.data) {
        listedResult.data.forEach(item => {
          const backdrop = extractBackdropFromNft(item);
          if (backdrop && backdrop.trim()) {
            uniqueBackdrops.add(backdrop);
          }
        });
      }
      
      // Unlisted NFT
      if (userResult.data && userResult.data.nft_links) {
        userResult.data.nft_links.forEach(nftData => {
          const backdrop = nftData.backdrop || '';
          if (backdrop && backdrop.trim()) {
            uniqueBackdrops.add(backdrop);
          }
        });
      }
      
      allBackdropOptions.value.myGifts = Array.from(uniqueBackdrops).sort();
      console.log(`✅ Загружено ${allBackdropOptions.value.myGifts.length} backdrop из my-gifts`);
      
    } else if (tab === 'activity') {
      // Загружаем ВСЕ записи активности
      const { data: allActivityData, error: activityError } = await supabase
        .from('activity_history')
        .select('*');
      
      if (activityError) throw activityError;
      
      const uniqueBackdrops = new Set();
      allActivityData.forEach(activity => {
        try {
          const nftObject = typeof activity.nft_object === 'string' 
            ? JSON.parse(activity.nft_object) 
            : activity.nft_object;
          
          if (nftObject && nftObject.backdrop && nftObject.backdrop.trim()) {
            uniqueBackdrops.add(nftObject.backdrop);
          }
        } catch (error) {
          console.warn('Ошибка при обработке backdrop из активности:', error);
        }
      });
      
      allBackdropOptions.value.activity = Array.from(uniqueBackdrops).sort();
      console.log(`✅ Загружено ${allBackdropOptions.value.activity.length} backdrop из activity`);
    }
    
  } catch (error) {
    console.error(`❌ Ошибка загрузки backdrop опций для ${tab}:`, error);
  }
};
// Универсальная функция для получения backdrop опций
const getAvailableBackdropOptions = (tab) => {
  console.log(`📊 Получение backdrop опций для вкладки: ${tab}`);
  
  let allBackdrops = [];
  
  switch(tab) {
    case 'market':
      allBackdrops = allBackdropOptions.value.market;
      console.log(`   Все backdrop в market: ${allBackdrops.length}`);
      break;
      
    case 'my-nfts':
      allBackdrops = allBackdropOptions.value.myGifts;
      console.log(`   Все backdrop в my-gifts: ${allBackdrops.length}`);
      break;
      
    case 'activity':
      allBackdrops = allBackdropOptions.value.activity;
      console.log(`   Все backdrop в activity: ${allBackdrops.length}`);
      break;
  }
  
  // Если еще не загружены, возвращаем пустой массив
  if (allBackdrops.length === 0) {
    console.log(`⚠️  Backdrop опции для ${tab} еще не загружены`);
    return [];
  }
  
  // Сортируем и фильтруем по поиску
  let filtered = [...allBackdrops];
  
  // Применяем поисковый запрос
  if (backdropSearchQuery.value) {
    const searchTerm = backdropSearchQuery.value.toLowerCase();
    filtered = filtered.filter(backdrop => 
      backdrop.toLowerCase().includes(searchTerm)
    );
  }
  
  // Группируем по категориям (цвет + редкость)
  const groupedBackdrops = filtered.map(backdrop => {
    try {
      // Извлекаем процент редкости
      const percentageMatch = backdrop.match(/(\d+(\.\d+)?%)/);
      const percentage = percentageMatch ? percentageMatch[1] : '';
      
      // Извлекаем цветовую часть
      const colorName = backdrop.replace(/\d+(\.\d+)?%/, '').trim();
      
      // Определяем класс редкости
      let rarityClass = 'common';
      let rarityText = 'Common';
      
      if (percentage) {
        const num = parseFloat(percentage);
        if (num < 0.1) rarityClass = 'mythic', rarityText = 'Mythic';
        else if (num < 1) rarityClass = 'legendary', rarityText = 'Legendary';
        else if (num < 5) rarityClass = 'rare', rarityText = 'Rare';
        else if (num < 20) rarityClass = 'uncommon', rarityText = 'Uncommon';
      }
      
      // Подсчитываем количество на рынке
      let count = 0;
      let floorPrice = 0;
      
      if (activeTab.value === 'market' && allFilterOptions.value.marketItems) {
        count = allFilterOptions.value.marketItems.filter(item => {
          const itemBackdrop = extractBackdropFromNft(item);
          return itemBackdrop === backdrop;
        }).length;
        
        // Находим минимальную цену
        const itemsWithThisBackdrop = allFilterOptions.value.marketItems.filter(item => {
          const itemBackdrop = extractBackdropFromNft(item);
          return itemBackdrop === backdrop && item.price_per_unit;
        });
        
        if (itemsWithThisBackdrop.length > 0) {
          floorPrice = Math.min(...itemsWithThisBackdrop.map(item => item.price_per_unit));
        }
      }
      
      // Генерируем SVG для превью
      const gradient = gradients[colorName] || gradients['Black'];
      const svgContent = `
        <svg width="40" height="40" viewBox="0 0 40 40" xmlns="http://www.w3.org/2000/svg">
          <defs>
            <linearGradient id="grad-${colorName.replace(/\s+/g, '-')}" x1="0%" y1="0%" x2="100%" y2="100%">
              ${gradient.stops.map(stop => 
                `<stop offset="${stop.offset}" stop-color="${stop.color}"/>`
              ).join('')}
            </linearGradient>
          </defs>
          <rect width="40" height="40" rx="8" fill="url(#grad-${colorName.replace(/\s+/g, '-')})"/>
        </svg>
      `;
      
      return {
        id: backdrop,
        name: backdrop,
        svgContent: svgContent,
        count: count,
        floorPrice: floorPrice,
        rarityClass: rarityClass,
        rarityText: rarityText,
        colorName: colorName,
        percentage: percentage
      };
    } catch (error) {
      console.warn(`Ошибка обработки backdrop "${backdrop}":`, error);
      return null;
    }
  }).filter(item => item !== null);
  
  console.log(`✅ Подготовлено ${groupedBackdrops.length} backdrop опций для отображения`);
  return groupedBackdrops;
};
