// Добавьте эту функцию для нормализации названий цветов
const normalizeColorName = (colorName) => {
  if (!colorName) return '';
  
  // Удаляем процент и все после него (если есть)
  const cleanName = colorName.replace(/\s*\d+\.?\d*%\s*$/, '').trim();
  
  // Преобразуем в формат как в gradients (заменяем пробелы на подчеркивания)
  return cleanName.replace(/\s+/g, '_');
};

// Функция для получения SVG цвета
// Внутри setup()
const getBackdropSvg = computed(() => {
  return (colorName) => {
    try {
      const normalizedColorName = colorName.replace(/\s+/g, '_');
      const gradient = gradients[normalizedColorName];
      
      if (!gradient) {
        // Fallback
        return `
          <svg width="40" height="40" viewBox="0 0 40 40" xmlns="http://www.w3.org/2000/svg">
            <rect width="40" height="40" rx="8" fill="#cccccc"/>
          </svg>
        `;
      }
      
      const uniqueId = `gradient-${normalizedColorName}-${Date.now()}`;
      const stops = gradient.stops.map(stop => 
        `<stop offset="${stop.offset}" stop-color="${stop.color}"/>`
      ).join('');
      
      return `
        <svg width="40" height="40" viewBox="0 0 40 40" xmlns="http://www.w3.org/2000/svg">
          <defs>
            <linearGradient id="${uniqueId}" x1="0%" y1="0%" x2="100%" y2="100%">
              ${stops}
            </linearGradient>
          </defs>
          <rect width="40" height="40" rx="8" fill="url(#${uniqueId})"/>
        </svg>
      `;
    } catch (error) {
      return `
        <svg width="40" height="40" viewBox="0 0 40 40" xmlns="http://www.w3.org/2000/svg">
          <rect width="40" height="40" rx="8" fill="#cccccc"/>
        </svg>
      `;
    }
  };
});

// Функция генерации SVG из градиента
const generateSvgFromGradient = (gradient, gradientId) => {
  const uniqueId = `gradient-${gradientId}-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
  
  const stops = gradient.stops.map(stop => 
    `<stop offset="${stop.offset}" stop-color="${stop.color}"/>`
  ).join('');
  
  return `
    <svg width="40" height="40" viewBox="0 0 40 40" xmlns="http://www.w3.org/2000/svg">
      <defs>
        <linearGradient id="${uniqueId}" x1="0%" y1="0%" x2="100%" y2="100%">
          ${stops}
        </linearGradient>
      </defs>
      <rect width="40" height="40" rx="8" fill="url(#${uniqueId})"/>
    </svg>
  `;
};

// Функция для fallback SVG
const generateFallbackSvg = (color) => {
  return `
    <svg width="40" height="40" viewBox="0 0 40 40" xmlns="http://www.w3.org/2000/svg">
      <rect width="40" height="40" rx="8" fill="${color}"/>
    </svg>
  `;
};

