const getBackdropRarityText = (backdropName) => {
  const commonBackdrops = ['Black', 'Aquamarine', 'Azure Blue', 'Battleship Grey', 'Burgundy'];
  const rareBackdrops = ['Cyberpunk', 'Electric Indigo', 'Electric Purple', 'Pure Gold', 'Satin Gold'];
  const epicBackdrops = ['Mystic Pearl', 'Neon Blue', 'French Violet', 'Fandango'];
  
  if (epicBackdrops.includes(backdropName)) return 'Epic';
  if (rareBackdrops.includes(backdropName)) return 'Rare';
  return 'Common';
};

