      'eternalrose': 'Eternal Rose',
      'berrybox': 'Berry Box',
      'vintagecigar': 'Vintage Cigar',
      'recordplayer': 'Record Player',
      'magicpotion': 'Magic Potion',
      'electricskull': 'Electric Skull',
      'kissedfrog': 'Kissed Frog',
      'hypnolollipop': 'Hypno Lollipop',
      'hexpot': 'Hex Pot',
