        }
        
        console.log(`✅ Баланс ${offer.buyer_name} обновлен: ${currentBalance} → ${newBalance} TON`);
        
        // 3. Обновляем статус оффера
        const { error: offerUpdateError } = await supabase
          .from('offers')
          .update({ 
            status: 'cancelled',
            updated_at: new Date().toISOString(),
            cancellation_reason: 'item_removed_from_market'
          })
          .eq('id', offer.id);
        
        if (offerUpdateError) {
          console.error(`❌ Ошибка обновления статуса оффера ${offer.id}:`, offerUpdateError);
          continue;
        }
        
        console.log(`✅ Оффер ${offer.id} помечен как отмененный`);
        
        // 4. Отправляем уведомление в Telegram покупателю
