// Добавьте эту вспомогательную функцию для уведомления пользователей
const notifyUserAboutRefund = async (userName, amount, offerData, reason) => {
  try {
    // Получаем данные пользователя
    const { data: userData } = await supabase
      .from('users')
      .select('telegram')
      .eq('name', userName)
      .single();
    
    if (userData?.telegram) {
      let reasonText = '';
      switch (reason) {
        case 'item_sold':
          reasonText = 'товар продан другому покупателю';
          break;
        case 'offer_declined':
          reasonText = 'продавец отклонил ваше предложение';
          break;
        case 'buyer_cancelled':
          reasonText = 'вы отменили предложение';
          break;
        default:
          reasonText = 'предложение отменено';
      }
      
      const messageText = `💸 *Возврат средств!*

Ваше предложение было отменено (${reasonText}).

💰 Сумма возврата: ${amount} TON
🏷 NFT: ${offerData.nft_name || 'Unknown NFT'}
🔗 ID: #${offerData.nft_id || 'N/A'}

Средства уже зачислены на ваш баланс.`;

      const telegramUrl = 'https://api.telegram.org/bot8181445961:AAFYWVT-x7IVGWrVa1-n3X_dOTDM9fnhxbw/sendMessage';
      
      await fetch(telegramUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          chat_id: userData.telegram,
          text: messageText,
          parse_mode: 'Markdown'
        })
      });
      
      console.log(`📨 Уведомление отправлено пользователю ${userName}`);
