  }
};
// Функция для отмены конкретного оффера пользователем
const cancelSingleOffer = async (offerId, reason = 'buyer_cancelled') => {
  try {
    console.log(`🔍 Поиск оффера ${offerId} для отмены...`);
    
    // Получаем данные оффера
    const { data: offerData, error: offerError } = await supabase
      .from('offers')
      .select('*')
      .eq('id', offerId)
      .single();

    if (offerError) {
      console.error('❌ Ошибка получения оффера:', offerError);
      return false;
    }

    // Проверяем что оффер активен
    if (offerData.status !== 'pending') {
      console.log(`⚠️ Оффер ${offerId} уже не активен (статус: ${offerData.status})`);
      return false;
    }

    console.log(`💸 Возвращаем ${offerData.offer_price} TON покупателю ${offerData.buyer_name}`);
    
    // Получаем данные покупателя
    const { data: buyerData } = await supabase
      .from('users')
      .select('ton_balance, operation_history')
      .eq('name', offerData.buyer_name)
      .single();

    if (!buyerData) {
      console.error(`❌ Покупатель ${offerData.buyer_name} не найден`);
      return false;
    }

    // Создаем запись операции возврата
    const refundOperation = {
      id: `op_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
      type: 'refund',
      amount: offerData.offer_price.toString(),
      timestamp: new Date().toISOString(),
      transactionHash: null,
      walletAddress: offerData.buyer_name,
      currency: 'TON',
      itemId: offerData.item_id,
      offerId: offerId,
      reason: reason,
      status: 'completed',
      nftName: offerData.nft_name || '',
      nftId: offerData.nft_id || ''
    };

    // Обновляем историю операций покупателя
    const buyerHistory = buyerData.operation_history || [];
    const updatedBuyerHistory = [refundOperation, ...buyerHistory].slice(0, 100);

    // Обновляем баланс и историю
    const currentBalance = parseFloat(buyerData.ton_balance) || 0;
    const newBalance = currentBalance + parseFloat(offerData.offer_price);
    
    const { error: updateError } = await supabase
      .from('users')
      .update({ 
        ton_balance: newBalance,
        operation_history: updatedBuyerHistory 
      })
      .eq('name', offerData.buyer_name);

    if (updateError) throw updateError;

    // Обновляем статус оффера
    const { error: offerUpdateError } = await supabase
      .from('offers')
      .update({ 
        status: 'cancelled',
        updated_at: new Date().toISOString(),
        cancellation_reason: reason,
        cancellation_date: new Date().toISOString()
      })
      .eq('id', offerId);

    if (offerUpdateError) {
      console.warn(`⚠️ Ошибка обновления оффера, пробуем без cancellation_reason`);
      await supabase
        .from('offers')
        .update({ 
          status: 'cancelled',
          updated_at: new Date().toISOString()
        })
        .eq('id', offerId);
    }

    // Записываем активность
    const activityData = {
      operation_type: 'offer_cancelled',
      user_name: offerData.buyer_name,
      nft_type: offerData.nft_type || '',
      nft_object: offerData.nft_data || {},
      price_per_unit: offerData.offer_price,
      currency: 'TON',
      amount: 1,
      total_price: offerData.offer_price,
      item_id: offerData.item_id,
      offer_id: offerId,
      reason: reason
    };

    await supabase
      .from('activity_history')
      .insert([activityData]);

    // Уведомляем пользователя
    await notifyUserAboutRefund(offerData.buyer_name, offerData.offer_price, offerData, reason);

    console.log(`✅ Оффер ${offerId} успешно отменен, средства возвращены`);
    
    // Если это текущий пользователь, обновляем локальный баланс
    if (currentAccountName.value === offerData.buyer_name) {
      tonBalance.value = newBalance.toString();
    }
    
    return true;

  } catch (error) {
    console.error('❌ Ошибка при отмене оффера:', error);
    return false;
  }
};

// Функция для проверки и возврата средств по истекшим офферам
const checkAndRefundExpiredOffers = async () => {
  try {
    console.log('🔄 Проверяем истекшие офферы для возврата средств...');
    
    const now = new Date();
    const twentyFourHoursAgo = new Date(now.getTime() - 24 * 60 * 60 * 1000).toISOString();
    
    console.log(`⏰ Текущее время: ${now.toISOString()}`);
    console.log(`⏰ 24 часа назад: ${twentyFourHoursAgo}`);
    
    // Находим все pending офферы созданные более 24 часов назад
    // Используем created_at вместо expires_at
    const { data: expiredOffers, error } = await supabase
      .from('offers')
      .select('*')
      .eq('status', 'pending')
      .lt('created_at', twentyFourHoursAgo); // created_at < 24 часа назад
    
    if (error) {
      console.error('❌ Ошибка получения истекших офферов:', error);
      return;
    }
    
    if (!expiredOffers || expiredOffers.length === 0) {
      console.log('✅ Нет истекших офферов');
      return;
    }
    
    console.log(`📊 Найдено ${expiredOffers.length} истекших офферов:`);
    expiredOffers.forEach(offer => {
      console.log(`   - ID: ${offer.id}, created_at: ${offer.created_at}, buyer: ${offer.buyer_name}, amount: ${offer.offer_price}`);
    });
    
    for (const offer of expiredOffers) {
      console.log(`🔄 Обрабатываем истекший оффер:`, offer.id);
      
      // 1. Проверяем, существует ли еще объявление
      const { data: marketItem } = await supabase
        .from('market')
        .select('id')
        .eq('id', offer.item_id)
        .maybeSingle();
      
      let refundReason = '';
      
      if (!marketItem) {
        refundReason = 'item_sold_or_removed';
      } else {
        refundReason = 'offer_expired_24h';
      }
      
      // 2. Получаем данные покупателя для обновления истории
      const { data: buyerData, error: buyerError } = await supabase
        .from('users')
        .select('ton_balance, operation_history')
        .eq('name', offer.buyer_name)
        .single();
      
      if (buyerError) {
        console.error(`❌ Ошибка получения данных покупателя ${offer.buyer_name}:`, buyerError);
        continue;
      }
      
      if (buyerData) {
        const currentBalance = parseFloat(buyerData.ton_balance) || 0;
        const offerAmount = parseFloat(offer.offer_price) || 0;
        const newBalance = currentBalance + offerAmount;
        
        // Формируем ссылку на изображение (если есть)
        let imageLink = null;
        if (offer.nft_data && offer.nft_data.url) {
          imageLink = offer.nft_data.url;
        } else if (offer.nft_id) {
          const nftName = offer.nft_name?.replace(/\s+/g, '') || 'Unknown';
          imageLink = `https://nft.fragment.com/gift/${nftName}-${offer.nft_id}.webp`;
        } else if (offer.nft_name) {
          imageLink = `https://nft.fragment.com/gift/${offer.nft_name.replace(/\s+/g, '')}-unknown.webp`;
        }
        
        // === ЗАПИСЬ В ИСТОРИЮ ОПЕРАЦИЙ (ТОЛЬКО operation_history) ===
        const refundOperation = {
          id: `op_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
          type: 'refund',
          amount: offerAmount.toString(),
          timestamp: new Date().toISOString(),
          transactionHash: null,
          walletAddress: offer.buyer_name,
          currency: 'TON',
          itemId: offer.item_id,
          nftId: offer.nft_id || 'unknown',
          nftName: offer.nft_name || 'Unknown NFT',
          offerId: offer.id,
          reason: refundReason,
          status: 'completed',
          link: imageLink
        };
        
        // Обновляем историю операций покупателя
        const currentHistory = buyerData.operation_history || [];
        const updatedHistory = [refundOperation, ...currentHistory].slice(0, 100);
        
        // Обновляем баланс и историю покупателя
        const { error: updateError } = await supabase
          .from('users')
          .update({ 
            ton_balance: newBalance,
            operation_history: updatedHistory
          })
          .eq('name', offer.buyer_name);
        
        if (updateError) {
          console.error(`❌ Ошибка обновления баланса для ${offer.buyer_name}:`, updateError);
          continue;
        }
        
        console.log(`✅ Возвращено ${offer.offer_price} TON пользователю ${offer.buyer_name}`);
        console.log(`📝 Операция возврата записана в operation_history:`, refundOperation);
        
        // 3. УДАЛЯЕМ ОФФЕР ИЗ ТАБЛИЦЫ
        const { error: deleteError } = await supabase
          .from('offers')
          .delete()
          .eq('id', offer.id);
        
        if (deleteError) {
          console.error(`❌ Ошибка удаления оффера ${offer.id}:`, deleteError);
          // Если не удалось удалить, пробуем хотя бы обновить статус
          await supabase
            .from('offers')
            .update({ 
              status: 'refunded',
              refund_reason: refundReason,
              refunded_at: new Date().toISOString()
            })
            .eq('id', offer.id);
          console.log(`⚠️ Оффер ${offer.id} помечен как refunded (не удален)`);
        } else {
          console.log(`✅ Оффер ${offer.id} УДАЛЕН из базы данных`);
        }
        
        // 4. Отправляем уведомление в Telegram продавцу (опционально)
        try {
          const { data: sellerData } = await supabase
            .from('users')
            .select('telegram')
            .eq('name', offer.seller_name)
            .single();
          
          if (sellerData && sellerData.telegram) {
            const messageText = `⏰ *Оффер истек*\n\n` +
              `*${offer.nft_name || 'NFT'}*\n` +
              `Предложение от ${offer.buyer_name} на ${offer.offer_price} TON истекло (24 часа).\n\n` +
              `Средства возвращены покупателю.`;
            
            await fetch('https://api.telegram.org/bot8549009179:AAES5a75EWbQs5roRKyosjUiNCTCgSUwRB4/sendMessage', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({
                chat_id: sellerData.telegram,
                text: messageText,
                parse_mode: 'Markdown'
              })
            });
            console.log(`📨 Уведомление отправлено продавцу ${offer.seller_name}`);
          }
        } catch (telegramError) {
          console.error('❌ Ошибка отправки уведомления продавцу:', telegramError);
        }
        
        // 5. Отправляем уведомление покупателю
        try {
          const { data: buyerUserData } = await supabase
            .from('users')
            .select('telegram')
            .eq('name', offer.buyer_name)
            .single();
          
          if (buyerUserData && buyerUserData.telegram) {
            const buyerMessageText = `💰 *Возврат средств*\n\n` +
              `Ваше предложение на *${offer.nft_name || 'NFT'}* истекло (24 часа).\n\n` +
              `💵 Сумма возврата: ${offer.offer_price} TON\n` +
              `🆔 ID предложения: ${offer.id.slice(0, 8)}...\n\n` +
              `Средства зачислены на ваш баланс.`;
            
            await fetch('https://api.telegram.org/bot8549009179:AAES5a75EWbQs5roRKyosjUiNCTCgSUwRB4/sendMessage', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({
                chat_id: buyerUserData.telegram,
                text: buyerMessageText,
                parse_mode: 'Markdown'
              })
            });
            console.log(`📨 Уведомление отправлено покупателю ${offer.buyer_name}`);
          }
        } catch (telegramError) {
          console.error('❌ Ошибка отправки уведомления покупателю:', telegramError);
        }
        
        // 6. Обновляем локальный баланс если это текущий пользователь
        if (offer.buyer_name === currentAccountName.value) {
          tonBalance.value = newBalance.toString();
          showNotification(`Your offer for ${offer.offer_price} TON has been refunded (expired)`, 'info');
        }
      }
    }
    
    console.log('✅ Все истекшие офферы обработаны');
    
  } catch (error) {
    console.error('❌ Ошибка проверки истекших офферов:', error);
  }
};
// Обновленная функция для получения отфильтрованных backdrop с учетом всех фильтров
const getFilteredBackdrops = () => {
  const query = backdropSearchQuery.value ? backdropSearchQuery.value.toLowerCase() : '';
  
  const filtered = backdropColors.value
    .filter(color => {
      const cleanColorId = color.id.toLowerCase().trim();
      const isAvailable = availableBackdropOptions.value.some(
        opt => opt.id === cleanColorId
      );
      const matchesSearch = color.name.toLowerCase().includes(query) ||
                           color.id.toLowerCase().includes(query);
      
      return isAvailable && matchesSearch;
    })
    .map(color => {
      const floorPrice = getFloorPrice('backdrop', color.id);
      
      return {
        id: color.id,
        name: color.name,
        svgContent: generateBackdropSVG(color.id),
        floorPrice: floorPrice,
        percentage: getBackdropPercentage(color.id),
        rarityText: getRarityText(getBackdropPercentage(color.id))
      };
    })
    .sort((a, b) => a.percentage - b.percentage);
  
  return filtered;
};

// Вспомогательная функция для получения процента backdrop
const getBackdropPercentage = (backdropId) => {
  const backdropData = availableBackdropOptions.value.find(
    opt => opt.id === backdropId.toLowerCase().trim()
  );
  return backdropData?.percentage || 0;
};


// Исправленная функция для получения backdrop - показываем все, что есть на рынке
const getFilteredBackdropOptions = () => {
  console.log('🔄 Getting ALL backdrop options from market data');
  
  if (!backdropColors.value) return [];
  
  // Собираем ВСЕ backdrop из текущих данных рынка
  const backdropDataMap = new Map();
  const items = getCurrentDataSource.value;
  
  items.forEach(item => {
    const backdrop = extractBackdropFromNft(item);
    if (backdrop) {
      // Извлекаем название и процент из данных NFT
      const backdropName = backdrop.replace(/\d+\.?\d*%/, '').trim();
      const percentageMatch = backdrop.match(/(\d+\.?\d*)%/);
      const percentage = percentageMatch ? parseFloat(percentageMatch[1]) : null;
      
      if (backdropName) {
        if (!backdropDataMap.has(backdropName)) {
          backdropDataMap.set(backdropName, {
            count: 0,
            percentage: percentage,
            floorPrice: Infinity
          });
        }
        
        // Обновляем счетчик
        const data = backdropDataMap.get(backdropName);
        data.count++;
        
        // Обновляем минимальную цену
        if (item.price_per_unit) {
          const price = parseFloat(item.price_per_unit);
          if (price < data.floorPrice) {
            data.floorPrice = price;
          }
        }
      }
    }
  });
  
  console.log('Все backdrop из данных рынка:', Array.from(backdropDataMap.entries()));
  
  // Фильтруем backdropColors по тем, которые есть в данных рынка
  let filtered = backdropColors.value.filter(color => {
    return Array.from(backdropDataMap.keys()).some(marketBackdrop => 
      marketBackdrop.toLowerCase() === color.name.toLowerCase()
    );
  });
  
  // Применяем поиск если есть запрос
  if (backdropSearchQuery.value) {
    const query = backdropSearchQuery.value.toLowerCase();
    filtered = filtered.filter(color => 
      color.name.toLowerCase().includes(query)
    );
  }
  
  const result = filtered.map(color => {
    // Находим данные для этого backdrop из данных рынка
    const backdropData = Array.from(backdropDataMap.entries()).find(([name, data]) => 
      name.toLowerCase() === color.name.toLowerCase()
    )?.[1];
    
    const count = backdropData ? backdropData.count : 0;
    const percentage = backdropData ? backdropData.percentage : null;
    const floorPrice = backdropData && backdropData.floorPrice !== Infinity ? backdropData.floorPrice : null;
    
    return {
      ...color,
      count: count,
      floorPrice: floorPrice,
      percentage: percentage,
      rarityText: percentage !== null ? `${percentage}%` : (count > 0 ? 'N/A' : 'No items'),
      rarityClass: getRarityClass(percentage),
      svgContent: generateBackdropSVG(color.id)
    };
  });
  
  console.log('Final backdrop options:', result.length);
  return result;
};

// Упрощенная функция extractBackdropFromNft
const extractBackdropFromNft = (item) => {
  try {
    if (!item) return null;
    
    // Если это unlisted NFT
    if (item.is_unlisted || item.nft_type?.includes('html_nft_')) {
      if (item.nft_object) {
        const nftObj = typeof item.nft_object === 'string' 
          ? JSON.parse(item.nft_object) 
          : item.nft_object;
        return nftObj.backdrop || null;
      }
      return null;
    }
    
    // Если это listed NFT из market
    if (item.nft_object) {
      const nftObj = typeof item.nft_object === 'string' 
        ? JSON.parse(item.nft_object) 
        : item.nft_object;
      return nftObj.backdrop || null;
    }
    
    return null;
  } catch (error) {
    console.warn('⚠️ Ошибка извлечения backdrop:', error);
    return null;
  }
};

// Упрощенная функция getBackdropFromNftObject
const getBackdropFromNftObject = (nftObject) => {
  if (!nftObject) return null;
  
  try {
    const nftObj = typeof nftObject === 'string' ? JSON.parse(nftObject) : nftObject;
    return nftObj.backdrop || null;
  } catch (e) {
    return null;
  }
};
// Функция для проверки статуса предложения (можно вызвать при загрузке страницы)
const checkOfferStatus = async (itemId) => {
  try {
    const { data, error } = await supabase
      .from('offers')
      .select('status')
      .eq('item_id', itemId)
      .eq('buyer_name', currentAccountName.value)
