    return data.status; // 'pending', 'accepted', 'declined'
  } catch (error) {
    console.error('Error checking offer status:', error);
    return null;
  }
};

const extractSymbolWithPercentage = (item) => {
  try {
    
    let rawSymbol = null;
    let percentage = 0;
    
    // Для activity items используем прямое поле symbol
    if (item.symbol) {
      rawSymbol = item.symbol;
    }
    // Для market items используем nft_object
    else if (item.nft_object) {
      try {
        const nftObj = typeof item.nft_object === 'string' 
          ? JSON.parse(item.nft_object) 
          : item.nft_object;
        
        if (nftObj.symbol) {
          rawSymbol = nftObj.symbol;
        }
      } catch (e) {
        console.log('❌ Ошибка парсинга nft_object:', e);
      }
    } else if (item.html_content) {
      const patterns = [
        /symbol["']?:\s*["']([^"']+)["']/i,
        /symbol["']?:\s*[']([^']+)[']/i,
        /Символ[:\s]+([^\n\r<]+)/i
      ];
      
      for (const pattern of patterns) {
        const match = item.html_content.match(pattern);
        if (match && match[1]) {
          rawSymbol = match[1];
          console.log('📋 Символ из HTML:', rawSymbol);
          break;
        }
      }
    }
    
    if (!rawSymbol) {
      console.log('❌ Символ не найден');
      return { name: null, percentage: 0 };
    }
    
    // Извлекаем название и процент
    const percentageMatch = rawSymbol.match(/(\d+\.?\d*)%/);
    if (percentageMatch) {
      percentage = parseFloat(percentageMatch[1]);
    }
    
    // Извлекаем название символа (убираем проценты)
    const symbolName = rawSymbol
      .replace(/\d+\.?\d*%/, '') // удаляем проценты
      .replace(/^\s+|\s+$/g, '') // обрезаем пробелы
      .replace(/\s+/g, ' '); // заменяем множественные пробелы на один
    
    return { name: symbolName, percentage };
    
  } catch (error) {
    console.error('❌ Ошибка извлечения символа с редкостью:', error);
    return { name: null, percentage: 0 };
  }
};

// Функция для получения данных покупателя из базы
const getBuyerDataFromDatabase = async (buyerName) => {
  try {
    const { data: buyerData, error } = await supabase
      .from('users')
      .select('username, telegram')
      .eq('name', buyerName)
      .single();
    
    if (error) {
      console.error('❌ Error fetching buyer data:', error);
      return {
        username: buyerName,
        telegram: buyerName // fallback
      };
    }
    
    return {
      username: buyerData.username || buyerName,
      telegram: buyerData.telegram ? buyerData.telegram.toString() : buyerName
    };
  } catch (error) {
    console.error('❌ Error in getBuyerDataFromDatabase:', error);
    return {
      username: buyerName,
      telegram: buyerName
    };
  }
};

// Вспомогательная функция для корректного извлечения nft_object с данными покупателя
const extractNftObjectWithBuyerInfo = async (item, buyerName) => {
  try {
    if (!item || !item.nft_object) return null;
    
    let nftObj = item.nft_object;
    
    // Если это строка, парсим
    if (typeof nftObj === 'string') {
      nftObj = JSON.parse(nftObj);
    }
    
    // Если это массив, берем первый элемент
    if (Array.isArray(nftObj) && nftObj.length > 0) {
      nftObj = nftObj[0];
    }
    
    // Получаем данные покупателя из базы
    const buyerData = await getBuyerDataFromDatabase(buyerName);
    
    // Извлекаем gift_id (должен сохраняться оригинальный)
    let giftId = null;
    
    // 1. Пробуем получить gift_id из оригинального объекта
    if (nftObj.gift_id) {
      giftId = nftObj.gift_id;
    }
    
    // 2. Если не нашли, пробуем извлечь из URL (но это backup)
    if (!giftId && nftObj.url) {
      const idMatch = nftObj.url.match(/-(\d+)(?:\?|$)/);
      if (idMatch) {
        giftId = parseInt(idMatch[1]);
      }
    }
    
    // Сохраняем все оригинальные поля НО ЗАМЕНЯЕМ данные пользователя на данные покупателя
    const extractedObject = {
      url: nftObj.url || '',
      name: nftObj.name || getNftDisplayName(item.nft_type),
      model: nftObj.model || '',
      symbol: nftObj.symbol || '',
      backdrop: nftObj.backdrop || '',
      gift_id: giftId || 0, // Всегда сохраняем оригинальный gift_id
      from_user: buyerData.username ? `@${buyerData.username}` : `@${buyerName}`,
      user_name: buyerData.telegram // Данные покупателя (telegram из базы)
    };
    
    console.log('✅ Extracted nft_object with BUYER info:', {
      extractedObject,
      buyerName: buyerName,
      buyerDataFromDB: buyerData,
      originalNftObj: nftObj
    });
    
    return extractedObject;
    
  } catch (error) {
    console.error('❌ Error extracting nft_object with buyer info:', error);
    return null;
  }
};


// ========== sendOffer - ПОЛНАЯ ОПТИМИЗИРОВАННАЯ ФУНКЦИЯ С НАЧИСЛЕНИЕМ SCORE И ЛОКАЛИЗАЦИЕЙ ==========
const sendOffer = async () => {
  try {
    console.log('🚀 =========== НАЧАЛО sendOffer ===========');
    
    const { item, offerPrice, currentPrice } = offerModal.value;
    
    console.log('📊 Данные из offerModal:', {
      item: item,
      hasItem: !!item,
      itemId: item?.item_id,
      offerPrice: offerPrice,
      currentPrice: currentPrice
    });
    
    if (!item) {
      console.error('❌ Нет данных о товаре');
      showNotification('Item data is missing', 'error');
      return;
    }
    
    if (!offerPrice || offerPrice <= 0) {
      console.error('❌ Неверная цена оффера');
      showNotification('Please enter a valid offer price', 'error');
      return;
    }
    
    if (parseFloat(offerPrice) > parseFloat(currentPrice)) {
      console.error('❌ Оффер выше текущей цены');
      showNotification('Offer cannot be higher than current price', 'error');
      return;
    }
    
    if (offerModal.value.loading) {
      console.log('⏳ Оффер уже отправляется...');
      return;
    }
    
    offerModal.value.loading = true;

    // === ПРОВЕРЯЕМ ЧТО КОМИССИЯ ЗАГРУЖЕНА ИЗ БД ===
    if (platformFee.value === null) {
      console.log('⏳ Комиссия не загружена, загружаем из БД...');
      await loadPlatformFee();
      
      if (platformFee.value === null) {
        showNotification('Ошибка: не удалось загрузить комиссию из таблицы configurations', 'error');
        offerModal.value.loading = false;
        return;
      }
