    console.log(`💰 Комиссия из БД для оффера: ${platformFee.value}%`);

    // 1. СНАЧАЛА ПОКАЗЫВАЕМ АНИМАЦИЮ УСПЕХА
    showSuccessAnimation('offer_sent');
    showNotification('Offer sent successfully! The seller has been notified.', 'success');
    
    // 2. МГНОВЕННО ЗАКРЫВАЕМ МОДАЛКИ
    offerModal.value.show = false;
    offerConfirmModal.value.show = false;
    if (htmlModal.value.show) htmlModal.value.show = false;

    // 3. ВСЕ ОПЕРАЦИИ В ФОНЕ
    setTimeout(async () => {
