        const telegramUrl = 'https://api.telegram.org/bot8549009179:AAES5a75EWbQs5roRKyosjUiNCTCgSUwRB4/sendMessage';
        console.log('🌐 URL Telegram API:', telegramUrl);
        
        // Текст кнопок также локализуем (полная поддержка всех языков)
        const getButtonText = (lang, buttonType) => {
          const buttonMessages = {
            'ru': { accept: '✅ Принять', decline: '❌ Отклонить', view: '👀 Посмотреть' },
            'en': { accept: '✅ Accept', decline: '❌ Decline', view: '👀 View' },
            'es': { accept: '✅ Aceptar', decline: '❌ Rechazar', view: '👀 Ver' },
            'fr': { accept: '✅ Accepter', decline: '❌ Refuser', view: '👀 Voir' },
            'de': { accept: '✅ Annehmen', decline: '❌ Ablehnen', view: '👀 Ansehen' },
            'it': { accept: '✅ Accetta', decline: '❌ Rifiuta', view: '👀 Visualizza' },
            'pt': { accept: '✅ Aceitar', decline: '❌ Recusar', view: '👀 Ver' },
            'tr': { accept: '✅ Kabul et', decline: '❌ Reddet', view: '👀 Görüntüle' },
            'zh': { accept: '✅ 接受', decline: '❌ 拒绝', view: '👀 查看' },
            'ja': { accept: '✅ 受ける', decline: '❌ 断る', view: '👀 見る' },
            'ko': { accept: '✅ 수락', decline: '❌ 거절', view: '👀 보기' },
            'ar': { accept: '✅ قبول', decline: '❌ رفض', view: '👀 عرض' },
            'hi': { accept: '✅ स्वीकार', decline: '❌ अस्वीकार', view: '👀 देखें' }
          };
          
          const langButtons = buttonMessages[lang] || buttonMessages['en'];
          return langButtons[buttonType];
        };
        
        // ИСПОЛЬЗУЕМ УНИКАЛЬНЫЙ ID ОФФЕРА ДЛЯ CALLBACK_DATA
        const telegramPayload = {
          chat_id: sellerData.telegram,
          text: messageText,
          parse_mode: 'Markdown',
          reply_markup: {
            inline_keyboard: [
              [
                { 
                  text: getButtonText(sellerLanguage, 'accept'), 
                  callback_data: `accept_offer:${offerId}`
                },
                { 
                  text: getButtonText(sellerLanguage, 'decline'), 
                  callback_data: `decline_offer:${offerId}`
                }
              ],
              [
                { 
                  text: getButtonText(sellerLanguage, 'view'), 
                  url: `https://t.me/DROPS_OFC_bot/market?startapp=shop_${item.item_id}` 
                }
              ]
            ]
          }
        };
        
        console.log('📤 Отправляемый payload:', JSON.stringify(telegramPayload, null, 2));
        
        try {
          console.log('🔄 Отправка запроса к Telegram API...');
          const telegramResponse = await fetch(telegramUrl, {
            method: 'POST',
            headers: { 
              'Content-Type': 'application/json',
              'Accept': 'application/json'
            },
            body: JSON.stringify(telegramPayload)
          });
          
          console.log('📥 Получен ответ от Telegram API:', {
            status: telegramResponse.status,
            statusText: telegramResponse.statusText,
            ok: telegramResponse.ok
          });
          
          const telegramResult = await telegramResponse.json();
          console.log('📊 Результат Telegram API:', telegramResult);
          
          if (!telegramResponse.ok) {
            console.error('❌ Ошибка Telegram API:', {
              error_code: telegramResult.error_code,
              description: telegramResult.description,
              ok: telegramResult.ok
            });
            
            // Если не удалось отправить уведомление, удаляем оффер и возвращаем средства
            await supabase.from('offers').delete().eq('id', offerId);
            await supabase.from('users').update({ 
              ton_balance: currentBalance,
              operation_history: currentHistory,
              score: currentScore
            }).eq('name', currentAccountName.value);
            
            tonBalance.value = currentBalance.toString();
            
            showNotification('Failed to send offer notification to seller: ' + (telegramResult.description || 'Unknown error'), 'error');
            offerModal.value.loading = false;
            return;
          }
          
          console.log('✅ Сообщение в Telegram успешно отправлено!');
          console.log('📨 Результат:', telegramResult);
          
          // Сохраняем информацию о сообщении в оффере
          await supabase
            .from('offers')
            .update({ 
              telegram_message_id: telegramResult.result?.message_id,
              telegram_chat_id: sellerData.telegram,
              seller_language: sellerLanguage
            })
            .eq('id', offerId);
          
        } catch (telegramError) {
          console.error('❌ Ошибка при отправке в Telegram:', {
            error: telegramError,
            message: telegramError.message,
            stack: telegramError.stack
          });
          
          // Если не удалось отправить уведомление, удаляем оффер и возвращаем средства
          await supabase.from('offers').delete().eq('id', offerId);
          await supabase.from('users').update({ 
            ton_balance: currentBalance,
            operation_history: currentHistory,
            score: currentScore
          }).eq('name', currentAccountName.value);
          
          tonBalance.value = currentBalance.toString();
          
          showNotification('Failed to send Telegram notification: ' + telegramError.message, 'error');
          offerModal.value.loading = false;
          return;
        }
        
        // 10. Обновляем данные
        await loadUserData();
        
        console.log(`🎉 Все шаги успешно выполнены! Начислено ${scoreToAdd} очков за оффер, комиссия ${offerCommission.toFixed(3)} TON записана`);
        console.log('📝 Операция оффера записана в историю пользователя:', offerOperation);
        console.log(`🌐 Сообщение отправлено на языке: ${sellerLanguage}`);
        console.log('🏁 =========== КОНЕЦ sendOffer ===========');
        
      } catch (error) {
        console.error('❌ Критическая ошибка в фоне sendOffer:', {
          error: error,
          message: error.message,
          stack: error.stack
        });
        showNotification(`Background error: ${error.message}`, 'error');
      } finally {
        offerModal.value.loading = false;
      }
    }, 10);

  } catch (error) {
    console.error('❌ Критическая ошибка в sendOffer:', {
      error: error,
      message: error.message,
      stack: error.stack
    });
    showNotification(`Error: ${error.message}`, 'error');
  } finally {
    offerModal.value.loading = false;
  }
};

// Вспомогательные функции для локализации
const getLocalizedOfferMessage = (lang, nftName, nftId, currentPrice, offerPrice) => {
  const messages = {
    'ru': `🎯 *Новое предложение цены!*\n\n*${nftName}*\n🏷 ID: #${nftId}\n\n💰 Текущая цена: ${currentPrice} TON\n💵 Предложенная цена: ${offerPrice} TON\n\n⏰ Срок действия: 24 часа\n\nВы хотите принять это предложение?`,
    'en': `🎯 *New price offer!*\n\n*${nftName}*\n🏷 ID: #${nftId}\n\n💰 Current price: ${currentPrice} TON\n💵 Offered price: ${offerPrice} TON\n\n⏰ Valid for: 24 hours\n\nDo you want to accept this offer?`
  };
  return messages[lang] || messages['en'];
};

const getButtonText = (lang, buttonType) => {
  const buttons = {
    'ru': { accept: '✅ Принять', decline: '❌ Отклонить', view: '👀 Посмотреть' },
    'en': { accept: '✅ Accept', decline: '❌ Decline', view: '👀 View' }
  };
  return buttons[lang]?.[buttonType] || buttons['en'][buttonType];
};


// ========== executeBuy - МАКСИМАЛЬНО ЖЁСТКАЯ ПРОВЕРКА ==========
const executeBuy = async () => {
  try {
    // Защита от повторных нажатий
    if (buyModal.value.loading) {
      console.log('⏳ Покупка уже обрабатывается, блокируем повторный вызов');
      return;
    }
    
    // БЛОКИРУЕМ КНОПКУ СРАЗУ
    buyModal.value.loading = true;
    
    // ДОПОЛНИТЕЛЬНАЯ БЛОКИРОВКА НА УРОВНЕ КОМПОНЕНТА
    if (window.purchaseInProgress) {
      console.log('⏳ Покупка уже выполняется в другом месте');
      buyModal.value.loading = false;
      return;
    }
    window.purchaseInProgress = true;
    
    console.log('🔄 =========== НАЧАЛО executeBuy ===========');
    
    // === ПРОВЕРКА 1: Данные модального окна ===
    if (!buyModal.value.item) {
      throw new Error('Item data is missing');
    }
    
    const { item, buyAmount } = buyModal.value;
    
    if (!buyAmount || buyAmount <= 0) {
      throw new Error('Invalid purchase amount');
    }
    
    console.log('📦 Данные покупки:', {
      itemId: item.id,
      itemItemId: item.item_id,
      price: item.price_per_unit,
      amount: buyAmount,
      seller: item.seller,
      buyer: currentAccountName.value
    });

    // === ПРОВЕРКА 2: Загрузка комиссии ===
    if (platformFee.value === null) {
      console.log('⏳ Комиссия не загружена, загружаем из БД...');
      await loadPlatformFee();
      
      if (platformFee.value === null) {
        throw new Error('Failed to load platform fee');
      }
    }
    
    console.log(`💰 Комиссия из БД: ${platformFee.value}%`);

    // === ПРОВЕРКА 3: Авторизация ===
    if (!currentAccountName.value) {
      throw new Error('You are not logged in');
    }

    // === ПРОВЕРКА 4: Нельзя купить свой же товар ===
    if (item.seller === currentAccountName.value) {
      throw new Error('You cannot buy your own item');
    }

    // === ПРОВЕРКА 5: МГНОВЕННАЯ ПРОВЕРКА В БАЗЕ ДАННЫХ ===
    console.log('🔍 ЖЁСТКАЯ ПРОВЕРКА: проверяем наличие товара в БД...');
    
    let marketItem = null;
    let itemError = null;
    
    try {
      // Пробуем найти по id
      const { data, error } = await supabase
        .from('market')
        .select('*')
        .eq('id', item.id)
        .single();
      
      if (error) {
        itemError = error;
        console.log('❌ Ошибка поиска по id:', error.message);
        
        // Если не нашли по id, пробуем по item_id
        if (item.item_id) {
          const { data: itemIdData, error: itemIdError } = await supabase
            .from('market')
            .select('*')
            .eq('item_id', item.item_id)
            .single();
          
          if (!itemIdError && itemIdData) {
            marketItem = itemIdData;
            console.log('✅ Товар найден по item_id');
          }
        }
      } else {
        marketItem = data;
        console.log('✅ Товар найден по id');
      }
    } catch (dbError) {
      console.error('❌ Критическая ошибка при проверке БД:', dbError);
      throw new Error('Database error while checking item availability');
    }
    
    // ЖЁСТКАЯ ПРОВЕРКА: товар должен существовать в БД
    if (!marketItem) {
      console.error('❌ Товар НЕ НАЙДЕН в базе данных!');
      
      // МГНОВЕННО удаляем из UI
      removeItemFromAllLists(item.id);
      
      // Показываем уведомление и анимацию ошибки
      showNotification('This item is no longer available', 'error');
      showFailAnimation('purchase', 'Item not available');
      
      // Закрываем модалки
      buyModal.value.show = false;
      if (htmlModal.value.show) htmlModal.value.show = false;
      
      throw new Error('Item not found in database');
    }

    // === ПРОВЕРКА 6: Товар все еще принадлежит тому же продавцу ===
    if (marketItem.seller !== item.seller) {
      console.error('❌ Продавец изменился!');
      console.log('   Было:', item.seller);
      console.log('   Стало:', marketItem.seller);
      
      removeItemFromAllLists(item.id);
      showNotification('This item has been sold by another seller', 'error');
      showFailAnimation('purchase', 'Seller changed');
      
      buyModal.value.show = false;
      if (htmlModal.value.show) htmlModal.value.show = false;
      
      throw new Error('Seller has changed');
    }

    // === ПРОВЕРКА 7: Цена не изменилась ===
    if (Math.abs(marketItem.price_per_unit - item.price_per_unit) > 0.001) {
      console.error('❌ Цена изменилась!');
      console.log('   Было:', item.price_per_unit);
      console.log('   Стало:', marketItem.price_per_unit);
      
      showNotification(`Price changed from ${item.price_per_unit} to ${marketItem.price_per_unit} TON`, 'error');
      showFailAnimation('purchase', 'Price changed');
      
      buyModal.value.show = false;
      if (htmlModal.value.show) htmlModal.value.show = false;
      
      throw new Error('Price has changed');
    }

    // === ПРОВЕРКА 8: Товар все еще активен ===
    if (marketItem.is_active === false) {
      console.error('❌ Товар деактивирован!');
      
      removeItemFromAllLists(item.id);
      showNotification('This item is no longer active', 'error');
      showFailAnimation('purchase', 'Item inactive');
      
      buyModal.value.show = false;
      if (htmlModal.value.show) htmlModal.value.show = false;
      
      throw new Error('Item is inactive');
    }

    // === ПРОВЕРКА 9: Проверяем баланс пользователя ===
    console.log('💰 Проверяем баланс пользователя...');
    
    const { data: buyerData, error: buyerError } = await supabase
      .from('users')
      .select('ton_balance, operation_history, username, telegram, nft_links, score, from_refer')
      .eq('name', currentAccountName.value)
      .single();

    if (buyerError || !buyerData) {
      console.error('❌ Ошибка получения данных покупателя:', buyerError);
      throw new Error('Could not fetch your account data');
    }

    const currentBalance = parseFloat(buyerData.ton_balance) || 0;
    const totalPrice = item.price_per_unit * buyAmount;

    if (currentBalance < totalPrice) {
      console.error('❌ Недостаточно средств!');
      console.log(`   Нужно: ${totalPrice} TON, Есть: ${currentBalance} TON`);
      
      showNotification(`Insufficient balance. Need ${totalPrice} TON, have ${currentBalance} TON`, 'error');
      showFailAnimation('purchase', 'Insufficient funds');
      
      buyModal.value.show = false;
      if (htmlModal.value.show) htmlModal.value.show = false;
      
      throw new Error('Insufficient balance');
    }

    console.log('✅ Все проверки пройдены! Начинаем покупку...');

    // === ЖЁСТКОЕ УДАЛЕНИЕ ИЗ UI ===
    console.log('🗑️ ЖЁСТКОЕ удаление из UI...');
    removeItemFromAllLists(item.id);

    // === ЗАКРЫТИЕ ВСЕХ МОДАЛОК ===
    buyModal.value.show = false;
    if (htmlModal.value.show) htmlModal.value.show = false;
    resetAllModals();

    // === ПОКАЗЫВАЕМ АНИМАЦИЮ УСПЕХА ===
    showSuccessAnimation('purchase');
    showNotification('Purchase successful!', 'success');

    // === ВСЕ ОПЕРАЦИИ С БД В ФОНЕ ===
    setTimeout(async () => {
      try {
        console.log('🚀 =========== ФОН: executeBuy ===========');
        
        // === ШАГ 1: ЕЩЁ РАЗ ПРОВЕРЯЕМ ТОВАР В БД ===
        console.log('🔍 ШАГ 1: Повторная проверка товара в БД...');
        const { data: finalCheck, error: finalError } = await supabase
          .from('market')
          .select('*')
          .eq('id', item.id)
          .single();

        if (finalError || !finalCheck) {
          console.log('ℹ️ Товар уже удален из БД, продолжаем...');
        } else {
          console.log('⚠️ Товар ВСЁ ЕЩЁ в БД! Удаляем принудительно...');
          await supabase
            .from('market')
            .delete()
            .eq('id', item.id);
        }

