    .eq('from_refer', buyerTelegramId?.toString());
  
  console.log('Рефереры, найденные по from_refer:', referrers);
  
  // 2. Проверяем всех пользователей у которых есть from_refer
  const { data: allWithRefer, error2 } = await supabase
    .from('users')
    .select('name, telegram, from_refer')
    .not('from_refer', 'is', null)
    .limit(10);
  
  console.log('Примеры пользователей с from_refer:', allWithRefer);
  
  return { referrers, allWithRefer };
};

// ВСПОМОГАТЕЛЬНАЯ ФУНКЦИЯ ДЛЯ УДАЛЕНИЯ ИЗ ВСЕХ СПИСКОВ
const removeItemFromAllLists = (itemId) => {
  console.log(`🗑️ Удаление ${itemId} из всех списков...`);
  
  let removed = false;
  
  // 1. Удаляем из marketItems
  const marketIndex = marketItems.value.findIndex(item => item.id === itemId);
  if (marketIndex !== -1) {
    marketItems.value.splice(marketIndex, 1);
    console.log(`✅ Удалено из marketItems, индекс: ${marketIndex}`);
    removed = true;
  }
  
  // 2. Удаляем из marketPagination.allItems
  const paginationIndex = marketPagination.value.allItems.findIndex(item => item.id === itemId);
  if (paginationIndex !== -1) {
    marketPagination.value.allItems.splice(paginationIndex, 1);
    console.log(`✅ Удалено из marketPagination.allItems, индекс: ${paginationIndex}`);
    removed = true;
  }
  
  // 3. Удаляем из allFilterOptions.marketItems
  if (allFilterOptions.value.marketItems) {
    const filterIndex = allFilterOptions.value.marketItems.findIndex(item => item.id === itemId);
    if (filterIndex !== -1) {
      allFilterOptions.value.marketItems.splice(filterIndex, 1);
      console.log(`✅ Удалено из allFilterOptions.marketItems, индекс: ${filterIndex}`);
      removed = true;
    }
  }
  
  // 4. Удаляем из корзины
  const cartIndex = cartItems.value.findIndex(item => item.id === itemId);
  if (cartIndex !== -1) {
    cartItems.value.splice(cartIndex, 1);
    console.log(`✅ Удалено из корзины`);
    removed = true;
  }
  
  // 5. Удаляем буст
  try {
    const storedPromoted = localStorage.getItem('promotedItems');
    if (storedPromoted) {
      const promotedList = JSON.parse(storedPromoted);
      const filteredPromoted = promotedList.filter(p => p.itemId !== itemId);
      localStorage.setItem('promotedItems', JSON.stringify(filteredPromoted));
      promotedItems.value = filteredPromoted;
      console.log(`✅ Буст удален из localStorage`);
    }
  } catch (e) {
    console.error('❌ Ошибка при удалении буста:', e);
  }
  
  if (!removed) {
    console.log(`⚠️ Товар ${itemId} не найден в списках`);
  }
  
  return removed;
};


// ВСПОМОГАТЕЛЬНАЯ ФУНКЦИЯ ДЛЯ ВОЗВРАТА СРЕДСТВ ПО ОФФЕРАМ
// ВСПОМОГАТЕЛЬНАЯ ФУНКЦИЯ ДЛЯ ВОЗВРАТА СРЕДСТВ ПО ОФФЕРАМ (УДАЛЕНИЕ ИЗ БД)
const refundOffersForItem = async (item) => {
  try {
    console.log('💰 Поиск активных офферов для возврата и удаления...');
    
    const { data: offers, error } = await supabase
      .from('offers')
      .select('*')
      .eq('item_id', item.item_id || item.id)
      .eq('status', 'pending');
    
    if (error) {
      console.error('❌ Ошибка поиска офферов:', error);
      return;
    }
    
    if (!offers || offers.length === 0) {
      console.log('✅ Нет активных офферов');
      return;
    }
    
    console.log(`📊 Найдено офферов: ${offers.length}`);
    
    for (const offer of offers) {
      try {
        // Получаем данные покупателя
        const { data: buyerData } = await supabase
          .from('users')
          .select('ton_balance, operation_history')
          .eq('name', offer.buyer_name)
          .single();
        
        if (buyerData) {
          const currentBalance = parseFloat(buyerData.ton_balance) || 0;
          const newBalance = currentBalance + parseFloat(offer.offer_price);
          
          // Возвращаем средства
          await supabase
            .from('users')
            .update({ 
              ton_balance: newBalance,
              operation_history: [
                {
                  id: `op_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
                  type: 'refund',
                  amount: offer.offer_price.toString(),
                  timestamp: new Date().toISOString(),
                  reason: 'item_sold'
                },
                ...(buyerData.operation_history || [])
              ].slice(0, 100)
            })
            .eq('name', offer.buyer_name);
          
          // 🔥🔥🔥 УДАЛЯЕМ ОФФЕР ИЗ БАЗЫ ДАННЫХ (вместо обновления статуса)
          const { error: deleteError } = await supabase
            .from('offers')
            .delete()
            .eq('id', offer.id);
          
          if (deleteError) {
            console.error(`❌ Ошибка удаления оффера ${offer.id}:`, deleteError);
            
            // Если не удалось удалить, пробуем хотя бы обновить статус
            await supabase
              .from('offers')
              .update({ 
                status: 'refunded',
                refunded_at: new Date().toISOString(),
                refund_reason: 'item_sold'
              })
              .eq('id', offer.id);
          } else {
            console.log(`✅ Оффер ${offer.id} удален из базы данных`);
          }
          
          console.log(`✅ Возвращено ${offer.offer_price} TON пользователю ${offer.buyer_name}`);
          
          // 🔥🔥🔥 УДАЛЯЕМ ОФФЕР ИЗ UI (если это текущий пользователь)
          if (offer.buyer_name === currentAccountName.value) {
            removeOfferFromUI(offer.id);
          }
        }
      } catch (offerError) {
        console.error(`❌ Ошибка при возврате оффера ${offer.id}:`, offerError);
      }
    }
  } catch (error) {
    console.error('❌ Ошибка в refundOffersForItem:', error);
  }
};

