// ========== executeCancelSale - С МГНОВЕННЫМ УДАЛЕНИЕМ ИЗ UI ==========
const executeCancelSale = async () => {
  try {
    if (cancelSaleModal.value.loading) return;
    
    cancelSaleModal.value.loading = true;
    
    const { item } = cancelSaleModal.value;

    if (!item) {
      showNotification('Invalid item data', 'error');
      cancelSaleModal.value.loading = false;
      return;
    }

    console.log('🔄 Снятие с продажи NFT...', item.id);

    // 🔥🔥🔥 МГНОВЕННО УДАЛЯЕМ ИЗ UI
    console.log('🗑️ МГНОВЕННО удаляем объявление из UI...');
    
    // Удаляем из marketItems (основной список)
    const itemIndex = marketItems.value.findIndex(marketItem => marketItem.id === item.id);
    if (itemIndex !== -1) {
      marketItems.value.splice(itemIndex, 1);
      console.log(`✅ Удалено из marketItems, индекс: ${itemIndex}`);
    }
    
    // Удаляем из marketPagination.allItems (lazy loading данные)
    const paginationIndex = marketPagination.value.allItems.findIndex(marketItem => marketItem.id === item.id);
    if (paginationIndex !== -1) {
      marketPagination.value.allItems.splice(paginationIndex, 1);
      console.log(`✅ Удалено из marketPagination.allItems, индекс: ${paginationIndex}`);
    }
    
    // Удаляем из allFilterOptions.marketItems (данные для фильтров)
    if (allFilterOptions.value.marketItems) {
      const filterIndex = allFilterOptions.value.marketItems.findIndex(marketItem => marketItem.id === item.id);
      if (filterIndex !== -1) {
        allFilterOptions.value.marketItems.splice(filterIndex, 1);
        console.log(`✅ Удалено из allFilterOptions.marketItems, индекс: ${filterIndex}`);
      }
    }
    
    // Удаляем из myMarketItems (если есть)
    if (myMarketItems.value) {
      const myMarketIndex = myMarketItems.value.findIndex(myItem => myItem.id === item.id);
      if (myMarketIndex !== -1) {
        myMarketItems.value.splice(myMarketIndex, 1);
        console.log(`✅ Удалено из myMarketItems, индекс: ${myMarketIndex}`);
      }
    }
    
    // Если товар был в корзине - удаляем оттуда
    if (isInCart(item.id)) {
      await removeFromCart(item.id);
      console.log('✅ Удалено из корзины');
    }
    
    console.log('✅ Объявление полностью удалено из UI');

    // 1. ПОКАЗЫВАЕМ АНИМАЦИЮ УСПЕХА (уже с удаленным объявлением)
    showSuccessAnimation('cancel_sale');
    showNotification('Sale cancelled! All pending offers refunded.', 'success');
    
    // 2. МГНОВЕННО ЗАКРЫВАЕМ МОДАЛКИ
    cancelSaleModal.value.show = false;
    if (htmlModal.value.show) htmlModal.value.show = false;

    // 3. ВСЕ ОПЕРАЦИИ С БД В ФОНЕ
    setTimeout(async () => {
      try {
        console.log('🚀 =========== ФОН: executeCancelSale ===========');
        
        // ШАГ 1: Возвращаем средства всем активным офферам
        console.log('🔍 ШАГ 1: Возвращаем средства по активным офферам...');
        
        let refundSuccess = false;
        try {
          refundSuccess = await refundAllPendingOffersForItem(item.id, 'item_removed_from_market');
          
          if (!refundSuccess) {
            console.warn('⚠️ Возврат средств по офферам завершился с предупреждениями, продолжаем отмену продажи...');
          } else {
            console.log('✅ Средства по офферам успешно возвращены');
          }
        } catch (refundError) {
          console.error('❌ Ошибка при возврате офферов:', refundError);
          // Продолжаем выполнение, даже если возврат офферов не удался
        }

        // ШАГ 2: Возвращаем NFT в коллекцию
        console.log('🔍 ШАГ 2: Возвращаем NFT в коллекцию...');
        let nftName = 'Unknown NFT';
        let nftObject = null;
        
        if (item.nft_object) {
          try {
            const parsedNftObj = typeof item.nft_object === 'string' 
              ? JSON.parse(item.nft_object) 
              : item.nft_object;
            nftName = parsedNftObj.name || nftName;
            nftObject = parsedNftObj;
          } catch (e) {
            console.warn('⚠️ Не удалось разобрать nft_object:', e);
          }
        }

        const nftData = {
          url: nftObject?.url || item.url || '',
          name: nftName,
          model: nftObject?.model || '',
          symbol: nftObject?.symbol || '',
          backdrop: nftObject?.backdrop || '',
          gift_id: nftObject?.gift_id || 0,
          from_user: nftObject?.from_user || '',
          user_name: nftObject?.user_name || '',
          acquired_at: new Date().toISOString()
        };

        console.log('📥 NFT data being restored to collection:', nftData);

        // Получаем текущие nft_links пользователя
        const { data: userData, error: userError } = await supabase
          .from('users')
          .select('nft_links, ton_balance, operation_history')
          .eq('name', currentAccountName.value)
          .single();

        if (userError) {
          console.error('❌ Ошибка получения данных пользователя:', userError);
          return;
        }

        const currentLinks = userData?.nft_links || [];
        
        // Проверяем, нет ли уже такого NFT в коллекции
        const nftExists = currentLinks.some(link => {
          const linkUrl = typeof link === 'object' ? link.url : link;
          return linkUrl === nftData.url;
        });

        let updatedLinks = currentLinks;
        if (!nftExists) {
          updatedLinks = [...currentLinks, nftData];
          console.log('✅ NFT будет добавлен в коллекцию');
        } else {
          console.log('ℹ️ NFT уже есть в коллекции, пропускаем добавление');
        }

        // Формируем ссылку на изображение
        let imageLink = null;
        if (nftData.url) {
          imageLink = nftData.url;
        } else {
          const nftNameForLink = nftName.replace(/\s+/g, '') || 'Unknown';
          const nftIdForLink = nftObject?.gift_id || extractNftIdFromData(item.nft_object) || 'unknown';
          imageLink = `https://nft.fragment.com/gift/${nftNameForLink}-${nftIdForLink}.webp`;
        }

        // Записываем операцию в историю пользователя
        const cancelOperation = {
          id: `op_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
          type: 'cancel_sale',
          amount: '0',
          timestamp: new Date().toISOString(),
          transactionHash: null,
          walletAddress: currentAccountName.value,
          currency: 'TON',
          itemId: item.id,
          nftName: nftName,
          offers_refunded: refundSuccess ? 'yes' : 'no',
          link: imageLink // Добавляем ссылку на изображение
        };

        const currentHistory = userData?.operation_history || [];
        const updatedHistory = [cancelOperation, ...currentHistory].slice(0, 100);

        // ПАРАЛЛЕЛЬНЫЕ ОПЕРАЦИИ С БД
        console.log('🔍 ШАГ 3: Выполняем параллельные операции с БД...');
        
        const operations = [
          supabase
            .from('users')
            .update({ 
              nft_links: updatedLinks,
              operation_history: updatedHistory
            })
            .eq('name', currentAccountName.value)
        ];

        // Удаляем из market (даже если он уже удален из UI)
        operations.push(
          supabase
            .from('market')
            .delete()
            .eq('id', item.id)
        );

        await Promise.all(operations);
        console.log('✅ Операции с БД выполнены');

        // ШАГ 4: Записываем активность
        console.log('🔍 ШАГ 4: Записываем активность...');
        const activityData = {
          operation_type: 'cancel_sale',
          user_name: currentAccountName.value,
          nft_type: item.nft_type,
          nft_object: nftObject || item.nft_object,
          price_per_unit: item.price_per_unit,
          currency: item.currency,
          amount: item.amount || 1,
          total_price: item.price_per_unit * (item.amount || 1),
          item_id: item.id,
          offer_refunds_processed: refundSuccess ? 'yes' : 'no'
        };
        
        await supabase
          .from('activity_history')
          .insert([activityData]);
        
        console.log('✅ NFT снято с продажи');
        
        // Обновляем unlisted NFT в UI
        if (activeTab.value === 'my-nfts' && myNftsViewMode.value === 'unlisted') {
          console.log('🔄 Обновляем unlisted NFT в UI...');
          
          // Добавляем NFT в unlisted список
          const unlistedItem = {
            id: `unlisted-${Date.now()}`,
            nft_type: item.nft_type,
            nft_object: nftData,
            seller: currentAccountName.value,
            is_unlisted: true,
            url: nftData.url,
            name: nftName,
            model: nftData.model,
            symbol: nftData.symbol,
            backdrop: nftData.backdrop,
            created_at: new Date().toISOString()
          };
          
          myUnlistedNfts.value = [unlistedItem, ...myUnlistedNfts.value];
          
          // Добавляем в myGiftsPagination.allItems для отображения
          myGiftsPagination.value.allItems = [
            unlistedItem,
            ...myGiftsPagination.value.allItems.filter(item => item.id !== `unlisted-${Date.now()}`)
          ];
          
          console.log('✅ Unlisted NFT добавлен в UI');
        }
        
        console.log('🏁 =========== КОНЕЦ ФОН: executeCancelSale ===========');

      } catch (error) {
        console.error('❌ Ошибка в фоне при снятии с продажи:', error);
        showNotification(`Background cancel failed: ${error.message}`, 'error');
      }
    }, 10);

  } catch (error) {
    console.error('❌ Ошибка снятия с продажи:', error);
    showNotification(`Cancel failed: ${error.message}`, 'error');
    showFailAnimation('cancellation_failed', 'Cancellation Failed');
  } finally {
    cancelSaleModal.value.loading = false;
  }
};

// Обновленная функция extractNameFromNftObject с корректной обработкой массива
const extractNameFromNftObject = (item) => {
  if (!item) return { name: 'Unknown NFT', number: '' };
  
  try {
    let name = 'Unknown NFT';
    let number = '';
    
    if (item.nft_object) {
      let nftObj = item.nft_object;
      
      // Если это строка, парсим
      if (typeof nftObj === 'string') {
        nftObj = JSON.parse(nftObj);
      }
      
      // Если это массив, берем первый элемент
      if (Array.isArray(nftObj) && nftObj.length > 0) {
        nftObj = nftObj[0];
      }
      
      name = nftObj.name || name;
      
      // В первую очередь используем gift_id (он всегда должен быть)
      if (nftObj.gift_id) {
        number = nftObj.gift_id.toString();
      } else if (nftObj.url) {
        // Если gift_id нет, только тогда извлекаем из URL
        const idMatch = nftObj.url.match(/-(\d+)(?:\?|$)/);
        if (idMatch) {
          number = idMatch[1];
        }
      }
    }
    
    return { name, number };
  } catch (error) {
    console.error('Error extracting name from NFT object:', error);
    return { name: 'Unknown NFT', number: '' };
  }
};

// Обновленная функция для извлечения Gift ID из nft_object
const extractGiftIdFromNftObject = (nftObject) => {
  try {
    if (!nftObject) return 0;
    
    let obj = nftObject;
    
    // Если это строка, парсим
    if (typeof obj === 'string') {
      obj = JSON.parse(obj);
    }
    
    // Если это массив, берем первый элемент
    if (Array.isArray(obj) && obj.length > 0) {
      obj = obj[0];
    }
    
    // 1. Пробуем получить gift_id из объекта
    if (obj.gift_id) {
      return obj.gift_id;
    }
    
    // 2. Если не нашли, пробуем извлечь из URL
    if (obj.url) {
      const match = obj.url.match(/-(\d+)(?:\?|$)/);
      return match ? parseInt(match[1]) : 0;
    }
    
    return 0;
  } catch (error) {
    console.error('Error extracting gift ID:', error);
    return 0;
  }
};

