// Функция отправки подарка
// Функция отправки подарка
// Функция отправки подарка
const sendGift = async () => {
  try {
    giftModal.value.loading = true;

    const { item, recipientUsername, isOwnItem } = giftModal.value;
    
    // Добавляем проверку на пустое имя получателя
    if (!recipientUsername || recipientUsername.trim() === '') {
      showNotification('Please enter recipient username', 'error');
      giftModal.value.loading = false;
      return;
    }

    // Получаем username текущего пользователя
    const currentUsername = await getCurrentUserUsername();
    
    // 🔥 ПРОВЕРКА: Нельзя отправить подарок самому себе
    if (currentUsername && recipientUsername.toLowerCase() === currentUsername.toLowerCase()) {
      showNotification('You cannot send a gift to yourself', 'error');
      giftModal.value.loading = false;
      return;
    }

    const giftPrice = item?.price_per_unit;

    const { data: users, error: recipientError } = await supabase
      .from('users')
      .select('name, username, nft_links')
      .ilike('username', recipientUsername)
      .limit(1);

    if (recipientError) {
      console.error('Error checking recipient:', recipientError);
      showNotification('Error checking recipient', 'error');
      giftModal.value.loading = false;
      return;
    }

    // Проверяем, найден ли пользователь
    if (!users || users.length === 0) {
      showNotification('Recipient not found', 'error');
      giftModal.value.loading = false;
      return;
    }

    const recipientData = users[0];
    
    // 🔥 ДОПОЛНИТЕЛЬНАЯ ПРОВЕРКА: Сравниваем с username текущего пользователя
    if (currentUsername && recipientData.username.toLowerCase() === currentUsername.toLowerCase()) {
      showNotification('You cannot send a gift to yourself', 'error');
      giftModal.value.loading = false;
      return;
    }
    
    const recipientNameForDb = recipientData.name || recipientData.username;

    if (isOwnItem) {
      // СВОЕ объявление - бесплатная передача
      await sendOwnItemAsGift(item, recipientNameForDb);
    } else {
      // ЧУЖОЕ объявление - покупка и отправка
      await sendPurchasedItemAsGift(item, recipientNameForDb, giftPrice);
    }

    showNotification(`Gift sent successfully to ${recipientData.username}!`, 'success');
    giftModal.value.show = false;
    
    // Закрываем полноэкранный просмотр если открыт
    if (htmlModal.value.show) {
      htmlModal.value.show = false;
    }

  } catch (error) {
    console.error('Error sending gift:', error);
    showNotification('Error sending gift: ' + error.message, 'error');
  } finally {
    giftModal.value.loading = false;
  }
};


const sendPurchasedItemAsGift = async (item, recipientName, giftPrice) => {
  // Получаем данные отправителя
  const { data: senderData, error: senderError } = await supabase
    .from('users')
    .select('ton_balance, operation_history, username')
    .eq('name', currentAccountName.value)
    .single();

  if (senderError) throw new Error('Failed to get sender data');

  const senderBalance = parseFloat(senderData.ton_balance) || 0;
  if (senderBalance < giftPrice) {
    throw new Error(`Insufficient TON balance. Need ${giftPrice} TON, have ${senderBalance} TON`);
  }

  // Получаем данные получателя
  const { data: recipientData, error: recipientError } = await supabase
    .from('users')
    .select('nft_links, operation_history, username')
    .eq('name', recipientName)
    .single();

  if (recipientError) throw new Error('Failed to get recipient data');

  // Получаем данные продавца
  const { data: sellerData, error: sellerFetchError } = await supabase
    .from('users')
    .select('ton_balance, operation_history')
    .eq('name', item.seller)
    .single();

  if (sellerFetchError) console.warn('Could not fetch seller data');

  // ====== ИЗВЛЕКАЕМ ОРИГИНАЛЬНЫЕ ДАННЫЕ NFT ======
  let originalNftData = null;
  
  if (item.nft_object) {
    originalNftData = typeof item.nft_object === 'string' 
      ? JSON.parse(item.nft_object) 
      : item.nft_object;
  } else {
    originalNftData = item;
  }

  // ====== КОПИРУЕМ ВСЕ ПОЛЯ ======
  const nftData = {
    // Основные поля
    url: originalNftData.url || item.nft_object?.url || item.url || '',
    name: originalNftData.name || extractNameFromNftObject(item).name || 'Unknown NFT',
    model: originalNftData.model || item.nft_object?.model || '',
    symbol: originalNftData.symbol || item.nft_object?.symbol || '',
    backdrop: originalNftData.backdrop || item.nft_object?.backdrop || '',
    
    // КРИТИЧЕСКИЕ ПОЛЯ ДЛЯ WITHDRAW
    gift_id: originalNftData.gift_id || item.nft_object?.gift_id || 0,
    msg_id: originalNftData.msg_id || item.nft_object?.msg_id || null,
    user_name: originalNftData.user_name || item.nft_object?.user_name || originalNftData.from_user || '',
    from_user: originalNftData.from_user || item.nft_object?.from_user || '',
    
    // Дополнительная информация о подарке
    acquired_at: new Date().toISOString(),
    gifted: true,
    gifted_from: currentAccountName.value,
    gifted_at: new Date().toISOString(),
    original_seller: item.seller,
    
    // Копируем ВСЕ остальные поля из оригинального объекта
    ...originalNftData
  };

  const nftId = extractNftIdFromData(nftData) || 'unknown';
  
  // 🔥 ИСПРАВЛЕНИЕ: Используем динамическую комиссию из platformFee
  // Если комиссия не загружена, используем 2% как запасной вариант
  const feePercent = platformFee.value !== null ? platformFee.value / 100 : 0.02;
  const sellerAmount = giftPrice * (1 - feePercent);
  const commissionAmount = giftPrice * feePercent;

  console.log(`💰 Gift purchase with commission: ${feePercent * 100}%`);
  console.log(`   - Gift price: ${giftPrice} TON`);
  console.log(`   - Commission: ${commissionAmount.toFixed(2)} TON`);
  console.log(`   - Seller receives: ${sellerAmount.toFixed(2)} TON`);
  console.log(`   - NFT Data preserved - gift_id: ${nftData.gift_id}, user_name: ${nftData.user_name}`);

  // === ЗАПИСЬ В ИСТОРИЮ ПОКУПАТЕЛЯ (с комиссией) ===
  const purchaseOperation = {
    id: `op_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
    type: 'gift_purchase',
    amount: giftPrice.toString(),
    commission: commissionAmount.toString(),
    timestamp: new Date().toISOString(),
    walletAddress: currentAccountName.value,
    currency: 'TON',
    recipient: recipientName,
    recipient_username: recipientData.username || recipientName,
    seller: item.seller,
    nftName: nftData.name,
    nftId: nftId,
    link: nftData.url || null,
    gift_id: nftData.gift_id // Сохраняем gift_id в истории
  };

  const senderCurrentHistory = senderData.operation_history || [];
  const updatedSenderHistory = [purchaseOperation, ...senderCurrentHistory].slice(0, 100);

  // === ЗАПИСЬ В ИСТОРИЮ ПОЛУЧАТЕЛЯ ===
  const receiveOperation = {
    id: `op_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
    type: 'gift_received',
    amount: '0',
    timestamp: new Date().toISOString(),
    walletAddress: recipientName,
    currency: 'TON',
    sender: currentAccountName.value,
    sender_username: currentAccountName.value,
    original_seller: item.seller,
    nftName: nftData.name,
    nftId: nftId,
    link: nftData.url || null,
    gift_id: nftData.gift_id, // Сохраняем gift_id в истории
    purchase_price: giftPrice
  };

  const recipientCurrentHistory = recipientData.operation_history || [];
  const updatedRecipientHistory = [receiveOperation, ...recipientCurrentHistory].slice(0, 100);

  // === ЗАПИСЬ В ИСТОРИЮ ПРОДАВЦА (с комиссией) ===
  let updatedSellerHistory = null;
  if (sellerData) {
    const saleOperation = {
      id: `op_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
      type: 'sale_for_gift',
      amount: sellerAmount.toString(),
      commission: commissionAmount.toString(),
      timestamp: new Date().toISOString(),
      walletAddress: item.seller,
      currency: 'TON',
      buyer: currentAccountName.value,
      recipient: recipientName,
      nftName: nftData.name,
      nftId: nftId,
      link: nftData.url || null,
      gift_id: nftData.gift_id // Сохраняем gift_id в истории
    };

    const sellerCurrentHistory = sellerData.operation_history || [];
    updatedSellerHistory = [saleOperation, ...sellerCurrentHistory].slice(0, 100);
  }

  // Обновляем балансы
  const newSenderBalance = senderBalance - giftPrice;
  const recipientLinks = recipientData.nft_links || [];
  const updatedRecipientLinks = [...recipientLinks, nftData];

  // === ДОБАВЛЯЕМ ЗАПИСЬ КОМИССИИ В ТАБЛИЦУ CONFIGURATIONS ===
  try {
    await updateConfigurationsStats(commissionAmount, 'gift_purchase_commission');
    console.log(`✅ Commission ${commissionAmount.toFixed(2)} TON recorded in configurations`);
  } catch (configError) {
    console.error('❌ Failed to record commission in configurations:', configError);
    // Не прерываем основной процесс, если не удалось записать комиссию
  }

  // Удаляем с рынка
  await supabase.from('market').delete().eq('id', item.id);

  // Обновляем всех участников
  await supabase
    .from('users')
    .update({ ton_balance: newSenderBalance, operation_history: updatedSenderHistory })
    .eq('name', currentAccountName.value);

  await supabase
    .from('users')
    .update({ nft_links: updatedRecipientLinks, operation_history: updatedRecipientHistory })
    .eq('name', recipientName);

  if (sellerData && updatedSellerHistory) {
    const sellerNewBalance = (parseFloat(sellerData.ton_balance) || 0) + sellerAmount;
    await supabase
      .from('users')
      .update({ ton_balance: sellerNewBalance, operation_history: updatedSellerHistory })
      .eq('name', item.seller);
  }

  // Обновляем локальные данные
  tonBalance.value = newSenderBalance.toString();
  await loadMarketItems();
  
  if (isInCart(item.id)) {
    await removeFromCart(item.id);
  }
  
  // 🔥 ПОКАЗЫВАЕМ АНИМАЦИЮ УСПЕХА
  console.log('🎉 Gift purchase successful! All original NFT data preserved:', {
    gift_id: nftData.gift_id,
    user_name: nftData.user_name,
    from_user: nftData.from_user,
    msg_id: nftData.msg_id
  });
  showSuccessAnimation('gift_sent');
  
  console.log('✅ Gift purchase completed successfully');
  console.log(`   - Commission paid: ${commissionAmount.toFixed(2)} TON`);
  console.log(`   - Seller received: ${sellerAmount.toFixed(2)} TON`);
};
const sendOwnItemAsGift = async (item, recipientName) => {
  // Получаем данные получателя
  const { data: recipientData, error: recipientError } = await supabase
    .from('users')
    .select('nft_links, operation_history, username')
    .eq('name', recipientName)
    .single();

  if (recipientError) {
    throw new Error('Failed to get recipient data');
  }

  // Получаем данные отправителя
  const { data: senderData, error: senderDataError } = await supabase
    .from('users')
    .select('operation_history, nft_links')
    .eq('name', currentAccountName.value)
    .single();

  if (senderDataError) {
    throw new Error('Failed to get sender data');
  }

  // ====== ИЗВЛЕКАЕМ ОРИГИНАЛЬНЫЕ ДАННЫЕ NFT ======
  let originalNftData = null;
  
  // Пытаемся извлечь данные из разных источников
  if (item.nft_object) {
    // Если это market item (listed NFT)
    originalNftData = typeof item.nft_object === 'string' 
      ? JSON.parse(item.nft_object) 
      : item.nft_object;
  } else {
    // Если это unlisted NFT или другой формат
    originalNftData = item;
  }

  // ====== КРИТИЧЕСКИ ВАЖНО: КОПИРУЕМ ВСЕ ПОЛЯ ======
  const nftData = {
    // Основные поля
    url: originalNftData.url || item.nft_object?.url || item.url || '',
    name: originalNftData.name || extractNameFromNftObject(item).name || 'Unknown NFT',
    model: originalNftData.model || item.nft_object?.model || '',
    symbol: originalNftData.symbol || item.nft_object?.symbol || '',
    backdrop: originalNftData.backdrop || item.nft_object?.backdrop || '',
    
    // КРИТИЧЕСКИЕ ПОЛЯ ДЛЯ WITHDRAW
    gift_id: originalNftData.gift_id || item.nft_object?.gift_id || 0,
    msg_id: originalNftData.msg_id || item.nft_object?.msg_id || null,
    user_name: originalNftData.user_name || item.nft_object?.user_name || originalNftData.from_user || '',
    from_user: originalNftData.from_user || item.nft_object?.from_user || '',
    
    // Дополнительная информация о подарке
    gifted: true,
    gifted_from: currentAccountName.value,
    gifted_at: new Date().toISOString(),
    
    // Сохраняем дату приобретения
    acquired_at: originalNftData.acquired_at || new Date().toISOString(),
    
    // Копируем ВСЕ остальные поля из оригинального объекта
    ...originalNftData
  };

  // Получаем ID NFT для записи
  const nftId = extractNftIdFromData(nftData) || 'unknown';

  // === ЗАПИСЬ В ИСТОРИЮ ОТПРАВИТЕЛЯ ===
  const sendOperation = {
    id: `op_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
    type: 'gift_sent',
    amount: '0',
    timestamp: new Date().toISOString(),
    walletAddress: currentAccountName.value,
    currency: 'TON',
    recipient: recipientName,
    recipient_username: recipientData.username || recipientName,
    nftName: nftData.name,
    nftId: nftId,
    link: nftData.url || null,
    gift_id: nftData.gift_id // Сохраняем gift_id в истории
  };

  const senderCurrentHistory = senderData.operation_history || [];
  const updatedSenderHistory = [sendOperation, ...senderCurrentHistory].slice(0, 100);

  // === ЗАПИСЬ В ИСТОРИЮ ПОЛУЧАТЕЛЯ ===
  const receiveOperation = {
    id: `op_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
    type: 'gift_received',
    amount: '0',
    timestamp: new Date().toISOString(),
    walletAddress: recipientName,
    currency: 'TON',
    sender: currentAccountName.value,
    sender_username: currentAccountName.value,
    nftName: nftData.name,
    nftId: nftId,
    link: nftData.url || null,
    gift_id: nftData.gift_id // Сохраняем gift_id в истории
  };

  const recipientCurrentHistory = recipientData.operation_history || [];
  const updatedRecipientHistory = [receiveOperation, ...recipientCurrentHistory].slice(0, 100);

  // Добавляем NFT получателю
  const recipientCurrentLinks = recipientData.nft_links || [];
  const updatedRecipientLinks = [...recipientCurrentLinks, nftData];

  // Удаляем NFT у отправителя
  if (item.is_unlisted) {
    if (senderData && senderData.nft_links) {
      const updatedSenderLinks = senderData.nft_links.filter(nft => {
        // Сравниваем по URL или gift_id
        const nftUrl = typeof nft === 'object' ? nft.url : nft;
        return nftUrl !== nftData.url && nft.gift_id !== nftData.gift_id;
      });
      await supabase
        .from('users')
        .update({ nft_links: updatedSenderLinks, operation_history: updatedSenderHistory })
        .eq('name', currentAccountName.value);
    }
  } else {
    await supabase.from('market').delete().eq('id', item.id);
    await supabase
      .from('users')
      .update({ operation_history: updatedSenderHistory })
      .eq('name', currentAccountName.value);
  }

  // Обновляем получателя
  await supabase
    .from('users')
    .update({ nft_links: updatedRecipientLinks, operation_history: updatedRecipientHistory })
    .eq('name', recipientName);

  // Обновляем локальные данные
  if (item.is_unlisted) {
    await loadUnlistedNfts();
  } else {
    await loadMarketItems();
  }
  
  // 🔥 ПОКАЗЫВАЕМ АНИМАЦИЮ УСПЕХА ДЛЯ БЕСПЛАТНОЙ ПЕРЕДАЧИ
  console.log('🎉 Free gift sent successfully! All original NFT data preserved:', {
    gift_id: nftData.gift_id,
    user_name: nftData.user_name,
    from_user: nftData.from_user,
    msg_id: nftData.msg_id
  });
  showSuccessAnimation('gift_sent_free');
};





    const extractNftType = (nftType) => {
