const calculateRarityTextForMarket = (count, total) => {
  // Эта функция только для Market, не заменяет основную логику
  if (!total) return 'Common';
  const percentage = (count / total) * 100;
  if (percentage < 5) return 'Legendary';
  if (percentage < 15) return 'Epic';
  if (percentage < 30) return 'Rare';
  return 'Common';
};

const calculateRarityClassForMarket = (count, total) => {
  // Эта функция только для Market, не заменяет основную логику
  if (!total) return 'common';
  const percentage = (count / total) * 100;
  if (percentage < 5) return 'legendary';
  if (percentage < 15) return 'epic';
  if (percentage < 30) return 'rare';
  return 'common';
};
