// Добавьте эти функции для получения доступных символов и фонов
const getAvailableSymbolOptions = () => {
  console.log('🔍 Получение доступных символов для фильтрации');
  
  let allItems = [];
  let sourceName = '';
  
  if (activeTab.value === 'market') {
    allItems = allFilterOptions.value.marketItems || [];
    sourceName = 'Market';
  } else if (activeTab.value === 'my-nfts') {
    allItems = allFilterOptions.value.myGiftsItems || [];
    sourceName = 'My Gifts';
  } else if (activeTab.value === 'activity') {
    allItems = allFilterOptions.value.activityItems || [];
    sourceName = 'Activity';
  }
  
  const symbolMap = new Map(); // Используем Map для уникальных символов
  
  allItems.forEach(item => {
    let symbol = '';
    
    if (activeTab.value === 'activity') {
      symbol = extractSymbolFromActivityItem(item);
    } else {
      symbol = extractSymbolFromNft(item);
    }
    
    if (symbol && symbol.trim()) {
      const normalizedSymbol = normalizeSymbolName(symbol);
      const symbolKey = normalizedSymbol.toLowerCase();
      
      if (!symbolMap.has(symbolKey)) {
        symbolMap.set(symbolKey, {
          name: symbol, // Сохраняем оригинальное имя для отображения
          normalized: normalizedSymbol,
          count: 1,
          // Сохраняем первый item для получения дополнительных данных
          sampleItem: item
        });
      } else {
        const existing = symbolMap.get(symbolKey);
        existing.count += 1;
      }
    }
  });
  
  const symbols = Array.from(symbolMap.values())
    .map(s => {
      // Получаем базовые данные
      const symbolData = {
        name: s.name,
        normalized: s.normalized,
        count: s.count
      };
      
      // Добавляем floorPrice ТОЛЬКО для вкладки Market
      if (activeTab.value === 'market') {
        // Для Market можем рассчитать floorPrice на основе данных
        let floorPrice = null;
        
        // Если есть данные о ценах, находим минимальную
        if (s.sampleItem && s.sampleItem.price_per_unit) {
          floorPrice = parseFloat(s.sampleItem.price_per_unit);
        } else {
          // Fallback: случайная цена для демонстрации (только на Market)
          floorPrice = parseFloat((Math.random() * 4.5 + 0.5).toFixed(1));
        }
        
        return {
          ...symbolData,
          floorPrice: floorPrice
        };
      }
      
      // Для других вкладок оставляем без floorPrice
      return symbolData;
    })
    .sort((a, b) => a.name.localeCompare(b.name));
  
  console.log(`📊 Уникальные символы в ${sourceName}: ${symbols.length}`);
  if (symbols.length > 0) {
    console.log(`📋 Список символов в ${sourceName}:`, symbols.map(s => `${s.name} (${s.count})`).join(', '));
  }
  
  return symbols;
};


