// Функция для получения стабильной модели (вместо случайной)
const getStableModelForNft = async (nftName) => {
  try {
    // Используем хэш имени NFT для детерминированного выбора
    const models = await getAvailableModelsForNft(nftName);
    if (!models || models.length === 0) return null;
    
    // Создаем простой хэш из имени NFT для стабильного выбора
    let hash = 0;
    for (let i = 0; i < nftName.length; i++) {
      hash = ((hash << 5) - hash) + nftName.charCodeAt(i);
      hash = hash & hash; // Convert to 32bit integer
    }
    
    // Выбираем модель на основе хэша
    const index = Math.abs(hash) % models.length;
    return models[index];
  } catch (error) {
    console.error('Ошибка получения стабильной модели:', error);
    return null;
  }
};

