// Функция для расчета суммы с комиссией
const calculateWithCommission = (price) => {
  // Убеждаемся что platformFee.value - число
  let feePercent = Number(platformFee.value);
  if (isNaN(feePercent) || feePercent < 0) {
    console.warn('⚠️ Невалидное значение комиссии в calculateWithCommission, используем 2%');
    feePercent = 2;
  }
  
  const commission = price * (feePercent / 100);
  const finalAmount = price - commission;
  
  console.log(`💰 calculateWithCommission: ${feePercent}% от ${price} TON = ${commission} TON, к получению: ${finalAmount} TON`);
  
  return finalAmount;
};

