    // 1. СРАЗУ УДАЛЯЕМ ИЗ MY GIFTS (UI)
    console.log('🗑️ Немедленно удаляем NFT из My Gifts...');
    
    if (activeTab.value === 'my-nfts' && myNftsViewMode.value === 'unlisted') {
      // Удаляем из UI сразу, не дожидаясь ответа сервера
      const nftId = extractNftIdFromData(nftData);
      const beforeCount = myGiftsPagination.value.allItems.length;
      
      // Фильтруем unlisted NFT
