    // === ДОБАВЛЯЕМ ЗАПИСЬ ОПЕРАЦИИ В ИСТОРИЮ ===
    try {
      // Формируем ссылку на изображение
      let imageLink = null;
      
      // Пытаемся получить URL из разных источников
      if (nftData && nftData.url) {
        // Если есть прямой URL (для unlisted NFT)
        imageLink = nftData.url;
      } else if (nftData && nftData.nft_object && nftData.nft_object.url) {
        // Если данные в nft_object (для обычных NFT)
