      } else if (nftData && nftData.url) {
        // Прямой URL
        imageLink = nftData.url;
      } else {
        // Fallback - генерируем ссылку из имени NFT
        const nftName = extractNftDataWithNumber(nftData).name || 'Unknown';
        const nftId = extractNftIdFromData(nftData) || 'unknown';
        imageLink = `https://nft.fragment.com/gift/${nftName.replace(/\s+/g, '')}-${nftId}.webp`;
      }

      // Получаем данные пользователя для обновления истории
      const { data: userData, error: userFetchError } = await supabase
        .from('users')
        .select('operation_history')
        .eq('name', currentAccountName.value)
        .single();

      if (!userFetchError && userData) {
        // Создаем запись операции
        const operation = {
          id: `op_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
