        };

        // Обновляем историю
        const currentHistory = userData.operation_history || [];
        const updatedHistory = [operation, ...currentHistory].slice(0, 100);

        await supabase
          .from('users')
          .update({ operation_history: updatedHistory })
          .eq('name', currentAccountName.value);

        console.log('✅ Операция листинга записана в историю:', operation);
      }
    } catch (historyError) {
      console.warn('⚠️ Не удалось записать операцию в историю:', historyError);
      // Не прерываем основной процесс
    }
    // === КОНЕЦ ДОБАВЛЕНИЯ ===

    // 4. Удаляем из коллекции пользователя (база данных)
    if (nftData && nftData.url) {
      await removeNftFromUserCollection(nftData);
    }

    // 5. Удаляем из локального списка unlisted NFT
    if (nftData && nftData.url) {
      myUnlistedNfts.value = myUnlistedNfts.value.filter(
        nft => nft.url !== nftData.url
