    }

    // 6. Записываем активность и обновляем данные
    await recordListingActivity(data[0]);
    
    // 7. Обновляем market данные
    await loadMarketItems();
    
    // 8. Если мы в My Gifts, переключаемся на Listed и обновляем
    if (activeTab.value === 'my-nfts') {
      console.log('🔄 Переключаемся на Listed в My Gifts...');
      myNftsViewMode.value = 'listed';
      
      // Перезагружаем listed NFT
      await loadMyGifts(false);
      
      // Показываем уведомление о переключении
      showNotification('NFT перемещен в Listed. Обновляем список...', 'info');
