// Обновленная функция для получения отфильтрованных символов из offers
const getFilteredSymbolOptions = () => {
  const query = searchQuery.value ? searchQuery.value.toLowerCase() : '';
  
  console.group('🎯 GET FILTERED SYMBOL OPTIONS FROM OFFERS');
  
  const currentDataSource = getCurrentDataSource.value;
  console.log('📊 Текущий источник данных:', currentDataSource.length, 'items');
  
  const symbolData = [];
  const seenSymbols = new Set();
  
  // Собираем уникальные символы из offers
  currentDataSource.forEach(item => {
    const symbol = item.symbol;
    if (symbol && !seenSymbols.has(symbol)) {
      seenSymbols.add(symbol);
      
      // Извлекаем название и процент
      const symbolName = symbol.replace(/\d+\.?\d*%/, '').trim();
      const percentageMatch = symbol.match(/(\d+\.?\d*)%/);
      const percentage = percentageMatch ? parseFloat(percentageMatch[1]) : 0;
      
      // Генерируем HTML контент для символа используя вашу функцию
      const htmlContent = generateSymbolHtml(symbolName);
      
      // Определяем класс редкости
      let rarityClass = 'common';
      if (percentage < 1) {
        rarityClass = 'ultra-rare';
      } else if (percentage < 5) {
        rarityClass = 'rare';
      } else if (percentage < 15) {
        rarityClass = 'uncommon';
      }
      
      symbolData.push({
        name: symbolName,
        value: symbolName.toLowerCase(),
        percentage: percentage,
        rarityText: percentage > 0 ? `${percentage}%` : 'N/A',
        rarityClass: rarityClass,
        count: 1,
        floorPrice: getFloorPriceForOffer('symbol', symbolName),
        htmlContent: htmlContent
      });
      
      console.log(`📋 Найден символ: "${symbol}" -> "${symbolName}" (${percentage}%)`);
    }
  });
  
  // Сортируем по проценту (редкости)
  symbolData.sort((a, b) => a.percentage - b.percentage);
  
  console.log(`📊 Всего символов: ${symbolData.length}`);
  
  // СОРТИРОВКА: сначала выбранные, потом невыбранные
  const selectedSymbols = symbolData.filter(symbol => 
    isOptionSelected('symbol', symbol.name)
  );
  const unselectedSymbols = symbolData.filter(symbol => 
    !isOptionSelected('symbol', symbol.name)
  );
  
  const sortedSymbols = [...selectedSymbols, ...unselectedSymbols];
  
  if (!query) {
    console.log('✅ Без поискового запроса, возвращаем все символы');
    console.groupEnd();
    return sortedSymbols;
  }
  
  const filteredSymbols = sortedSymbols.filter(symbol => 
    symbol.name.toLowerCase().includes(query) ||
    symbol.rarityText.toLowerCase().includes(query)
  );
  
  console.log(`🔎 После фильтрации по запросу "${query}": ${filteredSymbols.length} символов`);
  console.groupEnd();
  
  return filteredSymbols;
};



