// Функция для backdrop (используем вашу существующую)
const generateBackdropSVG = (colorName) => {
  try {
    // Создаем корректный ID для SVG (убираем пробелы)
    const svgId = colorName.replace(/\s+/g, '_');
    
    // Получаем градиент из вашего объекта gradients
    const gradient = gradients[svgId] || gradients['Black'];
    
    return `
      <svg width="100%" height="100%" viewBox="0 0 420 420" xmlns="http://www.w3.org/2000/svg" preserveAspectRatio="xMidYMid slice">
        <defs>
          <radialGradient id="${svgId}" cx="50%" cy="50%" fx="50%" fy="50%" r="69.65%" gradientTransform="translate(0.5, 0.5), scale(0.6667, 1), rotate(90), translate(-0.5, -0.5)">
            ${gradient.stops.map(stop => 
              `<stop stop-color="${stop.color}" offset="${stop.offset}"></stop>`
            ).join('')}
          </radialGradient>
        </defs>
        <rect x="0" y="0" width="420" height="420" fill="url(#${svgId})"></rect>
      </svg>
    `;
  } catch (error) {
    console.error('Error generating backdrop SVG:', error);
    return `
      <svg width="100%" height="100%" viewBox="0 0 420 420" xmlns="http://www.w3.org/2000/svg">
        <rect x="0" y="0" width="420" height="420" fill="#cccccc"></rect>
      </svg>
    `;
  }
};


// Универсальная функция для получения чистого имени символа
const getCleanSymbolName = (symbol) => {
  if (!symbol || !symbol.name) return '';
  
  // Для Activity: имя содержит процент в конце
  if (activeTab.value === 'activity') {
    return symbol.name.replace(/\s*\d+\.?\d*%\s*$/, '').trim();
  }
  
  // Для Market и MyGifts: имя уже чистое
  return symbol.name;
};

// Универсальная функция для отображения редкости символа
const getSymbolRarityDisplay = (symbol) => {
  if (!symbol) return '';
  
  // Вариант 1: Прямое поле percentage (для Market/MyGifts)
  if (symbol.percentage && symbol.percentage.trim()) {
    return symbol.percentage;
  }
  
  // Вариант 2: Извлекаем процент из имени (для Activity)
  if (symbol.name) {
    const match = symbol.name.match(/(\d+\.?\d*)%$/);
    if (match) {
      return `${match[1]}%`;
    }
  }
  
  // Вариант 3: Поле rarityText
  if (symbol.rarityText && symbol.rarityText.trim()) {
    return symbol.rarityText;
  }
  
  // Вариант 4: Если есть rarityClass, преобразуем в текст
  if (symbol.rarityClass) {
    const rarityMap = {
      'legendary': 'Легендарный',
      'epic': 'Эпический', 
      'rare': 'Редкий',
      'common': 'Обычный'
    };
    return rarityMap[symbol.rarityClass] || symbol.rarityClass;
  }
  
  return '';
};

// Функция для получения процента как числа (для сортировки)
const getSymbolRarityValue = (symbol) => {
  if (!symbol) return 0;
  
  // Пробуем получить процент разными способами
  let percentageText = '';
  
  if (symbol.percentage) {
    percentageText = symbol.percentage;
  } else if (symbol.name) {
    const match = symbol.name.match(/(\d+\.?\d*)%$/);
    if (match) {
      percentageText = match[1];
    }
  }
  
  // Преобразуем в число
  const value = parseFloat(percentageText);
  return isNaN(value) ? 0 : value;
};

