const generateNftImageUrl = async (nftName) => {
  if (nftImageCache.value[nftName]) {
    return nftImageCache.value[nftName];
  }
  
  try {
    // Форматируем имя
    const formattedNftName = nftName
      .toLowerCase()
      .replace(/[^a-z0-9]/g, '')
      .trim();
    
    // Получаем модель
    const modelName = await getRandomModelFromNft(nftName);
    
    // Генерируем URL
    const imageUrl = `https://storage.portal-market.com/portals-market/gifts/${formattedNftName}/models/png/${modelName}.png`;
    
    // Быстрая проверка URL
    const isAvailable = await testImageUrl(imageUrl);
    
    if (isAvailable) {
      nftImageCache.value[nftName] = imageUrl;
      return imageUrl;
    } else {
      nftImageCache.value[nftName] = default_nft_image;
      return default_nft_image;
    }
    
  } catch (error) {
    nftImageCache.value[nftName] = default_nft_image;
    return default_nft_image;
  }
};
const testImageUrl = (url) => {
  return new Promise((resolve) => {
    const img = new Image();
    
    img.onload = () => {
      console.log('✅ Тест URL успешен:', url);
      resolve(true);
    };
    
    img.onerror = (e) => {
      console.error('❌ Тест URL провален:', url);
      console.error('Ошибка:', e);
      resolve(false);
    };
    
    img.src = url;
    
    // Увеличим таймаут
    setTimeout(() => {
      console.warn('⚠️ Таймаут теста URL:', url);
      resolve(false);
    }, 3000);
  });
};

const isOptionSelected = (category, option) => {
  if (category === 'price') {
    return selectedIdFilter.value !== null;
  }
  
  if (!selectedFilters.value[category]) {
    return false;
  }
  
  let optionToCheck = option;
  
  // Нормализуем опцию для сравнения
  if (category === 'nft') {
    optionToCheck = normalizeNftName(option);
  } else if (category === 'symbol') {
    optionToCheck = normalizeSymbolName(option);
  } else if (category === 'backdrop') {
    optionToCheck = typeof option === 'object' ? option.id : option;
  } else if (category === 'model') {
    optionToCheck = option.toLowerCase().trim();
      }
  
  const result = selectedFilters.value[category].some(selected => {
    let normalizedSelected = selected;
    
    // Нормализуем выбранное значение для сравнения
    if (category === 'nft') {
      normalizedSelected = normalizeNftName(selected);
    } else if (category === 'symbol') {
      normalizedSelected = normalizeSymbolName(selected);
    } else if (category === 'model') {
      normalizedSelected = selected.toLowerCase().trim();
      console.log(`   Сравнение моделей: "${optionToCheck}" === "${normalizedSelected}"`);
    }
    
    return normalizedSelected === optionToCheck;
  });
  
  if (category === 'model') {
  }
  return result;
};



// Вспомогательные функции для работы с редкостью
