      symbol: calculateFloorPriceForSymbol(),
      backdrop: calculateFloorPriceForBackdrop()
    };
    
    console.log('✅ Floor prices вычислены:', floorPrices);
    floorPrices.value = floorPrices; // Предполагая, что у вас есть reactive переменная floorPrices
  } catch (error) {
