      // Удаляем старый обработчик если есть
      marketContainer.removeEventListener('scroll', handleContainerScroll);
      
      // Добавляем новый
      marketContainer.addEventListener('scroll', handleContainerScroll);
      
      // Проверяем сразу после загрузки, может уже нужно подгружать
      setTimeout(() => {
        console.log('🔍 Первоначальная проверка скролла');
        handleContainerScroll();
      }, 500);
    } else {
      console.warn('⚠️ Контейнер не найден при инициализации');
    }
  });
};



