const setupContainerObserver = () => {
  const container = document.querySelector('.market-container');
  if (!container) return;
  
  const observer = new ResizeObserver(() => {
    console.log('📏 Размер контейнера изменился');
    // Проверяем, нужно ли подгружать данные после изменения размера
    setTimeout(() => {
      handleContainerScroll();
    }, 100);
  });
  
  observer.observe(container);
  
  return observer;
};

