watch(() => myUnlistedNfts.value, (newNfts) => {
  if (newNfts && newNfts.length > 0) {
    // Быстрая проверка на дубликаты в реальном времени
    const keys = new Set();
    const hasDuplicates = newNfts.some(nft => {
      const key = createNftUniqueKey(nft);
      if (keys.has(key)) return true;
      keys.add(key);
      return false;
    });
    
    if (hasDuplicates) {
      console.log('⚠️ Обнаружены дубликаты в myUnlistedNfts, выполняем очистку...');
      // Не блокируем поток, выполняем асинхронно
      setTimeout(() => {
        removeDuplicatesFromDatabase();
      }, 100);
    }
  }
}, { deep: true });
