const loadNftFilterOptions = async () => {
  const currentTab = activeTab.value;
  
  if (!currentTab || nftOptionsLoading.value) {
    return;
  }
  
  nftOptionsLoading.value = true;
  
  try {
    console.log(`📥 Загрузка NFT опций для вкладки: ${currentTab}`);
    
    // В зависимости от вкладки используем разные источники данных
    let dataSource = [];
    
    if (currentTab === 'market') {
      dataSource = allFilterOptions.value.marketItems || [];
    } else if (currentTab === 'my-nfts') {
      dataSource = allFilterOptions.value.myGiftsItems || [];
    } else if (currentTab === 'activity') {
      dataSource = allFilterOptions.value.activityItems || [];
    }
    
    // Обработка данных...
    const processedOptions = processNftOptionsFromDataSource(dataSource);
    nftOptions.value = processedOptions;
    
    console.log(`✅ Загружено ${processedOptions.length} NFT опций для ${currentTab}`);
    
  } catch (error) {
    console.error('❌ Ошибка загрузки NFT опций:', error);
    nftOptions.value = [];
  } finally {
    nftOptionsLoading.value = false;
  }
};
