const setItemTypeClasses = () => {
  if (activeTab.value !== 'market') return;
  
  nextTick(() => {
    const items = document.querySelectorAll('.market-page[data-tab="market"] .market-item');
    
    items.forEach(item => {
      const actions = item.querySelector('.item-actions');
      if (!actions) return;
      
      // Проверяем наличие кнопок
      const hasEditButton = !!actions.querySelector('.edit-price-button');
      const hasCancelButton = !!actions.querySelector('.cancel-sale-button');
      const hasBuyButton = !!actions.querySelector('.buy-button');
      
      // Удаляем предыдущие классы
      item.classList.remove('with-edit-cancel', 'with-buy-only');
      
      // Добавляем класс в зависимости от кнопок
      if (hasEditButton || hasCancelButton) {
        item.classList.add('with-edit-cancel');
      } else if (hasBuyButton) {
        item.classList.add('with-buy-only');
      }
    });
  });
};

// Вызываем при загрузке и изменениях
watch(() => marketItems.value, () => {
  setItemTypeClasses();
