const adjustAddCardHeight = () => {
  // Только для My Gifts
  if (activeTab.value !== 'my-nfts') return;
  
  const grid = document.querySelector('.my-gifts-page .market-grid');
  if (!grid) return;
  
  const items = Array.from(grid.children);
  
  // Группируем по рядам (по 2 в ряд)
  for (let i = 0; i < items.length; i += 2) {
    const rowItems = items.slice(i, i + 2);
    
    // Находим максимальную высоту в ряду
    let maxHeight = 0;
    rowItems.forEach(item => {
      const height = item.offsetHeight;
      if (height > maxHeight) maxHeight = height;
    });
    
    // Применяем ко всем элементам в ряду
    if (maxHeight > 0) {
      rowItems.forEach(item => {
        item.style.height = maxHeight + 'px';
      });
    }
  }
};

