/* История операций */
.history-modal {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: rgba(0,0,0,0.5);
  display: flex;
  justify-content: center;
  align-items: center;
  z-index: 1000;
  padding: 20px;
}

.history-content {
  background-color: rgb(34, 34, 34);
  padding: 20px;
  border-radius: 12px;
  width: 100%;
  max-width: 500px;
  max-height: 80vh;
  overflow-y: auto;
  position: relative;
  box-shadow: 0 0 20px rgba(255, 196, 0, 0.5);
  border: 2px solid #ffc400;

}

.history-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 15px;
  padding-bottom: 10px;
  border-bottom: 1px solid #eee;
}

.history-header h3 {
  margin: 0;
  color: #ffd000;
  font-size: 1.3rem;
}

.close-history {
  background: none;
  border: none;
  font-size: 1.5rem;
  cursor: pointer;
  color: #666;
  padding: 5px;
  transition: color 0.2s;
}

.close-history:hover {
  color: #333;
}

.history-tabs {
  display: flex;
  border-bottom: 1px solid #000000;
  margin-bottom: 15px;
}

.tab-button {
  flex: 1;
  padding: 10px;
  background: none;
  border: none;
  border-bottom: 2px solid transparent;
  cursor: pointer;
  font-size: 0.95rem;
  color: #ffffff;
  transition: all 0.2s;
}

.tab-button.active {
  color: #ffd700;
  border-bottom-color: #ffd700;
  font-weight: bold;
}

.tab-button:hover:not(.active) {
  color: #333;
}

.loading-history {
  text-align: center;
  padding: 30px 0;
  color: #666;
  font-size: 1rem;
}

.history-list {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.history-item {
  display: flex;
  background-color: #525252;
  border-radius: 8px;
  padding: 12px;
  transition: all 0.2s;
  box-shadow: 0 2px 8px rgba(0,0,0,0.5);
}

.history-item:hover {
  transform: translateY(-2px);
  box-shadow: 0 2px 5px rgba(0,0,0,0.1);
}

.item-type {
  width: 80px;
  padding: 5px;
  border-radius: 4px;
  text-align: center;
  font-size: 0.8rem;
  font-weight: bold;
  margin-right: 12px;
  align-self: center;
}

.item-type.sale {
  background-color: rgb(28, 131, 31);
  color: rgb(0, 0, 0);
}

.item-type.transfer {
  background-color: rgb(28, 131, 31);
  color: rgb(0, 0, 0);
}

.item-type.buy {
  background-color: #ffbb00;
  color: rgb(2, 2, 2);
}

.item-details {
  flex: 1;
}

.item-info {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 5px;
}

.item-name {
  font-weight: bold;
  color: #ffc400;
}

.item-amount {
  color: #dddddd;
}

.item-price {
  color: rgb(28, 131, 31);
  font-weight: bold;
}

.item-recipient, 
.item-counterparty {
  color: rgb(28, 131, 31);
}

.item-total {
  text-align: right;
  font-weight: bold;
  color: #333;
}

.item-date {
  display: block;
  font-size: 0.8rem;
  color: #bdbdbd;
  margin-top: 3px;
}

.item-date-full {
  text-align: right;
  font-size: 0.8rem;
  color: #888;
}

/* Анимации */
@keyframes fadeIn {
  from { 
    opacity: 0;
    bottom: 0;
  }
  to { 
    opacity: 1;
    bottom: 20px;
  }
}

@keyframes fadeOut {
  from { 
    opacity: 1;
    bottom: 20px;
  }
  to { 
    opacity: 0;
    bottom: 0;
  }
}

/* Адаптивность */
@media (max-width: 500px) {
  .market-grid {
    grid-template-columns: 2fr;
  }
  
  .market-item {
    flex-direction: row;
  }
  
  .item-image {
    flex: 0 0 80px;
    margin-right: 15px;
    margin-bottom: 0;
  }
  
  .item-image img {
    max-width: 80px;
  }
}

@media (max-width: 480px) {
  .page-container {
    padding: 15px 10px 70px;
  }
  
  .navigation {
    margin-bottom: 15px;
  }
  
  .nav-button {
    padding: 10px 15px;
    font-size: 0.9rem;
  }
  
  .nft-page, 
  .market-page {
    padding: 15px;
  }
  
  .nft-item, 
  .market-item {
    flex-direction: column;
  }
  
  .nft-image, 
  .item-image img {
    width: 100%;
    height: auto;
    margin: 10px 0 0 0;
  }
  
  .button-group {
    flex-direction: column;
  }
  
  .modal-content {
    padding: 15px;
  }
  
  .market-item {
    flex-direction: column;
  }
  
  .item-image {
    flex: 0 0 auto;
    margin-right: 0;
    margin-bottom: 12px;
  }
}

