@keyframes fadeIn {
  from { 
    opacity: 0;
    bottom: 0;
  }
  to { 
    opacity: 1;
    bottom: 20px;
  }
}

@keyframes fadeOut {
  from { 
    opacity: 1;
    bottom: 20px;
  }
  to { 
    opacity: 0;
    bottom: 0;
  }
}

