.listed-unlisted-toggle-container {
  width: 100%;
  max-width: 400px;
  margin: 0 auto 20px auto;
  display: flex;
  flex-direction: column;
  align-items: center;
}

.listed-unlisted-toggle.ios-toggle {
  position: relative;
  width: 100%;
  max-width: 1000px;
  height: 30px;
  background: #1f1f1f;
  border-radius: 22px;
  display: flex;
  align-items: center;
  padding: 4px;
  box-sizing: border-box;
}

.toggle-track {
  position: absolute;
  top: 0px;
  left: 0px;
  right: 0px;
  bottom: 0px;
  background: #1f1f1f;
  border-radius: 50px;
  transition: all 0.3s ease;
}

.toggle-track.active {
  background: #1f1f1f;
}

.toggle-thumb {
  position: absolute;

  width: 50%;
  height: calc(100%);
  background: #ffbb00;
  border-radius: 20px;
  transition: all 0.3s ease;
}

.toggle-thumb.active {
  transform: translateX(100%);
}

.toggle-input {
  position: absolute;
  opacity: 0;
  width: 100%;
  height: 100%;
  cursor: pointer;
  z-index: 2;
}

.toggle-labels {
  position: relative;
  display: flex;
  width: 100%;
  height: 100%;
  z-index: 1;
}

.toggle-label {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
  font-weight: 500;
  color: #666;
  transition: color 0.3s ease;
  z-index: 1;
}

.toggle-label.active {
  color: white;
}

/* Расположение меток - Listed слева, Unlisted справа */
.toggle-labels {
  position: relative;
}

.toggle-label:first-child {
  order: 1;
}

.toggle-label:last-child {
  order: 2;
}

/* Для активного состояния - меняем порядок если нужно */
.toggle-track.active ~ .toggle-labels .toggle-label:first-child {
  color: #666;
}

.toggle-track.active ~ .toggle-labels .toggle-label:last-child {
  color: white;
}
.toggle-labels-below {
  display: flex;
  width: 100%;
  max-width: 1000px;
  margin-top: 5px;
}

.toggle-labels-below .toggle-label {
  font-size: 14px;
  font-weight: 500;
  color: #666;
  transition: color 0.3s ease;
}

.toggle-labels-below .toggle-label.active {
  color: #ffbb00;
  font-weight: 600;
}
.floor-price {
