/* Увеличьте специфичность для выбранных элементов */

/* Убедитесь, что hover не переопределяет selected */
.filter-option.selected:hover {
  background-color: rgba(255, 196, 0, 0.2) !important;
  transform: none !important;
}


.filter-header {
  display: flex;
  align-items: center; /* Выравниваем по центру по вертикали */
  gap: 10px;
  padding: 12px;

  height: 60px; /* Фиксированная высота для контейнера */
  box-sizing: border-box;
}

.search-box {
  flex: 1;
  display: flex;
}

.search-input {
  width: 100%;
  height: 36px; /* Фиксированная высота */
  padding: 0 12px;
  border-radius: 6px;
  font-size: 14px;
  box-sizing: border-box;
  margin: 0;
  line-height: 36px; /* Центрируем текст по вертикали */
  vertical-align: middle; /* Убираем смещение */
}

.clear-filter-btn {
  height: 36px; /* Такая же высота как у input */
  padding: 0 16px;
  background: #ca3a3a;
  color: white;
  border: none;
  border-radius: 15px;
  cursor: pointer;
  font-size: 14px;
  font-weight: 500;
  white-space: nowrap;
  flex-shrink: 0;
  min-width: 70px;
  font-weight: 800;
  line-height: 36px; /* Центрируем текст */
  vertical-align: middle; /* Убираем смещение */
  margin-bottom:40px;
}
.clear-filter-btn:hover:not(:disabled) {
  background: #ff5252;
  transform: translateY(-1px);
}

.clear-filter-btn:disabled {
  background: #ccc;
  cursor: not-allowed;
  opacity: 0.6;
}

.clear-filter-btn:active:not(:disabled) {
  transform: translateY(0);
}
/* Убираем все возможные отступы и границы по умолчанию */
.search-input, .clear-filter-btn {
  margin: 0;
}

.clear-filter-btn {
  border-color: #ff6b6b; /* Граница того же цвета что и фон */
    margin-bottom:15px;

}

/* Адаптивность для мобильных */
@media (max-width: 768px) {
  .filter-header {
    height: 56px;
    padding: 10px;
    gap: 8px;
  }
  
  .search-input {
    height: 36px;
    line-height: 36px;
    padding: 0 10px;
    font-size: 16px; /* Увеличиваем для мобильных */
    font-weight: 700;
  }
  
  .clear-filter-btn {
    height: 36px;
    line-height: 36px;
    padding: 0 14px;
    min-width: 65px;
    font-size: 13px;
  }
}
