/* Добавьте в CSS */
.html-container {
  cursor: pointer;
  position: relative;
}

.html-container::after {
  position: absolute;
  bottom: 10px;
  left: 50%;
  transform: translateX(-50%);
  color: white;
  padding: 5px 10px;
  border-radius: 5px;
  font-size: 12px;
  opacity: 0;
  transition: opacity 0.3s;
  pointer-events: none;
}

.html-container:hover::after {
  opacity: 1;
}


.html-content-iframe {
  cursor: pointer;
  transition: transform 0.2s ease;
}

.html-content-iframe:active {
  transform: scale(0.98);
}

/* Опционально: добавить подсказку при наведении */
.html-container-wrapper {
  position: relative;
}

.html-container-wrapper::after {
  position: absolute;
  bottom: -25px;
  left: 50%;
  transform: translateX(-50%);
  background: rgba(0, 0, 0, 0.8);
  color: white;
  padding: 5px 10px;
  border-radius: 4px;
  font-size: 12px;
  opacity: 0;
  transition: opacity 0.3s;
  pointer-events: none;
  white-space: nowrap;
}

.html-container-wrapper:hover::after {
  opacity: 1;
}
