  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  z-index: 10;
  transition: all 0.2s ease;
}

.cart-overlay-button:hover:not(:disabled) {
  background: rgba(0, 0, 0, 0.0);
  transform: scale(1.1);
}

.cart-overlay-button:disabled {
  cursor: not-allowed;
  opacity: 0.5;
}

.cart-overlay-button.in-cart {
  background: rgba(0,0,0, 0.0);
}

.cart-overlay-button.in-cart:hover:not(:disabled) {
  background: rgba(220, 53, 69, 0.9);
}

.cart-overlay-icon {
  width: 35px;
  height: 35px;
  object-fit: contain;
}
/* Общие стили для всех модальных окон в стиле filter-dropdown */
.modal-dropdown {
  position: fixed;
  bottom: 0;
  left: 50%;
  transform: translateX(-50%);
  width: 95%;
  max-width: 500px;
  max-height: 80vh;
  background: #1a1a1a;
  border-radius: 20px 20px 0 0;
  box-shadow: 0 -5px 25px rgba(0, 0, 0, 0.5);
  z-index: 1000;
  overflow: hidden;
  animation: slideUp 0.3s ease-out;
}

.modal-dropdown-overlay {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(0, 0, 0, 0.5);
  z-index: 999;
  animation: fadeIn 0.3s ease-out;
}

.modal-drag-handle {
  width: 40px;
  height: 4px;
  background: #666;
  border-radius: 2px;
  margin: 12px auto;
  cursor: grab;
}

.modal-dropdown-header {
  padding: 16px 20px;
  border-bottom: 1px solid #333;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.modal-dropdown-title {
  font-size: 18px;
  font-weight: 600;
  color: white;
  margin: 0;
}

.modal-dropdown-content {
  padding: 20px;
  max-height: calc(80vh - 120px);
  overflow-y: auto;
}

.modal-dropdown-actions {
  padding: 16px 20px;
  display: flex;
  gap: 12px;
  justify-content: flex-end;
}

@keyframes slideUp {
  from {
    transform: translateX(-50%) translateY(100%);
  }
  to {
    transform: translateX(-50%) translateY(0);
  }
}

@keyframes fadeIn {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}
/* Обновленные стили для модальных окон - подняты выше */
.modal-dropdown {
  position: fixed;
  bottom: 60px; /* Поднимаем над нижним меню */
  left: 50%;
  transform: translateX(-50%);
  width: 95%;
  max-width: 500px;
  max-height: 70vh; /* Уменьшаем высоту чтобы не упиралось в верх */
  background: #1a1a1a;
  border-radius: 20px;
  box-shadow: 0 -5px 25px rgba(0, 0, 0, 0.5);
  z-index: 1000;
  overflow: hidden;
  animation: slideUpHigher 0.3s ease-out;
}

.modal-dropdown-overlay {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(0, 0, 0, 0.5);
  z-index: 999;
  animation: fadeIn 0.3s ease-out;
}

.modal-drag-handle {
  width: 40px;
  height: 4px;
  background: #666;
  border-radius: 2px;
  margin: 12px auto;
  cursor: grab;
}

.modal-dropdown-header {
  padding: 16px 20px;
  border-bottom: 1px solid #333;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.modal-dropdown-title {
  font-size: 18px;
  font-weight: 600;
  color: white;
  margin: 0;
}

.modal-dropdown-content {
  padding: 20px;
  max-height: calc(70vh - 120px); /* Уменьшаем высоту контента */
  overflow-y: auto;
}

.modal-dropdown-actions {
  padding: 16px 20px;
  border-top: 1px solid #333;
  display: flex;
  gap: 12px;
  justify-content: flex-end;
}

/* Новая анимация - появляется выше */
@keyframes slideUpHigher {
  from {
    transform: translateX(-50%) translateY(100%);
    opacity: 0;
  }
  to {
    transform: translateX(-50%) translateY(0);
    opacity: 1;
  }
}

@keyframes fadeIn {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

/* Адаптация для маленьких экранов */
@media (max-height: 700px) {
  .modal-dropdown {
    bottom: 60px;
    max-height: 60vh;
  }
  
  .modal-dropdown-content {
    max-height: calc(60vh - 120px);
    padding: 15px;
  }
}

/* Убедимся что кнопки доступны */
.modal-dropdown-actions .cancel-button,
.modal-dropdown-actions .confirm-button {
  min-height: 44px; /* Минимальная высота для удобного тапа */
  padding: 20px 20px;
  font-size: 16px;
}

