  color: #666;
  font-style: italic;
  margin-top: 20px;
  padding: 0 10px;
}

.add-gift-close-btn {
  width: calc(100% - 40px);
  margin: 0 20px 20px 20px;
  padding: 16px;
  background: #007AFF;
  color: white;
  border: none;
  border-radius: 12px;
  font-size: 16px;
  font-weight: 600;
  cursor: pointer;
  transition: background-color 0.2s;
}

.add-gift-close-btn:hover {
  background: #0056CC;
}

.add-gift-close-btn:active {
  background: #004099;
}

/* Анимации для bottom sheet */
.bottom-sheet-enter-active,
.bottom-sheet-leave-active {
  transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

.bottom-sheet-enter-from {
  transform: translateY(100%);
  opacity: 0;
}

.bottom-sheet-leave-to {
  transform: translateY(100%);
  opacity: 0;
}

/* Затемнение фона */
.bottom-sheet-enter-active::before,
.bottom-sheet-leave-active::before {
  content: '';
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(0, 0, 0, 0.5);
  z-index: -1;
  transition: opacity 0.3s ease;
}

.bottom-sheet-enter-from::before {
  opacity: 0;
}

.bottom-sheet-leave-to::before {
  opacity: 0;
}

/* Адаптивность для маленьких экранов */
