/* Контейнер с прокруткой - минимальные отступы */
.market-container {
  height: calc(100vh - 120px);
  overflow-y: auto;
  overflow-x: hidden;
  padding: 4px; /* Минимальный padding */
  position: relative;
  width: 100%;
  box-sizing: border-box;
}

.market-grid {
  display: grid;
  /* Максимально широкие колонки */
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px; /* Минимальный, но видимый gap */
  padding: 0;
  width: 100%;
  margin: 0;
}

/* ОБЯЗАТЕЛЬНО для максимальной ширины объявлений */
.market-grid > * {
  width: 100% !important;
  max-width: 100% !important;
  min-width: 0 !important;
  box-sizing: border-box;
}

/* Индикаторы загрузки - компактные */
.initial-loading,
.loading-more-indicator {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 12px;
  color: #666;
  font-size: 12px;
  grid-column: 1 / -1;
}

.initial-loading {
  min-height: 100px;
}

.loading-spinner-large {
  width: 28px;
  height: 28px;
  border: 2px solid #f3f3f3;
  border-top: 2px solid #3498db;
  border-radius: 50%;
  animation: spin 1s linear infinite;
  margin-bottom: 6px;
}

.loading-spinner-small {
  width: 16px;
  height: 16px;
  border: 2px solid #f3f3f3;
  border-top: 2px solid #3498db;
  border-radius: 50%;
  animation: spin 1s linear infinite;
  margin-right: 5px;
}

@keyframes spin {
  0% { transform: rotate(0deg); }
  100% { transform: rotate(360deg); }
}

/* Кнопка загрузки - компактная */
.load-more-button-container {
  text-align: center;
  padding: 10px 0;
  margin: 10px 0;
  grid-column: 1 / -1;
}

.load-more-button {
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  color: white;
  border: none;
  padding: 7px 14px;
  border-radius: 14px;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  min-width: 130px;
  transition: all 0.2s ease;
  box-shadow: 0 2px 6px rgba(102, 126, 234, 0.3);
}

.load-more-button:hover {
  transform: translateY(-1px);
  box-shadow: 0 3px 8px rgba(102, 126, 234, 0.4);
}

.count-badge {
  background: rgba(255, 255, 255, 0.2);
  padding: 1px 5px;
  border-radius: 8px;
  font-size: 10px;
  min-width: 18px;
  text-align: center;
}

/* Конец списка - компактный */
.end-of-list {
  text-align: center;
  padding: 12px 0;
  color: #888;
  border-top: 1px solid #eee;
  margin-top: 10px;
  font-size: 12px;
  grid-column: 1 / -1;
}

.end-icon {
  font-size: 22px;
  margin-bottom: 4px;
  opacity: 0.5;
}

/* Сообщение о пустом market - компактное */
