/* Контейнер для текста с полупрозрачным фоном */
.title-container {
  margin-top: 25px;
  padding: 15px 25px;
  border-radius: 12px;
  display: inline-block;
  backdrop-filter: blur(10px);
  animation: titleContainerPulse 2s infinite alternate;
}

/* Фон для успеха */
.title-container.success {
  background: rgba(76, 255, 179, 0.15); /* Очень прозрачный зелёный фон */
  box-shadow: 
    0 0 20px rgba(76, 255, 179, 0.2),
    inset 0 0 15px rgba(76, 255, 179, 0.1);
}

/* Фон для ошибки */
.title-container.fail {
  background: rgba(255, 107, 107, 0.15); /* Очень прозрачный красный фон */
  box-shadow: 
    0 0 20px rgba(255, 107, 107, 0.2),
    inset 0 0 15px rgba(255, 107, 107, 0.1);
}

.animation-title {
  margin: 0;
  font-size: 22px;
  font-weight: 600;
  letter-spacing: 0.5px;
}

/* Цвета текста */
.title-container.success .animation-title {
  color: #3abc5e; /* Светло-зеленый */
  text-shadow: 0 0 10px rgba(76, 255, 179, 0.5);
}

.title-container.fail .animation-title {
  color: #ff6b6b; /* Светло-красный */
  text-shadow: 0 0 10px rgba(255, 107, 107, 0.5);
}

/* Fallback если тип не определен */
.title-container:not(.success):not(.fail) {
  background: rgba(255, 255, 255, 0.1);
}

.title-container:not(.success):not(.fail) .animation-title {
  color: #ffffff;
}

/* Анимации */
.fade-enter-active,
.fade-leave-active {
  transition: opacity 0.4s ease;
}

.fade-enter-from,
.fade-leave-to {
  opacity: 0;
}

/* Анимация контейнера */
@keyframes titleContainerPulse {
  0% {
    opacity: 0.9;
    transform: scale(1) translateY(0);
    box-shadow: 
      0 0 15px rgba(76, 255, 179, 0.1),
      inset 0 0 10px rgba(76, 255, 179, 0.05);
  }
  100% {
    opacity: 1;
    transform: scale(1.03) translateY(-2px);
    box-shadow: 
      0 0 25px rgba(76, 255, 179, 0.3),
      inset 0 0 20px rgba(76, 255, 179, 0.15);
  }
}

/* Специфичные анимации для success и fail */
.title-container.success {
  animation: successContainerPulse 2s infinite alternate;
}

.title-container.fail {
  animation: failContainerPulse 2s infinite alternate;
}

@keyframes successContainerPulse {
  0% {
    background: rgba(76, 255, 179, 0.12);
    transform: scale(1) translateY(0);
    box-shadow: 
      0 0 15px rgba(76, 255, 179, 0.15),
      inset 0 0 10px rgba(76, 255, 179, 0.08);
  }
  100% {
    background: rgba(76, 255, 179, 0.18);
    transform: scale(1.03) translateY(-2px);
    box-shadow: 
      0 0 25px rgba(76, 255, 179, 0.25),
      inset 0 0 20px rgba(76, 255, 179, 0.12);
  }
}

