}

.fade-enter-from,
.fade-leave-to {
  opacity: 0;
}
/* Вариант 2 - меню вылезает именно из левого нижнего угла */
.info-dropdown-menu.from-left-bottom-corner {
  position: absolute;
  top: calc(100% + 5px);
  right: -10px; /* Смещаем влево относительно кнопки */
  width: 280px;
  background: white;
  border-radius: 12px 0 12px 12px; /* Скругляем все углы кроме правого верхнего */
  box-shadow: -5px 10px 30px rgba(0, 0, 0, 0.2);
  z-index: 100;
  overflow: hidden;
  transform-origin: top right;
}

.info-dropdown-menu.from-left-bottom-corner .info-dropdown-arrow {
  position: absolute;
  top: -8px;
  right: 10px;
  width: 16px;
  height: 16px;
  background: white;
  transform: rotate(45deg);
  box-shadow: -2px -2px 5px rgba(0, 0, 0, 0.1);
}

/* Анимация вылезания из угла */
@keyframes slideFromLeftBottom {
  0% {
    opacity: 0;
    transform: translateX(10px) translateY(10px) scale(0.5);
    transform-origin: 90% 0%;
  }
  100% {
    opacity: 1;
    transform: translateX(0) translateY(0) scale(1);
    transform-origin: 90% 0%;
  }
}

.info-dropdown-enter-active.from-left-bottom-corner {
  animation: slideFromLeftBottom 0.3s ease-out;
}
