  margin: -0.000000001px; /* Отрицательный отступ для центрирования */
  object-fit: cover;
  display: block;
}
.nft-image-wrapper {
  position: relative;
  width: 100%;
  height: 0;
  padding-bottom: 100%;
  overflow: hidden;
  background: #2a2a2a;
  border-radius: 30px 30px 0 0;
