/* Основной контейнер market-item */
.market-item {
  display: flex;
  flex-direction: column;
  border-radius: 30px 30px 7px 7px;
  overflow: hidden;
  background: #2b2b2b;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
  transition: transform 0.2s;
  width: 100%;
  height: fit-content; /* Высота по содержимому */
}

/* Кликабельный контент */
.market-item-content {
  cursor: pointer;
  width: 100%;
  display: flex;
  flex-direction: column;
}

/* Контейнер для изображения */
.nft-image-wrapper {
  position: relative;
  width: 100%;
  aspect-ratio: 1 / 1; /* Квадратное соотношение */
  overflow: hidden;
  background: #2a2a2a;
  border-radius: 30px 30px 0 0;
}

.nft-image {
  position: absolute;
  top: -5%;
  left: -5%;
  width: 110%;
  height: 110%;
  object-fit: cover;
  display: block;
}





:root {
  --card-min-height: 80px;
  --card-max-height: 380px;
  --info-min-height: 40px;
  --actions-min-height: 80px;
  --button-min-height: 36px;
  --button-font-size: 14px;
}

@media (max-width: 480px) {
  :root {
    --card-min-height: 240px;
    --card-max-height: 320px;
    --info-min-height: 36px;
    --actions-min-height: 70px;
    --button-min-height: 32px;
    --button-font-size: 12px;
  }
}

@media (min-width: 481px) and (max-width: 768px) {
  :root {
    --card-min-height: 260px;
    --card-max-height: 340px;
    --info-min-height: 38px;
    --actions-min-height: 75px;
    --button-min-height: 34px;
    --button-font-size: 13px;
  }
}

@media (min-width: 1025px) {
  :root {
    --card-min-height: 300px;
    --card-max-height: 400px;
    --info-min-height: 44px;
    --actions-min-height: 85px;
    --button-min-height: 40px;
    --button-font-size: 15px;
  }
}



.nft-info-container {
  min-height: var(--info-min-height);
}

.item-actions,
.action-buttons-container {
  min-height: var(--actions-min-height);
}

.buy-button, 
.edit-price-button, 
.cancel-sale-button {
  min-height: var(--button-min-height);
  font-size: var(--button-font-size);
}

/* Стили для кликабельных активностей */
.activity-item.clickable {
  cursor: pointer;
  transition: all 0.2s ease;
}

.activity-item.clickable:hover {
  transform: translateY(-2px);
}

.activity-item.clickable:active {
  transform: translateY(0);
}

/* Для некликабельных - обычный курсор */
.activity-item:not(.clickable) {
  cursor: default;
}

/* Стили для превью изображения */
.activity-nft-preview {
  width: 60px;
  height: 60px;
  border-radius: 8px;
  overflow: hidden;
  flex-shrink: 0;
  background: #2a2a2a;
}

.activity-nft-image {
  width: 100%;
  height: 100%;
  object-fit: cover;
}
/* Стили для кликабельного изображения */
.activity-nft-preview {
  width: 110px;
  height: 110px;
  border-radius: 20px;
  overflow: hidden;
  flex-shrink: 0;
  background: #2a2a2a;
  transition: all 0.2s ease;
}

.activity-nft-preview.clickable {
  cursor: pointer;
}

.activity-nft-preview.clickable:hover {
  transform: scale(1.05);
  box-shadow: 0 4px 12px rgba(255, 187, 0, 0.3);
}

.activity-nft-preview.clickable:active {
  transform: scale(0.98);
}

.activity-nft-preview:not(.clickable) {
  cursor: default;
}

.activity-nft-image {
  width: 100%;
  height: 100%;
  object-fit: cover;
  pointer-events: none; /* Чтобы клик проходил через изображение к контейнеру */
}
/* Стили для информации об изменении цены */
.price-edit-info {
  padding: 12px 16px;
  margin: 10px 16px;
  background: rgba(255, 215, 0, 0.1);
  border-left: 3px solid #ffd700;
  border-radius: 8px;
  font-size: 14px;
}

.price-edit-info.fee {
  background: rgba(255, 107, 107, 0.1);
  border-left-color: #ff6b6b;
}

.price-edit-info p {
  margin: 4px 0;
  color: #fff;
}

.price-edit-info strong {
  color: #ffd700;
  font-weight: bold;
}

.price-edit-info.fee strong {
  color: #ff6b6b;
}
/* Стили для модального окна редактирования цены */
.modal-dropdown.fullscreen-modal-dropdown.edit-price-modal {
  display: flex;
  flex-direction: column;
  max-height: 85vh; /* Ограничиваем максимальную высоту */
  height: auto;
  overflow: hidden;
}

/* Контейнер с прокруткой для контента */
.modal-scrollable-content {
  flex: 1;
  overflow-y: auto;
  padding: 0 16px;
  -webkit-overflow-scrolling: touch; /* Плавный скролл на iOS */
  max-height: calc(85vh - 120px); /* Учитываем высоту header и кнопок */
}

/* Фиксированные кнопки внизу */
.modal-fixed-actions {
  display: flex;
  gap: 12px;
  padding: 16px;
  border-top: 1px solid #333;
  background: #1a1a1a;
  flex-shrink: 0;
  position: sticky;
  bottom: 0;
  left: 0;
  right: 0;
  z-index: 10;
  box-shadow: 0 -4px 10px rgba(0, 0, 0, 0.2);
}

.modal-fixed-actions .cancel-button,
.modal-fixed-actions .confirm-button {
  flex: 1;
  min-height: 44px;
  border-radius: 20px;
  font-weight: 600;
  font-size: 16px;
  margin: 0;
}

.modal-fixed-actions .cancel-button {
  background-color: #363636;
  color: #b4b4b4;
  border: 1px solid #444;
}

.modal-fixed-actions .confirm-button {
  background-color: #16a34a;
  color: white;
  border: none;
}

.modal-fixed-actions .confirm-button:hover:not(:disabled) {
  background-color: #15803d;
}

.modal-fixed-actions .confirm-button:disabled {
  opacity: 0.6;
  cursor: not-allowed;
  background-color: #4a4a4a;
}

/* Отступ внизу для удобства прокрутки */
.scroll-spacer {
  height: 10px;
  width: 100%;
}

/* Адаптация для мобильных устройств */
@media (max-width: 768px) {
  .modal-scrollable-content {
    max-height: calc(85vh - 140px);
    padding: 0 12px;
  }
  
  .modal-fixed-actions {
    padding: 12px;
  }
  
  .modal-fixed-actions .cancel-button,
  .modal-fixed-actions .confirm-button {
    min-height: 40px;
    font-size: 14px;
  }
}

/* Для очень маленьких экранов */
@media (max-width: 480px) {
  .modal-scrollable-content {
    max-height: calc(85vh - 130px);
  }
}
.modal-dropdown.fullscreen-modal-dropdown.edit-price-modal {
  max-height: v-bind(modalMaxHeight);
}
/* New styles for unlisted fullscreen buttons */
.unlisted-fullscreen-buttons-new {
  width: 100%;
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-top: 20px;
}

/* Full width buttons */
.send-button-fullscreen-new,
.sell-button-fullscreen-new,
.withdraw-button-fullscreen-new {
  width: 100%;
  padding: 16px 24px;
  border: none;
  border-radius: 20px;
  font-size: 18px;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.3s ease;
  text-align: center;
  color: white;
}

.send-button-fullscreen-new {
  background: #ffbb00;
  color: #222;
  border: 3px solid #ffbb00;
}

.send-button-fullscreen-new:hover {
  background: #e6a500;
  border-color: #e6a500;
  transform: translateY(-2px);
  box-shadow: 0 4px 12px rgba(255, 187, 0, 0.4);
}

.sell-button-fullscreen-new {
  background: #16a34a;
  border: 3px solid #16a34a;
}

.sell-button-fullscreen-new:hover {
  background: #15803d;
  border-color: #15803d;
  transform: translateY(-2px);
  box-shadow: 0 4px 12px rgba(22, 163, 74, 0.4);
}

.withdraw-button-fullscreen-new {
  background: #ff474a;
  border: 3px solid #ff474a;
}

.withdraw-button-fullscreen-new:hover {
  background: #d32f2f;
  border-color: #d32f2f;
  transform: translateY(-2px);
  box-shadow: 0 4px 12px rgba(255, 71, 74, 0.4);
}

/* Row buttons for additional actions */
.row-buttons-new {
  display: flex;
  width: 100%;
  gap: 12px;
  margin-top: 8px;
}

.action-btn-new {
  flex: 1;
  height: 50px;
  border: none;
  border-radius: 20px;
  cursor: pointer;
  transition: all 0.3s ease;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: 16px;
  color: white;
}

.sell-btn-new {
  background: #16a34a;
  border: 3px solid #16a34a;
  border-radius: 20px 0 0 20px;
}

.sell-btn-new:hover {
  background: #15803d;
  transform: translateY(-2px);
}

.withdraw-btn-new {
  background: #ff474a;
  border: 3px solid #ff474a;
  border-radius: 0 20px 20px 0;
}

.withdraw-btn-new:hover {
  background: #d32f2f;
  transform: translateY(-2px);
}

.action-btn-new:active {
  transform: translateY(1px);
}

.btn-text-new {
  font-weight: 700;
  color: white;
}

/* Animation */
.sell-btn-new, 
.withdraw-btn-new,
.send-button-fullscreen-new,
.sell-button-fullscreen-new,
.withdraw-button-fullscreen-new {
  animation: buttonAppear 0.3s ease;
}

@keyframes buttonAppear {
  from {
    opacity: 0;
    transform: translateY(10px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
/* New full-width button style */
.action-btn-fullwidth {
  width: 100%;
  height: 50px;
  border: none;
  border-radius: 20px;
  cursor: pointer;
  transition: all 0.3s ease;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: 18px;
  color: #222;
  margin-bottom: 8px;
}

.send-btn-fullwidth {
  background: #ffbb00;
  border: 3px solid #ffbb00;
}

.send-btn-fullwidth:hover {
  background: #e6a500;
  border-color: #e6a500;
  transform: translateY(-2px);
  box-shadow: 0 4px 12px rgba(255, 187, 0, 0.4);
}

.btn-text-fullwidth {
  font-weight: 700;
}
/* Уменьшение промежутков между кнопками */
.unlisted-fullscreen-buttons-new {
  width: 100%;
  display: flex;
  flex-direction: column;
  gap: 6px; /* Уменьшено с 12px до 6px */
  margin-top: 10px; /* Уменьшено с 20px до 10px */
}

.row-buttons-new {
  display: flex;
  width: 100%;
  gap: 6px; /* Уменьшено с 12px до 6px */
  margin-top: 0; /* Убрано 8px */
}

.action-btn-fullwidth {
  margin-bottom: 0; /* Убрано 8px */
}

/* Дополнительно можно уменьшить внутренние отступы */
.action-btn-fullwidth {
  height: 44px; /* Уменьшено с 50px */
}

.action-btn-new {
  height: 44px; /* Уменьшено с 50px */
}

.row-buttons-new {
  gap: 1px;
}
/* Уменьшение расстояния между кнопками и информационным блоком */
.fullscreen-view .unlisted-fullscreen-buttons-new {
  margin-top: -30px; /* Отрицательный отступ для поднятия кнопок вверх */
}
.option-image{
  width:50px;
  height:50px;
}
/* Стили для поля ввода с префиксом */
.username-input-wrapper {
  position: relative;
  display: flex;
  align-items: center;
  width: 100%;
}

.username-prefix {
  position: absolute;
  left: 12px;
  color: #888;
  font-size: 16px;
  font-weight: 500;
  z-index: 1;
  pointer-events: none; /* Чтобы можно было кликать сквозь префикс на поле ввода */
}

.username-input {
  padding-left: 28px !important; /* Отступ для префикса @ */
  width: 100%;
}

/* Адаптация для мобильных устройств */
@media (max-width: 768px) {
  .username-prefix {
    left: 10px;
    font-size: 14px;
  }
  
  .username-input {
    padding-left: 26px !important;
  }
}
/* Стили для отображения оригинального username */
.recipient-original {
  font-weight: 600;
  color: #ffbb00;
}

.original-username-note {
  margin-top: 5px;
  color: #888;
  font-style: italic;
}

.original-username-note small {
  color: #aaa;
}

/* Стили для сообщений о статусе проверки */
.check-message {
  margin-top: 5px;
  font-size: 13px;
}

.check-message.loading {
  color: #2196F3;
}

.check-message.success {
  color: #4CAF50;
}

.check-message.error {
  color: #f44336;
}
/* Стили для поля ввода с аватаркой */
.username-input-wrapper {
  position: relative;
  display: flex;
  align-items: center;
  width: 100%;
}

.username-prefix {
  position: absolute;
  left: 12px;
  color: #888;
  font-size: 16px;
  font-weight: 500;
  z-index: 1;
  pointer-events: none;
}

.username-input {
  padding-left: 28px !important;
  padding-right: 50px !important; /* Место для аватарки */
  width: 100%;
  transition: all 0.3s ease;
}

/* Стили для аватарки */
.user-avatar {
  position: absolute;
  right: 8px;
  width: 36px;
  height: 36px;
  border-radius: 30%;
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.2);
  animation: avatarAppear 0.3s ease;
}

.user-avatar-placeholder {
  position: absolute;
  right: 8px;
  width: 36px;
  height: 36px;
  border-radius: 30%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: white;
  font-weight: bold;
  font-size: 16px;
  text-transform: uppercase;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.2);
  animation: avatarAppear 0.3s ease;
}

.avatar-image {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

/* Анимация появления аватарки */
@keyframes avatarAppear {
  from {
    opacity: 0;
    transform: scale(0.8);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

/* Стили для сообщений о статусе */
.check-message {
  margin-top: 8px;
  padding: 6px 12px;
  border-radius: 20px;
  font-size: 13px;
  font-weight: 500;
  display: flex;
  align-items: center;
  gap: 6px;
}

.check-message.loading {
  background: rgba(33, 150, 243, 0.1);
  color: #2196F3;
}

.check-message.success {
  background: rgba(76, 175, 80, 0.1);
  color: #4CAF50;
}

.check-message.error {
  background: rgba(244, 67, 54, 0.1);
  color: #f44336;
}

/* Маленький спиннер для загрузки */
.spinner-small {
  display: inline-block;
  width: 14px;
  height: 14px;
  border-radius: 50%;
  animation: spin 0.6s linear infinite;
}

@keyframes spin {
  to { transform: rotate(360deg); }
}

/* Адаптация для мобильных */
@media (max-width: 768px) {
  .username-prefix {
    left: 10px;
    font-size: 14px;
  }
  
  .username-input {
    padding-left: 26px !important;
    padding-right: 46px !important;
  }
  
  .user-avatar,
  .user-avatar-placeholder {
    width: 28px;
    height: 28px;
    right: 6px;
  }
}

/* Состояние загрузки */
.username-input.loading {
  background-image: linear-gradient(90deg, transparent, rgba(255,255,255,0.1), transparent);
  background-size: 200% 100%;
  animation: loading 1.5s infinite;
}

@keyframes loading {
  0% { background-position: 200% 0; }
  100% { background-position: -200% 0; }
}
/* Современный тёмный дизайн для free-transfer-info - ЧИСТЫЙ ТЁМНЫЙ */
.free-transfer-info {
  background: linear-gradient(145deg, #2c2c2c 0%, #1d1d1d 100%);
  border-radius: 20px;
  padding: 18px 16px;
  margin: 16px 0 8px;
  border: 1px solid rgba(255, 255, 255, 0.03);
  box-shadow: 
    0 15px 30px -12px rgba(0, 0, 0, 0.7),
    inset 0 1px 1px rgba(255, 255, 255, 0.02);
  position: relative;
}

/* Тонкая текстура */
.free-transfer-info::after {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noise'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.65' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noise)' opacity='0.02'/%3E%3C/svg%3E");
  opacity: 0.1;
  pointer-events: none;
  border-radius: 20px;
  z-index: 0;
}

.free-transfer-info > * {
  position: relative;
  z-index: 1;
}

/* Заголовок секции */
.free-transfer-info .section-title {
  font-size: 13px;
  font-weight: 600;
  color: #808080;
  margin-bottom: 16px;
  letter-spacing: 0.5px;
  text-transform: uppercase;
  display: flex;
  align-items: center;
  gap: 8px;
}

.free-transfer-info .section-title::before {
  content: '🎁';
  font-size: 14px;
  opacity: 0.5;
}

/* Строка с деталями */
.free-transfer-info .detail-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 12px 0;
  border-bottom: 1px solid rgba(255, 255, 255, 0.04);
}

.free-transfer-info .detail-row:last-of-type {
  border-bottom: none;
}

/* Лейбл (левая часть) */
.free-transfer-info .detail-row span:first-child {
  color: #888888;
  font-size: 14px;
  font-weight: 500;
}

/* Значение (правая часть) */
.free-transfer-info .detail-row span:last-child {
  color: #cccccc;
  font-size: 15px;
  font-weight: 600;
}

/* Бейдж FREE - бледно-зелёный */
.free-transfer-info .free-badge {
  background: rgba(139, 195, 74, 0.08);
  color: #8bc34a;
  padding: 4px 12px;
  border-radius: 30px;
  font-size: 12px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.8px;
  border: 1px solid rgba(139, 195, 74, 0.15);
  display: inline-block;
}

/* Строка с балансом (total) - БЕЗ ЗЕЛЁНОГО */
.free-transfer-info .detail-row.total {
  margin-top: 12px;
  padding-top: 14px;
  border-top: 2px solid rgba(255, 255, 255, 0.05);
  background: #1d1d1d;
  border-radius: 12px;
  margin-bottom: -4px;
  padding-left: 12px;
  padding-right: 12px;
}

.free-transfer-info .detail-row.total span:first-child {
  color: #888888;
  font-weight: 600;
  font-size: 14px;
}

.free-transfer-info .detail-row.total span:last-child {
  color: #ffffff;
  font-size: 18px;
  font-weight: 700;
}

/* Информационная строка */
.free-transfer-info .detail-row.info-text {
  background: #1d1d1d;
  padding: 14px 12px;
  border-radius: 16px;
  margin: 14px 0 4px;
  border: 1px solid rgba(255, 255, 255, 0.02);
}

.free-transfer-info .detail-row.info-text span {
  color: #888888;
  font-size: 13px;
  font-weight: 400;
  line-height: 1.5;
  text-align: center;
  width: 100%;
}

/* Иконка подарка - нейтральная */
.free-transfer-info .gift-icon {
  display: flex;
  justify-content: center;
  margin-bottom: 16px;
}

.free-transfer-info .gift-icon svg {
  width: 32px;
  height: 32px;
  opacity: 0.5;
}

.free-transfer-info .gift-icon svg path {
  stroke: #808080;
  stroke-width: 1.5;
}

/* Акцент при наведении - очень тонкий */
.free-transfer-info:hover {
  background: linear-gradient(145deg, #303030 0%, #202020 100%);
  border-color: rgba(139, 195, 74, 0.08);
  transition: all 0.2s ease;
}

.free-transfer-info:hover .free-badge {
  background: rgba(139, 195, 74, 0.12);
  border-color: rgba(139, 195, 74, 0.2);
  transition: all 0.2s ease;
}

.free-transfer-info:hover .detail-row.total {
  background: #202020;
  transition: all 0.2s ease;
}

/* Адаптивность для мобильных */
@media (max-width: 480px) {
  .free-transfer-info {
    padding: 16px 14px;
    border-radius: 18px;
  }
  
  .free-transfer-info .detail-row {
    padding: 10px 0;
  }
  
  .free-transfer-info .detail-row span:first-child {
    font-size: 13px;
    color: #888888;
  }
  
  .free-transfer-info .detail-row span:last-child {
    font-size: 14px;
    color: #cccccc;
  }
  
  .free-transfer-info .free-badge {
    padding: 4px 10px;
    font-size: 11px;
    color: #8bc34a;
  }
  
  .free-transfer-info .detail-row.total span:last-child {
    font-size: 16px;
    color: #ffffff;
  }
  
  .free-transfer-info .detail-row.info-text {
    padding: 12px 10px;
    background: #1d1d1d;
  }
  
  .free-transfer-info .detail-row.info-text span {
    font-size: 12px;
    color: #888888;
  }
  
  .free-transfer-info .detail-row.total {
    background: #1d1d1d;
  }
}
/* Стили для верхнего ряда кнопок - гарантируем кликабельность */
.action-buttons-row {
  display: flex;
  justify-content: center;
  gap: 12px;
  margin: 70px 0 10px 0;
  width: 100%;
  position: relative;
  z-index: 100; /* Умеренный z-index, но выше основного контента */
  pointer-events: auto !important; /* Принудительно разрешаем клики */
}

.action-button-row {
  background-color: #2a2a2a;
  border: none;
  border-radius: 15px;
  width: 45.5%;
  height: 44px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer !important; /* Принудительно указываем cursor */
  transition: all 0.2s ease;
  position: relative;
  pointer-events: auto !important; /* Разрешаем клики */
  z-index: 101; /* Чуть выше родителя */
}

/* Специфично для кнопки подарка */
.action-button-row.gift-button {
  background-color: #2a2a2a;
  pointer-events: auto !important;
  cursor: pointer !important;
}

.action-button-row.gift-button:hover {
  background-color: #3a3a3a;
  transform: translateY(-2px);
}

.action-button-row.gift-button:active {
  transform: translateY(0);
}

.action-button-row:hover {
  background-color: #3a3a3a;
  transform: translateY(-2px);
}

.action-button-row:active {
  transform: translateY(0);
}

.action-button-row:disabled {
  opacity: 0.5;
  cursor: not-allowed !important;
  transform: none;
}

.action-button-row.in-cart {
  background-color: #3a2a2a;
}

.action-button-icon {
  width: 20px;
  height: 20px;
  object-fit: contain;
  pointer-events: none; /* Иконка не должна перехватывать клики */
}

/* Убедимся что никакие родительские элементы не блокируют клики */
.fullscreen-view {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: #1d1d1d;
  z-index: 1000;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  overflow-y: auto;
  pointer-events: auto; /* Разрешаем клики на весь экран */
}

.fullscreen-content {
  width: 100%;
  max-width: 800px;
  height: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 20px;
  pointer-events: auto; /* Разрешаем клики */
}

/* Исправляем возможные конфликты с модальными окнами */
.modal-dropdown-overlay.fullscreen-modal {
  pointer-events: none; /* Оверлей не перехватывает клики */
}

.modal-dropdown-overlay.fullscreen-modal .modal-dropdown.fullscreen-modal-dropdown {
  pointer-events: auto; /* Но модалка перехватывает */
}

/* Гарантируем что кнопка подарка не перекрывается другими элементами */
.html-container {
  position: relative;
  width: 85%;
  max-width: 70%;
  height: auto;
  margin: 0 auto;
  flex: 1;
  display: flex;
  flex-direction: column;
  justify-content: center;
  pointer-events: none; /* Контейнер с iframe не должен перехватывать клики */
}

.html-content-iframe {
  width: 100%;
  min-height: 3vh;
  max-height: 35vh;
  border: none;
  margin: 0 auto;
  pointer-events: none; /* iframe не должен перехватывать клики */
}

/* Убираем возможные блокирующие стили из предыдущих изменений */
.fullscreen-view * {
  pointer-events: auto; /* Все элементы по умолчанию кликабельны */
}

/* Но некоторые элементы должны пропускать клики */
.html-container,
.html-content-iframe,
.html-container * {
  pointer-events: none; /* iframe и его содержимое не перехватывают клики */
}

/* А кнопки должны быть кликабельны */
.action-buttons-row,
.action-button-row,
.action-button-row * {
  pointer-events: auto !important;
}

/* Поднимаем кнопки modal-dropdown-actions выше */
.modal-dropdown.fullscreen-modal-dropdown {
  display: flex;
  flex-direction: column;
  max-height: 60vh;
}

.modal-dropdown.fullscreen-modal-dropdown .modal-dropdown-content {
  flex: 1;
  overflow-y: auto;
  padding: 20px 20px 8px 20px;
  max-height: none; /* Убираем фиксированную высоту */
}

.modal-dropdown-actions {
  padding: 12px 20px 24px 20px; /* Уменьшен верхний padding с 20px до 12px */
  border-top: 1px solid rgba(255, 255, 255, 0.05);
  display: flex;
  gap: 12px;
  justify-content: flex-end;
  background: #1a1a1a;
  position: relative;
  z-index: 1002;
  box-shadow: 0 -4px 10px rgba(0, 0, 0, 0.2);
  margin-top: -8px; /* Отрицательный отступ для поднятия кнопок */
}

/* Убираем возможные лишние отступы */
.modal-dropdown-actions .cancel-button,
.modal-dropdown-actions .confirm-button {
  margin-top: -4px; /* Дополнительное поднятие самих кнопок */
}

/* Адаптация для разных размеров экрана */
@media (max-height: 700px) {
  .modal-dropdown-actions {
    padding: 8px 16px 20px 16px;
    margin-top: -6px;
  }
}

@media (max-height: 600px) {
  .modal-dropdown-actions {
    padding: 6px 16px 16px 16px;
    margin-top: -4px;
  }
}

@media (max-height: 500px) {
  .modal-dropdown-actions {
    padding: 4px 16px 12px 16px;
    margin-top: -2px;
  }
}
/* ТОЛЬКО ИСПРАВЛЕНИЕ ПОИСКОВОЙ СТРОКИ - без изменений модалок */
.search-box {
  padding: 0 10px 15px;
  width: 100%;
  box-sizing: border-box;
}

.search-input {
  width: 100%;
  padding: 12px 15px !important; /* Фиксированный padding */
  background-color: #3a3a3a;
  border-radius: 10px;
  color: white;
  font-size: 1rem;
  line-height: 1.2 !important; /* Фиксированный line-height */
  height: auto !important; /* Автовысота */
  min-height: 46px;
  box-sizing: border-box;
  border: 1px solid transparent;
  text-align: left !important; /* Текст всегда слева */
  vertical-align: middle;
}

/* Все состояния с одинаковым padding */
.search-input:focus,
.search-input:active,
.search-input:not(:placeholder-shown) {
  padding: 12px 15px !important;
  line-height: 1.2 !important;
  text-align: left !important;
}

/* Placeholder тоже слева */
.search-input::placeholder {
  color: #888;
  text-align: left !important;
  line-height: 1.2 !important;
  opacity: 1;
}

/* Для мобильных устройств */
@media (max-width: 768px) {
  .search-input {
    padding: 12px 15px !important;
    font-size: 16px;
    min-height: 44px;
  }
  
  .search-input:focus,
  .search-input:active,
  .search-input:not(:placeholder-shown) {
    padding: 12px 15px !important;
  }
}




/* Поднимаем весь блок item-actions, если внутри есть Edit Price или Cancel Sale */
.item-actions:has(.edit-price-button),
.item-actions:has(.cancel-sale-button) {
  margin-top: -10px; /* Отрицательный отступ сверху */
}
/* Для My Gifts - все карточки в ряду одинаковой высоты */
.my-gifts-page .market-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 8px;
  align-items: stretch; /* Все ячейки растягиваются */
}

.my-gifts-page .market-item {
  display: flex;
  flex-direction: column;
  height: 100%; /* Занимает всю высоту ячейки */
  min-height: 0; /* Сбрасываем min-height */
}

/* Карточка Add Gift */
.my-gifts-page .market-item.add-card {
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(255, 255, 255, 0.05);
  border: 2px dashed rgba(255, 187, 0, 0.3);
  cursor: pointer;
  height: 100%; /* Такая же высота как у других карточек */
  min-height: 0;
}

/* Контент внутри Add Card */
.my-gifts-page .empty-nft-square {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  width: 100%;
  height: 100%;
  padding: 10px;
  text-align: center;
}
/* Базовая высота для всех карточек в My Gifts */
.my-gifts-page .market-item {
  height: 280px; /* Фиксированная высота */
  display: flex;
  flex-direction: column;
}

/* Для My Gifts - все карточки в ряду одинаковой высоты */
.market-page[data-tab="my-gifts"] .market-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 8px;
  align-items: stretch; /* Растягиваем по высоте */
}



/* Уменьшаем высоту контейнера с кнопками */


/* Делаем кнопки более плоскими и низкими */
.modal-dropdown-actions .cancel-button,
.modal-dropdown-actions .confirm-button {
  padding: 8px 12px !important; /* Уменьшаем внутренние отступы */
  height: 50px !important; /* Фиксированная меньшая высота */
  min-height: 36px !important;
  border-radius: 20px !important; /* Более плоские (меньше радиус) */
  font-size: 14px !important; /* Немного уменьшаем шрифт */
  line-height: 1 !important;
  margin: 0 !important;
}

/* Современный Sell Modal в стиле free-transfer-info */
.modern-sell-modal {
  background: #1a1a1a !important;
}

/* Превью NFT */
.nft-preview-card {
  display: flex;
  align-items: center;
  gap: 16px;
  background: linear-gradient(145deg, #2c2c2c 0%, #1d1d1d 100%);
  border-radius: 20px;
  padding: 16px;
  margin-bottom: 20px;
  border: 1px solid rgba(255, 255, 255, 0.03);
  box-shadow: 0 10px 20px -10px rgba(0, 0, 0, 0.6);
  position: relative;
  overflow: hidden;
}

.nft-preview-card::after {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noise'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.65' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noise)' opacity='0.02'/%3E%3C/svg%3E");
  opacity: 0.1;
  pointer-events: none;
}

.nft-preview-image {
  width: 70px;
  height: 70px;
  border-radius: 16px;
  overflow: hidden;
  background: #2a2a2a;
  flex-shrink: 0;
  position: relative;
  z-index: 1;
  box-shadow: 0 5px 15px rgba(0, 0, 0, 0.3);
}

.preview-html-wrapper {
  width: 100%;
  height: 100%;
}

.preview-html-content {
  width: 100%;
  height: 100%;
  border: none;
}

.preview-image {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.nft-preview-info {
  flex: 1;
  position: relative;
  z-index: 1;
}

.preview-name-container {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 6px;
  flex-wrap: wrap;
}

.preview-name {
  font-weight: 700;
  font-size: 16px;
  color: #ffffff;
}

.preview-number {
  font-size: 13px;
  color: #888;
  font-weight: 500;
  background: rgba(255, 255, 255, 0.05);
  padding: 2px 8px;
  border-radius: 30px;
}



/* Карточка с информацией о минимальной цене */
.floor-info-card {
  display: flex;
  align-items: center;
  gap: 12px;
  background: rgba(255, 187, 0, 0.05);
  border: 1px solid rgba(255, 187, 0, 0.1);
  border-radius: 16px;
  padding: 12px 16px;
  margin-bottom: 20px;
}

.floor-info-icon {
  font-size: 20px;
  opacity: 0.7;
}

.floor-info-content {
  flex: 1;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.floor-info-label {
  color: #888;
  font-size: 14px;
  font-weight: 500;
}

.floor-info-value {
  color: #ffbb00;
  font-weight: 700;
  font-size: 16px;
}

/* Современные поля ввода */
.input-modern-container {
  margin-bottom: 20px;
}

.input-modern-label {
  display: block;
  margin-bottom: 8px;
  font-size: 13px;
  font-weight: 600;
  color: #888;
  letter-spacing: 0.3px;
  text-transform: uppercase;
}

.input-modern-wrapper {
  position: relative;
  display: flex;
  align-items: center;
}

.input-modern {
  width: 100%;
  padding: 16px 70px 16px 16px;
  background: #2c2c2c;
  border: 2px solid #3a3a3a;
  border-radius: 16px;
  color: white;
  font-size: 18px;
  font-weight: 600;
  transition: all 0.2s ease;
}

.input-modern:focus {
  outline: none;
  border-color: #ffbb00;
  background: #333;
}

.input-modern.error {
  border-color: #ff6b6b;
}

.input-modern-currency {
  position: absolute;
  right: 16px;
  color: #888;
  font-weight: 600;
  font-size: 16px;
  pointer-events: none;
}

.input-error-message {
  margin-top: 8px;
  color: #ff6b6b;
  font-size: 13px;
  font-weight: 500;
  display: flex;
  align-items: center;
  gap: 4px;
}

/* Детали цены в стиле free-transfer-info */
.price-details-modern {
  background: linear-gradient(145deg, #2c2c2c 0%, #1d1d1d 100%);
  border-radius: 20px;
  padding: 16px;
  margin: 16px 0 8px;
  border: 1px solid rgba(255, 255, 255, 0.03);
  box-shadow: 0 10px 20px -10px rgba(0, 0, 0, 0.6);
  position: relative;
}

.price-details-modern::after {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noise'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.65' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noise)' opacity='0.02'/%3E%3C/svg%3E");
  opacity: 0.1;
  pointer-events: none;
  border-radius: 20px;
}

.price-details-header {
  margin-bottom: 12px;
  padding-bottom: 8px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.05);
}

.price-details-title {
  font-size: 13px;
  font-weight: 600;
  color: #808080;
  letter-spacing: 0.5px;
  text-transform: uppercase;
}

.price-details-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 10px 0;
  border-bottom: 1px solid rgba(255, 255, 255, 0.04);
}

.price-details-row:last-child {
  border-bottom: none;
}

.price-details-row span:first-child {
  color: #888;
  font-size: 14px;
}

.price-details-row .price-value {
  color: #ccc;
  font-weight: 600;
}

.price-details-row.commission span:last-child {
  color: #ff6b6b;
  font-weight: 600;
}

.price-details-row.total {
  margin-top: 8px;
  padding-top: 12px;
  border-top: 2px solid rgba(255, 255, 255, 0.05);
}

.price-details-row.total .total-value {
  color: #8bc34a;
  font-size: 18px;
  font-weight: 700;
}

/* Шаг подтверждения */
.confirmation-modern {
  text-align: center;
  padding: 8px 0;
}

.confirmation-icon {
  font-size: 48px;
  margin-bottom: 12px;
  animation: bounce 0.5s ease;
}

.confirmation-title {
  font-size: 20px;
  font-weight: 700;
  color: white;
  margin-bottom: 20px;
}

.confirmation-details-modern {
  background: linear-gradient(145deg, #2c2c2c 0%, #1d1d1d 100%);
  border-radius: 20px;
  padding: 16px;
  margin-bottom: 16px;
  border: 1px solid rgba(255, 255, 255, 0.03);
}

.confirmation-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 12px 0;
  border-bottom: 1px solid rgba(255, 255, 255, 0.04);
}

.confirmation-row:last-child {
  border-bottom: none;
}

.confirmation-row span:first-child {
  color: #888;
  font-size: 14px;
}

.confirmation-highlight {
  color: #ffbb00;
  font-weight: 700;
  font-size: 16px;
}

.commission-text {
  color: #ff6b6b;
  font-weight: 600;
}

.confirmation-row.total {
  margin-top: 8px;
  padding-top: 12px;
  border-top: 2px solid rgba(255, 255, 255, 0.05);
}

.total-highlight {
  color: #8bc34a;
  font-size: 20px;
  font-weight: 700;
}

.confirmation-warning-modern {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 12px;
  background: rgba(255, 187, 0, 0.05);
  border-radius: 30px;
  margin-top: 8px;
}

.warning-icon {
  font-size: 14px;
  opacity: 0.7;
}

.warning-text {
  color: #888;
  font-size: 13px;
  font-weight: 500;
}

/* Современные кнопки */
.modern-actions {
  display: flex;
  gap: 12px;
  padding: 16px;
  border-top: 1px solid rgba(255, 255, 255, 0.05);
  background: #1a1a1a;
}

.modern-cancel,
.modern-confirm {
  flex: 1;
  padding: 14px !important;
  border-radius: 30px !important;
  font-size: 15px !important;
  font-weight: 600 !important;
  transition: all 0.2s ease !important;
}

.modern-cancel {
  background: #2c2c2c !important;
  color: #888 !important;
  border: 1px solid #3a3a3a !important;
}

.modern-cancel:hover:not(:disabled) {
  background: #3a3a3a !important;
  color: #ccc !important;
}

.modern-confirm {
  background: linear-gradient(135deg, #ffbb00 0%, #e6a500 100%) !important;
  color: #000 !important;
  border: none !important;
  box-shadow: 0 5px 15px rgba(255, 187, 0, 0.2) !important;
}

.modern-confirm:hover:not(:disabled) {
  transform: translateY(-2px) !important;
  box-shadow: 0 8px 20px rgba(255, 187, 0, 0.3) !important;
}

.modern-confirm:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

/* Мини-спиннер для загрузки */
.loading-spinner-mini {
  display: inline-block;
  width: 16px;
  height: 16px;
  border: 2px solid rgba(0, 0, 0, 0.2);
  border-top-color: #000;
  border-radius: 50%;
  animation: spin 0.6s linear infinite;
}

/* Анимации */
@keyframes bounce {
  0%, 100% { transform: scale(1); }
  50% { transform: scale(1.1); }
}

/* Адаптивность для мобильных */
@media (max-width: 480px) {
  .nft-preview-card {
    padding: 12px;
    gap: 12px;
  }
  
  .nft-preview-image {
    width: 60px;
    height: 60px;
  }
  
  .preview-name {
    font-size: 14px;
  }
  
  .input-modern {
    padding: 14px 60px 14px 14px;
    font-size: 16px;
  }
  
  .price-details-row span:first-child {
    font-size: 13px;
  }
  
  .price-details-row.total .total-value {
    font-size: 16px;
  }
  
  .modern-cancel,
  .modern-confirm {
    padding: 12px !important;
    font-size: 14px !important;
  }
}
