/* Контейнер для навигации */
.navigation-toggle-container {
  width: 100%;
  max-width: 400px;
  margin: 0 auto 20px auto;
  display: flex;
  flex-direction: column;
  align-items: center;
}

/* iOS-подобный переключатель */
.navigation-ios-toggle {
  position: relative;
  width: 100%;
  max-width: 300px;
  height: 32px;
  background: #2c2c2c;
  border-radius: 22px;
  display: flex;
  align-items: center;
  padding: 4px;
  box-sizing: border-box;
}

.navigation-track {
  position: absolute;
  top: 0px;
  left: 0px;
  right: 0px;
  bottom: 0px;
  background: #1f1f1f;
  border-radius: 50px;
  transition: all 0.3s ease;
}

.navigation-track.active {
  background: #1f1f1f;
}

.navigation-thumb {
  position: absolute;
  width: 33.33%; /* Равная ширина для трех вкладок */
  height: calc(100%);
  background: #ffbb00;
  border-radius: 20px;
  transition: all 0.3s ease;
}

.navigation-thumb.market-active {
  transform: translateX(0%);
}

.navigation-thumb.my-gifts-active {
  transform: translateX(100%);
}

.navigation-thumb.activity-active {
  transform: translateX(200%);
}

.navigation-input {
  position: absolute;
  opacity: 0;
  width: 100%;
  height: 100%;
  cursor: pointer;
  z-index: 2;
}

/* Метки под переключателем */
.navigation-labels-below {
  display: flex;
  width: 100%;
  max-width: 300px;
  margin-top: 8px;
  justify-content: space-between;
  padding: 0 4px;
}

.navigation-label {
  font-size: 14px;
  font-weight: 500;
  color: #666;
  transition: color 0.3s ease;
  cursor: pointer;
  text-align: center;
  width: 33.33%;
}

.navigation-label.active {
  color: #ffbb00;
  font-weight: 600;
}

/* Адаптация для мобильных устройств */
@media (max-width: 768px) {
  .navigation-ios-toggle {
    max-width: 280px;
    height: 30px;
  }
  
  .navigation-labels-below {
    max-width: 280px;
  }
  
  .navigation-label {
    font-size: 13px;
  }
}

@media (max-width: 480px) {
  .navigation-ios-toggle {
    max-width: 260px;
    height: 28px;
  }
  
  .navigation-labels-below {
    max-width: 260px;
  }
  
  .navigation-label {
    font-size: 12px;
  }
}
