/* Drag handle на всю верхнюю часть меню */
.modal-drag-handle {
  position: absolute; /* Меняем на absolute */
  top: 0;
  left: 0;
  width: 100%;
  height: 58px; /* Высота всей верхней части */
  background-color: rgba(255, 255, 255, 0.00001); /* Едва заметный фон */
  border-radius: 50px 50px 0 0; /* Скругление только сверху */
  margin: 0;
  cursor: grab;
  z-index: 100001;
  
  /* Центрированная полоска-индикатор */
  &::after {
    content: '';
    position: absolute;
    top: 20px; /* Отступ от верхнего края */
    left: 50%;
    transform: translateX(-50%);
    width: 60px;
    height: 5px;
    background-color: rgba(255, 255, 255, 0.4);
    border-radius: 3px;
    pointer-events: none;
    transition: all 0.8s ease;
  }
  
  /* Анимация при наведении */
  &:hover {
    background-color: rgba(255, 255, 255, 0.00001);
    
    &::after {
      background-color: rgba(255, 187, 0, 0.7);
      width: 70px;
    }
  }
  
  /* Состояние активного перетаскивания */
  &:active {
    cursor: grabbing;
    background-color: rgba(255, 187, 0, 0.000001);
    
    &::after {
      background-color: #ffbb00;
      width: 80px;
      height: 6px;
    }
  }
}
